(* ========================================================================= *)
(* Conway--Schneeberger Fifteen Theorem.                                     *)
(*                                                                           *)
(* This file proves that a positive-definite integral quadratic form         *)
(* represents every positive integer if and only if it represents every      *)
(* positive integer up to 15. Here "integral" means that the Gram matrix     *)
(* has integer entries, so the associated quadratic polynomial has even      *)
(* cross coefficients.                                                       *)
(*                                                                           *)
(* The organizing argument follows Manjul Bhargava, "On the                  *)
(* Conway-Schneeberger Fifteen Theorem", in Quadratic Forms and Their        *)
(* Applications, Contemporary Mathematics 272 (2000), 27--37. In             *)
(* particular, it uses Bhargava's truants, escalator lattices, nine ternary  *)
(* escalators, and the rank-four closure summarized in his tables. Conway's  *)
(* preceding article in the same volume gives historical context and an      *)
(* account of the original Conway--Schneeberger proof.                       *)
(*                                                                           *)
(* The ternary representation results are formalized constructively from     *)
(* classical methods and results in:                                         *)
(*                                                                           *)
(*   L. E. Dickson, "Integers Represented by Positive Ternary Quadratic      *)
(*   Forms" (1927);                                                          *)
(*                                                                           *)
(*   B. W. Jones, "The Regularity of a Genus of Positive Ternary             *)
(*   Quadratic Forms" (1931);                                                *)
(*                                                                           *)
(*   B. W. Jones and Gordon Pall, "Regular and Semi-Regular Positive         *)
(*   Ternary Quadratic Forms";                                               *)
(*                                                                           *)
(*   Gordon Pall, "Representation by Quadratic Forms" (1949), and "An        *)
(*   Almost Universal Form"; and                                             *)
(*                                                                           *)
(*   Irving Kaplansky, "The First Nontrivial Genus of Positive Definite      *)
(*   Ternary Forms" (1995).                                                  *)
(*                                                                           *)
(* The proof has the following shape. A form representing the required       *)
(* small integers contains one of the nine ternary escalator forms. Each     *)
(* ternary node is escalated once more. Positivity, integral changes of      *)
(* basis, and explicit square bounds reduce the resulting rank-four forms    *)
(* to finitely many families. Their universality is proved using regular     *)
(* ternary subforms, Legendre's three-squares theorem, Dirichlet-prime and   *)
(* genus arguments for determinants 3, 5, and 7, elementary descent, and     *)
(* finite certificates for the remaining small targets. Universality then    *)
(* passes from the embedded rank-four form to the original form. The reverse *)
(* implication in the final equivalence is immediate.                        *)
(* ========================================================================= *)

needs "Library/isum.ml";;
needs "Autoformalization/three_squares.ml";;

prioritize_int();;

let qindex = new_definition
 `qindex n = {i:num | i < n}`;;

let FINITE_QINDEX = prove
 (`!n. FINITE(qindex n)`,
  REWRITE_TAC[qindex; FINITE_NUMSEG_LT]);;

let iqbilin = new_definition
 `iqbilin n (A:num->num->int) (x:num->int) (y:num->int) =
    isum (qindex n)
      (\i. isum (qindex n) (\j. A i j * x i * y j))`;;

let iqeval = new_definition
 `iqeval n (A:num->num->int) (x:num->int) = iqbilin n A x x`;;

let iq_symmetric = new_definition
 `iq_symmetric n (A:num->num->int) <=>
    !i j. i < n /\ j < n ==> A i j = A j i`;;

let iq_nonzero = new_definition
 `iq_nonzero n (x:num->int) <=> ?i. i < n /\ ~(x i = &0)`;;

let iq_positive = new_definition
 `iq_positive n (A:num->num->int) <=>
    !x. iq_nonzero n x ==> &0 < iqeval n A x`;;

let iq_represents = new_definition
 `iq_represents n (A:num->num->int) m <=>
    ?x. iqeval n A x = m`;;

let iq_universal = new_definition
 `iq_universal n (A:num->num->int) <=>
    !m:int. &0 < m ==> iq_represents n A m`;;

let iqgram = new_definition
 `iqgram n (A:num->num->int) (V:num->num->int) i j =
    iqbilin n A (V i) (V j)`;;

let iq_embeds = new_definition
 `iq_embeds n d (P:num->num->int) (A:num->num->int) <=>
    ?V. !i j. i < d /\ j < d ==> iqgram n A V i j = P i j`;;

let iqcombine = new_definition
 `iqcombine d (c:num->int) (V:num->num->int) k =
    isum (qindex d) (\i. c i * V i k)`;;

(* ------------------------------------------------------------------------- *)
(* Bilinearity and symmetry.                                                 *)
(* ------------------------------------------------------------------------- *)

let IQBILIN_LADD = prove
  (`!n A x y z.
     iqbilin n A (\i. x i + y i) z =
     iqbilin n A x z + iqbilin n A y z`,
  REPEAT GEN_TAC THEN REWRITE_TAC[iqbilin] THEN
  SIMP_TAC[GSYM ISUM_ADD; FINITE_QINDEX] THEN
  MATCH_MP_TAC ISUM_EQ THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC ISUM_EQ THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
  REPEAT STRIP_TAC THEN INT_ARITH_TAC);;

let IQBILIN_RADD = prove
  (`!n A x y z.
     iqbilin n A x (\i. y i + z i) =
     iqbilin n A x y + iqbilin n A x z`,
  REPEAT GEN_TAC THEN REWRITE_TAC[iqbilin] THEN
  SIMP_TAC[GSYM ISUM_ADD; FINITE_QINDEX] THEN
  MATCH_MP_TAC ISUM_EQ THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC ISUM_EQ THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
  REPEAT STRIP_TAC THEN INT_ARITH_TAC);;

let IQBILIN_LMUL = prove
 (`!n A a x y.
     iqbilin n A (\i. a * x i) y = a * iqbilin n A x y`,
  REPEAT GEN_TAC THEN REWRITE_TAC[iqbilin] THEN
  REWRITE_TAC[GSYM ISUM_LMUL] THEN
  MATCH_MP_TAC ISUM_EQ THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
  REPEAT STRIP_TAC THEN REWRITE_TAC[GSYM ISUM_LMUL] THEN
  MATCH_MP_TAC ISUM_EQ THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
  REPEAT STRIP_TAC THEN INT_ARITH_TAC);;

let IQBILIN_RMUL = prove
 (`!n A a x y.
     iqbilin n A x (\i. a * y i) = a * iqbilin n A x y`,
  REPEAT GEN_TAC THEN REWRITE_TAC[iqbilin] THEN
  REWRITE_TAC[GSYM ISUM_LMUL] THEN
  MATCH_MP_TAC ISUM_EQ THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
  REPEAT STRIP_TAC THEN REWRITE_TAC[GSYM ISUM_LMUL] THEN
  MATCH_MP_TAC ISUM_EQ THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
  REPEAT STRIP_TAC THEN INT_ARITH_TAC);;

let IQBILIN_SYM = prove
 (`!n A x y.
     iq_symmetric n A ==> iqbilin n A x y = iqbilin n A y x`,
  REPEAT GEN_TAC THEN REWRITE_TAC[iq_symmetric; iqbilin] THEN DISCH_TAC THEN
  TRANS_TAC EQ_TRANS
   `isum (qindex n)
      (\j. isum (qindex n) (\i. A i j * y i * x j))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC ISUM_EQ THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
    X_GEN_TAC `i:num` THEN DISCH_TAC THEN
    MATCH_MP_TAC ISUM_EQ THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
    X_GEN_TAC `j:num` THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPECL [`i:num`; `j:num`]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN CONV_TAC INT_RING;
    MP_TAC(ISPECL
     [`\j:num. \i:num.
          (A:num->num->int) i j * (y:num->int) i * (x:num->int) j`;
      `qindex n:num->bool`; `qindex n:num->bool`] ISUM_SWAP) THEN
    REWRITE_TAC[FINITE_QINDEX]]);;

let IQEVAL_COMBO = prove
 (`!n A a b x y.
     iq_symmetric n A
     ==> iqeval n A (\i. a * x i + b * y i) =
         a pow 2 * iqeval n A x +
         &2 * a * b * iqbilin n A x y +
         b pow 2 * iqeval n A y`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[iqeval; IQBILIN_LADD; IQBILIN_RADD;
    IQBILIN_LMUL; IQBILIN_RMUL] THEN
  MP_TAC(SPECL [`n:num`; `A:num->num->int`; `x:num->int`; `y:num->int`]
    IQBILIN_SYM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN CONV_TAC INT_RING);;

(* ------------------------------------------------------------------------- *)
(* Positivity and the integral Cauchy--Schwarz bound.                        *)
(* ------------------------------------------------------------------------- *)

let IQEVAL_ZERO_ON_INDEX = prove
 (`!n A x.
     (!i. i < n ==> x i = &0) ==> iqeval n A x = &0`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[iqeval; iqbilin] THEN
  MATCH_MP_TAC ISUM_EQ_0 THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
  X_GEN_TAC `i:num` THEN DISCH_TAC THEN
  MATCH_MP_TAC ISUM_EQ_0 THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
  X_GEN_TAC `j:num` THEN DISCH_TAC THEN ASM_SIMP_TAC[INT_MUL_RZERO]);;

let IQ_POSITIVE_IMP_NONNEG = prove
 (`!n A. iq_positive n A ==> !x. &0 <= iqeval n A x`,
  REPEAT GEN_TAC THEN REWRITE_TAC[iq_positive] THEN DISCH_TAC THEN
  GEN_TAC THEN ASM_CASES_TAC `iq_nonzero n (x:num->int)` THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `x:num->int`) THEN ASM_REWRITE_TAC[] THEN
    INT_ARITH_TAC;
    SUBGOAL_THEN `iqeval n A (x:num->int) = &0` SUBST1_TAC THENL
     [MATCH_MP_TAC IQEVAL_ZERO_ON_INDEX THEN
      UNDISCH_TAC `~iq_nonzero n (x:num->int)` THEN
      REWRITE_TAC[iq_nonzero; NOT_EXISTS_THM] THEN MESON_TAC[];
      INT_ARITH_TAC]]);;

let IQBILIN_SQ_LE = prove
 (`!n A x y.
     iq_symmetric n A /\ (!z. &0 <= iqeval n A z)
     ==> iqbilin n A x y pow 2 <= iqeval n A x * iqeval n A y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `a = iqeval n A (x:num->int)` THEN
  ABBREV_TAC `b = iqbilin n A (x:num->int) (y:num->int)` THEN
  ABBREV_TAC `c = iqeval n A (y:num->int)` THEN
  SUBGOAL_THEN `&0 <= a /\ &0 <= c` STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["a"; "c"] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_CASES_TAC `c = &0` THENL
   [SUBGOAL_THEN `b = &0` SUBST1_TAC THENL
     [ASM_CASES_TAC `b = &0` THEN ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `b < &0 \/ &0 < b` MP_TAC THENL
       [ASM_INT_ARITH_TAC; ALL_TAC] THEN
      DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
       [SUBGOAL_THEN
         `iqeval n A (\i:num. x i + (a + &1) * y i) =
          a + &2 * ((a + &1) * b)` ASSUME_TAC THENL
         [MP_TAC(SPECL
           [`n:num`; `A:num->num->int`; `&1:int`; `a + &1:int`;
            `x:num->int`; `y:num->int`] IQEVAL_COMBO) THEN
          ASM_REWRITE_TAC[] THEN
          DISCH_THEN(fun th -> ASSUME_TAC(REWRITE_RULE
           [INT_MUL_LID; INT_POW_2; INT_MUL_RZERO; INT_ADD_RID] th)) THEN
          ASM_REWRITE_TAC[];
          ALL_TAC] THEN
        SUBGOAL_THEN
         `(a + &1) * b <= (a + &1) * -- &1` ASSUME_TAC THENL
         [MATCH_MP_TAC INT_LE_LMUL THEN ASM_INT_ARITH_TAC;
          FIRST_X_ASSUM(MP_TAC o SPEC
           `(\i:num. x i + (a + &1) * y i):num->int`) THEN
          ASM_REWRITE_TAC[] THEN ASM_INT_ARITH_TAC];
        SUBGOAL_THEN
         `iqeval n A (\i:num. x i + (--(a + &1)) * y i) =
          a - &2 * ((a + &1) * b)` ASSUME_TAC THENL
         [MP_TAC(SPECL
           [`n:num`; `A:num->num->int`; `&1:int`; `--(a + &1):int`;
            `x:num->int`; `y:num->int`] IQEVAL_COMBO) THEN
          ASM_REWRITE_TAC[] THEN
          DISCH_THEN(fun th -> ASSUME_TAC(REWRITE_RULE
           [INT_MUL_LID; INT_POW_2; INT_MUL_RZERO; INT_ADD_RID] th)) THEN
          MATCH_MP_TAC EQ_TRANS THEN
          EXISTS_TAC `a + &2 * --(a + &1) * b:int` THEN
          CONJ_TAC THENL [ASM_REWRITE_TAC[]; CONV_TAC INT_RING];
          ALL_TAC] THEN
        SUBGOAL_THEN
         `(a + &1) * &1 <= (a + &1) * b` ASSUME_TAC THENL
         [MATCH_MP_TAC INT_LE_LMUL THEN ASM_INT_ARITH_TAC;
          FIRST_X_ASSUM(MP_TAC o SPEC
           `(\i:num. x i + (--(a + &1)) * y i):num->int`) THEN
          ASM_REWRITE_TAC[] THEN ASM_INT_ARITH_TAC]];
      REWRITE_TAC[INT_POW_ZERO; INT_MUL_LZERO; INT_MUL_RZERO] THEN
      REWRITE_TAC[ARITH_RULE `~(2 = 0)`] THEN
      MATCH_MP_TAC INT_LE_MUL THEN ASM_REWRITE_TAC[]];
    SUBGOAL_THEN
     `iqeval n A (\i:num. c * x i + --b * y i) =
      c * (a * c - b pow 2)` ASSUME_TAC THENL
     [MP_TAC(SPECL [`n:num`; `A:num->num->int`; `c:int`; `--b:int`;
        `x:num->int`; `y:num->int`] IQEVAL_COMBO) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(fun th -> ASSUME_TAC(REWRITE_RULE
       [INT_POW_2; INT_ADD_RID] th)) THEN
      MATCH_MP_TAC EQ_TRANS THEN
      EXISTS_TAC
       `(c * c) * a + &2 * c * --b * b + (--b * --b) * c:int` THEN
      CONJ_TAC THENL [ASM_REWRITE_TAC[]; CONV_TAC INT_RING];
      ALL_TAC] THEN
    SUBGOAL_THEN `&0 < c` ASSUME_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
    FIRST_X_ASSUM(MP_TAC o SPEC
      `(\i:num. c * x i + --b * y i):num->int`) THEN
    ASM_REWRITE_TAC[] THEN
    ASM_SIMP_TAC[INT_LE_MUL_EQ] THEN INT_ARITH_TAC]);;

let IQ_POSITIVE_BILIN_SQ_LE = prove
 (`!n A x y.
     iq_symmetric n A /\ iq_positive n A
     ==> iqbilin n A x y pow 2 <= iqeval n A x * iqeval n A y`,
  MESON_TAC[IQBILIN_SQ_LE; IQ_POSITIVE_IMP_NONNEG]);;

(* ------------------------------------------------------------------------- *)
(* Gram pullback and transfer of representation/universality.                *)
(* ------------------------------------------------------------------------- *)

let IQBILIN_ISUM_L = prove
 (`!n A (s:num->bool) f y.
     FINITE s
     ==> iqbilin n A (\k. isum s (\i. f i k)) y =
         isum s (\i. iqbilin n A (f i) y)`,
  REPEAT GEN_TAC THEN SPEC_TAC (`s:num->bool`,`s:num->bool`) THEN
  MATCH_MP_TAC FINITE_INDUCT_STRONG THEN CONJ_TAC THENL
   [SIMP_TAC[ISUM_CLAUSES; iqbilin; INT_MUL_LZERO; INT_MUL_RZERO;
     ISUM_0];
    REPEAT STRIP_TAC THEN
    ASM_SIMP_TAC[ISUM_CLAUSES; IQBILIN_LADD] THEN REWRITE_TAC[ETA_AX]]);;

let IQBILIN_ISUM_R = prove
 (`!n A (s:num->bool) x f.
     FINITE s
     ==> iqbilin n A x (\k. isum s (\i. f i k)) =
         isum s (\i. iqbilin n A x (f i))`,
  REPEAT GEN_TAC THEN SPEC_TAC (`s:num->bool`,`s:num->bool`) THEN
  MATCH_MP_TAC FINITE_INDUCT_STRONG THEN CONJ_TAC THENL
   [SIMP_TAC[ISUM_CLAUSES; iqbilin; INT_MUL_LZERO; INT_MUL_RZERO;
     ISUM_0];
    REPEAT STRIP_TAC THEN
    ASM_SIMP_TAC[ISUM_CLAUSES; IQBILIN_RADD; ETA_AX]]);;

let IQEVAL_PULLBACK = prove
 (`!n d A V c.
     iqeval n A (iqcombine d c V) =
     iqeval d (iqgram n A V) c`,
  REPEAT GEN_TAC THEN REWRITE_TAC[iqeval] THEN
  SUBGOAL_THEN
   `iqcombine d c V = (\k. isum (qindex d) (\i. c i * V i k))`
  SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; iqcombine]; ALL_TAC] THEN
  MP_TAC(ISPECL
   [`n:num`; `A:num->num->int`; `qindex d:num->bool`;
    `\i:num. \k:num. c i * V i k`;
    `(\k:num. isum (qindex d) (\i. c i * V i k)):num->int`]
   IQBILIN_ISUM_L) THEN
  REWRITE_TAC[FINITE_QINDEX] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  CONV_TAC(RAND_CONV(REWRITE_CONV[iqbilin])) THEN
  MATCH_MP_TAC ISUM_EQ THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
  X_GEN_TAC `i:num` THEN DISCH_TAC THEN
  MP_TAC(ISPECL
   [`n:num`; `A:num->num->int`; `{j:num | j < d}`;
    `(\k:num. (c:num->int) (i:num) *
       (V:num->num->int) i k):num->int`;
    `(\j:num. \k:num. (c:num->int) j *
       (V:num->num->int) j k):num->num->int`]
   IQBILIN_ISUM_R) THEN
  REWRITE_TAC[FINITE_NUMSEG_LT] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC ISUM_EQ THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
  X_GEN_TAC `j:num` THEN DISCH_TAC THEN
  REWRITE_TAC[IQBILIN_LMUL; IQBILIN_RMUL; iqgram; ETA_AX] THEN
  CONV_TAC INT_RING);;

let IQEVAL_EQ_ON_INDEX = prove
 (`!d P R c.
     (!i j. i < d /\ j < d ==> P i j = R i j)
     ==> iqeval d P c = iqeval d R c`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[iqeval; iqbilin] THEN
  MATCH_MP_TAC ISUM_EQ THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
  X_GEN_TAC `i:num` THEN DISCH_TAC THEN
  MATCH_MP_TAC ISUM_EQ THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
  X_GEN_TAC `j:num` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPECL [`i:num`; `j:num`]) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN REFL_TAC);;

let IQ_REPRESENTS_OF_EMBEDS = prove
 (`!n d P A m.
     iq_embeds n d P A /\ iq_represents d P m
     ==> iq_represents n A m`,
  REPEAT GEN_TAC THEN REWRITE_TAC[iq_embeds; iq_represents] THEN
  DISCH_THEN(CONJUNCTS_THEN2
    (X_CHOOSE_TAC `V:num->num->int`) (X_CHOOSE_TAC `c:num->int`)) THEN
  EXISTS_TAC `iqcombine d c V` THEN
  REWRITE_TAC[IQEVAL_PULLBACK] THEN
  MATCH_MP_TAC EQ_TRANS THEN EXISTS_TAC `iqeval d P c` THEN
  CONJ_TAC THENL
   [CONV_TAC SYM_CONV THEN MATCH_MP_TAC IQEVAL_EQ_ON_INDEX THEN
    ASM_MESON_TAC[];
    ASM_REWRITE_TAC[]]);;

let IQ_UNIVERSAL_OF_EMBEDS = prove
 (`!n d P A.
     iq_embeds n d P A /\ iq_universal d P
     ==> iq_universal n A`,
  REPEAT GEN_TAC THEN REWRITE_TAC[iq_universal] THEN
  STRIP_TAC THEN X_GEN_TAC `m:int` THEN DISCH_TAC THEN
  MATCH_MP_TAC IQ_REPRESENTS_OF_EMBEDS THEN
  ASM_MESON_TAC[]);;

(* Fixed small symmetric matrices. Only entries in the indicated rank matter,
   but the definitions are zero outside that rank for convenient rewriting. *)

let iqsym = new_definition
 `iqsym (A:num->num->int) i j =
    if i <= j then A i j else A j i`;;

let iqmat2 = new_definition
 `iqmat2 (a:int) b c =
    iqsym (\i j.
      if i = 0 /\ j = 0 then a else
      if i = 0 /\ j = 1 then b else
      if i = 1 /\ j = 1 then c else &0)`;;

let iqmat3 = new_definition
 `iqmat3 (a:int) b c d e f =
    iqsym (\i j.
      if i = 0 /\ j = 0 then a else
      if i = 0 /\ j = 1 then b else
      if i = 0 /\ j = 2 then c else
      if i = 1 /\ j = 1 then d else
      if i = 1 /\ j = 2 then e else
      if i = 2 /\ j = 2 then f else &0)`;;

let iqmat4 = new_definition
 `iqmat4 (a:int) b c d e f g h k l =
    iqsym (\i j.
      if i = 0 /\ j = 0 then a else
      if i = 0 /\ j = 1 then b else
      if i = 0 /\ j = 2 then c else
      if i = 0 /\ j = 3 then d else
      if i = 1 /\ j = 1 then e else
      if i = 1 /\ j = 2 then f else
      if i = 1 /\ j = 3 then g else
      if i = 2 /\ j = 2 then h else
      if i = 2 /\ j = 3 then k else
      if i = 3 /\ j = 3 then l else &0)`;;

let IQBILIN_MAT2 = prove
 (`!a b c x y.
     iqbilin 2 (iqmat2 a b c) x y =
     a * x 0 * y 0 + b * x 0 * y 1 +
     b * x 1 * y 0 + c * x 1 * y 1`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[iqbilin; qindex; NUMSEG_LT; iqmat2; iqsym] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  CONV_TAC(ONCE_DEPTH_CONV EXPAND_ISUM_CONV) THEN
  CONV_TAC(ONCE_DEPTH_CONV EXPAND_ISUM_CONV) THEN
  CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_RING);;

let IQBILIN_MAT3 = prove
 (`!a b c d e f x y.
     iqbilin 3 (iqmat3 a b c d e f) x y =
     a * x 0 * y 0 + b * x 0 * y 1 + c * x 0 * y 2 +
     b * x 1 * y 0 + d * x 1 * y 1 + e * x 1 * y 2 +
     c * x 2 * y 0 + e * x 2 * y 1 + f * x 2 * y 2`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[iqbilin; qindex; NUMSEG_LT; iqmat3; iqsym] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  CONV_TAC(ONCE_DEPTH_CONV EXPAND_ISUM_CONV) THEN
  CONV_TAC(ONCE_DEPTH_CONV EXPAND_ISUM_CONV) THEN
  CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_RING);;

let IQEVAL_MAT3 = prove
 (`!a b c d e f x.
     iqeval 3 (iqmat3 a b c d e f) x =
     a * x 0 pow 2 + &2 * b * x 0 * x 1 + &2 * c * x 0 * x 2 +
     d * x 1 pow 2 + &2 * e * x 1 * x 2 + f * x 2 pow 2`,
  REPEAT GEN_TAC THEN REWRITE_TAC[iqeval; IQBILIN_MAT3] THEN
  CONV_TAC INT_RING);;

(* ------------------------------------------------------------------------- *)
(* Pullback by an integer matrix and congruence transport.                   *)
(* ------------------------------------------------------------------------- *)

let IQBILIN_EQ_ON_INDEX = prove
 (`!d P R x y.
     (!i j. i < d /\ j < d ==> P i j = R i j)
     ==> iqbilin d P x y = iqbilin d R x y`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[iqbilin] THEN
  MATCH_MP_TAC ISUM_EQ THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
  X_GEN_TAC `i:num` THEN DISCH_TAC THEN
  MATCH_MP_TAC ISUM_EQ THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
  X_GEN_TAC `j:num` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPECL [`i:num`; `j:num`]) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN REFL_TAC);;

let IQBILIN_PULLBACK = prove
 (`!n d A V c e.
     iqbilin n A (iqcombine d c V) (iqcombine d e V) =
     iqbilin d (iqgram n A V) c e`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
   `iqcombine d c V = (\k. isum (qindex d) (\i. c i * V i k))`
  SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; iqcombine]; ALL_TAC] THEN
  SUBGOAL_THEN
   `iqcombine d e V = (\k. isum (qindex d) (\i. e i * V i k))`
  SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; iqcombine]; ALL_TAC] THEN
  MP_TAC(ISPECL
   [`n:num`; `A:num->num->int`; `qindex d:num->bool`;
    `\i:num. \k:num. c i * V i k`;
    `(\k:num. isum (qindex d) (\i. e i * V i k)):num->int`]
   IQBILIN_ISUM_L) THEN
  REWRITE_TAC[FINITE_QINDEX] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  CONV_TAC(RAND_CONV(REWRITE_CONV[iqbilin])) THEN
  MATCH_MP_TAC ISUM_EQ THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
  X_GEN_TAC `i:num` THEN DISCH_TAC THEN
  MP_TAC(ISPECL
   [`n:num`; `A:num->num->int`; `{j:num | j < d}`;
    `(\k:num. (c:num->int) i * (V:num->num->int) i k):num->int`;
    `(\j:num. \k:num. (e:num->int) j *
       (V:num->num->int) j k):num->num->int`]
   IQBILIN_ISUM_R) THEN
  REWRITE_TAC[FINITE_NUMSEG_LT] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC ISUM_EQ THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
  X_GEN_TAC `j:num` THEN DISCH_TAC THEN
  REWRITE_TAC[IQBILIN_LMUL; IQBILIN_RMUL; iqgram; ETA_AX] THEN
  CONV_TAC INT_RING);;

let IQ_EMBEDS_EQ = prove
 (`!n d P R A.
     iq_embeds n d P A /\
     (!i j. i < d /\ j < d ==> P i j = R i j)
     ==> iq_embeds n d R A`,
  REPEAT GEN_TAC THEN REWRITE_TAC[iq_embeds] THEN MESON_TAC[]);;

let IQ_EMBEDS_CONGRUENCE = prove
 (`!n d e P A U.
     iq_embeds n d P A
     ==> iq_embeds n e (iqgram d P U) A`,
  REPEAT GEN_TAC THEN REWRITE_TAC[iq_embeds] THEN
  DISCH_THEN(X_CHOOSE_TAC `V:num->num->int`) THEN
  EXISTS_TAC
   `\i:num. iqcombine d ((U:num->num->int) i) V` THEN
  REPEAT STRIP_TAC THEN REWRITE_TAC[iqgram; IQBILIN_PULLBACK] THEN
  MATCH_MP_TAC IQBILIN_EQ_ON_INDEX THEN ASM_MESON_TAC[]);;

let iqappend = new_definition
 `iqappend d (V:num->num->int) (x:num->int) i k =
    if i < d then V i k else x k`;;

let IQAPPEND_LT = prove
 (`!d V x i.
     i < d ==> iqappend d (V:num->num->int) (x:num->int) i = V i`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[FUN_EQ_THM; iqappend] THEN
  ASM_REWRITE_TAC[]);;

let IQAPPEND_REFL = prove
 (`!d V x. iqappend d (V:num->num->int) (x:num->int) d = x`,
  REPEAT GEN_TAC THEN REWRITE_TAC[FUN_EQ_THM; iqappend; LT_REFL]);;

let IQ_ESCALATION_STEP = prove
 (`!n d P A t.
     iq_symmetric n A /\ iq_positive n A /\
     iq_embeds n d P A /\ iq_represents n A t
     ==> ?V.
       (!i j. i < d /\ j < d ==> iqgram n A V i j = P i j) /\
       iqgram n A V d d = t /\
       (!i. i < d ==> iqgram n A V i d pow 2 <= P i i * t) /\
       iq_embeds n (d + 1) (iqgram n A V) A`,
  REPEAT GEN_TAC THEN REWRITE_TAC[iq_embeds; iq_represents] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2
      (X_CHOOSE_TAC `V:num->num->int`)
      (X_CHOOSE_TAC `x:num->int`)))) THEN
  EXISTS_TAC `iqappend d V x` THEN
  CONJ_TAC THENL
   [REPEAT STRIP_TAC THEN REWRITE_TAC[iqgram] THEN
    SUBGOAL_THEN `iqappend d V x i = (V:num->num->int) i`
    SUBST1_TAC THENL
     [MATCH_MP_TAC IQAPPEND_LT THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `iqappend d V x j = (V:num->num->int) j`
    SUBST1_TAC THENL
     [MATCH_MP_TAC IQAPPEND_LT THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    FIRST_X_ASSUM(MP_TAC o SPECL [`i:num`; `j:num`]) THEN
    ASM_REWRITE_TAC[iqgram];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [REWRITE_TAC[iqgram] THEN
    SUBGOAL_THEN `iqappend d V x d = (x:num->int)` SUBST1_TAC THENL
     [REWRITE_TAC[IQAPPEND_REFL];
      ASM_MESON_TAC[iqeval]];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [X_GEN_TAC `i:num` THEN DISCH_TAC THEN
    REWRITE_TAC[iqgram] THEN
    SUBGOAL_THEN `iqappend d V x i = (V:num->num->int) i`
    SUBST1_TAC THENL
     [MATCH_MP_TAC IQAPPEND_LT THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `iqappend d V x d = (x:num->int)` SUBST1_TAC THENL
     [REWRITE_TAC[IQAPPEND_REFL];
      ALL_TAC] THEN
    SUBGOAL_THEN `iqeval n A ((V:num->num->int) i) = P i i`
    ASSUME_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o SPECL [`i:num`; `i:num`]) THEN
      ASM_REWRITE_TAC[iqgram; iqeval];
      ALL_TAC] THEN
    MP_TAC(SPECL
     [`n:num`; `A:num->num->int`; `(V:num->num->int) i`;
      `x:num->int`] IQ_POSITIVE_BILIN_SQ_LE) THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[iq_embeds] THEN
    EXISTS_TAC `iqappend d V x` THEN SIMP_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Square residues modulo 8, 9 and 16.                                      *)
(* ------------------------------------------------------------------------- *)

(* The square-residue-mod-8 facts are REM_8_CASES and SQ_MOD_8 from          *)
(* three_squares.ml (loaded above).                                          *)

let IQ_REM_9_CASES = prove
 (`!x:int.
     x rem &9 = &0 \/ x rem &9 = &1 \/ x rem &9 = &2 \/
     x rem &9 = &3 \/ x rem &9 = &4 \/ x rem &9 = &5 \/
     x rem &9 = &6 \/ x rem &9 = &7 \/ x rem &9 = &8`,
  GEN_TAC THEN MP_TAC(SPECL [`x:int`; `&9:int`] INT_DIVISION) THEN
  INT_ARITH_TAC);;

let IQ_SQ_MOD_9 = prove
 (`!x:int.
     x pow 2 rem &9 = &0 \/
     x pow 2 rem &9 = &1 \/
     x pow 2 rem &9 = &4 \/
     x pow 2 rem &9 = &7`,
  GEN_TAC THEN ONCE_REWRITE_TAC[GSYM INT_POW_REM] THEN
  MP_TAC(SPEC `x:int` IQ_REM_9_CASES) THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN CONV_TAC INT_REDUCE_CONV);;

let IQ_SQUARE_REM_16_OF_MOD8 = prove
 (`!x q r:int.
     x = &8 * q + r
     ==> x pow 2 rem &16 = r pow 2 rem &16`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[INT_REM_EQ; int_congruent] THEN
  EXISTS_TAC `&4 * q pow 2 + q * r` THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING);;

let IQ_SQ_MOD_16 = prove
 (`!x:int.
     x pow 2 rem &16 = &0 \/
     x pow 2 rem &16 = &1 \/
     x pow 2 rem &16 = &4 \/
     x pow 2 rem &16 = &9`,
  GEN_TAC THEN
  SUBGOAL_THEN
   `x pow 2 rem &16 = (x rem &8) pow 2 rem &16`
  SUBST1_TAC THENL
   [MATCH_MP_TAC IQ_SQUARE_REM_16_OF_MOD8 THEN
    EXISTS_TAC `x div &8` THEN
    MP_TAC(SPECL [`x:int`; `&8:int`] INT_DIVISION) THEN
    ANTS_TAC THENL [INT_ARITH_TAC; INT_ARITH_TAC];
    MP_TAC(SPEC `x:int` REM_8_CASES) THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[] THEN CONV_TAC INT_REDUCE_CONV]);;

(* ------------------------------------------------------------------------- *)
(* The three obstructions.                                                   *)
(* ------------------------------------------------------------------------- *)

let IQ_122_MOD8_CORE = prove
 (`!a b c:int.
     (a = &0 \/ a = &1 \/ a = &4) /\
     (b = &0 \/ b = &1 \/ b = &4) /\
     (c = &0 \/ c = &1 \/ c = &4) /\
     (a + &2 * b + &2 * c) rem &8 = &7
     ==> F`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  POP_ASSUM MP_TAC THEN ASM_REWRITE_TAC[] THEN
  CONV_TAC INT_REDUCE_CONV);;

let INT_122_NOT_7 = prove
 (`!x y z:int.
     ~(x pow 2 + &2 * y pow 2 + &2 * z pow 2 = &7)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC(SPECL
   [`x pow 2 rem &8`; `y pow 2 rem &8`; `z pow 2 rem &8`]
   IQ_122_MOD8_CORE) THEN
  REWRITE_TAC[SQ_MOD_8] THEN
  SUBGOAL_THEN
   `(x pow 2 rem &8 + &2 * (y pow 2 rem &8) +
      &2 * (z pow 2 rem &8)) rem &8 =
    (x pow 2 + &2 * y pow 2 + &2 * z pow 2) rem &8`
  SUBST1_TAC THENL
   [CONV_TAC INT_REM_DOWN_CONV THEN REFL_TAC;
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_REDUCE_CONV]);;

let IQ_113_MOD9_CORE = prove
 (`!a b c:int.
     (a = &0 \/ a = &1 \/ a = &4 \/ a = &7) /\
     (b = &0 \/ b = &1 \/ b = &4 \/ b = &7) /\
     (c = &0 \/ c = &1 \/ c = &4 \/ c = &7) /\
     (a + b + &3 * c) rem &9 = &6
     ==> F`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  POP_ASSUM MP_TAC THEN ASM_REWRITE_TAC[] THEN
  CONV_TAC INT_REDUCE_CONV);;

let INT_113_NOT_6 = prove
 (`!x y z:int.
     ~(x pow 2 + y pow 2 + &3 * z pow 2 = &6)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC(SPECL
   [`x pow 2 rem &9`; `y pow 2 rem &9`; `z pow 2 rem &9`]
   IQ_113_MOD9_CORE) THEN
  REWRITE_TAC[IQ_SQ_MOD_9] THEN
  SUBGOAL_THEN
   `(x pow 2 rem &9 + y pow 2 rem &9 +
      &3 * (z pow 2 rem &9)) rem &9 =
    (x pow 2 + y pow 2 + &3 * z pow 2) rem &9`
  SUBST1_TAC THENL
   [CONV_TAC INT_REM_DOWN_CONV THEN REFL_TAC;
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_REDUCE_CONV]);;

let IQ_112_MOD16_CORE = prove
 (`!a b c:int.
     (a = &0 \/ a = &1 \/ a = &4 \/ a = &9) /\
     (b = &0 \/ b = &1 \/ b = &4 \/ b = &9) /\
     (c = &0 \/ c = &1 \/ c = &4 \/ c = &9) /\
     (a + b + &2 * c) rem &16 = &14
     ==> F`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  POP_ASSUM MP_TAC THEN ASM_REWRITE_TAC[] THEN
  CONV_TAC INT_REDUCE_CONV);;

let INT_112_NOT_14 = prove
 (`!x y z:int.
     ~(x pow 2 + y pow 2 + &2 * z pow 2 = &14)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC(SPECL
   [`x pow 2 rem &16`; `y pow 2 rem &16`; `z pow 2 rem &16`]
   IQ_112_MOD16_CORE) THEN
  REWRITE_TAC[IQ_SQ_MOD_16] THEN
  SUBGOAL_THEN
   `(x pow 2 rem &16 + y pow 2 rem &16 +
      &2 * (z pow 2 rem &16)) rem &16 =
    (x pow 2 + y pow 2 + &2 * z pow 2) rem &16`
  SUBST1_TAC THENL
   [CONV_TAC INT_REM_DOWN_CONV THEN REFL_TAC;
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_REDUCE_CONV]);;

(* Row matrices used for integral changes of basis. *)

let iqrows2 = new_definition
 `iqrows2 (a:int) b c d i j =
    if i = 0 then (if j = 0 then a else if j = 1 then b else &0)
    else if i = 1 then (if j = 0 then c else if j = 1 then d else &0)
    else &0`;;

let iqrows3 = new_definition
 `iqrows3 (a:int) b c d e f g h k i j =
    if i = 0 then
      (if j = 0 then a else if j = 1 then b else if j = 2 then c else &0)
    else if i = 1 then
      (if j = 0 then d else if j = 1 then e else if j = 2 then f else &0)
    else if i = 2 then
      (if j = 0 then g else if j = 1 then h else if j = 2 then k else &0)
    else &0`;;

let iqclear2 = new_definition
 `iqclear2 a = iqrows2 (&1) (&0) (--a) (&1)`;;

let iqclear11 = new_definition
 `iqclear11 a b =
    iqrows3 (&1) (&0) (&0) (&0) (&1) (&0) (--a) (--b) (&1)`;;

let iqclear12 = new_definition
 `iqclear12 a q =
    iqrows3 (&1) (&0) (&0) (&0) (&1) (&0) (--a) (--q) (&1)`;;

(* ------------------------------------------------------------------------- *)
(* Small integral square bounds used in the finite branches.                 *)
(* ------------------------------------------------------------------------- *)

let INT_SQ_LE_2_CASES = prove
 (`!a:int. a pow 2 <= &2 ==> a = -- &1 \/ a = &0 \/ a = &1`,
  GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `abs a < &2` ASSUME_TAC THENL
   [MP_TAC(SPECL [`a:int`; `&2:int`] INT_LT_SQUARE_ABS) THEN
    REWRITE_TAC[INT_ABS_NUM] THEN
    CONV_TAC NUM_REDUCE_CONV THEN ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `abs a <= &1` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`a:int`; `&1:int`] INT_ABS_BOUNDS) THEN
  ASM_REWRITE_TAC[] THEN INT_ARITH_TAC);;

let INT_SQ_LE_3_CASES = prove
 (`!a:int. a pow 2 <= &3 ==> a = -- &1 \/ a = &0 \/ a = &1`,
  GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `abs a < &2` ASSUME_TAC THENL
   [MP_TAC(SPECL [`a:int`; `&2:int`] INT_LT_SQUARE_ABS) THEN
    REWRITE_TAC[INT_ABS_NUM] THEN
    CONV_TAC NUM_REDUCE_CONV THEN ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `abs a <= &1` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`a:int`; `&1:int`] INT_ABS_BOUNDS) THEN
  ASM_REWRITE_TAC[] THEN INT_ARITH_TAC);;

let INT_SQ_LE_5_CASES = prove
 (`!a:int.
     a pow 2 <= &5
     ==> a = -- &2 \/ a = -- &1 \/ a = &0 \/ a = &1 \/ a = &2`,
  GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `abs a < &3` ASSUME_TAC THENL
   [MP_TAC(SPECL [`a:int`; `&3:int`] INT_LT_SQUARE_ABS) THEN
    REWRITE_TAC[INT_ABS_NUM] THEN
    CONV_TAC NUM_REDUCE_CONV THEN ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `abs a <= &2` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`a:int`; `&2:int`] INT_ABS_BOUNDS) THEN
  ASM_REWRITE_TAC[] THEN INT_ARITH_TAC);;

let INT_SQ_LE_10_CASES = prove
 (`!a:int.
     a pow 2 <= &10
     ==> a = -- &3 \/ a = -- &2 \/ a = -- &1 \/ a = &0 \/
         a = &1 \/ a = &2 \/ a = &3`,
  GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `abs a < &4` ASSUME_TAC THENL
   [MP_TAC(SPECL [`a:int`; `&4:int`] INT_LT_SQUARE_ABS) THEN
    REWRITE_TAC[INT_ABS_NUM] THEN
    CONV_TAC NUM_REDUCE_CONV THEN ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `abs a <= &3` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`a:int`; `&3:int`] INT_ABS_BOUNDS) THEN
  ASM_REWRITE_TAC[] THEN INT_ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* Positivity and symbolic clearing under an embedded Gram matrix.           *)
(* ------------------------------------------------------------------------- *)

let IQ_EMBEDDED_NONNEG = prove
 (`!n d P A.
     iq_positive n A /\ iq_embeds n d P A
     ==> !c. &0 <= iqeval d P c`,
  REPEAT GEN_TAC THEN REWRITE_TAC[iq_embeds] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_TAC `V:num->num->int`)) THEN
  X_GEN_TAC `c:num->int` THEN
  SUBGOAL_THEN
   `iqeval d P c = iqeval d (iqgram n A V) c`
  SUBST1_TAC THENL
   [CONV_TAC SYM_CONV THEN MATCH_MP_TAC IQEVAL_EQ_ON_INDEX THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[GSYM IQEVAL_PULLBACK] THEN
    MP_TAC(SPECL [`n:num`; `A:num->num->int`]
      IQ_POSITIVE_IMP_NONNEG) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th ->
      MATCH_ACCEPT_TAC(SPEC `iqcombine d c V` th))]);;

let IQ_EMBEDS_CLEAR_UNIT2 = prove
 (`!n A a t.
     iq_embeds n 2 (iqmat2 (&1) a t) A
     ==> iq_embeds n 2 (iqmat2 (&1) (&0) (t - a pow 2)) A`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `2`; `iqgram 2 (iqmat2 (&1) a t) (iqclear2 a)`;
    `iqmat2 (&1) (&0) (t - a pow 2)`; `A:num->num->int`]
   IQ_EMBEDS_EQ) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC IQ_EMBEDS_CONGRUENCE THEN ASM_REWRITE_TAC[];
    REPEAT STRIP_TAC THEN
    (SUBGOAL_THEN `i = 0 \/ i = 1` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    (SUBGOAL_THEN `j = 0 \/ j = 1` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    ASM_REWRITE_TAC[iqgram; IQBILIN_MAT2; iqclear2; iqrows2;
      iqmat2; iqsym] THEN
    CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_RING]);;

let IQ_EMBEDS_CLEAR_11 = prove
 (`!n A a b t.
     iq_embeds n 3 (iqmat3 (&1) (&0) a (&1) b t) A
     ==> iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&1) (&0)
            (t - a pow 2 - b pow 2)) A`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `3`;
    `iqgram 3 (iqmat3 (&1) (&0) a (&1) b t) (iqclear11 a b)`;
    `iqmat3 (&1) (&0) (&0) (&1) (&0)
      (t - a pow 2 - b pow 2)`;
    `A:num->num->int`] IQ_EMBEDS_EQ) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC IQ_EMBEDS_CONGRUENCE THEN ASM_REWRITE_TAC[];
    REPEAT STRIP_TAC THEN
    (SUBGOAL_THEN `i = 0 \/ i = 1 \/ i = 2` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(DISJ_CASES_THEN2 SUBST_ALL_TAC
      (DISJ_CASES_THEN SUBST_ALL_TAC)) THEN
    (SUBGOAL_THEN `j = 0 \/ j = 1 \/ j = 2` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(DISJ_CASES_THEN2 SUBST_ALL_TAC
      (DISJ_CASES_THEN SUBST_ALL_TAC)) THEN
    ASM_REWRITE_TAC[iqgram; IQBILIN_MAT3; iqclear11; iqrows3;
      iqmat3; iqsym] THEN
    CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_RING]);;

let IQ_EMBEDS_CLEAR_12 = prove
 (`!n A a q r t.
     iq_embeds n 3 (iqmat3 (&1) (&0) a (&2) (&2 * q + r) t) A
     ==> iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&2) r
            (t - a pow 2 - &2 * q pow 2 - &2 * q * r)) A`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `3`;
    `iqgram 3
      (iqmat3 (&1) (&0) a (&2) (&2 * q + r) t) (iqclear12 a q)`;
    `iqmat3 (&1) (&0) (&0) (&2) r
      (t - a pow 2 - &2 * q pow 2 - &2 * q * r)`;
    `A:num->num->int`] IQ_EMBEDS_EQ) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC IQ_EMBEDS_CONGRUENCE THEN ASM_REWRITE_TAC[];
    REPEAT STRIP_TAC THEN
    (SUBGOAL_THEN `i = 0 \/ i = 1 \/ i = 2` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(DISJ_CASES_THEN2 SUBST_ALL_TAC
      (DISJ_CASES_THEN SUBST_ALL_TAC)) THEN
    (SUBGOAL_THEN `j = 0 \/ j = 1 \/ j = 2` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(DISJ_CASES_THEN2 SUBST_ALL_TAC
      (DISJ_CASES_THEN SUBST_ALL_TAC)) THEN
    ASM_REWRITE_TAC[iqgram; IQBILIN_MAT3; iqclear12; iqrows3;
      iqmat3; iqsym] THEN
    CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_RING]);;

(* ------------------------------------------------------------------------- *)
(* Rank one to the two binary nodes.                                         *)
(* ------------------------------------------------------------------------- *)

let IQ_EMBEDS_ONE = prove
 (`!n A.
     iq_represents n A (&1)
     ==> iq_embeds n 1 (iqmat2 (&1) (&0) (&0)) A`,
  REPEAT GEN_TAC THEN REWRITE_TAC[iq_represents; iq_embeds] THEN
  DISCH_THEN(X_CHOOSE_TAC `x:num->int`) THEN
  EXISTS_TAC `\i:num. x:num->int` THEN
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `i = 0 /\ j = 0` STRIP_ASSUME_TAC THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[iqgram; GSYM iqeval; iqmat2; iqsym] THEN
  CONV_TAC NUM_REDUCE_CONV);;

let IQGRAM_SWAP = prove
 (`!n A V i j.
     iq_symmetric n A
     ==> iqgram n A V i j = iqgram n A V j i`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[iqgram] THEN
  MATCH_MP_TAC IQBILIN_SYM THEN ASM_REWRITE_TAC[]);;

let IQ_EMBEDS_BINARY = prove
 (`!n A.
     iq_symmetric n A /\ iq_positive n A /\
     iq_represents n A (&1) /\ iq_represents n A (&2)
     ==> iq_embeds n 2 (iqmat2 (&1) (&0) (&1)) A \/
         iq_embeds n 2 (iqmat2 (&1) (&0) (&2)) A`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `iq_embeds n 1 (iqmat2 (&1) (&0) (&0)) A`
  ASSUME_TAC THENL
   [MATCH_MP_TAC IQ_EMBEDS_ONE THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL
   [`n:num`; `1`; `iqmat2 (&1) (&0) (&0)`;
    `A:num->num->int`; `&2:int`] IQ_ESCALATION_STEP) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `V:num->num->int` STRIP_ASSUME_TAC) THEN
  ABBREV_TAC `a = iqgram n A V 0 1` THEN
  SUBGOAL_THEN `iqgram n A V 0 0 = &1` ASSUME_TAC THENL
   [MP_TAC(SPECL [`0`; `0`] (ASSUME
     `!i j. i < 1 /\ j < 1
            ==> iqgram n A V i j = iqmat2 (&1) (&0) (&0) i j`)) THEN
    REWRITE_TAC[iqmat2; iqsym] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN `iqgram n A V 1 0 = a` ASSUME_TAC THENL
   [EXPAND_TAC "a" THEN
    MATCH_MP_TAC(SPECL
     [`n:num`; `A:num->num->int`; `V:num->num->int`; `1`; `0`]
     IQGRAM_SWAP) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `iq_embeds n 2 (iqmat2 (&1) a (&2)) A`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`n:num`; `2`; `iqgram n A V`;
      `iqmat2 (&1) a (&2)`; `A:num->num->int`] IQ_EMBEDS_EQ) THEN
    CONJ_TAC THENL [ASM_MESON_TAC[ARITH_RULE `1 + 1 = 2`]; ALL_TAC] THEN
    REPEAT STRIP_TAC THEN
    (SUBGOAL_THEN `i = 0 \/ i = 1` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    (SUBGOAL_THEN `j = 0 \/ j = 1` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    ASM_REWRITE_TAC[iqmat2; iqsym] THEN
    CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN `a pow 2 <= &2` ASSUME_TAC THENL
   [MP_TAC(SPEC `0` (ASSUME
     `!i. i < 1
          ==> iqgram n A V i 1 pow 2 <=
              iqmat2 (&1) (&0) (&0) i i * &2`)) THEN
    REWRITE_TAC[iqmat2; iqsym] THEN
    CONV_TAC NUM_REDUCE_CONV THEN DISCH_TAC THEN
    ONCE_REWRITE_TAC[GSYM(ASSUME `iqgram n A V 0 1 = a`)] THEN
    ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `iq_embeds n 2 (iqmat2 (&1) (&0) (&2 - a pow 2)) A`
  ASSUME_TAC THENL
   [MATCH_MP_TAC IQ_EMBEDS_CLEAR_UNIT2 THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP INT_SQ_LE_2_CASES (ASSUME `a pow 2 <= &2`)) THEN
  DISCH_THEN(DISJ_CASES_THEN2
    (fun th -> SUBST_ALL_TAC th THEN DISJ1_TAC)
    (DISJ_CASES_THEN2
      (fun th -> SUBST_ALL_TAC th THEN DISJ2_TAC)
      (fun th -> SUBST_ALL_TAC th THEN DISJ1_TAC))) THEN
  FIRST_X_ASSUM(MP_TAC) THEN
  CONV_TAC INT_REDUCE_CONV);;

(* ------------------------------------------------------------------------- *)
(* Rank two to rank three.                                                   *)
(* ------------------------------------------------------------------------- *)

let IQ_ESCALATE_MAT2 = prove
 (`!n A u v w t.
     iq_symmetric n A /\ iq_positive n A /\
     iq_embeds n 2 (iqmat2 u v w) A /\ iq_represents n A t
     ==> ?a b.
          iq_embeds n 3 (iqmat3 u v a w b t) A /\
          a pow 2 <= u * t /\ b pow 2 <= w * t`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL
   [`n:num`; `2`; `iqmat2 u v w`;
    `A:num->num->int`; `t:int`] IQ_ESCALATION_STEP) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `V:num->num->int` STRIP_ASSUME_TAC) THEN
  ABBREV_TAC `a = iqgram n A V 0 2` THEN
  ABBREV_TAC `b = iqgram n A V 1 2` THEN
  SUBGOAL_THEN `iqgram n A V 0 0 = u` ASSUME_TAC THENL
   [MP_TAC(SPECL [`0`; `0`] (ASSUME
     `!i j. i < 2 /\ j < 2
            ==> iqgram n A V i j = iqmat2 u v w i j`)) THEN
    REWRITE_TAC[iqmat2; iqsym] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN `iqgram n A V 0 1 = v` ASSUME_TAC THENL
   [MP_TAC(SPECL [`0`; `1`] (ASSUME
     `!i j. i < 2 /\ j < 2
            ==> iqgram n A V i j = iqmat2 u v w i j`)) THEN
    REWRITE_TAC[iqmat2; iqsym] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN `iqgram n A V 1 0 = v` ASSUME_TAC THENL
   [MP_TAC(SPECL [`1`; `0`] (ASSUME
     `!i j. i < 2 /\ j < 2
            ==> iqgram n A V i j = iqmat2 u v w i j`)) THEN
    REWRITE_TAC[iqmat2; iqsym] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN `iqgram n A V 1 1 = w` ASSUME_TAC THENL
   [MP_TAC(SPECL [`1`; `1`] (ASSUME
     `!i j. i < 2 /\ j < 2
            ==> iqgram n A V i j = iqmat2 u v w i j`)) THEN
    REWRITE_TAC[iqmat2; iqsym] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN `iqgram n A V 2 0 = a` ASSUME_TAC THENL
   [EXPAND_TAC "a" THEN
    MATCH_MP_TAC(SPECL
     [`n:num`; `A:num->num->int`; `V:num->num->int`; `2`; `0`]
     IQGRAM_SWAP) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `iqgram n A V 2 1 = b` ASSUME_TAC THENL
   [EXPAND_TAC "b" THEN
    MATCH_MP_TAC(SPECL
     [`n:num`; `A:num->num->int`; `V:num->num->int`; `2`; `1`]
     IQGRAM_SWAP) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`a:int`; `b:int`] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`n:num`; `3`; `iqgram n A V`;
      `iqmat3 u v a w b t`; `A:num->num->int`] IQ_EMBEDS_EQ) THEN
    CONJ_TAC THENL
     [ASM_MESON_TAC[ARITH_RULE `2 + 1 = 3`];
      ALL_TAC] THEN
    REPEAT STRIP_TAC THEN
    (SUBGOAL_THEN `i = 0 \/ i = 1 \/ i = 2` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(DISJ_CASES_THEN2 SUBST_ALL_TAC
      (DISJ_CASES_THEN SUBST_ALL_TAC)) THEN
    (SUBGOAL_THEN `j = 0 \/ j = 1 \/ j = 2` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(DISJ_CASES_THEN2 SUBST_ALL_TAC
      (DISJ_CASES_THEN SUBST_ALL_TAC)) THEN
    ASM_REWRITE_TAC[iqmat3; iqsym] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [MP_TAC(SPEC `0` (ASSUME
     `!i. i < 2
          ==> iqgram n A V i 2 pow 2 <= iqmat2 u v w i i * t`)) THEN
    REWRITE_TAC[iqmat2; iqsym] THEN CONV_TAC NUM_REDUCE_CONV THEN
    ONCE_REWRITE_TAC[GSYM(ASSUME `iqgram n A V 0 2 = a`)] THEN
    MESON_TAC[];
    MP_TAC(SPEC `1` (ASSUME
     `!i. i < 2
          ==> iqgram n A V i 2 pow 2 <= iqmat2 u v w i i * t`)) THEN
    REWRITE_TAC[iqmat2; iqsym] THEN CONV_TAC NUM_REDUCE_CONV THEN
    ONCE_REWRITE_TAC[GSYM(ASSUME `iqgram n A V 1 2 = b`)] THEN
    MESON_TAC[]]);;

let IQ_CORNER_11_CASES = prove
 (`!a b:int.
     a pow 2 <= &3 /\ b pow 2 <= &3
     ==> &3 - a pow 2 - b pow 2 = &1 \/
         &3 - a pow 2 - b pow 2 = &2 \/
         &3 - a pow 2 - b pow 2 = &3`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP INT_SQ_LE_3_CASES (ASSUME `a pow 2 <= &3`)) THEN
  DISCH_THEN(DISJ_CASES_THEN2 SUBST_ALL_TAC
    (DISJ_CASES_THEN SUBST_ALL_TAC)) THEN
  MP_TAC(MATCH_MP INT_SQ_LE_3_CASES (ASSUME `b pow 2 <= &3`)) THEN
  DISCH_THEN(DISJ_CASES_THEN2 SUBST_ALL_TAC
    (DISJ_CASES_THEN SUBST_ALL_TAC)) THEN
  CONV_TAC INT_REDUCE_CONV);;

let IQ_EMBEDS_TERNARY_11 = prove
 (`!n A.
     iq_symmetric n A /\ iq_positive n A /\
     iq_embeds n 2 (iqmat2 (&1) (&0) (&1)) A /\
     iq_represents n A (&3)
     ==> iq_embeds n 3 (iqmat3 (&1) (&0) (&0) (&1) (&0) (&1)) A \/
         iq_embeds n 3 (iqmat3 (&1) (&0) (&0) (&1) (&0) (&2)) A \/
         iq_embeds n 3 (iqmat3 (&1) (&0) (&0) (&1) (&0) (&3)) A`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL
   [`n:num`; `A:num->num->int`;
    `&1:int`; `&0:int`; `&1:int`; `&3:int`] IQ_ESCALATE_MAT2) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:int`
    (X_CHOOSE_THEN `b:int` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN
   `iq_embeds n 3
      (iqmat3 (&1) (&0) (&0) (&1) (&0)
        (&3 - a pow 2 - b pow 2)) A`
  ASSUME_TAC THENL
   [MATCH_MP_TAC IQ_EMBEDS_CLEAR_11 THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `a pow 2 <= &3 /\ b pow 2 <= &3` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(MATCH_MP (SPECL [`a:int`; `b:int`] IQ_CORNER_11_CASES)
    (ASSUME `a pow 2 <= &3 /\ b pow 2 <= &3`)) THEN
  DISCH_THEN(DISJ_CASES_THEN2
   (fun th ->
      DISJ1_TAC THEN
      MATCH_ACCEPT_TAC(REWRITE_RULE[th] (ASSUME
       `iq_embeds n 3
         (iqmat3 (&1) (&0) (&0) (&1) (&0)
           (&3 - a pow 2 - b pow 2)) A`)))
   (DISJ_CASES_THEN2
    (fun th ->
       DISJ2_TAC THEN DISJ1_TAC THEN
       MATCH_ACCEPT_TAC(REWRITE_RULE[th] (ASSUME
        `iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&1) (&0)
            (&3 - a pow 2 - b pow 2)) A`)))
    (fun th ->
       DISJ2_TAC THEN DISJ2_TAC THEN
       MATCH_ACCEPT_TAC(REWRITE_RULE[th] (ASSUME
        `iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&1) (&0)
            (&3 - a pow 2 - b pow 2)) A`))))));;

let INT_DIV2_DECOMP = prove
 (`!b:int.
     b = &2 * (b div &2) + b rem &2 /\
     (b rem &2 = &0 \/ b rem &2 = &1)`,
  GEN_TAC THEN
  MP_TAC(SPECL [`b:int`; `&2:int`] INT_DIVISION) THEN
  CONV_TAC NUM_REDUCE_CONV THEN INT_ARITH_TAC);;

let IQ_12_PARAMETERS = prove
 (`!a b:int.
     a pow 2 <= &5 /\ b pow 2 <= &10
     ==> ?q r k.
          b = &2 * q + r /\
          k = &5 - a pow 2 - &2 * q pow 2 - &2 * q * r /\
          ((r = &0 /\
            (k = -- &1 \/ k = &1 \/ k = &2 \/ k = &3 \/
             k = &4 \/ k = &5)) \/
           (r = &1 /\
            (k = -- &3 \/ k = &0 \/ k = &1 \/ k = &4 \/ k = &5)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MAP_EVERY EXISTS_TAC
   [`b div &2:int`; `b rem &2:int`;
    `&5 - a pow 2 - &2 * (b div &2) pow 2 -
     &2 * (b div &2) * (b rem &2):int`] THEN
  CONJ_TAC THENL
   [MP_TAC(SPEC `b:int` INT_DIV2_DECOMP) THEN MESON_TAC[];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [REFL_TAC;
    ALL_TAC] THEN
  MP_TAC(MATCH_MP INT_SQ_LE_5_CASES (ASSUME `a pow 2 <= &5`)) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  MP_TAC(MATCH_MP INT_SQ_LE_10_CASES (ASSUME `b pow 2 <= &10`)) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  CONV_TAC INT_REDUCE_CONV);;

let iqswap12 = new_definition
 `iqswap12 =
    iqrows3 (&1) (&0) (&0) (&0) (&0) (&1) (&0) (&1) (&0)`;;

let iqcross1 = new_definition
 `iqcross1 =
    iqrows3 (&1) (&0) (&0) (&0) (&0) (&1) (&0) (&1) (-- &1)`;;

let IQ_EMBEDS_121_TO_112 = prove
 (`!n A.
     iq_embeds n 3 (iqmat3 (&1) (&0) (&0) (&2) (&0) (&1)) A
     ==> iq_embeds n 3 (iqmat3 (&1) (&0) (&0) (&1) (&0) (&2)) A`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `3`;
    `iqgram 3 (iqmat3 (&1) (&0) (&0) (&2) (&0) (&1)) iqswap12`;
    `iqmat3 (&1) (&0) (&0) (&1) (&0) (&2)`;
    `A:num->num->int`] IQ_EMBEDS_EQ) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC IQ_EMBEDS_CONGRUENCE THEN ASM_REWRITE_TAC[];
    REPEAT STRIP_TAC THEN
    (SUBGOAL_THEN `i = 0 \/ i = 1 \/ i = 2` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(DISJ_CASES_THEN2 SUBST_ALL_TAC
      (DISJ_CASES_THEN SUBST_ALL_TAC)) THEN
    (SUBGOAL_THEN `j = 0 \/ j = 1 \/ j = 2` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(DISJ_CASES_THEN2 SUBST_ALL_TAC
      (DISJ_CASES_THEN SUBST_ALL_TAC)) THEN
    ASM_REWRITE_TAC[iqgram; IQBILIN_MAT3; iqswap12; iqrows3;
      iqmat3; iqsym] THEN
    CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_RING]);;

let IQ_EMBEDS_12X1_TO_111 = prove
 (`!n A.
     iq_embeds n 3 (iqmat3 (&1) (&0) (&0) (&2) (&1) (&1)) A
     ==> iq_embeds n 3 (iqmat3 (&1) (&0) (&0) (&1) (&0) (&1)) A`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `3`;
    `iqgram 3 (iqmat3 (&1) (&0) (&0) (&2) (&1) (&1)) iqcross1`;
    `iqmat3 (&1) (&0) (&0) (&1) (&0) (&1)`;
    `A:num->num->int`] IQ_EMBEDS_EQ) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC IQ_EMBEDS_CONGRUENCE THEN ASM_REWRITE_TAC[];
    REPEAT STRIP_TAC THEN
    (SUBGOAL_THEN `i = 0 \/ i = 1 \/ i = 2` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(DISJ_CASES_THEN2 SUBST_ALL_TAC
      (DISJ_CASES_THEN SUBST_ALL_TAC)) THEN
    (SUBGOAL_THEN `j = 0 \/ j = 1 \/ j = 2` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(DISJ_CASES_THEN2 SUBST_ALL_TAC
      (DISJ_CASES_THEN SUBST_ALL_TAC)) THEN
    ASM_REWRITE_TAC[iqgram; IQBILIN_MAT3; iqcross1; iqrows3;
      iqmat3; iqsym] THEN
    CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_RING]);;

let IQ_EMBEDS_TERNARY_12 = prove
 (`!n A.
     iq_symmetric n A /\ iq_positive n A /\
     iq_embeds n 2 (iqmat2 (&1) (&0) (&2)) A /\
     iq_represents n A (&5)
     ==> iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&1) (&0) (&1)) A \/
         iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&1) (&0) (&2)) A \/
         iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&2) (&0) (&2)) A \/
         iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&2) (&0) (&3)) A \/
         iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&2) (&0) (&4)) A \/
         iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&2) (&0) (&5)) A \/
         iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&2) (&1) (&4)) A \/
         iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&2) (&1) (&5)) A`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL
   [`n:num`; `A:num->num->int`;
    `&1:int`; `&0:int`; `&2:int`; `&5:int`] IQ_ESCALATE_MAT2) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:int`
    (X_CHOOSE_THEN `b:int` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `a pow 2 <= &5 /\ b pow 2 <= &10` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(MATCH_MP (SPECL [`a:int`; `b:int`] IQ_12_PARAMETERS)
    (ASSUME `a pow 2 <= &5 /\ b pow 2 <= &10`)) THEN
  DISCH_THEN(X_CHOOSE_THEN `q:int`
    (X_CHOOSE_THEN `r:int`
      (X_CHOOSE_THEN `k:int`
        (CONJUNCTS_THEN2 ASSUME_TAC
          (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC))))) THEN
  SUBGOAL_THEN
   `iq_embeds n 3
      (iqmat3 (&1) (&0) a (&2) (&2 * q + r) (&5)) A`
  ASSUME_TAC THENL
   [MATCH_ACCEPT_TAC(REWRITE_RULE[ASSUME `b = &2 * q + r`] (ASSUME
     `iq_embeds n 3 (iqmat3 (&1) (&0) a (&2) b (&5)) A`));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `iq_embeds n 3 (iqmat3 (&1) (&0) (&0) (&2) r k) A`
  ASSUME_TAC THENL
   [ONCE_REWRITE_TAC[ASSUME
     `k = &5 - a pow 2 - &2 * q pow 2 - &2 * q * r`] THEN
    MATCH_MP_TAC IQ_EMBEDS_CLEAR_12 THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= k` ASSUME_TAC THENL
   [MP_TAC(MATCH_MP
     (ISPECL
       [`n:num`; `3`; `iqmat3 (&1) (&0) (&0) (&2) r k`;
        `A:num->num->int`] IQ_EMBEDDED_NONNEG)
     (CONJ (ASSUME `iq_positive n A`) (ASSUME
       `iq_embeds n 3 (iqmat3 (&1) (&0) (&0) (&2) r k) A`))) THEN
    DISCH_THEN(MP_TAC o SPEC
      `\i:num. if i = 2 then &1 else &0`) THEN
    REWRITE_TAC[IQEVAL_MAT3] THEN CONV_TAC NUM_REDUCE_CONV THEN
    INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `r = &1 ==> &1 <= k` ASSUME_TAC THENL
   [DISCH_TAC THEN
    MP_TAC(MATCH_MP
     (ISPECL
       [`n:num`; `3`; `iqmat3 (&1) (&0) (&0) (&2) r k`;
        `A:num->num->int`] IQ_EMBEDDED_NONNEG)
     (CONJ (ASSUME `iq_positive n A`) (ASSUME
       `iq_embeds n 3 (iqmat3 (&1) (&0) (&0) (&2) r k) A`))) THEN
    DISCH_THEN(MP_TAC o SPEC
      `\i:num. if i = 1 then -- &1 else if i = 2 then &2 else &0`) THEN
    ASM_REWRITE_TAC[IQEVAL_MAT3] THEN
    CONV_TAC NUM_REDUCE_CONV THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  UNDISCH_TAC
   `(r = &0 /\
     (k = -- &1 \/ k = &1 \/ k = &2 \/ k = &3 \/
      k = &4 \/ k = &5)) \/
    (r = &1 /\
     (k = -- &3 \/ k = &0 \/ k = &1 \/ k = &4 \/ k = &5))` THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN STRIP_ASSUME_TAC) THEN
  FIRST
   [ASM_INT_ARITH_TAC;
    ASM_MESON_TAC[IQ_EMBEDS_121_TO_112; IQ_EMBEDS_12X1_TO_111]]);;

let IQ_EMBEDS_TERNARY = prove
 (`!n A.
     iq_symmetric n A /\ iq_positive n A /\
     iq_represents n A (&1) /\ iq_represents n A (&2) /\
     iq_represents n A (&3) /\ iq_represents n A (&5)
     ==> iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&1) (&0) (&1)) A \/
         iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&1) (&0) (&2)) A \/
         iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&1) (&0) (&3)) A \/
         iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&2) (&0) (&2)) A \/
         iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&2) (&0) (&3)) A \/
         iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&2) (&0) (&4)) A \/
         iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&2) (&0) (&5)) A \/
         iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&2) (&1) (&4)) A \/
         iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&2) (&1) (&5)) A`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`n:num`; `A:num->num->int`] IQ_EMBEDS_BINARY) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
   [MP_TAC(SPECL [`n:num`; `A:num->num->int`] IQ_EMBEDS_TERNARY_11) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    MP_TAC(SPECL [`n:num`; `A:num->num->int`] IQ_EMBEDS_TERNARY_12) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[]]);;

let iqdiag = new_definition
 `iqdiag (a:num->int) i j = if j = i then a i else &0`;;

let iqdiag4 = new_definition
 `iqdiag4 (a:int) b c d =
    iqdiag
      (\i. if i = 0 then a else if i = 1 then b else
           if i = 2 then c else d)`;;

let IQEVAL_IQDIAG = prove
 (`!n a x.
     iqeval n (iqdiag a) x =
     isum (qindex n) (\i. a i * x i pow 2)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[iqeval; iqbilin] THEN
  MATCH_MP_TAC ISUM_EQ THEN REWRITE_TAC[qindex; IN_ELIM_THM] THEN
  X_GEN_TAC `i:num` THEN DISCH_TAC THEN
  SIMP_TAC[iqdiag; COND_RAND; COND_RATOR; INT_MUL_LZERO] THEN
  REWRITE_TAC[ISUM_DELTA] THEN
  ASM_REWRITE_TAC[IN_ELIM_THM; INT_POW_2]);;

let IQEVAL_DIAG4 = prove
 (`!a b c d x.
     iqeval 4 (iqdiag4 a b c d) x =
     a * x 0 pow 2 + b * x 1 pow 2 + c * x 2 pow 2 + d * x 3 pow 2`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[iqdiag4; IQEVAL_IQDIAG; qindex; NUMSEG_LT] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  CONV_TAC(ONCE_DEPTH_CONV EXPAND_ISUM_CONV) THEN
  CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_RING);;

let IQ_REPRESENTS_DIAG4 = prove
 (`!a b c d m.
     (?x y z w:int.
        a * x pow 2 + b * y pow 2 + c * z pow 2 + d * w pow 2 = m)
     ==> iq_represents 4 (iqdiag4 a b c d) m`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int` (X_CHOOSE_THEN `y:int`
   (X_CHOOSE_THEN `z:int` (X_CHOOSE_TAC `w:int`)))) THEN
  REWRITE_TAC[iq_represents] THEN
  EXISTS_TAC
   `\i:num. if i = 0 then (x:int) else if i = 1 then y else
        if i = 2 then z else w` THEN
  REWRITE_TAC[IQEVAL_DIAG4] THEN
  CONV_TAC NUM_REDUCE_CONV THEN ASM_REWRITE_TAC[]);;

let INT_THREE_SQUARES_OF_LEGENDRE = prove
 (`!n:num.
     ~(?a m. n = 4 EXP a * (8 * m + 7))
     ==> ?x y z:int. x pow 2 + y pow 2 + z pow 2 = &n`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPEC `n:num` LEGENDRE_THREE_SQUARES) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `x:num`
   (X_CHOOSE_THEN `y:num` (X_CHOOSE_TAC `z:num`))) THEN
  MAP_EVERY EXISTS_TAC [`&x:int`; `&y:int`; `&z:int`] THEN
  REWRITE_TAC[INT_OF_NUM_ADD; INT_OF_NUM_POW] THEN
  ASM_REWRITE_TAC[]);;

let INT_SAME_PARITY_HALF = prove
 (`!x y:int.
     x rem &2 = y rem &2 ==> ?e. x + y = &2 * e`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`x:int`; `&2:int`] INT_DIVISION) THEN
  ANTS_TAC THENL [INT_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`y:int`; `&2:int`] INT_DIVISION) THEN
  ANTS_TAC THENL [INT_ARITH_TAC; ALL_TAC] THEN
  REPEAT STRIP_TAC THEN
  EXISTS_TAC `x div &2 + y div &2 + x rem &2` THEN
  ASM_INT_ARITH_TAC);;

let INT_PARITY_WITNESS = prove
 (`!x:int. (?a. x = &2 * a) \/ (?a. x = &2 * a + &1)`,
  GEN_TAC THEN MP_TAC(SPEC `x:int` INT_REM_2_CASES) THEN
  DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
   [DISJ1_TAC THEN EXISTS_TAC `x div &2` THEN
    MP_TAC(SPECL [`x:int`; `&2:int`] INT_DIVISION) THEN
    ANTS_TAC THENL
     [INT_ARITH_TAC; STRIP_TAC THEN ASM_INT_ARITH_TAC];
    DISJ2_TAC THEN EXISTS_TAC `x div &2` THEN
    MP_TAC(SPECL [`x:int`; `&2:int`] INT_DIVISION) THEN
    ANTS_TAC THENL
     [INT_ARITH_TAC; STRIP_TAC THEN ASM_INT_ARITH_TAC]]);;

let INT_TWO_MUL_NE_ONE = prove
 (`!k:int. ~(&2 * k = &1)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `(&2:int) divides &1` MP_TAC THENL
   [REWRITE_TAC[int_divides] THEN EXISTS_TAC `k:int` THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[INT_DIVIDES_ONE] THEN INT_ARITH_TAC]);;

let INT_ONE_ODD_SQUARES_NE_DOUBLE = prove
 (`!a b c n:int.
     ~((&2 * a + &1) pow 2 + (&2 * b) pow 2 + (&2 * c) pow 2 =
       &2 * n)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `&2 * (n - &2 * a pow 2 - &2 * a -
              &2 * b pow 2 - &2 * c pow 2) = &1`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(INT_RING
     `(&2*a + &1) pow 2 + (&2*b) pow 2 + (&2*c) pow 2 = &2*n
      ==> &2 * (n - &2*a pow 2 - &2*a -
                    &2*b pow 2 - &2*c pow 2) = &1`) THEN
    ASM_REWRITE_TAC[];
    MP_TAC(SPEC
     `n - &2 * a pow 2 - &2 * a -
          &2 * b pow 2 - &2 * c pow 2`
     INT_TWO_MUL_NE_ONE) THEN
    ASM_REWRITE_TAC[]]);;

let INT_EVEN_EVEN_ODD_SQUARES_NE_DOUBLE = prove
 (`!a b c n:int.
     ~((&2 * a) pow 2 + (&2 * b) pow 2 + (&2 * c + &1) pow 2 =
       &2 * n)`,
  MESON_TAC[INT_ONE_ODD_SQUARES_NE_DOUBLE;
    INT_RING
     `(&2*a) pow 2 + (&2*b) pow 2 + (&2*c + &1) pow 2 = &2*n
      ==> (&2*c + &1) pow 2 + (&2*a) pow 2 + (&2*b) pow 2 = &2*n`]);;

let INT_EVEN_ODD_EVEN_SQUARES_NE_DOUBLE = prove
 (`!a b c n:int.
     ~((&2 * a) pow 2 + (&2 * b + &1) pow 2 + (&2 * c) pow 2 =
       &2 * n)`,
  MESON_TAC[INT_ONE_ODD_SQUARES_NE_DOUBLE;
    INT_RING
     `(&2*a) pow 2 + (&2*b + &1) pow 2 + (&2*c) pow 2 = &2*n
      ==> (&2*b + &1) pow 2 + (&2*a) pow 2 + (&2*c) pow 2 = &2*n`]);;

let INT_THREE_ODD_SQUARES_NE_DOUBLE = prove
 (`!a b c n:int.
     ~((&2 * a + &1) pow 2 + (&2 * b + &1) pow 2 +
       (&2 * c + &1) pow 2 = &2 * n)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `&2 * (n - &2 * a pow 2 - &2 * a -
              &2 * b pow 2 - &2 * b -
              &2 * c pow 2 - &2 * c - &1) = &1`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(INT_RING
     `(&2*a + &1) pow 2 + (&2*b + &1) pow 2 +
       (&2*c + &1) pow 2 = &2*n
      ==> &2 * (n - &2*a pow 2 - &2*a -
                    &2*b pow 2 - &2*b -
                    &2*c pow 2 - &2*c - &1) = &1`) THEN
    ASM_REWRITE_TAC[];
    MP_TAC(SPEC
     `n - &2 * a pow 2 - &2 * a -
          &2 * b pow 2 - &2 * b -
          &2 * c pow 2 - &2 * c - &1`
     INT_TWO_MUL_NE_ONE) THEN
    ASM_REWRITE_TAC[]]);;

let INT_THREE_PARITY_PAIR = prove
 (`!x y z:int.
     (?e. x + y = &2 * e) \/
     (?e. x + z = &2 * e) \/
     (?e. y + z = &2 * e)`,
  REPEAT GEN_TAC THEN
  MP_TAC(SPEC `x:int` INT_REM_2_CASES) THEN
  MP_TAC(SPEC `y:int` INT_REM_2_CASES) THEN
  MP_TAC(SPEC `z:int` INT_REM_2_CASES) THEN
  MESON_TAC[INT_SAME_PARITY_HALF]);;

let INT_PAIR_HALF = prove
 (`!c d e:int.
     c + d = &2 * e
     ==> ?u v. &2 * u pow 2 + &2 * v pow 2 = c pow 2 + d pow 2`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MAP_EVERY EXISTS_TAC [`e:int`; `c - e:int`] THEN
  MATCH_MP_TAC(INT_RING
   `c + d = &2 * e
    ==> &2 * e pow 2 + &2 * (c - e) pow 2 = c pow 2 + d pow 2`) THEN
  ASM_REWRITE_TAC[]);;

let REPR_112_OF_THREE_SQUARES = prove
 (`!n:int.
     (?u v w. u pow 2 + v pow 2 + w pow 2 = &2 * n)
     ==> ?x y z. x pow 2 + y pow 2 + &2 * z pow 2 = n`,
  GEN_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `u:int`
   (X_CHOOSE_THEN `v:int` (X_CHOOSE_TAC `w:int`))) THEN
  MP_TAC(SPEC `u:int` INT_PARITY_WITNESS) THEN
  DISCH_THEN(DISJ_CASES_THEN
   (X_CHOOSE_THEN `a:int` SUBST_ALL_TAC)) THEN
  MP_TAC(SPEC `v:int` INT_PARITY_WITNESS) THEN
  DISCH_THEN(DISJ_CASES_THEN
   (X_CHOOSE_THEN `b:int` SUBST_ALL_TAC)) THEN
  MP_TAC(SPEC `w:int` INT_PARITY_WITNESS) THEN
  DISCH_THEN(DISJ_CASES_THEN
   (X_CHOOSE_THEN `c:int` SUBST_ALL_TAC)) THENL
   [MAP_EVERY EXISTS_TAC [`a + b:int`; `a - b:int`; `c:int`] THEN
    FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING;
    ASM_MESON_TAC[INT_EVEN_EVEN_ODD_SQUARES_NE_DOUBLE];
    ASM_MESON_TAC[INT_EVEN_ODD_EVEN_SQUARES_NE_DOUBLE];
    MAP_EVERY EXISTS_TAC
     [`b + c + &1:int`; `b - c:int`; `a:int`] THEN
    FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING;
    ASM_MESON_TAC[INT_ONE_ODD_SQUARES_NE_DOUBLE];
    MAP_EVERY EXISTS_TAC
     [`a + c + &1:int`; `a - c:int`; `b:int`] THEN
    FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING;
    MAP_EVERY EXISTS_TAC
     [`a + b + &1:int`; `a - b:int`; `c:int`] THEN
    FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING;
    ASM_MESON_TAC[INT_THREE_ODD_SQUARES_NE_DOUBLE]]);;

let REPR_122_OF_THREE_SQUARES = prove
 (`!n:int.
     (?a b c. a pow 2 + b pow 2 + c pow 2 = n)
     ==> ?x y z. x pow 2 + &2 * y pow 2 + &2 * z pow 2 = n`,
  GEN_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `a:int`
   (X_CHOOSE_THEN `b:int` (X_CHOOSE_TAC `c:int`))) THEN
  MP_TAC(SPECL [`a:int`; `b:int`; `c:int`] INT_THREE_PARITY_PAIR) THEN
  DISCH_THEN(DISJ_CASES_THEN2
   (X_CHOOSE_THEN `e:int` ASSUME_TAC)
   (DISJ_CASES_THEN (X_CHOOSE_THEN `e:int` ASSUME_TAC))) THENL
   [MP_TAC(SPECL [`a:int`; `b:int`; `e:int`] INT_PAIR_HALF);
    MP_TAC(SPECL [`a:int`; `c:int`; `e:int`] INT_PAIR_HALF);
    MP_TAC(SPECL [`b:int`; `c:int`; `e:int`] INT_PAIR_HALF)] THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `u:int` (X_CHOOSE_TAC `v:int`)) THENL
   [MAP_EVERY EXISTS_TAC [`c:int`; `u:int`; `v:int`];
    MAP_EVERY EXISTS_TAC [`b:int`; `u:int`; `v:int`];
    MAP_EVERY EXISTS_TAC [`a:int`; `u:int`; `v:int`]] THEN
  ASM_INT_ARITH_TAC);;

let THREE_SQUARES_AVOIDS_OF_MOD = prove
 (`!u:num.
     ~(u MOD 4 = 0) /\ ~(u MOD 8 = 7)
     ==> ~(?a m. u = 4 EXP a * (8 * m + 7))`,
  GEN_TAC THEN STRIP_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `a:num` (X_CHOOSE_THEN `m:num` ASSUME_TAC)) THEN
  ASM_CASES_TAC `a = 0` THENL
   [UNDISCH_TAC `~(u MOD 8 = 7)` THEN
    ASM_REWRITE_TAC[EXP; MULT_CLAUSES; MOD_MULT_ADD] THEN
    CONV_TAC NUM_REDUCE_CONV;
    MP_TAC(SPEC `a:num` num_CASES) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `k:num` SUBST_ALL_TAC) THEN
    UNDISCH_TAC `~(u MOD 4 = 0)` THEN ASM_REWRITE_TAC[EXP] THEN
    REWRITE_TAC[ARITH_RULE `(4 * x) * y = 4 * (x * y)`; MOD_MULT]]);;

let THREE_SQUARES_AVOIDS_FOUR_MUL = prove
 (`!u:num.
     ~(?a m. u = 4 EXP a * (8 * m + 7))
     ==> ~(?a m. 4 * u = 4 EXP a * (8 * m + 7))`,
  GEN_TAC THEN DISCH_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `a:num` (X_CHOOSE_THEN `m:num` ASSUME_TAC)) THEN
  ASM_CASES_TAC `a = 0` THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN
    UNDISCH_TAC `4 * u = 4 EXP 0 * (8 * m + 7)` THEN
    REWRITE_TAC[EXP; MULT_CLAUSES] THEN
    DISCH_THEN(MP_TAC o AP_TERM `\n:num. n MOD 4`) THEN
    REWRITE_TAC[ARITH_RULE `8 * m + 7 = 4 * (2 * m + 1) + 3`] THEN
    SIMP_TAC[MOD_MULT_ADD; MOD_MULT] THEN CONV_TAC NUM_REDUCE_CONV;
    MP_TAC(SPEC `a:num` num_CASES) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `k:num` SUBST_ALL_TAC) THEN
    SUBGOAL_THEN `u = 4 EXP k * (8 * m + 7)` ASSUME_TAC THENL
     [UNDISCH_TAC `4 * u = 4 EXP (SUC k) * (8 * m + 7)` THEN
      REWRITE_TAC[EXP; ARITH_RULE `(4 * x) * y = 4 * (x * y)`;
        ARITH_RULE `(4 * x = 4 * y) <=> x = y`];
      UNDISCH_TAC `~(?a m. u = 4 EXP a * (8 * m + 7))` THEN
      ASM_MESON_TAC[]]]);;

let IQ_UNIVERSAL_DIAG4_OF_NUM = prove
 (`!a b c d.
     (!n:num. 0 < n
              ==> ?x y z w:int.
                    a * x pow 2 + b * y pow 2 +
                    c * z pow 2 + d * w pow 2 = &n)
     ==> iq_universal 4 (iqdiag4 a b c d)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN REWRITE_TAC[iq_universal] THEN
  X_GEN_TAC `m:int` THEN DISCH_TAC THEN
  MP_TAC(EQ_MP (SYM(SPEC `m:int` INT_OF_NUM_EXISTS))
   (MATCH_MP (SPECL [`&0:int`; `m:int`] INT_LT_IMP_LE)
    (ASSUME `&0 < m`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `n:num` SUBST_ALL_TAC) THEN
  MATCH_MP_TAC IQ_REPRESENTS_DIAG4 THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
  UNDISCH_TAC `&0 < &n` THEN REWRITE_TAC[INT_OF_NUM_LT]);;

let IQ_DIAG4_REPRESENTATION_SCALE4 = prove
 (`!a b c d r:int.
     (?x y z w.
        a * x pow 2 + b * y pow 2 +
        c * z pow 2 + d * w pow 2 = r)
     ==> ?x y z w.
           a * x pow 2 + b * y pow 2 +
           c * z pow 2 + d * w pow 2 = &4 * r`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int` (X_CHOOSE_THEN `y:int`
   (X_CHOOSE_THEN `z:int` (X_CHOOSE_TAC `w:int`)))) THEN
  MAP_EVERY EXISTS_TAC
   [`&2 * x:int`; `&2 * y:int`; `&2 * z:int`; `&2 * w:int`] THEN
  FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING);;

let IQ_UNIVERSAL_122C_OF_111C = prove
 (`!c:int.
     iq_universal 4 (iqdiag4 (&1:int) (&1:int) (&1:int) c)
     ==> iq_universal 4 (iqdiag4 (&1:int) (&2:int) (&2:int) c)`,
  GEN_TAC THEN REWRITE_TAC[iq_universal] THEN DISCH_TAC THEN
  X_GEN_TAC `m:int` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `m:int`) THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[iq_represents; IQEVAL_DIAG4] THEN
  DISCH_THEN(X_CHOOSE_THEN `v:num->int` ASSUME_TAC) THEN
  MP_TAC(SPEC
   `(m:int) - (c:int) * ((v:num->int) 3) pow 2`
   REPR_122_OF_THREE_SQUARES) THEN
  ANTS_TAC THENL
   [MAP_EVERY EXISTS_TAC
     [`(v:num->int) 0`; `(v:num->int) 1`; `(v:num->int) 2`] THEN
    FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING;
    DISCH_THEN(X_CHOOSE_THEN `x:int`
     (X_CHOOSE_THEN `y:int` (X_CHOOSE_TAC `z:int`))) THEN
    EXISTS_TAC
     `\i:num.
        if i = 0 then (x:int) else if i = 1 then y else
        if i = 2 then z else (v:num->int) 3` THEN
    REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
    FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING]);;

let THREE_SQUARES_AVOIDS_SUB2 = prove
 (`!n:num.
     0 < n /\ (n MOD 4 = 0 \/ n MOD 8 = 7)
     ==> ~((n - 2) MOD 4 = 0) /\ ~((n - 2) MOD 8 = 7)`,
  GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (DISJ_CASES_THEN ASSUME_TAC)) THENL
   [SUBGOAL_THEN `n = n DIV 4 * 4` ASSUME_TAC THENL
     [MP_TAC(SPECL [`n:num`; `4`] DIVISION) THEN
      CONV_TAC NUM_REDUCE_CONV THEN ASM_REWRITE_TAC[ADD_CLAUSES] THEN
      MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `n - 2 = 4 * (n DIV 4 - 1) + 2` ASSUME_TAC THENL
     [ASM_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `(n - 2) MOD 4 = 2` ASSUME_TAC THENL
     [ASM_REWRITE_TAC[MOD_MULT_ADD] THEN CONV_TAC NUM_REDUCE_CONV;
      ALL_TAC] THEN
    CONJ_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV;
      DISCH_TAC THEN
      SUBGOAL_THEN
       `(n - 2) MOD 4 = (n - 2) MOD 8 MOD 4`
      MP_TAC THENL
       [REWRITE_TAC[ARITH_RULE `8 = 4 * 2`; MOD_MOD];
        ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV]];
    SUBGOAL_THEN `n = n DIV 8 * 8 + 7` ASSUME_TAC THENL
     [MP_TAC(SPECL [`n:num`; `8`] DIVISION) THEN
      CONV_TAC NUM_REDUCE_CONV THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `n - 2 = 8 * (n DIV 8) + 5` ASSUME_TAC THENL
     [ASM_ARITH_TAC;
      CONJ_TAC THENL
       [ASM_REWRITE_TAC
         [ARITH_RULE `8 * q + 5 = 4 * (2 * q + 1) + 1`;
          MOD_MULT_ADD] THEN
        CONV_TAC NUM_REDUCE_CONV;
        ASM_REWRITE_TAC[MOD_MULT_ADD] THEN CONV_TAC NUM_REDUCE_CONV]]]);;

let IQ_UNIVERSAL_1112_NUM = prove
 (`!n:num.
     0 < n
     ==> ?x y z w:int.
           &1 * x pow 2 + &1 * y pow 2 +
           &1 * z pow 2 + &2 * w pow 2 = &n`,
  GEN_TAC THEN DISCH_TAC THEN
  ASM_CASES_TAC `n MOD 4 = 0 \/ n MOD 8 = 7` THENL
   [SUBGOAL_THEN `2 <= n` ASSUME_TAC THENL
     [ASM_CASES_TAC `n = 1` THENL
       [UNDISCH_TAC `n MOD 4 = 0 \/ n MOD 8 = 7` THEN
        ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV;
        ASM_ARITH_TAC];
      ALL_TAC] THEN
    MP_TAC(MATCH_MP INT_THREE_SQUARES_OF_LEGENDRE
     (MATCH_MP THREE_SQUARES_AVOIDS_OF_MOD
      (MATCH_MP THREE_SQUARES_AVOIDS_SUB2
       (CONJ (ASSUME `0 < n`)
             (ASSUME `n MOD 4 = 0 \/ n MOD 8 = 7`))))) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:int`
     (X_CHOOSE_THEN `y:int` (X_CHOOSE_TAC `z:int`))) THEN
    MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`; `&1:int`] THEN
    FIRST_X_ASSUM(MP_TAC) THEN
    ASM_SIMP_TAC[GSYM INT_OF_NUM_SUB] THEN CONV_TAC INT_RING;
    SUBGOAL_THEN
     `~(n MOD 4 = 0) /\ ~(n MOD 8 = 7)`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MP_TAC(MATCH_MP INT_THREE_SQUARES_OF_LEGENDRE
     (MATCH_MP THREE_SQUARES_AVOIDS_OF_MOD
      (ASSUME `~(n MOD 4 = 0) /\ ~(n MOD 8 = 7)`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:int`
     (X_CHOOSE_THEN `y:int` (X_CHOOSE_TAC `z:int`))) THEN
    MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`; `&0:int`] THEN
    FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING]);;

