let INT_THREE_SQUARES_OF_MOD = prove
 (`!u:num.
     ~(u MOD 4 = 0) /\ ~(u MOD 8 = 7)
     ==> ?x y z:int. x pow 2 + y pow 2 + z pow 2 = &u`,
  MESON_TAC[THREE_SQUARES_AVOIDS_OF_MOD;
    INT_THREE_SQUARES_OF_LEGENDRE]);;

let IQ_DIAG4_REPRESENTATION_SCALE4_NUM = prove
 (`!a b c d k.
     (?x y z w:int.
        a * x pow 2 + b * y pow 2 +
        c * z pow 2 + d * w pow 2 = &k)
     ==> ?x y z w:int.
           a * x pow 2 + b * y pow 2 +
           c * z pow 2 + d * w pow 2 = &(4 * k)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(MP_TAC o MATCH_MP
   (SPECL [`a:int`; `b:int`; `c:int`; `d:int`; `&k:int`]
     IQ_DIAG4_REPRESENTATION_SCALE4)) THEN
  REWRITE_TAC[INT_OF_NUM_MUL]);;

let IQ_DIAG4_111C_REPRESENTATION_STEP = prove
 (`!c:int. !n u k:num. !d:int.
     (?x y z:int. x pow 2 + y pow 2 + z pow 2 = &u) /\
     c * d pow 2 = &k /\ n = u + k
     ==> ?x y z w:int.
           &1 * x pow 2 + &1 * y pow 2 +
           &1 * z pow 2 + c * w pow 2 = &n`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2
   (X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int` (X_CHOOSE_TAC `z:int`)))
   (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
  FIRST_X_ASSUM SUBST1_TAC THEN
  MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`; `d:int`] THEN
  REWRITE_TAC[GSYM INT_OF_NUM_ADD] THEN
  FIRST_X_ASSUM(MP_TAC) THEN FIRST_X_ASSUM(MP_TAC) THEN
  CONV_TAC INT_RING);;

let MOD32_7_CASES = prove
 (`!n:num.
     n MOD 8 = 7
     ==> n MOD 32 = 7 \/ n MOD 32 = 15 \/
         n MOD 32 = 23 \/ n MOD 32 = 31`,
  GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `(n MOD 32) MOD 8 = 7` ASSUME_TAC THENL
   [SUBGOAL_THEN `(n MOD 32) MOD 8 = n MOD 8` MP_TAC THENL
     [REWRITE_TAC[ARITH_RULE `32 = 8 * 4`; MOD_MOD];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`n MOD 32`; `8`] DIVISION) THEN
  CONV_TAC NUM_REDUCE_CONV THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(SPECL [`n:num`; `32`] DIVISION) THEN
  CONV_TAC NUM_REDUCE_CONV THEN STRIP_TAC THEN
  ASM_CASES_TAC `(n MOD 32) DIV 8 = 0` THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  ASM_CASES_TAC `(n MOD 32) DIV 8 = 1` THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  ASM_CASES_TAC `(n MOD 32) DIV 8 = 2` THEN ASM_ARITH_TAC);;

