        SUBGOAL_THEN `n = 32 * (n DIV 32) + 15` ASSUME_TAC THENL
         [MP_TAC(SPECL [`n:num`; `32`] DIVISION) THEN
          CONV_TAC NUM_REDUCE_CONV THEN
