        MATCH_MP_TAC(SPECL
         [`&7:int`; `n:num`;
          `8 * (4 * (n DIV 32 - 1) + 1) + 3`;
          `28`; `&2:int`]
         IQ_DIAG4_111C_REPRESENTATION_STEP) THEN
        REPEAT CONJ_TAC THENL
         [MATCH_MP_TAC INT_THREE_SQUARES_8Q_MOD THEN
          CONV_TAC NUM_REDUCE_CONV;
          CONV_TAC INT_REDUCE_CONV;
          ASM_ARITH_TAC];
        SUBGOAL_THEN `n = 32 * (n DIV 32) + 23` ASSUME_TAC THENL
         [MP_TAC(SPECL [`n:num`; `32`] DIVISION) THEN
          CONV_TAC NUM_REDUCE_CONV THEN
          ASM_REWRITE_TAC[] THEN ARITH_TAC;
          ALL_TAC] THEN
        SUBGOAL_THEN `0 < n DIV 32` ASSUME_TAC THENL
         [ASM_ARITH_TAC; ALL_TAC] THEN
        MATCH_MP_TAC(SPECL
         [`&7:int`; `n:num`;
          `8 * (4 * (n DIV 32 - 1) + 3) + 3`;
          `28`; `&2:int`]
         IQ_DIAG4_111C_REPRESENTATION_STEP) THEN
        REPEAT CONJ_TAC THENL
         [MATCH_MP_TAC INT_THREE_SQUARES_8Q_MOD THEN
          CONV_TAC NUM_REDUCE_CONV;
          CONV_TAC INT_REDUCE_CONV;
          ASM_ARITH_TAC]]];
    MATCH_MP_TAC(SPECL
     [`&7:int`; `n:num`; `n:num`; `0`; `&0:int`]
     IQ_DIAG4_111C_REPRESENTATION_STEP) THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC INT_THREE_SQUARES_OF_MOD THEN ASM_REWRITE_TAC[];
      CONV_TAC INT_REDUCE_CONV;
      ARITH_TAC]]);;

