let INT_REPRESENTS_112_OF_LEGENDRE = prove
 (`!n:num.
     ~(?a m. 2 * n = 4 EXP a * (8 * m + 7))
     ==> ?x y z:int. x pow 2 + y pow 2 + &2 * z pow 2 = &n`,
  GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC(SPEC `&n:int` REPR_112_OF_THREE_SQUARES) THEN
  REWRITE_TAC[INT_OF_NUM_MUL] THEN
  MATCH_MP_TAC INT_THREE_SQUARES_OF_LEGENDRE THEN
  ASM_REWRITE_TAC[]);;

let MOD4_CASES = prove
 (`!n:num.
     n MOD 4 = 0 \/ n MOD 4 = 1 \/ n MOD 4 = 2 \/ n MOD 4 = 3`,
  GEN_TAC THEN
  MP_TAC(SPECL [`n:num`; `4`] DIVISION) THEN
  CONV_TAC NUM_REDUCE_CONV THEN STRIP_TAC THEN
  ASM_CASES_TAC `n MOD 4 = 0` THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_CASES_TAC `n MOD 4 = 1` THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_CASES_TAC `n MOD 4 = 2` THEN ASM_REWRITE_TAC[] THEN
  ASM_ARITH_TAC);;

let MOD2_OF_MOD4 = prove
 (`!n:num. (n MOD 4) MOD 2 = n MOD 2`,
  REWRITE_TAC[ARITH_RULE `4 = 2 * 2`; MOD_MOD]);;

let NUM_MOD4_NONZERO_NONODD = prove
 (`!n:num.
     ~(n MOD 4 = 0) /\ ~(n MOD 2 = 1)
     ==> n MOD 4 = 2`,
  GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPEC `n:num` MOD4_CASES) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(DISJ_CASES_THEN2 ASSUME_TAC
   (DISJ_CASES_THEN ASSUME_TAC)) THENL
   [MP_TAC(SPEC `n:num` MOD2_OF_MOD4) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
    ASM_MESON_TAC[];
    ASM_REWRITE_TAC[];
    MP_TAC(SPEC `n:num` MOD2_OF_MOD4) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
    ASM_MESON_TAC[]]);;

let MOD16_2_CASES = prove
 (`!n:num.
     n MOD 4 = 2
     ==> n MOD 16 = 2 \/ n MOD 16 = 6 \/
         n MOD 16 = 10 \/ n MOD 16 = 14`,
  GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `(n MOD 16) MOD 4 = 2` ASSUME_TAC THENL
   [SUBGOAL_THEN `(n MOD 16) MOD 4 = n MOD 4` MP_TAC THENL
     [REWRITE_TAC[ARITH_RULE `16 = 4 * 4`; MOD_MOD];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`n MOD 16`; `4`] DIVISION) THEN
  CONV_TAC NUM_REDUCE_CONV THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(SPECL [`n:num`; `16`] DIVISION) THEN
  CONV_TAC NUM_REDUCE_CONV THEN STRIP_TAC THEN
  ASM_CASES_TAC `(n MOD 16) DIV 4 = 0` THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  ASM_CASES_TAC `(n MOD 16) DIV 4 = 1` THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  ASM_CASES_TAC `(n MOD 16) DIV 4 = 2` THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  ASM_CASES_TAC `(n MOD 16) DIV 4 = 3` THEN ASM_ARITH_TAC);;

let INT_REPRESENTS_112_ODD = prove
 (`!u:num.
     u MOD 2 = 1
     ==> ?x y z:int. x pow 2 + y pow 2 + &2 * z pow 2 = &u`,
  GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC INT_REPRESENTS_112_OF_LEGENDRE THEN
  MATCH_MP_TAC THREE_SQUARES_AVOIDS_OF_MOD THEN CONJ_TAC THENL
   [SUBGOAL_THEN `u = u DIV 2 * 2 + 1` ASSUME_TAC THENL
     [MP_TAC(SPECL [`u:num`; `2`] DIVISION) THEN
      CONV_TAC NUM_REDUCE_CONV THEN ASM_REWRITE_TAC[] THEN ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `2 * u = 4 * (u DIV 2) + 2` ASSUME_TAC THENL
     [ASM_ARITH_TAC;
      ASM_REWRITE_TAC[MOD_MULT_ADD] THEN CONV_TAC NUM_REDUCE_CONV];
    DISCH_TAC THEN
    SUBGOAL_THEN
     `(2 * u) MOD 8 MOD 2 = (2 * u) MOD 2`
    MP_TAC THENL
     [REWRITE_TAC[ARITH_RULE `8 = 2 * 4`; MOD_MOD];
      ASM_REWRITE_TAC[MOD_MULT] THEN CONV_TAC NUM_REDUCE_CONV]]);;

let NUM_DECOMPOSE_MOD = prove
 (`!n m r:num.
     ~(m = 0) /\ n MOD m = r
     ==> ?q. n = m * q + r`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  EXISTS_TAC `n DIV m` THEN
  MP_TAC(SPECL [`n:num`; `m:num`] DIVISION) THEN
  ASM_REWRITE_TAC[] THEN ARITH_TAC);;

let INT_REPRESENTS_112_TWICE_8Q_MOD = prove
 (`!q r:num.
     ~(r MOD 4 = 0) /\ ~(r MOD 8 = 7)
     ==> ?x y z:int.
           x pow 2 + y pow 2 + &2 * z pow 2 = &(2 * (8 * q + r))`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC INT_REPRESENTS_112_OF_LEGENDRE THEN
  REWRITE_TAC[ARITH_RULE `2 * (2 * v) = 4 * v`] THEN
  MATCH_MP_TAC THREE_SQUARES_AVOIDS_FOUR_MUL THEN
  MATCH_MP_TAC THREE_SQUARES_AVOIDS_OF_MOD THEN CONJ_TAC THENL
   [ASM_REWRITE_TAC
     [ARITH_RULE `8 * q + r = 4 * (2 * q) + r`; MOD_MULT_ADD];
    ASM_REWRITE_TAC[MOD_MULT_ADD]]);;

let INT_REPRESENTS_112_TWO = prove
 (`!u:num.
     u MOD 4 = 2 /\ ~(u MOD 16 = 14)
     ==> ?x y z:int. x pow 2 + y pow 2 + &2 * z pow 2 = &u`,
  GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPEC `u:num` MOD16_2_CASES) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(DISJ_CASES_THEN2 ASSUME_TAC
   (DISJ_CASES_THEN ASSUME_TAC)) THENL
   [MP_TAC(SPECL [`u:num`; `16`; `2`] NUM_DECOMPOSE_MOD) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
    DISCH_THEN(X_CHOOSE_THEN `q:num` SUBST1_TAC) THEN
    REWRITE_TAC[ARITH_RULE `16 * q + 2 = 2 * (8 * q + 1)`] THEN
    MATCH_MP_TAC INT_REPRESENTS_112_TWICE_8Q_MOD THEN
    CONV_TAC NUM_REDUCE_CONV;
    MP_TAC(SPECL [`u:num`; `16`; `6`] NUM_DECOMPOSE_MOD) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
    DISCH_THEN(X_CHOOSE_THEN `q:num` SUBST1_TAC) THEN
    REWRITE_TAC[ARITH_RULE `16 * q + 6 = 2 * (8 * q + 3)`] THEN
    MATCH_MP_TAC INT_REPRESENTS_112_TWICE_8Q_MOD THEN
    CONV_TAC NUM_REDUCE_CONV;
    MP_TAC(SPECL [`u:num`; `16`; `10`] NUM_DECOMPOSE_MOD) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
    DISCH_THEN(X_CHOOSE_THEN `q:num` SUBST1_TAC) THEN
    REWRITE_TAC[ARITH_RULE `16 * q + 10 = 2 * (8 * q + 5)`] THEN
    MATCH_MP_TAC INT_REPRESENTS_112_TWICE_8Q_MOD THEN
    CONV_TAC NUM_REDUCE_CONV]);;

let INT_REPRESENTS_112_SCALE4_NUM = prove
 (`!u:num.
     (?x y z:int. x pow 2 + y pow 2 + &2 * z pow 2 = &u)
     ==> ?x y z:int.
           x pow 2 + y pow 2 + &2 * z pow 2 = &(4 * u)`,
  GEN_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
   (X_CHOOSE_THEN `y:int` (X_CHOOSE_TAC `z:int`))) THEN
  MAP_EVERY EXISTS_TAC
   [`&2 * x:int`; `&2 * y:int`; `&2 * z:int`] THEN
  REWRITE_TAC[GSYM INT_OF_NUM_MUL] THEN
  FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING);;

let IQ_DIAG4_112C_REPRESENTATION_STEP = prove
 (`!c:int. !n u k:num. !d:int.
     (?x y z:int. x pow 2 + y pow 2 + &2 * z pow 2 = &u) /\
     c * d pow 2 = &k /\ n = u + k
     ==> ?x y z w:int.
           &1 * x pow 2 + &1 * y pow 2 +
           &2 * z pow 2 + c * w pow 2 = &n`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2
   (X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int` (X_CHOOSE_TAC `z:int`)))
   (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
  FIRST_X_ASSUM SUBST1_TAC THEN
  MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`; `d:int`] THEN
  REWRITE_TAC[GSYM INT_OF_NUM_ADD] THEN
  FIRST_X_ASSUM(MP_TAC) THEN FIRST_X_ASSUM(MP_TAC) THEN
  CONV_TAC INT_RING);;

let IQ_UNIVERSAL_112C_NUM_OF_BAD = prove
 (`!c:num.
     (!n:num.
        0 < n ==> n MOD 16 = 14 ==>
        (!m:num.
           m < n ==> 0 < m ==>
           ?x y z w:int.
             &1 * x pow 2 + &1 * y pow 2 +
             &2 * z pow 2 + &c * w pow 2 = &m)
        ==> ?x y z w:int.
              &1 * x pow 2 + &1 * y pow 2 +
              &2 * z pow 2 + &c * w pow 2 = &n)
     ==> !n:num.
           0 < n
           ==> ?x y z w:int.
                 &1 * x pow 2 + &1 * y pow 2 +
                 &2 * z pow 2 + &c * w pow 2 = &n`,
  GEN_TAC THEN DISCH_THEN(fun bad ->
    MATCH_MP_TAC num_WF THEN X_GEN_TAC `n:num` THEN
    DISCH_TAC THEN DISCH_TAC THEN
    ASM_CASES_TAC `n MOD 4 = 0` THENL
     [SUBGOAL_THEN `n = 4 * (n DIV 4)` ASSUME_TAC THENL
       [MP_TAC(SPECL [`n:num`; `4`] DIVISION) THEN
        CONV_TAC NUM_REDUCE_CONV THEN
        ASM_REWRITE_TAC[ADD_CLAUSES] THEN ARITH_TAC;
        ALL_TAC] THEN
      FIRST_X_ASSUM SUBST1_TAC THEN
      MATCH_MP_TAC IQ_DIAG4_REPRESENTATION_SCALE4_NUM THEN
      SUBGOAL_THEN
       `n DIV 4 < n /\ 0 < n DIV 4`
      STRIP_ASSUME_TAC THENL
       [MP_TAC(SPECL [`n:num`; `4`] DIVISION) THEN
        CONV_TAC NUM_REDUCE_CONV THEN
        ASM_REWRITE_TAC[ADD_CLAUSES] THEN ASM_ARITH_TAC;
        ALL_TAC] THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `n DIV 4`) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_CASES_TAC `n MOD 2 = 1` THENL
     [MATCH_MP_TAC(SPECL
       [`&c:int`; `n:num`; `n:num`; `0`; `&0:int`]
       IQ_DIAG4_112C_REPRESENTATION_STEP) THEN
      REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC INT_REPRESENTS_112_ODD THEN ASM_REWRITE_TAC[];
        CONV_TAC INT_REDUCE_CONV;
        ARITH_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `n MOD 4 = 2` ASSUME_TAC THENL
     [MATCH_MP_TAC NUM_MOD4_NONZERO_NONODD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_CASES_TAC `n MOD 16 = 14` THENL
     [MP_TAC(SPEC `n:num` bad) THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(SPECL
       [`&c:int`; `n:num`; `n:num`; `0`; `&0:int`]
       IQ_DIAG4_112C_REPRESENTATION_STEP) THEN
      REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC INT_REPRESENTS_112_TWO THEN ASM_REWRITE_TAC[];
        CONV_TAC INT_REDUCE_CONV;
        ARITH_TAC]]));;

let NUM_MOD2_SUB_ODD = prove
 (`!n c:num.
     n MOD 2 = 0 /\ c MOD 2 = 1 /\ c <= n
     ==> (n - c) MOD 2 = 1`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `n = n DIV 2 * 2` ASSUME_TAC THENL
   [MP_TAC(SPECL [`n:num`; `2`] DIVISION) THEN
    CONV_TAC NUM_REDUCE_CONV THEN
    ASM_REWRITE_TAC[ADD_CLAUSES] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `c = c DIV 2 * 2 + 1` ASSUME_TAC THENL
   [MP_TAC(SPECL [`c:num`; `2`] DIVISION) THEN
    CONV_TAC NUM_REDUCE_CONV THEN ASM_REWRITE_TAC[] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `n - c = 2 * (n DIV 2 - c DIV 2 - 1) + 1`
  ASSUME_TAC THENL
   [ASM_ARITH_TAC;
    ASM_REWRITE_TAC[MOD_MULT_ADD] THEN CONV_TAC NUM_REDUCE_CONV]);;

