let IQ_UNIVERSAL_112_ODD_NUM = prove
 (`!c:num.
     c MOD 2 = 1 /\ 3 <= c /\ c <= 13
     ==> !n:num.
           0 < n
           ==> ?x y z w:int.
                 &1 * x pow 2 + &1 * y pow 2 +
