    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(SPECL
   [`&c:int`; `n:num`; `(n - c):num`; `c:num`; `&1:int`]
   IQ_DIAG4_112C_REPRESENTATION_STEP) THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC INT_REPRESENTS_112_ODD THEN
    MATCH_MP_TAC NUM_MOD2_SUB_ODD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC NUM_MOD2_OF_MOD16_14 THEN ASM_REWRITE_TAC[];
    CONV_TAC INT_RING;
    ASM_ARITH_TAC]);;

