   [`n:num`; `4`;
    `iqmat4 a (&0) (&0) (&0) b (&0) (&0) c (&0) d`;
    `iqdiag4 a b c d`; `A:num->num->int`] IQ_EMBEDS_EQ) THEN
  CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    REPEAT STRIP_TAC THEN
    (SUBGOAL_THEN `i = 0 \/ i = 1 \/ i = 2 \/ i = 3` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    (SUBGOAL_THEN `j = 0 \/ j = 1 \/ j = 2 \/ j = 3` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    REWRITE_TAC[iqmat4; iqsym; iqdiag4; iqdiag] THEN
    CONV_TAC NUM_REDUCE_CONV]);;

let INT_SQ_LE_14_CASES = prove
 (`!a:int.
     a pow 2 <= &14
     ==> a = -- &3 \/ a = -- &2 \/ a = -- &1 \/ a = &0 \/
         a = &1 \/ a = &2 \/ a = &3`,
  GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `abs a < &4` ASSUME_TAC THENL
   [MP_TAC(SPECL [`a:int`; `&4:int`] INT_LT_SQUARE_ABS) THEN
    REWRITE_TAC[INT_ABS_NUM] THEN
    CONV_TAC NUM_REDUCE_CONV THEN ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `abs a <= &3` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`a:int`; `&3:int`] INT_ABS_BOUNDS) THEN
  ASM_REWRITE_TAC[] THEN INT_ARITH_TAC);;

let INT_SQ_LE_28_CASES = prove
 (`!a:int.
     a pow 2 <= &28
     ==> a = -- &5 \/ a = -- &4 \/ a = -- &3 \/ a = -- &2 \/
         a = -- &1 \/ a = &0 \/ a = &1 \/ a = &2 \/
         a = &3 \/ a = &4 \/ a = &5`,
  GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `abs a < &6` ASSUME_TAC THENL
   [MP_TAC(SPECL [`a:int`; `&6:int`] INT_LT_SQUARE_ABS) THEN
    REWRITE_TAC[INT_ABS_NUM] THEN
    CONV_TAC NUM_REDUCE_CONV THEN ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `abs a <= &5` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`a:int`; `&5:int`] INT_ABS_BOUNDS) THEN
  ASM_REWRITE_TAC[] THEN INT_ARITH_TAC);;

let IQ_112_PARAMETERS = prove
 (`!a b c:int.
     a pow 2 <= &14 /\ b pow 2 <= &14 /\ c pow 2 <= &28
     ==> ?q r k.
          c = &2 * q + r /\
          k = &14 - a pow 2 - b pow 2 -
              &2 * q pow 2 - &2 * q * r /\
          ((r = &0 /\ (k < &0 \/ (&1 <= k /\ k <= &14))) \/
           (r = &1 /\
            (k <= &0 \/
             (&1 <= k /\ k <= &14 /\ ~(k rem &4 = &3)))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MAP_EVERY EXISTS_TAC
   [`c div &2:int`; `c rem &2:int`;
    `&14 - a pow 2 - b pow 2 -
     &2 * (c div &2) pow 2 - &2 * (c div &2) * (c rem &2):int`] THEN
  CONJ_TAC THENL
   [MP_TAC(SPEC `c:int` INT_DIV2_DECOMP) THEN MESON_TAC[];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [REFL_TAC;
    ALL_TAC] THEN
  MP_TAC(MATCH_MP INT_SQ_LE_14_CASES
    (ASSUME `a pow 2 <= &14`)) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  MP_TAC(MATCH_MP INT_SQ_LE_14_CASES
    (ASSUME `b pow 2 <= &14`)) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  MP_TAC(MATCH_MP INT_SQ_LE_28_CASES
    (ASSUME `c pow 2 <= &28`)) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  CONV_TAC INT_REDUCE_CONV);;

let IQ_EMBEDS_QUATERNARY_112 = prove
 (`!n A.
     iq_symmetric n A /\ iq_positive n A /\
     iq_embeds n 3
       (iqmat3 (&1) (&0) (&0) (&1) (&0) (&2)) A /\
     iq_represents n A (&14)
     ==> (?k.
            &1 <= k /\ k <= &14 /\
            iq_embeds n 4 (iqdiag4 (&1) (&1) (&2) k) A) \/
         (?k.
            &1 <= k /\ k <= &14 /\ ~(k rem &4 = &3) /\
            iq_embeds n 4
              (iqmat4 (&1) (&0) (&0) (&0)
                      (&1) (&0) (&0) (&2) (&1) k) A)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL
   [`n:num`; `A:num->num->int`;
    `&1:int`; `&0:int`; `&0:int`; `&1:int`; `&0:int`; `&2:int`;
    `&14:int`] IQ_ESCALATE_MAT3) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:int`
    (X_CHOOSE_THEN `b:int`
      (X_CHOOSE_THEN `c:int` STRIP_ASSUME_TAC))) THEN
  MP_TAC(SPECL [`a:int`; `b:int`; `c:int`] IQ_112_PARAMETERS) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `q:int`
    (X_CHOOSE_THEN `r:int`
      (X_CHOOSE_THEN `k:int`
        (CONJUNCTS_THEN2 ASSUME_TAC
          (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC))))) THEN
  SUBGOAL_THEN
   `iq_embeds n 4
      (iqmat4 (&1) (&0) (&0) a
              (&1) (&0) b (&2) (&2 * q + r) (&14)) A`
  ASSUME_TAC THENL
   [MATCH_ACCEPT_TAC(REWRITE_RULE[ASSUME `c = &2 * q + r`] (ASSUME
     `iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) a
               (&1) (&0) b (&2) c (&14)) A`));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `iq_embeds n 4
      (iqmat4 (&1) (&0) (&0) (&0)
              (&1) (&0) (&0) (&2) r k) A`
  ASSUME_TAC THENL
   [ONCE_REWRITE_TAC[ASSUME
     `k = &14 - a pow 2 - b pow 2 -
          &2 * q pow 2 - &2 * q * r`] THEN
    MATCH_MP_TAC IQ_EMBEDS_CLEAR_112 THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= k` ASSUME_TAC THENL
   [MP_TAC(MATCH_MP
     (ISPECL
       [`n:num`; `4`;
        `iqmat4 (&1) (&0) (&0) (&0)
                (&1) (&0) (&0) (&2) r k`;
        `A:num->num->int`] IQ_EMBEDDED_NONNEG)
     (CONJ (ASSUME `iq_positive n A`) (ASSUME
       `iq_embeds n 4
        (iqmat4 (&1) (&0) (&0) (&0)
                (&1) (&0) (&0) (&2) r k) A`))) THEN
    DISCH_THEN(MP_TAC o SPEC
      `\i:num. if i = 3 then &1 else &0`) THEN
    REWRITE_TAC[IQEVAL_MAT4] THEN
    CONV_TAC NUM_REDUCE_CONV THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `r = &1 ==> &1 <= k` ASSUME_TAC THENL
   [DISCH_TAC THEN
    MP_TAC(MATCH_MP
     (ISPECL
       [`n:num`; `4`;
        `iqmat4 (&1) (&0) (&0) (&0)
                (&1) (&0) (&0) (&2) r k`;
        `A:num->num->int`] IQ_EMBEDDED_NONNEG)
     (CONJ (ASSUME `iq_positive n A`) (ASSUME
       `iq_embeds n 4
        (iqmat4 (&1) (&0) (&0) (&0)
                (&1) (&0) (&0) (&2) r k) A`))) THEN
    DISCH_THEN(MP_TAC o SPEC
      `\i:num.
         if i = 2 then -- &1 else if i = 3 then &2 else &0`) THEN
    ASM_REWRITE_TAC[IQEVAL_MAT4] THEN
    CONV_TAC NUM_REDUCE_CONV THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  UNDISCH_TAC
   `(r = &0 /\ (k < &0 \/ (&1 <= k /\ k <= &14))) \/
    (r = &1 /\
     (k <= &0 \/ (&1 <= k /\ k <= &14 /\ ~(k rem &4 = &3))))` THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN STRIP_ASSUME_TAC) THENL
   [ASM_INT_ARITH_TAC;
    DISJ1_TAC THEN EXISTS_TAC `k:int` THEN
    CONJ_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    CONJ_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC IQ_EMBEDS_MAT4_DIAG THEN
    MATCH_ACCEPT_TAC(REWRITE_RULE[ASSUME `r = &0`] (ASSUME
      `iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&1) (&0) (&0) (&2) r k) A`));
    ASM_INT_ARITH_TAC;
    DISJ2_TAC THEN EXISTS_TAC `k:int` THEN
    CONJ_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    CONJ_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    CONJ_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_ACCEPT_TAC(REWRITE_RULE[ASSUME `r = &1`] (ASSUME
      `iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&1) (&0) (&0) (&2) r k) A`))]);;

(* ------------------------------------------------------------------------- *)
(* Diagonal children.                                                        *)
(* ------------------------------------------------------------------------- *)

let IQ_UNIVERSAL_1121_NUM = prove
 (`!n:num.
     0 < n
     ==> ?x y z w:int.
           &1 * x pow 2 + &1 * y pow 2 +
           &2 * z pow 2 + &1 * w pow 2 = &n`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(MATCH_MP IQ_UNIVERSAL_1112_NUM (ASSUME `0 < n`)) THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int`
      (X_CHOOSE_THEN `z:int` (X_CHOOSE_TAC `w:int`)))) THEN
  MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `w:int`; `z:int`] THEN
  FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING);;

let IQ_UNIVERSAL_1121 = prove
 (`iq_universal 4 (iqdiag4 (&1) (&1) (&2) (&1))`,
  MATCH_MP_TAC IQ_UNIVERSAL_DIAG4_OF_NUM THEN
  ACCEPT_TAC IQ_UNIVERSAL_1121_NUM);;

let IQ_UNIVERSAL_OF_DIAG112_CHILD = prove
 (`!n A k.
     iq_embeds n 4 (iqdiag4 (&1) (&1) (&2) k) A /\
     &1 <= k /\ k <= &14
     ==> iq_universal n A`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `4`; `iqdiag4 (&1) (&1) (&2) k`;
    `A:num->num->int`] IQ_UNIVERSAL_OF_EMBEDS) THEN
  CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `k = &1 \/ k = &2 \/ k = &3 \/ k = &4 \/ k = &5 \/
    k = &6 \/ k = &7 \/ k = &8 \/ k = &9 \/ k = &10 \/
    k = &11 \/ k = &12 \/ k = &13 \/ k = &14`
  ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  UNDISCH_TAC
   `k = &1 \/ k = &2 \/ k = &3 \/ k = &4 \/ k = &5 \/
    k = &6 \/ k = &7 \/ k = &8 \/ k = &9 \/ k = &10 \/
    k = &11 \/ k = &12 \/ k = &13 \/ k = &14` THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  ASM_REWRITE_TAC
   [IQ_UNIVERSAL_1121; IQ_UNIVERSAL_1122; IQ_UNIVERSAL_1123;
    IQ_UNIVERSAL_1124; IQ_UNIVERSAL_1125; IQ_UNIVERSAL_1126;
    IQ_UNIVERSAL_1127; IQ_UNIVERSAL_1128; IQ_UNIVERSAL_1129;
    IQ_UNIVERSAL_11210; IQ_UNIVERSAL_11211; IQ_UNIVERSAL_11212;
    IQ_UNIVERSAL_11213; IQ_UNIVERSAL_11214]);;

(* ------------------------------------------------------------------------- *)
(* Cross children x^2 + y^2 + 2z^2 + 2zw + k w^2.                           *)
(* ------------------------------------------------------------------------- *)

let NUM_CROSS112_TARGET_AVOIDS = prove
 (`!n k:num.
     n MOD 16 = 14 /\ k <= n /\ ~(k MOD 4 = 3)
     ==> ~((2 * (n - k) + 1) MOD 4 = 0) /\
         ~((2 * (n - k) + 1) MOD 8 = 7)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `n MOD 4 = 2` ASSUME_TAC THENL
   [SUBGOAL_THEN `(n MOD 16) MOD 4 = n MOD 4` MP_TAC THENL
     [REWRITE_TAC[ARITH_RULE `16 = 4 * 4`; MOD_MOD];
      ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN ARITH_TAC];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP (SPECL [`n:num`; `4`; `2`] NUM_DECOMPOSE_MOD)
    (CONJ (ARITH_RULE `~(4 = 0)`)
      (ASSUME `n MOD 4 = 2`))) THEN
  DISCH_THEN(X_CHOOSE_TAC `qn:num`) THEN
  MP_TAC(SPEC `k:num` MOD4_CASES) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [MP_TAC(MATCH_MP (SPECL [`k:num`; `4`; `0`] NUM_DECOMPOSE_MOD)
      (CONJ (ARITH_RULE `~(4 = 0)`)
        (ASSUME `k MOD 4 = 0`))) THEN
    DISCH_THEN(X_CHOOSE_TAC `qk:num`) THEN
    SUBGOAL_THEN `(qk:num) <= qn` ASSUME_TAC THENL
     [MATCH_MP_TAC(ARITH_RULE
       `4 * qk + 0 <= 4 * qn + 2 ==> qk <= qn`) THEN
      REWRITE_TAC[GSYM(ASSUME `n = 4 * qn + 2`);
        GSYM(ASSUME `k = 4 * qk + 0`)] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `n - k = 4 * (qn - qk) + 2` SUBST1_TAC THENL
     [ONCE_REWRITE_TAC[ASSUME `n = 4 * qn + 2`] THEN
      ONCE_REWRITE_TAC[ASSUME `k = 4 * qk + 0`] THEN
      MATCH_MP_TAC(ARITH_RULE
       `qk <= qn
        ==> (4 * qn + 2) - (4 * qk + 0) = 4 * (qn - qk) + 2`) THEN
      ASM_REWRITE_TAC[ASSUME `(qk:num) <= qn`];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC
       [ARITH_RULE `2 * (4 * d + 2) + 1 = 4 * (2 * d + 1) + 1`;
        MOD_MULT_ADD] THEN CONV_TAC NUM_REDUCE_CONV;
      REWRITE_TAC
       [ARITH_RULE `2 * (4 * d + 2) + 1 = 8 * d + 5`;
        MOD_MULT_ADD] THEN CONV_TAC NUM_REDUCE_CONV];
    MP_TAC(MATCH_MP (SPECL [`k:num`; `4`; `1`] NUM_DECOMPOSE_MOD)
      (CONJ (ARITH_RULE `~(4 = 0)`)
        (ASSUME `k MOD 4 = 1`))) THEN
    DISCH_THEN(X_CHOOSE_TAC `qk:num`) THEN
    SUBGOAL_THEN `(qk:num) <= qn` ASSUME_TAC THENL
     [MATCH_MP_TAC(ARITH_RULE
       `4 * qk + 1 <= 4 * qn + 2 ==> qk <= qn`) THEN
      REWRITE_TAC[GSYM(ASSUME `n = 4 * qn + 2`);
        GSYM(ASSUME `k = 4 * qk + 1`)] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `n - k = 4 * (qn - qk) + 1` SUBST1_TAC THENL
     [ONCE_REWRITE_TAC[ASSUME `n = 4 * qn + 2`] THEN
      ONCE_REWRITE_TAC[ASSUME `k = 4 * qk + 1`] THEN
      MATCH_MP_TAC(ARITH_RULE
       `qk <= qn
        ==> (4 * qn + 2) - (4 * qk + 1) = 4 * (qn - qk) + 1`) THEN
      ASM_REWRITE_TAC[ASSUME `(qk:num) <= qn`];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC
       [ARITH_RULE `2 * (4 * d + 1) + 1 = 4 * (2 * d) + 3`;
        MOD_MULT_ADD] THEN CONV_TAC NUM_REDUCE_CONV;
      REWRITE_TAC
       [ARITH_RULE `2 * (4 * d + 1) + 1 = 8 * d + 3`;
        MOD_MULT_ADD] THEN CONV_TAC NUM_REDUCE_CONV];
    MP_TAC(MATCH_MP (SPECL [`k:num`; `4`; `2`] NUM_DECOMPOSE_MOD)
      (CONJ (ARITH_RULE `~(4 = 0)`)
        (ASSUME `k MOD 4 = 2`))) THEN
    DISCH_THEN(X_CHOOSE_TAC `qk:num`) THEN
    SUBGOAL_THEN `(qk:num) <= qn` ASSUME_TAC THENL
     [MATCH_MP_TAC(ARITH_RULE
       `4 * qk + 2 <= 4 * qn + 2 ==> qk <= qn`) THEN
      REWRITE_TAC[GSYM(ASSUME `n = 4 * qn + 2`);
        GSYM(ASSUME `k = 4 * qk + 2`)] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `n - k = 4 * (qn - qk)` SUBST1_TAC THENL
     [ONCE_REWRITE_TAC[ASSUME `n = 4 * qn + 2`] THEN
      ONCE_REWRITE_TAC[ASSUME `k = 4 * qk + 2`] THEN
      MATCH_MP_TAC(ARITH_RULE
       `qk <= qn
        ==> (4 * qn + 2) - (4 * qk + 2) = 4 * (qn - qk)`) THEN
      ASM_REWRITE_TAC[ASSUME `(qk:num) <= qn`];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC
       [ARITH_RULE `2 * (4 * d) + 1 = 4 * (2 * d) + 1`;
        MOD_MULT_ADD] THEN CONV_TAC NUM_REDUCE_CONV;
      REWRITE_TAC
       [ARITH_RULE `2 * (4 * d) + 1 = 8 * d + 1`;
        MOD_MULT_ADD] THEN CONV_TAC NUM_REDUCE_CONV];
    ASM_MESON_TAC[]]);;

let INT_REPRESENTS_CROSS112_BAD = prove
 (`!k n:num.
     1 <= k /\ k <= 14 /\ ~(k MOD 4 = 3) /\ n MOD 16 = 14
     ==> ?x y z:int.
          x pow 2 + y pow 2 + &2 * z pow 2 + &2 * z + &k = &n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `14 <= n` ASSUME_TAC THENL
   [MP_TAC(SPECL [`n:num`; `16`; `14`] NUM_DECOMPOSE_MOD) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
    DISCH_THEN(X_CHOOSE_TAC `q:num`) THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(k:num) <= n` ASSUME_TAC THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(MATCH_MP REPR_122_OF_THREE_SQUARES
    (MATCH_MP INT_THREE_SQUARES_OF_MOD
      (MATCH_MP (SPECL [`n:num`; `k:num`] NUM_CROSS112_TARGET_AVOIDS)
        (CONJ (ASSUME `n MOD 16 = 14`)
          (CONJ (ASSUME `(k:num) <= n`)
            (ASSUME `~(k MOD 4 = 3)`)))))) THEN
  DISCH_THEN(X_CHOOSE_THEN `u:int`
    (X_CHOOSE_THEN `x:int` (X_CHOOSE_THEN `y:int` ASSUME_TAC))) THEN
  SUBGOAL_THEN
   `u pow 2 + &2 * x pow 2 + &2 * y pow 2 =
    &2 * (&n - &k) + &1`
  ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC) THEN
    ASM_SIMP_TAC[INT_OF_NUM_ADD; INT_OF_NUM_MUL; INT_OF_NUM_SUB];
    ALL_TAC] THEN
  MP_TAC(SPEC `u:int` INT_PARITY_WITNESS) THEN
  DISCH_THEN(DISJ_CASES_THEN (X_CHOOSE_TAC `z:int`)) THENL
   [SUBGOAL_THEN
     `&2 * (&2 * z pow 2 + x pow 2 + y pow 2 - (&n - &k)) = &1`
    ASSUME_TAC THENL
     [MATCH_ACCEPT_TAC
       (MATCH_MP
         (MATCH_MP
           (INT_RING
             `u = &2 * z
              ==> u pow 2 + &2 * x pow 2 + &2 * y pow 2 =
                  &2 * (nn - kk) + &1
              ==> &2 *
                  (&2 * z pow 2 + x pow 2 + y pow 2 - (nn - kk)) =
                  &1`)
           (ASSUME `u = &2 * z`))
         (ASSUME
           `u pow 2 + &2 * x pow 2 + &2 * y pow 2 =
            &2 * (&n - &k) + &1`));
      MP_TAC(SPEC
       `&2 * z pow 2 + x pow 2 + y pow 2 - (&n - &k):int`
       INT_TWO_MUL_NE_ONE) THEN ASM_REWRITE_TAC[]];
    MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`] THEN
    MATCH_ACCEPT_TAC
     (MATCH_MP
       (MATCH_MP
         (INT_RING
           `u = &2 * z + &1
            ==> u pow 2 + &2 * x pow 2 + &2 * y pow 2 =
                &2 * (nn - kk) + &1
            ==> x pow 2 + y pow 2 + &2 * z pow 2 + &2 * z + kk =
                nn`)
         (ASSUME `u = &2 * z + &1`))
       (ASSUME
         `u pow 2 + &2 * x pow 2 + &2 * y pow 2 =
          &2 * (&n - &k) + &1`))]);;

let INT_UNIVERSAL_CROSS112_NUM = prove
 (`!k:num.
     1 <= k /\ k <= 14 /\ ~(k MOD 4 = 3)
     ==> !n:num.
          0 < n
          ==> ?x y z w:int.
               x pow 2 + y pow 2 + &2 * z pow 2 +
               &2 * z * w + &k * w pow 2 = &n`,
  GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC num_WF THEN X_GEN_TAC `n:num` THEN
  DISCH_TAC THEN DISCH_TAC THEN
  ASM_CASES_TAC `n MOD 4 = 0` THENL
   [SUBGOAL_THEN `n = 4 * (n DIV 4)` SUBST1_TAC THENL
     [MP_TAC(SPECL [`n:num`; `4`] DIVISION) THEN
      CONV_TAC NUM_REDUCE_CONV THEN
      ASM_REWRITE_TAC[ADD_CLAUSES] THEN ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `n DIV 4 < n /\ 0 < n DIV 4` STRIP_ASSUME_TAC THENL
     [MP_TAC(SPECL [`n:num`; `4`] DIVISION) THEN
      CONV_TAC NUM_REDUCE_CONV THEN
      ASM_REWRITE_TAC[ADD_CLAUSES] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    MP_TAC(MATCH_MP
      (MATCH_MP
        (SPEC `n DIV 4` (ASSUME
         `!m. m < n
              ==> 0 < m
              ==> ?x y z w:int.
                   x pow 2 + y pow 2 + &2 * z pow 2 +
                   &2 * z * w + &k * w pow 2 = &m`))
        (ASSUME `n DIV 4 < n`))
      (ASSUME `0 < n DIV 4`)) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:int`
      (X_CHOOSE_THEN `y:int`
        (X_CHOOSE_THEN `z:int` (X_CHOOSE_TAC `w:int`)))) THEN
    MAP_EVERY EXISTS_TAC
     [`&2 * x:int`; `&2 * y:int`; `&2 * z:int`; `&2 * w:int`] THEN
    FIRST_X_ASSUM(MP_TAC) THEN
    REWRITE_TAC[GSYM INT_OF_NUM_MUL] THEN CONV_TAC INT_RING;
    ALL_TAC] THEN
  ASM_CASES_TAC `n MOD 2 = 1` THENL
   [MP_TAC(MATCH_MP INT_REPRESENTS_112_ODD
      (ASSUME `n MOD 2 = 1`)) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:int`
      (X_CHOOSE_THEN `y:int` (X_CHOOSE_TAC `z:int`))) THEN
    MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`; `&0:int`] THEN
    FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN `n MOD 4 = 2` ASSUME_TAC THENL
   [MATCH_MP_TAC NUM_MOD4_NONZERO_NONODD THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
