  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int`
      (X_CHOOSE_THEN `z:int` (X_CHOOSE_TAC `w:int`)))) THEN
  MAP_EVERY EXISTS_TAC [`x:int`; `z:int`; `w:int`; `y:int`] THEN
  FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING);;

let IQ_UNIVERSAL_1221 = prove
 (`iq_universal 4
    (iqmat4 (&1) (&0) (&0) (&0)
            (&2) (&0) (&0) (&2) (&0) (&1))`,
  REWRITE_TAC[iq_universal] THEN
  X_GEN_TAC `m:int` THEN DISCH_TAC THEN
  MP_TAC(EQ_MP (SYM(SPEC `m:int` INT_OF_NUM_EXISTS))
    (MATCH_MP (SPECL [`&0:int`; `m:int`] INT_LT_IMP_LE)
      (ASSUME `&0 < m`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `n:num` SUBST_ALL_TAC) THEN
  MP_TAC(MATCH_MP IQ_UNIVERSAL_1221_NUM
    (REWRITE_RULE[INT_OF_NUM_LT] (ASSUME `&0 < &n`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int`
      (X_CHOOSE_THEN `z:int` (X_CHOOSE_TAC `w:int`)))) THEN
  REWRITE_TAC[iq_represents] THEN
  EXISTS_TAC
   `\i:num.
      if i = 0 then (x:int) else if i = 1 then y else
      if i = 2 then z else w` THEN
  REWRITE_TAC[IQEVAL_MAT4] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING);;

let IQ_UNIVERSAL_MAT4_DIAG = prove
 (`!a b c d.
     iq_universal 4 (iqdiag4 a b c d)
     ==> iq_universal 4
          (iqmat4 a (&0) (&0) (&0)
                  b (&0) (&0) c (&0) d)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[iq_universal] THEN
  DISCH_TAC THEN X_GEN_TAC `m:int` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `m:int`) THEN
  ASM_REWRITE_TAC[iq_represents] THEN
  DISCH_THEN(X_CHOOSE_THEN `x:num->int` ASSUME_TAC) THEN
  EXISTS_TAC `x:num->int` THEN
  ONCE_REWRITE_TAC[GSYM(ASSUME
    `iqeval 4 (iqdiag4 a b c d) x = m`)] THEN
  REWRITE_TAC[IQEVAL_MAT4; IQEVAL_DIAG4] THEN
  CONV_TAC INT_RING);;

let IQ_UNIVERSAL_MAT1222 =
