let IQ_UNIVERSAL_OF_DIAG122_CHILD = prove
 (`!n A k.
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&0) (&0) (&2) (&0) k) A /\
     &1 <= k /\ k <= &7
     ==> iq_universal n A`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `4`;
    `iqmat4 (&1) (&0) (&0) (&0)
            (&2) (&0) (&0) (&2) (&0) k`;
    `A:num->num->int`] IQ_UNIVERSAL_OF_EMBEDS) THEN
  CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `k = &1 \/ k = &2 \/ k = &3 \/ k = &4 \/
    k = &5 \/ k = &6 \/ k = &7`
  ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  UNDISCH_TAC
   `k = &1 \/ k = &2 \/ k = &3 \/ k = &4 \/
    k = &5 \/ k = &6 \/ k = &7` THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  ASM_REWRITE_TAC
   [IQ_UNIVERSAL_1221; IQ_UNIVERSAL_MAT1222;
    IQ_UNIVERSAL_MAT1223; IQ_UNIVERSAL_MAT1224;
    IQ_UNIVERSAL_MAT1225; IQ_UNIVERSAL_MAT1226;
    IQ_UNIVERSAL_MAT1227]);;

