  DISCH_THEN(MP_TAC o SPEC `n:num`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int`
      (X_CHOOSE_THEN `z:int` (X_CHOOSE_TAC `w:int`)))) THEN
  MAP_EVERY EXISTS_TAC [`x:int`; `z:int`; `y:int`; `w:int`] THEN
  FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING);;

