  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      UNDISCH_TAC `&0 < &n` THEN REWRITE_TAC[INT_OF_NUM_LT]];
    DISCH_THEN(X_CHOOSE_THEN `x:int`
      (X_CHOOSE_THEN `y:int`
        (X_CHOOSE_THEN `z:int` (X_CHOOSE_TAC `w:int`)))) THEN
    REWRITE_TAC[iq_represents] THEN
    EXISTS_TAC
     `\i:num.
        if i = 0 then (x:int) else if i = 1 then y else
        if i = 2 then z else w` THEN
    REWRITE_TAC[IQEVAL_MAT4] THEN
    CONV_TAC NUM_REDUCE_CONV THEN
    FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING]);;

let IQ_UNIVERSAL_OF_CROSSA122_Y_CHILD = prove
 (`!n A k.
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&0) (&1) (&2) (&0) k) A /\
     &1 <= k /\ k <= &7
     ==> iq_universal n A`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(EQ_MP (SYM(SPEC `k:int` INT_OF_NUM_EXISTS))
    (MATCH_MP (INT_ARITH `&1 <= k ==> &0 <= k`)
      (ASSUME `&1 <= k`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `c:num` SUBST_ALL_TAC) THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `4`;
    `iqmat4 (&1) (&0) (&0) (&0)
            (&2) (&0) (&1) (&2) (&0) (&c)`;
    `A:num->num->int`] IQ_UNIVERSAL_OF_EMBEDS) THEN
  CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    MATCH_MP_TAC(SPEC `c:num` IQ_UNIVERSAL_CROSSA122_Y_NUM) THEN
    UNDISCH_TAC `&1 <= &c` THEN
    UNDISCH_TAC `&c <= &7` THEN
    REWRITE_TAC[INT_OF_NUM_LE] THEN ARITH_TAC]);;

