  DISCH_THEN(DISJ_CASES_THEN (X_CHOOSE_TAC `u:int`)) THEN
  MP_TAC(SPEC `b:int` INT_PARITY_WITNESS) THEN
  DISCH_THEN(DISJ_CASES_THEN (X_CHOOSE_TAC `v:int`)) THEN
  MP_TAC(SPEC `c:int` INT_PARITY_WITNESS) THEN
  DISCH_THEN(DISJ_CASES_THEN (X_CHOOSE_TAC `w:int`)) THENL
   [MATCH_MP_TAC(SPECL [`m:int`; `a:int`; `b:int`; `c:int`]
      INT_PATTERN123_OF_SLOTS) THEN
    REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[INT_REM_MUL; INT_REM_MUL_ADD] THEN
      CONV_TAC INT_REDUCE_CONV;
      ASM_REWRITE_TAC[INT_REM_MUL; INT_REM_MUL_ADD] THEN
      CONV_TAC INT_REDUCE_CONV;
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]];
    ASM_MESON_TAC[INT_EVEN_EVEN_ODD_SQUARES_NE_DOUBLE;
      INT_RING `&6*m = &2 * (&3*m)`];
    ASM_MESON_TAC[INT_EVEN_ODD_EVEN_SQUARES_NE_DOUBLE;
      INT_RING `&6*m = &2 * (&3*m)`];
    MATCH_MP_TAC(SPECL [`m:int`; `b:int`; `c:int`; `a:int`]
      INT_PATTERN123_OF_SLOTS) THEN
    REPEAT CONJ_TAC THENL
     [MP_TAC(ASSUME `a pow 2 + b pow 2 + c pow 2 = &6*m`) THEN
