      ASM_REWRITE_TAC[INT_REM_MUL; INT_REM_MUL_ADD] THEN
      CONV_TAC INT_REDUCE_CONV;
      ASM_REWRITE_TAC[INT_REM_MUL; INT_REM_MUL_ADD] THEN
      CONV_TAC INT_REDUCE_CONV;
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]];
    ASM_MESON_TAC[INT_ONE_ODD_SQUARES_NE_DOUBLE;
      INT_RING `&6*m = &2 * (&3*m)`];
    MATCH_MP_TAC(SPECL [`m:int`; `a:int`; `c:int`; `b:int`]
      INT_PATTERN123_OF_SLOTS) THEN
    REPEAT CONJ_TAC THENL
     [MP_TAC(ASSUME `a pow 2 + b pow 2 + c pow 2 = &6*m`) THEN
      CONV_TAC INT_RING;
      ASM_REWRITE_TAC[INT_REM_MUL; INT_REM_MUL_ADD] THEN
      CONV_TAC INT_REDUCE_CONV;
      ASM_REWRITE_TAC[INT_REM_MUL; INT_REM_MUL_ADD] THEN
      CONV_TAC INT_REDUCE_CONV;
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]];
    MATCH_MP_TAC(SPECL [`m:int`; `a:int`; `b:int`; `c:int`]
      INT_PATTERN123_OF_SLOTS) THEN
    REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[INT_REM_MUL; INT_REM_MUL_ADD] THEN
      CONV_TAC INT_REDUCE_CONV;
      ASM_REWRITE_TAC[INT_REM_MUL; INT_REM_MUL_ADD] THEN
      CONV_TAC INT_REDUCE_CONV;
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]];
    ASM_MESON_TAC[INT_THREE_ODD_SQUARES_NE_DOUBLE;
      INT_RING `&6*m = &2 * (&3*m)`]]);;

let NUM_TRIPLE_EQ_16B14_MOD16 = prove
 (`!m b:num. 3*m = 16*b+14 ==> m MOD 16 = 10`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `b MOD 3 = 1` ASSUME_TAC THENL
   [SUBGOAL_THEN
     `b MOD 3 = 0 \/ b MOD 3 = 1 \/ b MOD 3 = 2`
    MP_TAC THENL
     [MP_TAC(SPECL [`b:num`; `3`] DIVISION) THEN
      CONV_TAC NUM_REDUCE_CONV THEN ARITH_TAC;
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
       [UNDISCH_TAC `3*m = 16*b+14` THEN
        DISCH_THEN(MP_TAC o AP_TERM `\x:num. x MOD 3`) THEN
        BETA_TAC THEN
        REWRITE_TAC[MOD_MULT;
          ARITH_RULE `16*b+14 = 3*(5*b+4)+(b+2)`;
          MOD_MULT_ADD] THEN
        ONCE_REWRITE_TAC[GSYM MOD_ADD_MOD] THEN
        ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV;
        ASM_REWRITE_TAC[];
        UNDISCH_TAC `3*m = 16*b+14` THEN
        DISCH_THEN(MP_TAC o AP_TERM `\x:num. x MOD 3`) THEN
        BETA_TAC THEN
        REWRITE_TAC[MOD_MULT;
          ARITH_RULE `16*b+14 = 3*(5*b+4)+(b+2)`;
          MOD_MULT_ADD] THEN
        ONCE_REWRITE_TAC[GSYM MOD_ADD_MOD] THEN
        ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV]];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP (SPECL [`b:num`; `3`; `1`] NUM_DECOMPOSE_MOD)
    (CONJ (ARITH_RULE `~(3 = 0)`) (ASSUME `b MOD 3 = 1`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `q:num` SUBST_ALL_TAC) THEN
  SUBGOAL_THEN `m = 16*q+10` SUBST1_TAC THENL
   [UNDISCH_TAC `3*m = 16*(3*q+1)+14` THEN ARITH_TAC;
    REWRITE_TAC[MOD_MULT_ADD] THEN CONV_TAC NUM_REDUCE_CONV]);;

let NUM_6M_EQ_16T_IMP_DIV4 = prove
 (`!m t:num. 6*m = 16*t ==> 4 divides m`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `t MOD 3 = 0` ASSUME_TAC THENL
   [UNDISCH_TAC `6*m = 16*t` THEN
    DISCH_THEN(MP_TAC o AP_TERM `\x:num. x MOD 3`) THEN
    BETA_TAC THEN
    REWRITE_TAC
     [ARITH_RULE `6*m = 3*(2*m)+0`;
      ARITH_RULE `16*t = 3*(5*t)+t`;
      MOD_MULT_ADD] THEN
    CONV_TAC NUM_REDUCE_CONV THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP (SPECL [`t:num`; `3`; `0`] NUM_DECOMPOSE_MOD)
    (CONJ (ARITH_RULE `~(3 = 0)`) (ASSUME `t MOD 3 = 0`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `q:num` SUBST_ALL_TAC) THEN
  REWRITE_TAC[divides] THEN EXISTS_TAC `2*q:num` THEN
  ASM_ARITH_TAC);;

let NUM_6M_AVOIDS_THREE_SQUARE_FORM = prove
 (`!m:num.
     ~(4 divides m) /\ ~(m MOD 16 = 10)
     ==> ~(?a b. 6*m = 4 EXP a * (8*b+7))`,
  GEN_TAC THEN STRIP_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `a:num`
    (X_CHOOSE_THEN `b:num` ASSUME_TAC)) THEN
  ASM_CASES_TAC `a = 0` THENL
   [UNDISCH_TAC `6*m = 4 EXP a * (8*b+7)` THEN
    ASM_REWRITE_TAC[EXP; MULT_CLAUSES] THEN
    DISCH_THEN(MP_TAC o AP_TERM `\x:num. x MOD 2`) THEN
    BETA_TAC THEN
    REWRITE_TAC
     [ARITH_RULE `6*m = 2*(3*m)+0`;
      ARITH_RULE `8*b+7 = 2*(4*b+3)+1`;
      MOD_MULT_ADD] THEN
    CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  MP_TAC(SPEC `a:num` num_CASES) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:num` SUBST_ALL_TAC) THEN
  ASM_CASES_TAC `d = 0` THENL
   [SUBGOAL_THEN `m MOD 16 = 10` MP_TAC THENL
     [MATCH_MP_TAC(SPECL [`m:num`; `b:num`]
        NUM_TRIPLE_EQ_16B14_MOD16) THEN
      UNDISCH_TAC `6*m = 4 EXP SUC d * (8*b+7)` THEN
      ASM_REWRITE_TAC[EXP; MULT_CLAUSES] THEN ARITH_TAC;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(SPEC `d:num` num_CASES) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:num` SUBST_ALL_TAC) THEN
  SUBGOAL_THEN `4 divides m` MP_TAC THENL
   [MATCH_MP_TAC(SPECL
      [`m:num`; `4 EXP e * (8*b+7)`]
      NUM_6M_EQ_16T_IMP_DIV4) THEN
    UNDISCH_TAC `6*m = 4 EXP SUC (SUC e) * (8*b+7)` THEN
    REWRITE_TAC[EXP] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    CONV_TAC NUM_RING;
    ASM_REWRITE_TAC[]]);;

let INT_REPR123_CORE = prove
 (`!m:num.
     ~(3 divides m) /\ ~(4 divides m) /\ ~(m MOD 16 = 10)
     ==> ?x y z:int. x pow 2 + &2*y pow 2 + &3*z pow 2 = &m`,
  GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP (SPEC `6*m` INT_THREE_SQUARES_OF_LEGENDRE)
    (MATCH_MP (SPEC `m:num` NUM_6M_AVOIDS_THREE_SQUARE_FORM)
      (CONJ (ASSUME `~(4 divides m)`)
        (ASSUME `~(m MOD 16 = 10)`)))) THEN
  DISCH_THEN(X_CHOOSE_THEN `a:int`
    (X_CHOOSE_THEN `b:int` (X_CHOOSE_THEN `c:int` ASSUME_TAC))) THEN
  SUBGOAL_THEN
   `a pow 2 + b pow 2 + c pow 2 = &6 * &m`
  ASSUME_TAC THENL
   [MP_TAC(ASSUME `a pow 2 + b pow 2 + c pow 2 = &(6*m)`) THEN
    REWRITE_TAC[INT_OF_NUM_MUL];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(&3 divides &m)` ASSUME_TAC THENL
   [UNDISCH_TAC `~(3 divides m)` THEN REWRITE_TAC[num_divides];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
    (SPECL [`&m:int`; `a:int`; `b:int`; `c:int`]
      INT_EXISTS_PATTERN123)
    (CONJ (ASSUME `~(&3 divides &m)`)
      (ASSUME `a pow 2 + b pow 2 + c pow 2 = &6 * &m`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `A:int`
    (X_CHOOSE_THEN `B:int`
      (X_CHOOSE_THEN `C:int` STRIP_ASSUME_TAC))) THEN
  MATCH_MP_TAC(SPECL [`&m:int`; `A:int`; `B:int`; `C:int`]
    INT_REPR123_OF_PATTERN) THEN
  ASM_REWRITE_TAC[]);;

let INT_REPR123_THREE_MUL = prove
 (`!u:num.
     ~(?a b. 2*u = 4 EXP a * (8*b+7))
     ==> ?x y z:int.
          x pow 2 + &2*y pow 2 + &3*z pow 2 = &(3*u)`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(MATCH_MP (SPEC `u:num` INT_REPRESENTS_112_OF_LEGENDRE)
    (ASSUME `~(?a b. 2*u = 4 EXP a * (8*b+7))`)) THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int` (X_CHOOSE_TAC `z:int`))) THEN
  MAP_EVERY EXISTS_TAC [`y + &2*z:int`; `y - z:int`; `x:int`] THEN
  MP_TAC(ASSUME `x pow 2 + y pow 2 + &2*z pow 2 = &u`) THEN
  REWRITE_TAC[GSYM INT_OF_NUM_MUL] THEN CONV_TAC INT_RING);;

let REGULAR_123_NOT_FORM = prove
 (`!n:num.
     ~(?a b. n = 4 EXP a * (16*b+10))
     ==> ?x y z:int. x pow 2 + &2*y pow 2 + &3*z pow 2 = &n`,
  MATCH_MP_TAC num_WF THEN X_GEN_TAC `n:num` THEN
  DISCH_TAC THEN DISCH_TAC THEN
  ASM_CASES_TAC `n = 0` THENL
   [MAP_EVERY EXISTS_TAC [`&0:int`; `&0:int`; `&0:int`] THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING;
    ALL_TAC] THEN
  ASM_CASES_TAC `4 divides n` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `q:num` ASSUME_TAC o
      REWRITE_RULE[divides]) THEN
    SUBGOAL_THEN `(q:num) < (n:num)` ASSUME_TAC THENL
     [MATCH_MP_TAC(SPECL [`n:num`; `q:num`]
       (ARITH_RULE
        `!n q:num. n = 4*q /\ ~(n = 0) ==> q < n`)) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `~(?a b. q = 4 EXP a * (16*b+10))`
    ASSUME_TAC THENL
     [REWRITE_TAC[NOT_EXISTS_THM] THEN
      MAP_EVERY X_GEN_TAC [`a:num`; `b:num`] THEN DISCH_TAC THEN
      UNDISCH_TAC `~(?a b. n = 4 EXP a * (16*b+10))` THEN
      REWRITE_TAC[] THEN MAP_EVERY EXISTS_TAC [`SUC a`; `b:num`] THEN
      ASM_REWRITE_TAC[EXP; GSYM MULT_ASSOC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `?x y z:int. x pow 2 + &2*y pow 2 + &3*z pow 2 = &q`
    MP_TAC THENL
     [MATCH_MP_TAC(MATCH_MP
       (SPEC `q:num` (ASSUME
        `!m. m < n
             ==> ~(?a b. m = 4 EXP a * (16*b+10))
             ==> ?x y z:int.
                  x pow 2 + &2*y pow 2 + &3*z pow 2 = &m`))
       (ASSUME `(q:num) < (n:num)`)) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `x:int`
      (X_CHOOSE_THEN `y:int` (X_CHOOSE_TAC `z:int`))) THEN
    MAP_EVERY EXISTS_TAC [`&2*x:int`; `&2*y:int`; `&2*z:int`] THEN
    MP_TAC(ASSUME `x pow 2 + &2*y pow 2 + &3*z pow 2 = &q`) THEN
    SUBGOAL_THEN `&n = &4 * &q:int` ASSUME_TAC THENL
     [MP_TAC(AP_TERM `\r:num. &r:int` (ASSUME `n = 4*q`)) THEN
      REWRITE_TAC[INT_OF_NUM_MUL];
      ALL_TAC] THEN
    ONCE_REWRITE_TAC[ASSUME `&n = &4 * &q`] THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  ASM_CASES_TAC `3 divides n` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `u:num` ASSUME_TAC o
      REWRITE_RULE[divides]) THEN
    SUBGOAL_THEN `~(?a b. 2*u = 4 EXP a * (8*b+7))`
    ASSUME_TAC THENL
     [REWRITE_TAC[NOT_EXISTS_THM] THEN
      MAP_EVERY X_GEN_TAC [`a:num`; `b:num`] THEN DISCH_TAC THEN
      ASM_CASES_TAC `a = 0` THENL
       [UNDISCH_TAC `2*u = 4 EXP a * (8*b+7)` THEN
        ASM_REWRITE_TAC[EXP; MULT_CLAUSES] THEN
        DISCH_THEN(MP_TAC o AP_TERM `\x:num. x MOD 2`) THEN
        BETA_TAC THEN
        REWRITE_TAC
         [MOD_MULT;
          ARITH_RULE `8*b+7 = 2*(4*b+3)+1`;
          MOD_MULT_ADD] THEN
        CONV_TAC NUM_REDUCE_CONV;
        ALL_TAC] THEN
      MP_TAC(SPEC `a:num` num_CASES) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `d:num` SUBST_ALL_TAC) THEN
      UNDISCH_TAC `~(?a b. n = 4 EXP a * (16*b+10))` THEN
      REWRITE_TAC[] THEN MAP_EVERY EXISTS_TAC [`d:num`; `3*b+2`] THEN
      MAP_EVERY UNDISCH_TAC
       [`n = 3*u`; `2*u = 4 EXP SUC d * (8*b+7)`] THEN
      REWRITE_TAC[EXP] THEN ARITH_TAC;
      ALL_TAC] THEN
    MP_TAC(MATCH_MP (SPEC `u:num` INT_REPR123_THREE_MUL)
      (ASSUME `~(?a b. 2*u = 4 EXP a * (8*b+7))`)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(n MOD 16 = 10)` ASSUME_TAC THENL
   [DISCH_TAC THEN
    UNDISCH_TAC `~(?a b. n = 4 EXP a * (16*b+10))` THEN
    REWRITE_TAC[] THEN MAP_EVERY EXISTS_TAC [`0`; `n DIV 16`] THEN
    REWRITE_TAC[EXP; MULT_CLAUSES] THEN
    MP_TAC(SPECL [`n:num`; `16`] DIVISION) THEN
    CONV_TAC NUM_REDUCE_CONV THEN ASM_REWRITE_TAC[] THEN ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(SPEC `n:num` INT_REPR123_CORE) THEN
  ASM_REWRITE_TAC[]);;

