let INT_SQ_LE_20_CASES = prove
 (`!a:int.
     a pow 2 <= &20
     ==> a = -- &4 \/ a = -- &3 \/ a = -- &2 \/ a = -- &1 \/
         a = &0 \/ a = &1 \/ a = &2 \/ a = &3 \/ a = &4`,
  GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `abs a < &5` ASSUME_TAC THENL
   [MP_TAC(SPECL [`a:int`; `&5:int`] INT_LT_SQUARE_ABS) THEN
    REWRITE_TAC[INT_ABS_NUM] THEN
    CONV_TAC NUM_REDUCE_CONV THEN ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `abs a <= &4` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`a:int`; `&4:int`] INT_ABS_BOUNDS) THEN
  ASM_REWRITE_TAC[] THEN INT_ARITH_TAC);;

let INT_SQ_LE_30_CASES = prove
 (`!a:int.
     a pow 2 <= &30
     ==> a = -- &5 \/ a = -- &4 \/ a = -- &3 \/ a = -- &2 \/
         a = -- &1 \/ a = &0 \/ a = &1 \/ a = &2 \/ a = &3 \/
         a = &4 \/ a = &5`,
  GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `abs a < &6` ASSUME_TAC THENL
   [MP_TAC(SPECL [`a:int`; `&6:int`] INT_LT_SQUARE_ABS) THEN
    REWRITE_TAC[INT_ABS_NUM] THEN
    CONV_TAC NUM_REDUCE_CONV THEN ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `abs a <= &5` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`a:int`; `&5:int`] INT_ABS_BOUNDS) THEN
  ASM_REWRITE_TAC[] THEN INT_ARITH_TAC);;

let INT_YC123_NOT_10_4 = prove
 (`!x y z w:int.
     ~(x pow 2 + &2 * y pow 2 + &3 * z pow 2 +
       &2 * y * w + &4 * w pow 2 = &10)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `&2 * x pow 2 + &6 * z pow 2 + (&2 * y + w) pow 2 +
    &7 * w pow 2 = &20`
  (LABEL_TAC "sum") THENL
   [FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING;
    ALL_TAC] THEN
  MP_TAC(SPEC `x:int` INT_LE_POW_2) THEN
  MP_TAC(SPEC `z:int` INT_LE_POW_2) THEN
  MP_TAC(SPEC `&2 * y + w:int` INT_LE_POW_2) THEN
  MP_TAC(SPEC `w:int` INT_LE_POW_2) THEN
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `x pow 2 <= &10` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `z pow 2 <= &3` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(&2 * y + w) pow 2 <= &20` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `w pow 2 <= &2` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(MATCH_MP INT_SQ_LE_10_CASES (ASSUME `x pow 2 <= &10`)) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  MP_TAC(MATCH_MP INT_SQ_LE_3_CASES (ASSUME `z pow 2 <= &3`)) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  MP_TAC(MATCH_MP INT_SQ_LE_20_CASES
    (ASSUME `(&2 * y + w) pow 2 <= &20`)) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THEN
  MP_TAC(MATCH_MP INT_SQ_LE_2_CASES (ASSUME `w pow 2 <= &2`)) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  REMOVE_THEN "sum" MP_TAC THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC INT_REDUCE_CONV);;

let INT_YC123_NOT_10_8 = prove
 (`!x y z w:int.
