   `k = &1 \/ k = &2 \/ k = &3 \/ k = &4 \/ k = &5 \/
    k = &6 \/ k = &7 \/ k = &8 \/ k = &9 \/ k = &10`
  MP_TAC THENL
   [ASM_INT_ARITH_TAC;
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    ASM_MESON_TAC
     [IQ_YC123_NOT_REPRESENTS_10_4;
      IQ_YC123_NOT_REPRESENTS_10_8]]);;

