(* ------------------------------------------------------------------------- *)
(* A common induction for every child containing <1,2,3>.                   *)
(* ------------------------------------------------------------------------- *)

let NUM_123_EXCEPTION_MOD16 = prove
 (`!n:num.
     (?a b. n = 4 EXP a * (16*b+10))
     ==> n MOD 16 = 0 \/ n MOD 16 = 8 \/ n MOD 16 = 10`,
  GEN_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `a:num`
    (X_CHOOSE_THEN `b:num` ASSUME_TAC)) THEN
  ASM_CASES_TAC `a = 0` THENL
   [DISJ2_TAC THEN DISJ2_TAC THEN
    ASM_REWRITE_TAC[EXP; MULT_CLAUSES; MOD_MULT_ADD] THEN
    CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  MP_TAC(SPEC `a:num` num_CASES) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:num` SUBST_ALL_TAC) THEN
  ASM_CASES_TAC `d = 0` THENL
   [DISJ2_TAC THEN DISJ1_TAC THEN
    ASM_REWRITE_TAC[EXP; MULT_CLAUSES;
      ARITH_RULE `4 * (16*b+10) = 16 * (4*b+2) + 8`;
      MOD_MULT_ADD] THEN
    CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  MP_TAC(SPEC `d:num` num_CASES) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:num` SUBST_ALL_TAC) THEN
  DISJ1_TAC THEN
  ASM_REWRITE_TAC[EXP;
    ARITH_RULE `(4 * 4 * q) * r = 16 * (q*r)`;
    MOD_MULT]);;

let NUM_AVOIDS_123_OF_MOD16 = prove
 (`!n:num.
     ~(n MOD 16 = 0) /\ ~(n MOD 16 = 8) /\ ~(n MOD 16 = 10)
     ==> ~(?a b. n = 4 EXP a * (16*b+10))`,
  MESON_TAC[NUM_123_EXCEPTION_MOD16]);;

let NUM_DIV4_OF_MOD16_0_OR_8 = prove
 (`!n:num.
     n MOD 16 = 0 \/ n MOD 16 = 8
     ==> 4 divides n`,
  GEN_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[DIVIDES_MOD] THEN
  SUBGOAL_THEN `(n MOD 16) MOD 4 = 0` ASSUME_TAC THENL
   [UNDISCH_TAC `n MOD 16 = 0 \/ n MOD 16 = 8` THEN
    DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN `(n MOD 16) MOD 4 = n MOD 4` MP_TAC THENL
   [REWRITE_TAC[ARITH_RULE `16 = 4 * 4`; MOD_MOD];
    ASM_MESON_TAC[]]);;

let NUM_AVOIDS_123_SUB_SMALL = prove
 (`!n c:num.
     n MOD 16 = 10 /\
     (c = 1 \/ c = 3 \/ c = 4 \/ c = 5 \/
      c = 6 \/ c = 7 \/ c = 8 \/ c = 9)
     ==> ~(?a b. n - c = 4 EXP a * (16*b+10))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC)) THEN
  MP_TAC(MATCH_MP (SPECL [`n:num`; `16`; `10`] NUM_DECOMPOSE_MOD)
    (CONJ (ARITH_RULE `~(16 = 0)`) (ASSUME `n MOD 16 = 10`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `q:num` SUBST1_TAC) THEN
  MATCH_MP_TAC NUM_AVOIDS_123_OF_MOD16 THEN
  REWRITE_TAC
   [ARITH_RULE `(16*q+10)-1 = 16*q+9`;
    ARITH_RULE `(16*q+10)-3 = 16*q+7`;
    ARITH_RULE `(16*q+10)-4 = 16*q+6`;
    ARITH_RULE `(16*q+10)-5 = 16*q+5`;
    ARITH_RULE `(16*q+10)-6 = 16*q+4`;
    ARITH_RULE `(16*q+10)-7 = 16*q+3`;
    ARITH_RULE `(16*q+10)-8 = 16*q+2`;
    ARITH_RULE `(16*q+10)-9 = 16*q+1`;
    MOD_MULT_ADD] THEN
  CONV_TAC NUM_REDUCE_CONV);;

let INT_REPRESENTS_123_CHILD_SCALE4 = prove
 (`!rb rc k n:num.
     (?x y z w:int.
        x pow 2 + &2 * y pow 2 + &3 * z pow 2 +
        &2 * &rb * y * w + &2 * &rc * z * w +
        &k * w pow 2 = &n)
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &3 * z pow 2 +
          &2 * &rb * y * w + &2 * &rc * z * w +
          &k * w pow 2 = &(4*n)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int`
      (X_CHOOSE_THEN `z:int` (X_CHOOSE_TAC `w:int`)))) THEN
  MAP_EVERY EXISTS_TAC
   [`&2*x:int`; `&2*y:int`; `&2*z:int`; `&2*w:int`] THEN
  FIRST_X_ASSUM(MP_TAC) THEN
  REWRITE_TAC[GSYM INT_OF_NUM_MUL] THEN CONV_TAC INT_RING);;

let INT_UNIVERSAL_123_CHILD_OF_MOD16 = prove
 (`!rb rc k:num.
     (!n:num.
        0 < n /\ n MOD 16 = 10
        ==> ?x y z w:int.
             x pow 2 + &2 * y pow 2 + &3 * z pow 2 +
             &2 * &rb * y * w + &2 * &rc * z * w +
             &k * w pow 2 = &n)
     ==> !n:num.
          0 < n
          ==> ?x y z w:int.
               x pow 2 + &2 * y pow 2 + &3 * z pow 2 +
               &2 * &rb * y * w + &2 * &rc * z * w +
               &k * w pow 2 = &n`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "mod16") THEN
  MATCH_MP_TAC num_WF THEN X_GEN_TAC `n:num` THEN
  DISCH_THEN(LABEL_TAC "ind") THEN DISCH_TAC THEN
  ASM_CASES_TAC `4 divides n` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `q:num` ASSUME_TAC o
      REWRITE_RULE[divides]) THEN
    SUBGOAL_THEN `q < n /\ 0 < q` STRIP_ASSUME_TAC THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    ONCE_REWRITE_TAC[ASSUME `n = 4 * q`] THEN
    MATCH_MP_TAC
     (SPECL [`rb:num`; `rc:num`; `k:num`; `q:num`]
       INT_REPRESENTS_123_CHILD_SCALE4) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `?a b. n = 4 EXP a * (16*b+10)` THENL
   [ASM_MESON_TAC
     [NUM_123_EXCEPTION_MOD16; NUM_DIV4_OF_MOD16_0_OR_8];
    MP_TAC(MATCH_MP (SPEC `n:num` REGULAR_123_NOT_FORM)
      (ASSUME `~(?a b. n = 4 EXP a * (16*b+10))`)) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:int`
      (X_CHOOSE_THEN `y:int`
        (X_CHOOSE_THEN `z:int` (LABEL_TAC "tern")))) THEN
    MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`; `&0:int`] THEN
    REMOVE_THEN "tern" MP_TAC THEN CONV_TAC INT_RING]);;

(* ------------------------------------------------------------------------- *)
(* Diagonal children x^2 + 2y^2 + 3z^2 + k w^2.                            *)
(* ------------------------------------------------------------------------- *)

let INT_REPRESENTS_DIAG123_SHIFT = prove
 (`!k s n:num.
     k * s EXP 2 <= n /\
     ~(?a b. n - k * s EXP 2 = 4 EXP a * (16*b+10))
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &3 * z pow 2 +
          &k * w pow 2 = &n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP (SPEC `n - k * s EXP 2` REGULAR_123_NOT_FORM)
    (ASSUME `~(?a b. n - k * s EXP 2 = 4 EXP a * (16*b+10))`)) THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int` (X_CHOOSE_TAC `z:int`))) THEN
  MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`; `&s:int`] THEN
  SUBGOAL_THEN
   `&(n - k * s EXP 2) = (&n:int) - (&k:int) * (&s:int) pow 2`
  ASSUME_TAC THENL
   [ASM_SIMP_TAC[INT_OF_NUM_SUB; INT_OF_NUM_MUL; INT_OF_NUM_POW];
    MP_TAC(REWRITE_RULE
      [ASSUME
        `&(n - k * s EXP 2) = (&n:int) - (&k:int) * (&s:int) pow 2`]
      (ASSUME
