    INT_REPRESENTS_DIAG123_SHIFT) THEN
  CONJ_TAC THENL
   [ASM_ARITH_TAC;
    MATCH_MP_TAC(SPECL [`n:num`; `k * s EXP 2`]
      NUM_AVOIDS_123_SUB_SMALL) THEN
    ASM_REWRITE_TAC[]]);;

let INT_REPRESENTS_DIAG123_MOD16 = prove
