  MP_TAC THENL
   [ASM_ARITH_TAC;
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THENL
     [MATCH_MP_TAC(SPECL [`1`; `1`; `n:num`]
        INT_REPRESENTS_DIAG123_SMALL_SHIFT) THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV;
      MATCH_MP_TAC(SPECL [`2`; `2`; `n:num`]
