      MATCH_MP_TAC(SPECL [`7`; `1`; `n:num`]
        INT_REPRESENTS_DIAG123_SMALL_SHIFT) THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV;
      MATCH_MP_TAC(SPECL [`8`; `1`; `n:num`]
        INT_REPRESENTS_DIAG123_SMALL_SHIFT) THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV;
      MATCH_MP_TAC(SPECL [`9`; `1`; `n:num`]
        INT_REPRESENTS_DIAG123_SMALL_SHIFT) THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV;
      ASM_CASES_TAC `n < 40` THENL
       [SUBGOAL_THEN `n = 10 \/ n = 26` MP_TAC THENL
         [MP_TAC(MATCH_MP (SPECL [`n:num`; `16`; `10`]
