           [ASM_ARITH_TAC;
            SUBGOAL_THEN `q = 0 \/ q = 1` MP_TAC THENL
             [ASM_ARITH_TAC;
              DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
              ASM_ARITH_TAC]];
          DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THENL
           [MAP_EVERY EXISTS_TAC
             [`&0:int`; `&0:int`; `&0:int`; `&1:int`];
            MAP_EVERY EXISTS_TAC
             [`&4:int`; `&0:int`; `&0:int`; `&1:int`]] THEN
          CONV_TAC INT_REDUCE_CONV];
        MATCH_MP_TAC(SPECL [`10`; `2`; `n:num`]
          INT_REPRESENTS_DIAG123_SHIFT) THEN
        CONJ_TAC THENL
         [CONV_TAC NUM_REDUCE_CONV THEN ASM_ARITH_TAC;
          MATCH_MP_TAC(SPEC `n - 10 * 2 EXP 2`
            NUM_AVOIDS_123_OF_MOD16) THEN
