            NUM_DECOMPOSE_MOD)
           (CONJ (ARITH_RULE `~(16 = 0)`)
             (ASSUME `n MOD 16 = 10`))) THEN
          DISCH_THEN(X_CHOOSE_THEN `q:num` ASSUME_TAC) THEN
          SUBGOAL_THEN `2 <= q` ASSUME_TAC THENL
           [ASM_ARITH_TAC;
            MP_TAC(ASSUME `2 <= q`) THEN REWRITE_TAC[LE_EXISTS] THEN
            DISCH_THEN(X_CHOOSE_THEN `d:num` SUBST_ALL_TAC) THEN
            SUBGOAL_THEN `n - 10 * 2 EXP 2 = 16 * d + 2`
            SUBST1_TAC THENL
             [ASM_REWRITE_TAC[] THEN ARITH_TAC;
              REWRITE_TAC[MOD_MULT_ADD] THEN
              CONV_TAC NUM_REDUCE_CONV]]]]]]);;

