let IQ_UNIVERSAL_DIAG123_NUM = prove
 (`!k:num.
     1 <= k /\ k <= 10
     ==> iq_universal 4
          (iqmat4 (&1) (&0) (&0) (&0)
                  (&2) (&0) (&0) (&3) (&0) (&k))`,
  GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC
   (SPECL [`&1:int`; `&2:int`; `&3:int`; `&k:int`]
     IQ_UNIVERSAL_MAT4_DIAG) THEN
  MATCH_MP_TAC
   (SPECL [`&1:int`; `&2:int`; `&3:int`; `&k:int`]
     IQ_UNIVERSAL_DIAG4_OF_NUM) THEN
  X_GEN_TAC `n:num` THEN DISCH_TAC THEN
  MP_TAC(MATCH_MP
    (MATCH_MP (SPEC `k:num` INT_UNIVERSAL_DIAG123_NUM)
      (ASSUME `1 <= k /\ k <= 10`))
    (ASSUME `0 < n`)) THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int`
      (X_CHOOSE_THEN `z:int` (X_CHOOSE_TAC `w:int`)))) THEN
  MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`; `w:int`] THEN
  FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING);;

let IQ_UNIVERSAL_OF_DIAG123_CHILD = prove
 (`!n A k.
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&0) (&0) (&3) (&0) k) A /\
     &1 <= k /\ k <= &10
     ==> iq_universal n A`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(EQ_MP (SYM(SPEC `k:int` INT_OF_NUM_EXISTS))
    (MATCH_MP (INT_ARITH `&1 <= k ==> &0 <= k`)
      (ASSUME `&1 <= k`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `c:num` SUBST_ALL_TAC) THEN
  SUBGOAL_THEN `1 <= c /\ c <= 10` ASSUME_TAC THENL
   [UNDISCH_TAC `&1 <= &c` THEN
    UNDISCH_TAC `&c <= &10` THEN
    REWRITE_TAC[INT_OF_NUM_LE] THEN ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `4`;
    `iqmat4 (&1) (&0) (&0) (&0)
            (&2) (&0) (&0) (&3) (&0) (&c)`;
    `A:num->num->int`] IQ_UNIVERSAL_OF_EMBEDS) THEN
  CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    MATCH_MP_TAC(SPEC `c:num` IQ_UNIVERSAL_DIAG123_NUM) THEN
    ASM_REWRITE_TAC[]]);;

