(* The bounded checks below are proof-producing searches: the search only
   supplies concrete witnesses, which INT_REDUCE_CONV then verifies. *)

let int123_num_of_int i =
  if i < 0
  then minus_num(num_of_string(string_of_int(-i)))
  else num_of_string(string_of_int i);;

let INT123_CERT_TAC rb rc k =
  fun (asl,goal) ->
    let _,bod = strip_exists goal in
    let _,rhs = dest_eq bod in
    let n = int_of_string(string_of_num(dest_intconst rhs)) in
    let bound =
      int_of_float(float_sqrt(float_of_int(6 * n))) + 2 in
    let signed i =
      if i = 0 then 0 else if i mod 2 = 1 then (i + 1) / 2 else -(i / 2) in
    let rec find_w iw =
      if iw > 2 * bound then failwith "INT123_CERT_TAC" else
      let w = signed iw in
      let rec find_z iz =
        if iz > 2 * bound then find_w (iw + 1) else
        let z = signed iz in
        let rec find_y iy =
          if iy > 2 * bound then find_z (iz + 1) else
          let y = signed iy in
          let r =
            n - 2*y*y - 3*z*z - 2*rb*y*w - 2*rc*z*w - k*w*w in
          if r < 0 then find_y (iy + 1) else
          let x = int_of_float(float_sqrt(float_of_int r)) in
          if x*x = r then (x,y,z,w) else find_y (iy + 1) in
        find_y 0 in
      find_z 0 in
    let x,y,z,w = find_w 0 in
    (MAP_EVERY EXISTS_TAC
       (map (mk_intconst o int123_num_of_int) [x;y;z;w]) THEN
     CONV_TAC INT_REDUCE_CONV) (asl,goal);;

(* Close each concrete case before opening the next one. This lets THENL
   collapse the finished justification instead of retaining every subgoal. *)
let NUM_RANGE_CASES_THEN tm hi tac =
  let rec cases tm i =
    let v = genvar `:num` in
    MP_TAC(SPEC tm num_CASES) THEN
    DISCH_THEN(DISJ_CASES_THEN2 SUBST_ALL_TAC
      (X_CHOOSE_THEN v SUBST_ALL_TAC)) THENL
     [tac;
      if i = hi then ASM_ARITH_TAC else cases v (i + 1)] in
  cases tm 0;;

let NUM_RANGE_CASES_TAC tm hi =
  NUM_RANGE_CASES_THEN tm hi ALL_TAC;;

let NUM_INTERVAL_CASES_THEN tm lo hi tac =
  let rec cases lo hi =
    if lo > hi then failwith "NUM_INTERVAL_CASES_THEN" else
    if lo = hi then
      SUBGOAL_THEN (mk_eq(tm,mk_small_numeral lo)) SUBST_ALL_TAC THENL
       [ASM_ARITH_TAC;
        tac]
    else
      let mid = (lo + hi) / 2 in
      let cond =
        mk_comb
         (mk_comb(`(<=):num->num->bool`,tm),
          mk_small_numeral mid) in
      ASM_CASES_TAC cond THENL
       [cases lo mid;
        cases (mid + 1) hi] in
  cases lo hi;;

let NUM_AVOIDS_123_SUB_OF_RESIDUE = prove
 (`!n c:num.
     c <= n /\ n MOD 16 = 10 /\
     ~(c MOD 16 = 0) /\ ~(c MOD 16 = 2) /\ ~(c MOD 16 = 10)
     ==> ~(?a b. n - c = 4 EXP a * (16*b+10))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  DISCH_THEN(fun th ->
    MP_TAC(MATCH_MP (SPEC `n - c:num` NUM_123_EXCEPTION_MOD16) th)) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THEN
  (SUBGOAL_THEN
    `((n - c) MOD 16 + c MOD 16) MOD 16 = 10`
   ASSUME_TAC THENL
    [REWRITE_TAC[MOD_ADD_MOD] THEN
     ASM_SIMP_TAC[SUB_ADD];
     ALL_TAC]) THEN
  MP_TAC(SPECL [`(n - c) MOD 16`; `c MOD 16`; `16`]
    MOD_ADD_CASES) THEN
  (ANTS_TAC THENL
    [CONJ_TAC THEN REWRITE_TAC[MOD_LT_EQ] THEN ARITH_TAC;
     ASM_REWRITE_TAC[] THEN
     COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]));;

