              4 EXP a * (16*b+10))`)) THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int` (X_CHOOSE_TAC `z:int`))) THEN
  MAP_EVERY EXISTS_TAC
   [`x:int`; `y:int`; `z - &s:int`; `&3 * &s:int`] THEN
  SUBGOAL_THEN `3 <= 9*k` ASSUME_TAC THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&(n - (9*k - 3) * s EXP 2) =
    (&n:int) - (&9 * &k - &3) * &s pow 2`
  ASSUME_TAC THENL
   [ASM_SIMP_TAC[INT_OF_NUM_SUB; INT_OF_NUM_MUL; INT_OF_NUM_POW];
    MP_TAC(REWRITE_RULE
      [ASSUME
        `&(n - (9*k - 3) * s EXP 2) =
         (&n:int) - (&9 * &k - &3) * &s pow 2`]
      (ASSUME
        `x pow 2 + &2 * y pow 2 + &3 * z pow 2 =
         &(n - (9*k - 3) * s EXP 2)`)) THEN
    CONV_TAC INT_RING]);;

