let IQ_EMBEDS_CLEAR_124 = prove
 (`!n A a b c rb rc t.
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) a
               (&2) (&0) (&2 * b + rb)
               (&4) (&4 * c + rc) t) A
     ==> iq_embeds n 4
          (iqmat4 (&1) (&0) (&0) (&0)
                  (&2) (&0) rb (&4) rc
                  (t - a pow 2 -
                       &2 * b pow 2 - &2 * b * rb -
                       &4 * c pow 2 - &2 * c * rc)) A`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `4`;
    `iqgram 4
      (iqmat4 (&1) (&0) (&0) a
              (&2) (&0) (&2 * b + rb)
              (&4) (&4 * c + rc) t)
      (iqclear124 a b c)`;
    `iqmat4 (&1) (&0) (&0) (&0)
            (&2) (&0) rb (&4) rc
            (t - a pow 2 -
                 &2 * b pow 2 - &2 * b * rb -
                 &4 * c pow 2 - &2 * c * rc)`;
    `A:num->num->int`] IQ_EMBEDS_EQ) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC IQ_EMBEDS_CONGRUENCE THEN ASM_REWRITE_TAC[];
    REPEAT STRIP_TAC THEN
    (SUBGOAL_THEN `i = 0 \/ i = 1 \/ i = 2 \/ i = 3` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    (SUBGOAL_THEN `j = 0 \/ j = 1 \/ j = 2 \/ j = 3` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    ASM_REWRITE_TAC[iqgram; IQBILIN_MAT4; iqclear124; iqrows4;
      iqmat4; iqsym] THEN
    CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_RING]);;

