let IQ_124_REDUCED_K_NONZERO = prove
 (`!n A a qb rb qc rc k.
     iq_positive n A /\
     (rb = &0 \/ rb = &1) /\
     (rc = -- &2 \/ rc = -- &1 \/ rc = &0 \/ rc = &1) /\
     k = &14 - a pow 2 -
          &2 * qb pow 2 - &2 * qb * rb -
          &4 * qc pow 2 - &2 * qc * rc /\
     iq_embeds n 4
      (iqmat4 (&1) (&0) (&0) (&0)
              (&2) (&0) rb (&4) rc k) A
     ==> ~(k = &0)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)))) THEN
  DISCH_TAC THEN
  let emb0 = REWRITE_RULE [ASSUME `k = &0`]
    (ASSUME
      `iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&0) rb (&4) rc k) A`) in
  let rb0 = MATCH_MP
    (ISPECL [`n:num`; `A:num->num->int`;
      `rb:int`; `rc:int`] IQ_124_ZERO_FORCES_RB)
    (CONJ (ASSUME `iq_positive n A`)
      (CONJ (ASSUME `rb = &0 \/ rb = &1`) emb0)) in
  let rc0 = MATCH_MP
    (ISPECL [`n:num`; `A:num->num->int`;
      `rb:int`; `rc:int`] IQ_124_ZERO_FORCES_RC)
    (CONJ (ASSUME `iq_positive n A`)
      (CONJ
        (ASSUME
          `rc = -- &2 \/ rc = -- &1 \/ rc = &0 \/ rc = &1`)
        emb0)) in
  ACCEPT_TAC
   (MP
    (NOT_ELIM(SPECL [`a:int`; `qb:int`; `qc:int`] INT_124_NOT_14))
    (MP (MP (MP (MP
      (INT_RING
        `k = &14 - a pow 2 -
             &2 * qb pow 2 - &2 * qb * rb -
             &4 * qc pow 2 - &2 * qc * rc
         ==> k = &0 ==> rb = &0 ==> rc = &0
         ==> a pow 2 + &2 * qb pow 2 + &4 * qc pow 2 = &14`)
      (ASSUME
        `k = &14 - a pow 2 -
             &2 * qb pow 2 - &2 * qb * rb -
             &4 * qc pow 2 - &2 * qc * rc`))
     (ASSUME `k = &0`))
    rb0)
   rc0)));;

let IQ_124_REDUCED_K_BOUNDS = prove
 (`!n A a qb rb qc rc k.
     iq_positive n A /\
     (rb = &0 \/ rb = &1) /\
     (rc = -- &2 \/ rc = -- &1 \/ rc = &0 \/ rc = &1) /\
     k = &14 - a pow 2 -
          &2 * qb pow 2 - &2 * qb * rb -
          &4 * qc pow 2 - &2 * qc * rc /\
     iq_embeds n 4
