    (CONJ (ASSUME `iq_positive n A`)
      (ASSUME
        `iq_embeds n 4
         (iqmat4 (&1) (&0) (&0) (&0)
                 (&2) (&0) rb (&4) rc k) A`)) in
  let knonzero = MATCH_MP
    (ISPECL [`n:num`; `A:num->num->int`; `a:int`; `qb:int`;
      `rb:int`; `qc:int`; `rc:int`; `k:int`]
      IQ_124_REDUCED_K_NONZERO)
    (CONJ (ASSUME `iq_positive n A`)
      (CONJ (ASSUME `rb = &0 \/ rb = &1`)
        (CONJ
          (ASSUME
            `rc = -- &2 \/ rc = -- &1 \/ rc = &0 \/ rc = &1`)
          (CONJ
            (ASSUME
              `k = &14 - a pow 2 -
                   &2 * qb pow 2 - &2 * qb * rb -
                   &4 * qc pow 2 - &2 * qc * rc`)
            (ASSUME
              `iq_embeds n 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) rb (&4) rc k) A`))))) in
  let kupper = MATCH_MP
    (SPECL [`a:int`; `qb:int`; `rb:int`; `qc:int`; `rc:int`; `k:int`]
      IQ_124_REDUCED_K_UPPER)
    (CONJ (ASSUME `rb = &0 \/ rb = &1`)
      (CONJ
        (ASSUME
          `rc = -- &2 \/ rc = -- &1 \/ rc = &0 \/ rc = &1`)
        (ASSUME
          `k = &14 - a pow 2 -
               &2 * qb pow 2 - &2 * qb * rb -
               &4 * qc pow 2 - &2 * qc * rc`))) in
  ACCEPT_TAC
   (CONJ
     (MP (MP
       (INT_ARITH `&0 <= k ==> ~(k = &0) ==> &1 <= k`)
       knonneg)
      knonzero)
     kupper));;

