  MP_TAC(SPEC `b:int` INT_DIV2_QR) THEN
  DISCH_THEN(X_CHOOSE_THEN `qb:int`
    (X_CHOOSE_THEN `rb:int`
      (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC))) THEN
  MP_TAC(SPEC `c:int` INT_DIV4_BALANCED) THEN
  DISCH_THEN(X_CHOOSE_THEN `qc:int`
    (X_CHOOSE_THEN `rc:int`
      (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC))) THEN
  let kval =
    `&14 - a pow 2 -
     &2 * qb pow 2 - &2 * qb * rb -
     &4 * qc pow 2 - &2 * qc * rc` in
  let source_emb = REWRITE_RULE
    [ASSUME `b = &2 * qb + rb`; ASSUME `c = &4 * qc + rc`]
    (ASSUME
      `iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) a
               (&2) (&0) b (&4) c (&14)) A`) in
  let emb = MATCH_MP
    (ISPECL [`n:num`; `A:num->num->int`; `a:int`; `qb:int`;
      `qc:int`; `rb:int`; `rc:int`; `&14:int`]
      IQ_EMBEDS_CLEAR_124)
    source_emb in
  let bounds = MATCH_MP
    (ISPECL [`n:num`; `A:num->num->int`; `a:int`; `qb:int`;
      `rb:int`; `qc:int`; `rc:int`; kval]
      IQ_124_REDUCED_K_BOUNDS)
    (CONJ (ASSUME `iq_positive n A`)
      (CONJ (ASSUME `rb = &0 \/ rb = &1`)
        (CONJ
          (ASSUME
            `rc = -- &2 \/ rc = -- &1 \/ rc = &0 \/ rc = &1`)
          (CONJ (REFL kval) emb)))) in
  let rep14 = MATCH_MP
    (SPECL [`a:int`; `qb:int`; `rb:int`; `qc:int`; `rc:int`; kval]
      IQ_124_REDUCED_REPRESENTS_14)
    (REFL kval) in
  MAP_EVERY EXISTS_TAC [`rb:int`; `rc:int`; kval] THEN
  ACCEPT_TAC
   (CONJ (ASSUME `rb = &0 \/ rb = &1`)
     (CONJ
       (ASSUME
         `rc = -- &2 \/ rc = -- &1 \/ rc = &0 \/ rc = &1`)
       (CONJ (CONJUNCT1 bounds)
         (CONJ (CONJUNCT2 bounds) (CONJ emb rep14))))));;

let IQ_EMBEDS_QUATERNARY_124 = prove
 (`!n A.
     iq_symmetric n A /\ iq_positive n A /\
     iq_embeds n 3
       (iqmat3 (&1) (&0) (&0) (&2) (&0) (&4)) A /\
     iq_represents n A (&14)
     ==> (?k. &1 <= k /\ k <= &14 /\
              iq_embeds n 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&0) (&4) (&0) k) A /\
              iq_represents 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&0) (&4) (&0) k) (&14)) \/
         (?k. &1 <= k /\ k <= &14 /\
              iq_embeds n 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&0) (&4) (&1) k) A /\
              iq_represents 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&0) (&4) (&1) k) (&14)) \/
         (?k. &1 <= k /\ k <= &14 /\
              iq_embeds n 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&0) (&4) (&2) k) A /\
              iq_represents 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&0) (&4) (&2) k) (&14)) \/
         (?k. &1 <= k /\ k <= &14 /\
              iq_embeds n 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&1) (&4) (&0) k) A /\
              iq_represents 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&1) (&4) (&0) k) (&14)) \/
         (?k. &1 <= k /\ k <= &14 /\
              iq_embeds n 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&1) (&4) (&1) k) A /\
              iq_represents 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&1) (&4) (&1) k) (&14)) \/
         (?k. &1 <= k /\ k <= &14 /\
              iq_embeds n 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&1) (&4) (&2) k) A /\
              iq_represents 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&1) (&4) (&2) k) (&14))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`n:num`; `A:num->num->int`]
    IQ_EMBEDS_QUATERNARY_124_RAW) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `rb:int`
    (X_CHOOSE_THEN `rc:int`
      (X_CHOOSE_THEN `k:int`
        (CONJUNCTS_THEN2 ASSUME_TAC
          (CONJUNCTS_THEN2 ASSUME_TAC
            (CONJUNCTS_THEN2 ASSUME_TAC
              (CONJUNCTS_THEN2 ASSUME_TAC
                (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)))))))) THEN
  UNDISCH_TAC `rb = &0 \/ rb = &1` THEN
  DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  UNDISCH_TAC
   `rc = -- &2 \/ rc = -- &1 \/ rc = &0 \/ rc = &1` THEN
  DISCH_THEN(DISJ_CASES_THEN2 SUBST_ALL_TAC
    (DISJ_CASES_THEN2 SUBST_ALL_TAC
      (DISJ_CASES_THEN SUBST_ALL_TAC))) THENL
   [DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
    EXISTS_TAC `k:int` THEN REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC IQ_EMBEDS_FLIP_124_NEG2 THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC IQ_REPRESENTS_FLIP_124_NEG2 THEN ASM_REWRITE_TAC[]];
    DISJ2_TAC THEN DISJ1_TAC THEN
    EXISTS_TAC `k:int` THEN REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC IQ_EMBEDS_FLIP_124_NEG1 THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC IQ_REPRESENTS_FLIP_124_NEG1 THEN ASM_REWRITE_TAC[]];
    DISJ1_TAC THEN EXISTS_TAC `k:int` THEN ASM_REWRITE_TAC[];
    DISJ2_TAC THEN DISJ1_TAC THEN
    EXISTS_TAC `k:int` THEN ASM_REWRITE_TAC[];
    DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN
    DISJ2_TAC THEN DISJ2_TAC THEN
    EXISTS_TAC `k:int` THEN REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC IQ_EMBEDS_FLIP_124_NEG2 THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC IQ_REPRESENTS_FLIP_124_NEG2 THEN ASM_REWRITE_TAC[]];
    DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN
    DISJ2_TAC THEN DISJ1_TAC THEN
    EXISTS_TAC `k:int` THEN REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC IQ_EMBEDS_FLIP_124_NEG1 THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC IQ_REPRESENTS_FLIP_124_NEG1 THEN ASM_REWRITE_TAC[]];
    DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN
    DISJ1_TAC THEN EXISTS_TAC `k:int` THEN ASM_REWRITE_TAC[];
    DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN
    DISJ2_TAC THEN DISJ1_TAC THEN
    EXISTS_TAC `k:int` THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* A common descent for every child containing <1,2,4>.                     *)
(* ------------------------------------------------------------------------- *)

let NUM_124_EXCEPTION_MOD16 = prove
 (`!n:num.
     (?a b. n = 4 EXP a * (16*b+14))
     ==> n MOD 16 = 0 \/ n MOD 16 = 8 \/ n MOD 16 = 14`,
  GEN_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `a:num`
    (X_CHOOSE_THEN `b:num` ASSUME_TAC)) THEN
  ASM_CASES_TAC `a = 0` THENL
   [DISJ2_TAC THEN DISJ2_TAC THEN
    ASM_REWRITE_TAC[EXP; MULT_CLAUSES; MOD_MULT_ADD] THEN
    CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  MP_TAC(SPEC `a:num` num_CASES) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:num` SUBST_ALL_TAC) THEN
  ASM_CASES_TAC `d = 0` THENL
   [DISJ2_TAC THEN DISJ1_TAC THEN
    ASM_REWRITE_TAC[EXP; MULT_CLAUSES;
      ARITH_RULE `4 * (16*b+14) = 16 * (4*b+3) + 8`;
      MOD_MULT_ADD] THEN
    CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  MP_TAC(SPEC `d:num` num_CASES) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:num` SUBST_ALL_TAC) THEN
  DISJ1_TAC THEN
  ASM_REWRITE_TAC[EXP;
    ARITH_RULE `(4 * 4 * q) * r = 16 * (q*r)`;
    MOD_MULT]);;

let INT_REPRESENTS_124_CHILD_SCALE4 = prove
 (`!rb rc k n:num.
     (?x y z w:int.
        x pow 2 + &2 * y pow 2 + &4 * z pow 2 +
        &2 * &rb * y * w + &2 * &rc * z * w +
        &k * w pow 2 = &n)
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &4 * z pow 2 +
          &2 * &rb * y * w + &2 * &rc * z * w +
          &k * w pow 2 = &(4*n)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int`
      (X_CHOOSE_THEN `z:int` (X_CHOOSE_TAC `w:int`)))) THEN
  MAP_EVERY EXISTS_TAC
   [`&2*x:int`; `&2*y:int`; `&2*z:int`; `&2*w:int`] THEN
  FIRST_X_ASSUM(MP_TAC) THEN
  REWRITE_TAC[GSYM INT_OF_NUM_MUL] THEN CONV_TAC INT_RING);;

let INT_UNIVERSAL_124_CHILD_OF_MOD16 = prove
 (`!rb rc k:num.
     (!n:num.
        0 < n /\ n MOD 16 = 14
        ==> ?x y z w:int.
             x pow 2 + &2 * y pow 2 + &4 * z pow 2 +
             &2 * &rb * y * w + &2 * &rc * z * w +
             &k * w pow 2 = &n)
     ==> !n:num.
          0 < n
          ==> ?x y z w:int.
               x pow 2 + &2 * y pow 2 + &4 * z pow 2 +
               &2 * &rb * y * w + &2 * &rc * z * w +
               &k * w pow 2 = &n`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "mod16") THEN
  MATCH_MP_TAC num_WF THEN X_GEN_TAC `n:num` THEN
  DISCH_THEN(LABEL_TAC "ind") THEN DISCH_TAC THEN
  ASM_CASES_TAC `4 divides n` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `q:num` ASSUME_TAC o
      REWRITE_RULE[divides]) THEN
    SUBGOAL_THEN `q < n /\ 0 < q` STRIP_ASSUME_TAC THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    ONCE_REWRITE_TAC[ASSUME `n = 4 * q`] THEN
    MATCH_MP_TAC
     (SPECL [`rb:num`; `rc:num`; `k:num`; `q:num`]
       INT_REPRESENTS_124_CHILD_SCALE4) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `?a b. n = 4 EXP a * (16*b+14)` THENL
   [ASM_MESON_TAC
     [NUM_124_EXCEPTION_MOD16; NUM_DIV4_OF_MOD16_0_OR_8];
    MP_TAC(MATCH_MP (SPEC `n:num` INT_REPRESENTS_124_OF_LEGENDRE)
      (ASSUME `~(?a b. n = 4 EXP a * (16*b+14))`)) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:int`
      (X_CHOOSE_THEN `y:int`
        (X_CHOOSE_THEN `z:int` (LABEL_TAC "tern")))) THEN
    MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`; `&0:int`] THEN
    REMOVE_THEN "tern" MP_TAC THEN CONV_TAC INT_RING]);;

let NUM_AVOIDS_124_SUB_OF_RESIDUE = prove
 (`!n c:num.
     c <= n /\ n MOD 16 = 14 /\
     ~(c MOD 16 = 0) /\ ~(c MOD 16 = 6) /\ ~(c MOD 16 = 14)
     ==> ~(?a b. n - c = 4 EXP a * (16*b+14))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  DISCH_THEN(fun th ->
    MP_TAC(MATCH_MP (SPEC `n - c:num` NUM_124_EXCEPTION_MOD16) th)) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THEN
  (SUBGOAL_THEN
    `((n - c) MOD 16 + c MOD 16) MOD 16 = 14`
   ASSUME_TAC THENL
    [REWRITE_TAC[MOD_ADD_MOD] THEN
     ASM_SIMP_TAC[SUB_ADD];
     ALL_TAC]) THEN
  MP_TAC(SPECL [`(n - c) MOD 16`; `c MOD 16`; `16`]
    MOD_ADD_CASES) THEN
  (ANTS_TAC THENL
    [CONJ_TAC THEN REWRITE_TAC[MOD_LT_EQ] THEN ARITH_TAC;
     ASM_REWRITE_TAC[] THEN
     COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]));;

(* ------------------------------------------------------------------------- *)
(* Orthogonal shifts into the regular ternary subform.                       *)
(* ------------------------------------------------------------------------- *)

let INT_REPRESENTS_DIAG124_SHIFT = prove
 (`!k s n:num.
     k * s EXP 2 <= n /\
     ~(?a b. n - k * s EXP 2 = 4 EXP a * (16*b+14))
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &4 * z pow 2 +
          &k * w pow 2 = &n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP
    (SPEC `n - k * s EXP 2` INT_REPRESENTS_124_OF_LEGENDRE)
    (ASSUME
      `~(?a b. n - k * s EXP 2 = 4 EXP a * (16*b+14))`)) THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int` (X_CHOOSE_TAC `z:int`))) THEN
  MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`; `&s:int`] THEN
  SUBGOAL_THEN
   `&(n - k * s EXP 2) =
    (&n:int) - (&k:int) * (&s:int) pow 2`
  ASSUME_TAC THENL
   [ASM_SIMP_TAC[INT_OF_NUM_SUB; INT_OF_NUM_MUL; INT_OF_NUM_POW];
    MP_TAC(REWRITE_RULE
      [ASSUME
        `&(n - k * s EXP 2) =
         (&n:int) - (&k:int) * (&s:int) pow 2`]
      (ASSUME
        `x pow 2 + &2 * y pow 2 + &4 * z pow 2 =
         &(n - k * s EXP 2)`)) THEN
    CONV_TAC INT_RING]);;

let INT_REPRESENTS_ZC124_SHIFT = prove
 (`!k s n:num.
     1 <= k /\ (16*k-4) * s EXP 2 <= n /\
     ~(?a b. n - (16*k-4) * s EXP 2 =
