   `&(n - (4*k-6) * s EXP 2) =
    (&n:int) - (&4 * &k - &6) * &s pow 2`
  ASSUME_TAC THENL
   [ASM_SIMP_TAC[INT_OF_NUM_SUB; INT_OF_NUM_MUL; INT_OF_NUM_POW];
    MP_TAC(REWRITE_RULE
      [ASSUME
        `&(n - (4*k-6) * s EXP 2) =
         (&n:int) - (&4 * &k - &6) * &s pow 2`]
      (ASSUME
        `x pow 2 + &2 * y pow 2 + &4 * z pow 2 =
         &(n - (4*k-6) * s EXP 2)`)) THEN
    CONV_TAC INT_RING]);;

(* The search supplies concrete witnesses only; INT_REDUCE_CONV checks them. *)

let int124_num_of_int i =
  if i < 0
  then minus_num(num_of_string(string_of_int(-i)))
  else num_of_string(string_of_int i);;

let INT124_CERT_TAC rb rc k =
  fun (asl,goal) ->
    let _,bod = strip_exists goal in
    let _,rhs = dest_eq bod in
    let n = int_of_string(string_of_num(dest_intconst rhs)) in
    let bound =
      int_of_float(float_sqrt(float_of_int(8 * n))) + 2 in
    let signed i =
      if i = 0 then 0 else if i mod 2 = 1 then (i + 1) / 2 else -(i / 2) in
    let rec find_w iw =
      if iw > 2 * bound then failwith "INT124_CERT_TAC" else
      let w = signed iw in
      let rec find_z iz =
        if iz > 2 * bound then find_w (iw + 1) else
        let z = signed iz in
        let rec find_y iy =
          if iy > 2 * bound then find_z (iz + 1) else
          let y = signed iy in
          let r =
            n - 2*y*y - 4*z*z - 2*rb*y*w - 2*rc*z*w - k*w*w in
          if r < 0 then find_y (iy + 1) else
          let x = int_of_float(float_sqrt(float_of_int r)) in
          if x*x = r then (x,y,z,w) else find_y (iy + 1) in
        find_y 0 in
      find_z 0 in
    let x,y,z,w = find_w 0 in
    (MAP_EVERY EXISTS_TAC
       (map (mk_intconst o int124_num_of_int) [x;y;z;w]) THEN
     CONV_TAC INT_REDUCE_CONV) (asl,goal);;

