(* ------------------------------------------------------------------------- *)
(* The two families whose orthogonal offsets have a fixed good residue.      *)
(* ------------------------------------------------------------------------- *)

let INT_REPRESENTS_ZC124_MOD16 = prove
 (`!k n:num.
     1 <= k /\ k <= 14 /\ 0 < n /\ n MOD 16 = 14
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &4 * z pow 2 +
          &2 * z * w + &k * w pow 2 = &n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP (SPECL [`n:num`; `16`; `14`] NUM_DECOMPOSE_MOD)
    (CONJ (ARITH_RULE `~(16 = 0)`) (ASSUME `n MOD 16 = 14`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `q:num` SUBST_ALL_TAC) THEN
  ASM_CASES_TAC `q < 13` THENL
   [MATCH_MP_TAC(SPECL [`k:num`; `q:num`]
      INT_REPRESENTS_ZC124_SMALL) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(SPECL [`k:num`; `1`; `16*q+14`]
      INT_REPRESENTS_ZC124_SHIFT) THEN
    REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_ARITH_TAC;
      REWRITE_TAC[NUM_REDUCE_CONV `(1:num) EXP 2`; MULT_CLAUSES] THEN
      MATCH_MP_TAC(SPECL [`16*q+14`; `16*k-4`]
        NUM_AVOIDS_124_SUB_OF_RESIDUE) THEN
      SUBGOAL_THEN `16*k-4 = 16*(k-1)+12` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        ASM_REWRITE_TAC[MOD_MULT_ADD] THEN
        CONV_TAC NUM_REDUCE_CONV THEN ASM_ARITH_TAC]]]);;

let INT_UNIVERSAL_ZC124_NUM = prove
 (`!k:num.
     1 <= k /\ k <= 14
     ==> !n:num.
          0 < n
          ==> ?x y z w:int.
               x pow 2 + &2 * y pow 2 + &4 * z pow 2 +
               &2 * z * w + &k * w pow 2 = &n`,
  GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC(SIMP_RULE
    [INT_MUL_LZERO; INT_MUL_RZERO; INT_MUL_LID; INT_MUL_RID;
     INT_ADD_LID; INT_ADD_RID]
    (SPECL [`0`; `1`; `k:num`]
      INT_UNIVERSAL_124_CHILD_OF_MOD16)) THEN
  X_GEN_TAC `n:num` THEN STRIP_TAC THEN
  MATCH_MP_TAC(SPECL [`k:num`; `n:num`]
    INT_REPRESENTS_ZC124_MOD16) THEN
  ASM_REWRITE_TAC[]);;

let INT_REPRESENTS_DC1_124_MOD16 = prove
