(* ------------------------------------------------------------------------- *)
(* Choices between the offsets m and 4m.                                    *)
(* ------------------------------------------------------------------------- *)

let NUM_DIAG124_OFFSET_CHOICE = prove
  (`!k:num.
     1 <= k /\ k <= 14
     ==> ?s.
          k * s EXP 2 <= 56 /\
          ~((k * s EXP 2) MOD 16 = 0) /\
          ~((k * s EXP 2) MOD 16 = 6) /\
          ~((k * s EXP 2) MOD 16 = 14)`,
  GEN_TAC THEN STRIP_TAC THEN
  EXISTS_TAC `if k = 6 \/ k = 14 then 2 else 1` THEN
  NUM_RANGE_CASES_TAC `k:num` 14 THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
  ASM_ARITH_TAC);;

let NUM_YC124_OFFSET_CHOICE = prove
 (`!k:num.
     (k = 1 \/ k = 2 \/ k = 3 \/ k = 4 \/ k = 5 \/
      k = 6 \/ k = 9 \/ k = 10 \/ k = 13 \/ k = 14)
     ==> ?s.
          (4*k-2) * s EXP 2 <= 216 /\
          ~(((4*k-2) * s EXP 2) MOD 16 = 0) /\
          ~(((4*k-2) * s EXP 2) MOD 16 = 6) /\
          ~(((4*k-2) * s EXP 2) MOD 16 = 14)`,
  GEN_TAC THEN DISCH_TAC THEN
  EXISTS_TAC
   `if k = 2 \/ k = 4 \/ k = 6 \/ k = 10 \/ k = 14
    then 2 else 1` THEN
  UNDISCH_TAC
   `k = 1 \/ k = 2 \/ k = 3 \/ k = 4 \/ k = 5 \/
    k = 6 \/ k = 9 \/ k = 10 \/ k = 13 \/ k = 14` THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  CONV_TAC NUM_REDUCE_CONV);;

let NUM_RC2_124_OFFSET_CHOICE = prove
 (`!k:num.
     (k = 2 \/ k = 3 \/ k = 4 \/ k = 6 \/
      k = 8 \/ k = 10 \/ k = 11 \/ k = 12 \/ k = 14)
     ==> ?s.
          (4*k-4) * s EXP 2 <= 52 /\
          ~(((4*k-4) * s EXP 2) MOD 16 = 0) /\
          ~(((4*k-4) * s EXP 2) MOD 16 = 6) /\
          ~(((4*k-4) * s EXP 2) MOD 16 = 14)`,
  GEN_TAC THEN DISCH_TAC THEN
  EXISTS_TAC `1` THEN
  UNDISCH_TAC
   `k = 2 \/ k = 3 \/ k = 4 \/ k = 6 \/
    k = 8 \/ k = 10 \/ k = 11 \/ k = 12 \/ k = 14` THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  CONV_TAC NUM_REDUCE_CONV);;

let NUM_DC2_124_OFFSET_CHOICE = prove
