let INT_REPRESENTS_DIAG124_MOD16 = prove
 (`!k n:num.
     1 <= k /\ k <= 14 /\ 0 < n /\ n MOD 16 = 14
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &4 * z pow 2 +
          &k * w pow 2 = &n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP (SPECL [`n:num`; `16`; `14`] NUM_DECOMPOSE_MOD)
    (CONJ (ARITH_RULE `~(16 = 0)`) (ASSUME `n MOD 16 = 14`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `q:num` SUBST_ALL_TAC) THEN
  ASM_CASES_TAC `q < 13` THENL
   [MATCH_MP_TAC(SPECL [`k:num`; `q:num`]
      INT_REPRESENTS_DIAG124_SMALL) THEN
    ASM_REWRITE_TAC[];
    MP_TAC(MATCH_MP (SPEC `k:num` NUM_DIAG124_OFFSET_CHOICE)
      (CONJ (ASSUME `1 <= k`) (ASSUME `k <= 14`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `s:num` STRIP_ASSUME_TAC) THEN
    MATCH_MP_TAC(SPECL [`k:num`; `s:num`; `16*q+14`]
      INT_REPRESENTS_DIAG124_SHIFT) THEN
    CONJ_TAC THENL
     [ASM_ARITH_TAC;
      MATCH_MP_TAC(SPECL [`16*q+14`; `k * s EXP 2`]
        NUM_AVOIDS_124_SUB_OF_RESIDUE) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]]);;

let INT_UNIVERSAL_DIAG124_NUM = prove
 (`!k:num.
     1 <= k /\ k <= 14
     ==> !n:num.
          0 < n
          ==> ?x y z w:int.
               x pow 2 + &2 * y pow 2 + &4 * z pow 2 +
               &k * w pow 2 = &n`,
  GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC(SIMP_RULE
    [INT_MUL_LZERO; INT_MUL_RZERO; INT_MUL_LID; INT_MUL_RID;
     INT_ADD_LID; INT_ADD_RID]
    (SPECL [`0`; `0`; `k:num`]
      INT_UNIVERSAL_124_CHILD_OF_MOD16)) THEN
  X_GEN_TAC `n:num` THEN STRIP_TAC THEN
  MATCH_MP_TAC(SPECL [`k:num`; `n:num`]
    INT_REPRESENTS_DIAG124_MOD16) THEN
  ASM_REWRITE_TAC[]);;

let INT_REPRESENTS_YC124_LARGE = prove
 (`!k q:num.
     (k = 1 \/ k = 2 \/ k = 3 \/ k = 4 \/ k = 5 \/
      k = 6 \/ k = 9 \/ k = 10 \/ k = 13 \/ k = 14) /\
     ~(q < 13)
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &4 * z pow 2 +
          &2 * y * w + &k * w pow 2 = &(16*q+14)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP (SPEC `k:num` NUM_YC124_OFFSET_CHOICE)
    (ASSUME
      `k = 1 \/ k = 2 \/ k = 3 \/ k = 4 \/ k = 5 \/
       k = 6 \/ k = 9 \/ k = 10 \/ k = 13 \/ k = 14`)) THEN
  DISCH_THEN(X_CHOOSE_THEN `s:num` STRIP_ASSUME_TAC) THEN
  let offle = MATCH_MP
    (SPECL [`(4*k-2) * s EXP 2`; `q:num`]
      NUM_LE_16Q14_OF_LE_216)
    (CONJ (ASSUME `(4*k-2) * s EXP 2 <= 216`)
      (ASSUME `~(q < 13)`)) in
  let kpos = MATCH_MP (SPEC `k:num` NUM_YC124_K_POS)
    (ASSUME
      `k = 1 \/ k = 2 \/ k = 3 \/ k = 4 \/ k = 5 \/
       k = 6 \/ k = 9 \/ k = 10 \/ k = 13 \/ k = 14`) in
  let nres = EQT_ELIM
    ((REWRITE_CONV[MOD_MULT_ADD] THENC NUM_REDUCE_CONV)
      `(16*q+14) MOD 16 = 14`) in
  let avoids = MATCH_MP
    (SPECL [`16*q+14`; `(4*k-2) * s EXP 2`]
      NUM_AVOIDS_124_SUB_OF_RESIDUE)
    (CONJ offle
      (CONJ nres
        (CONJ
          (ASSUME `~(((4*k-2) * s EXP 2) MOD 16 = 0)`)
          (CONJ
            (ASSUME `~(((4*k-2) * s EXP 2) MOD 16 = 6)`)
            (ASSUME `~(((4*k-2) * s EXP 2) MOD 16 = 14)`))))) in
  ACCEPT_TAC(MATCH_MP
    (SPECL [`k:num`; `s:num`; `16*q+14`]
      INT_REPRESENTS_YC124_SHIFT)
    (CONJ kpos (CONJ offle avoids))));;

