   [MATCH_MP_TAC(INT_RING
     `(&2*a) pow 2 + (&2*b) pow 2 + &2*(&2*c) pow 2 =
      &16*q + &2
      ==> &2 * (a pow 2 + b pow 2 + &2*c pow 2 - &4*q) = &1`) THEN
    ASM_REWRITE_TAC[];
    MP_TAC(SPEC
      `a pow 2 + b pow 2 + &2*c pow 2 - &4*q`
      INT_TWO_MUL_NE_ONE) THEN
    ASM_REWRITE_TAC[]]);;

