      ASM_REWRITE_TAC[]];
    SUBGOAL_THEN
     `&2 * (&2*q - &2*a pow 2 - &2*b pow 2 - &2*b -
            &4*d pow 2 - &6*d - &2) = &1`
    ASSUME_TAC THENL
     [MATCH_MP_TAC(INT_RING
       `(&4*a) pow 2 + (&4*b + &2) pow 2 +
        &2*(&2*(&2*d + &1) + &1) pow 2 = &16*q + &2
        ==> &2 * (&2*q - &2*a pow 2 - &2*b pow 2 - &2*b -
