let INT_REPRESENTS_112_ODD_SECOND_16Q2 = prove
  (`!q:num.
     ?x y z t:int.
       x pow 2 + y pow 2 + &2*z pow 2 = &(16*q+2) /\
       y = &2*t + &1`,
  GEN_TAC THEN
  MP_TAC(SPEC `16*q+2` INT_REPRESENTS_112_TWO) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[ARITH_RULE `16*q+2 = 4*(4*q)+2`; MOD_MULT_ADD] THEN
      CONV_TAC NUM_REDUCE_CONV;
      REWRITE_TAC[MOD_MULT_ADD] THEN CONV_TAC NUM_REDUCE_CONV];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int`
      (X_CHOOSE_THEN `z:int` (LABEL_TAC "rep")))) THEN
  MP_TAC(SPEC `x:int` INT_PARITY_WITNESS) THEN
  DISCH_THEN(DISJ_CASES_THEN
    (X_CHOOSE_THEN `a:int` SUBST_ALL_TAC)) THEN
  MP_TAC(SPEC `y:int` INT_PARITY_WITNESS) THEN
  DISCH_THEN(DISJ_CASES_THEN
    (X_CHOOSE_THEN `b:int` SUBST_ALL_TAC)) THENL
   [MP_TAC(SPEC `z:int` INT_PARITY_WITNESS) THEN
    DISCH_THEN(DISJ_CASES_THEN
      (X_CHOOSE_THEN `c:int` SUBST_ALL_TAC)) THENL
     [CONTR_TAC
       (MP
        (NOT_ELIM(SPECL [`a:int`; `b:int`; `c:int`; `&q:int`]
          INT_112_ALL_EVEN_NE_16Q2))
        (REWRITE_RULE[GSYM INT_OF_NUM_ADD; GSYM INT_OF_NUM_MUL]
          (ASSUME
            `(&2*a) pow 2 + (&2*b) pow 2 + &2*(&2*c) pow 2 =
             &(16*q+2)`)));
      MP_TAC(SPEC `a:int` INT_PARITY_WITNESS) THEN
      DISCH_THEN(DISJ_CASES_THEN
        (X_CHOOSE_THEN `aa:int` SUBST_ALL_TAC)) THEN
      MP_TAC(SPEC `b:int` INT_PARITY_WITNESS) THEN
      DISCH_THEN(DISJ_CASES_THEN
        (X_CHOOSE_THEN `bb:int` SUBST_ALL_TAC)) THENL
       [MAP_EVERY EXISTS_TAC
         [`(&2*aa) + (&2*bb) + (&2*c + &1):int`;
          `(&2*aa) + (&2*bb) - (&2*c + &1):int`;
          `(&2*aa) - (&2*bb):int`;
          `aa + bb - c - &1:int`] THEN
        CONJ_TAC THENL
         [REMOVE_THEN "rep" MP_TAC THEN CONV_TAC INT_RING;
          CONV_TAC INT_RING];
        CONTR_TAC
         (MP
          (NOT_ELIM(SPECL [`aa:int`; `bb:int`; `c:int`; `&q:int`]
            INT_112_OPPOSITE_HALVES_NE_16Q2))
          (MATCH_MP
            (INT_RING
             `(&2*(&2*aa)) pow 2 + (&2*(&2*bb + &1)) pow 2 +
              &2*(&2*c + &1) pow 2 = &16 * &q + &2
              ==> (&4*aa) pow 2 + (&4*bb + &2) pow 2 +
                  &2*(&2*c + &1) pow 2 = &16 * &q + &2`)
            (REWRITE_RULE[GSYM INT_OF_NUM_ADD; GSYM INT_OF_NUM_MUL]
              (ASSUME
               `(&2*(&2*aa)) pow 2 + (&2*(&2*bb + &1)) pow 2 +
                &2*(&2*c + &1) pow 2 = &(16*q+2)`))));
        CONTR_TAC
         (MP
          (NOT_ELIM(SPECL [`aa:int`; `bb:int`; `c:int`; `&q:int`]
            INT_112_OPPOSITE_HALVES_SYM_NE_16Q2))
          (MATCH_MP
            (INT_RING
             `(&2*(&2*aa + &1)) pow 2 + (&2*(&2*bb)) pow 2 +
              &2*(&2*c + &1) pow 2 = &16 * &q + &2
              ==> (&4*aa + &2) pow 2 + (&4*bb) pow 2 +
                  &2*(&2*c + &1) pow 2 = &16 * &q + &2`)
            (REWRITE_RULE[GSYM INT_OF_NUM_ADD; GSYM INT_OF_NUM_MUL]
              (ASSUME
               `(&2*(&2*aa + &1)) pow 2 + (&2*(&2*bb)) pow 2 +
                &2*(&2*c + &1) pow 2 = &(16*q+2)`))));
        MAP_EVERY EXISTS_TAC
         [`(&2*aa + &1) + (&2*bb + &1) + (&2*c + &1):int`;
          `(&2*aa + &1) + (&2*bb + &1) - (&2*c + &1):int`;
          `(&2*aa + &1) - (&2*bb + &1):int`;
          `aa + bb - c:int`] THEN
        CONJ_TAC THENL
         [REMOVE_THEN "rep" MP_TAC THEN CONV_TAC INT_RING;
          CONV_TAC INT_RING]]];
    MAP_EVERY EXISTS_TAC
     [`&2*a:int`; `&2*b + &1:int`; `z:int`; `b:int`] THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY EXISTS_TAC
     [`&2*b:int`; `&2*a + &1:int`; `z:int`; `a:int`] THEN
    REMOVE_THEN "rep" MP_TAC THEN CONV_TAC INT_RING;
    MAP_EVERY EXISTS_TAC
     [`&2*a + &1:int`; `&2*b + &1:int`; `z:int`; `b:int`] THEN
    ASM_REWRITE_TAC[]]);;

let INT_REPRESENTS_112_ODD_SECOND_16Q10 = prove
 (`!q:num.
     ?x y z t:int.
       x pow 2 + y pow 2 + &2*z pow 2 = &(16*q+10) /\
       y = &2*t + &1`,
