let INT_REPRESENTS_RC2_124_5 = prove
 (`!n:num.
     n MOD 16 = 14
     ==> ?x y z w:int.
          x pow 2 + &2*y pow 2 + &4*z pow 2 +
          &4*z*w + &5*w pow 2 = &n`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(MATCH_MP (SPECL [`n:num`; `16`; `14`] NUM_DECOMPOSE_MOD)
    (CONJ (ARITH_RULE `~(16 = 0)`) (ASSUME `n MOD 16 = 14`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `q:num` SUBST_ALL_TAC) THEN
  MP_TAC(SPEC `q:num` INT_REPRESENTS_112_ODD_SECOND_16Q10) THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `u:int`
      (X_CHOOSE_THEN `y:int`
        (X_CHOOSE_THEN `z:int` STRIP_ASSUME_TAC)))) THEN
  let rep = REWRITE_RULE[GSYM INT_OF_NUM_ADD; GSYM INT_OF_NUM_MUL]
    (ASSUME
      `x pow 2 + u pow 2 + &2*y pow 2 = &(16*q+10)`) in
  let eq = MP (MP
    (INT_RING
      `x pow 2 + u pow 2 + &2*y pow 2 = &16 * &q + &10
       ==> u = &2*z + &1
       ==> x pow 2 + &2*y pow 2 + &4*z pow 2 +
           &4*z * &1 + &5 * &1 pow 2 = &16 * &q + &14`)
    rep) (ASSUME `u = &2*z + &1`) in
  MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`; `&1:int`] THEN
  MATCH_ACCEPT_TAC
   (REWRITE_RULE[INT_OF_NUM_ADD; INT_OF_NUM_MUL] eq));;

let INT_REPRESENTS_RC2_124_13 = prove
 (`!n:num.
     n MOD 16 = 14
     ==> ?x y z w:int.
          x pow 2 + &2*y pow 2 + &4*z pow 2 +
          &4*z*w + &13*w pow 2 = &n`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(MATCH_MP (SPECL [`n:num`; `16`; `14`] NUM_DECOMPOSE_MOD)
    (CONJ (ARITH_RULE `~(16 = 0)`) (ASSUME `n MOD 16 = 14`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `q:num` SUBST_ALL_TAC) THEN
  MP_TAC(SPEC `q:num` INT_REPRESENTS_112_ODD_SECOND_16Q2) THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `u:int`
      (X_CHOOSE_THEN `y:int`
        (X_CHOOSE_THEN `z:int` STRIP_ASSUME_TAC)))) THEN
  let rep = REWRITE_RULE[GSYM INT_OF_NUM_ADD; GSYM INT_OF_NUM_MUL]
    (ASSUME
      `x pow 2 + u pow 2 + &2*y pow 2 = &(16*q+2)`) in
  let eq = MP (MP
    (INT_RING
      `x pow 2 + u pow 2 + &2*y pow 2 = &16 * &q + &2
       ==> u = &2*z + &1
       ==> x pow 2 + &2*y pow 2 + &4*z pow 2 +
           &4*z * &1 + &13 * &1 pow 2 = &16 * &q + &14`)
    rep) (ASSUME `u = &2*z + &1`) in
  MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`; `&1:int`] THEN
  MATCH_ACCEPT_TAC
   (REWRITE_RULE[INT_OF_NUM_ADD; INT_OF_NUM_MUL] eq));;

let INT_REPRESENTS_RC2_124_SPECIAL = prove
 (`!k n:num.
     (k = 5 \/ k = 13) /\ n MOD 16 = 14
     ==> ?x y z w:int.
          x pow 2 + &2*y pow 2 + &4*z pow 2 +
          &4*z*w + &k*w pow 2 = &n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  let case5 = REWRITE_RULE[GSYM(ASSUME `k = 5`)]
    (MATCH_MP (SPEC `n:num` INT_REPRESENTS_RC2_124_5)
      (ASSUME `n MOD 16 = 14`)) in
  let case13 = REWRITE_RULE[GSYM(ASSUME `k = 13`)]
    (MATCH_MP (SPEC `n:num` INT_REPRESENTS_RC2_124_13)
      (ASSUME `n MOD 16 = 14`)) in
  ACCEPT_TAC(DISJ_CASES (ASSUME `k = 5 \/ k = 13`) case5 case13));;

let NUM_RC2_124_REDUCED_RANGE = prove
 (`!k:num.
     (k = 2 \/ k = 3 \/ k = 4 \/ k = 5 \/ k = 6 \/
      k = 8 \/ k = 10 \/ k = 11 \/ k = 12 \/ k = 13 \/ k = 14) /\
     ~(k = 5 \/ k = 13)
     ==> (k = 2 \/ k = 3 \/ k = 4 \/ k = 6 \/
          k = 8 \/ k = 10 \/ k = 11 \/ k = 12 \/ k = 14)`,
  MESON_TAC[]);;

let INT_REPRESENTS_RC2_124_LARGE = prove
 (`!k q:num.
     (k = 2 \/ k = 3 \/ k = 4 \/ k = 6 \/
      k = 8 \/ k = 10 \/ k = 11 \/ k = 12 \/ k = 14) /\
     ~(q < 13)
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &4 * z pow 2 +
          &4 * z * w + &k * w pow 2 = &(16*q+14)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP (SPEC `k:num` NUM_RC2_124_OFFSET_CHOICE)
    (ASSUME
      `k = 2 \/ k = 3 \/ k = 4 \/ k = 6 \/
       k = 8 \/ k = 10 \/ k = 11 \/ k = 12 \/ k = 14`)) THEN
  DISCH_THEN(X_CHOOSE_THEN `s:num` STRIP_ASSUME_TAC) THEN
  let offle = MATCH_MP
    (SPECL [`(4*k-4) * s EXP 2`; `q:num`]
      NUM_LE_16Q14_OF_LE_52)
    (CONJ (ASSUME `(4*k-4) * s EXP 2 <= 52`)
      (ASSUME `~(q < 13)`)) in
  let kpos = MATCH_MP (SPEC `k:num` NUM_RC2_124_K_POS)
    (ASSUME
      `k = 2 \/ k = 3 \/ k = 4 \/ k = 6 \/
       k = 8 \/ k = 10 \/ k = 11 \/ k = 12 \/ k = 14`) in
  let nres = EQT_ELIM
    ((REWRITE_CONV[MOD_MULT_ADD] THENC NUM_REDUCE_CONV)
      `(16*q+14) MOD 16 = 14`) in
  let avoids = MATCH_MP
    (SPECL [`16*q+14`; `(4*k-4) * s EXP 2`]
      NUM_AVOIDS_124_SUB_OF_RESIDUE)
    (CONJ offle
      (CONJ nres
        (CONJ
          (ASSUME `~(((4*k-4) * s EXP 2) MOD 16 = 0)`)
          (CONJ
            (ASSUME `~(((4*k-4) * s EXP 2) MOD 16 = 6)`)
            (ASSUME `~(((4*k-4) * s EXP 2) MOD 16 = 14)`))))) in
  ACCEPT_TAC(MATCH_MP
    (SPECL [`k:num`; `s:num`; `16*q+14`]
      INT_REPRESENTS_RC2_124_SHIFT)
    (CONJ kpos (CONJ offle avoids))));;

let INT_REPRESENTS_RC2_124_LARGE_ALL = prove
 (`!k q:num.
     (k = 2 \/ k = 3 \/ k = 4 \/ k = 5 \/ k = 6 \/
      k = 8 \/ k = 10 \/ k = 11 \/ k = 12 \/ k = 13 \/ k = 14) /\
     ~(q < 13)
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &4 * z pow 2 +
          &4 * z * w + &k * w pow 2 = &(16*q+14)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  let krange = ASSUME
    `k = 2 \/ k = 3 \/ k = 4 \/ k = 5 \/ k = 6 \/
     k = 8 \/ k = 10 \/ k = 11 \/ k = 12 \/ k = 13 \/ k = 14` in
  let nres = EQT_ELIM
    ((REWRITE_CONV[MOD_MULT_ADD] THENC NUM_REDUCE_CONV)
      `(16*q+14) MOD 16 = 14`) in
  let special = MATCH_MP
    (SPECL [`k:num`; `16*q+14`] INT_REPRESENTS_RC2_124_SPECIAL)
    (CONJ (ASSUME `k = 5 \/ k = 13`) nres) in
  let reduced = MATCH_MP (SPEC `k:num` NUM_RC2_124_REDUCED_RANGE)
    (CONJ krange (ASSUME `~(k = 5 \/ k = 13)`)) in
  let ordinary = MATCH_MP
    (SPECL [`k:num`; `q:num`] INT_REPRESENTS_RC2_124_LARGE)
    (CONJ reduced (ASSUME `~(q < 13)`)) in
  ACCEPT_TAC(DISJ_CASES
    (SPEC `k = 5 \/ k = 13` EXCLUDED_MIDDLE) special ordinary));;

let INT_REPRESENTS_RC2_124_MOD16 = prove
 (`!k n:num.
     (k = 2 \/ k = 3 \/ k = 4 \/ k = 5 \/ k = 6 \/
      k = 8 \/ k = 10 \/ k = 11 \/ k = 12 \/ k = 13 \/ k = 14) /\
     0 < n /\ n MOD 16 = 14
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &4 * z pow 2 +
          &4 * z * w + &k * w pow 2 = &n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP (SPECL [`n:num`; `16`; `14`] NUM_DECOMPOSE_MOD)
    (CONJ (ARITH_RULE `~(16 = 0)`) (ASSUME `n MOD 16 = 14`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `q:num` SUBST_ALL_TAC) THEN
  let krange = ASSUME
    `k = 2 \/ k = 3 \/ k = 4 \/ k = 5 \/ k = 6 \/
     k = 8 \/ k = 10 \/ k = 11 \/ k = 12 \/ k = 13 \/ k = 14` in
  let small = MATCH_MP
    (SPECL [`k:num`; `q:num`] INT_REPRESENTS_RC2_124_SMALL)
    (CONJ krange (ASSUME `q < 13`)) in
  let large = MATCH_MP
    (SPECL [`k:num`; `q:num`] INT_REPRESENTS_RC2_124_LARGE_ALL)
    (CONJ krange (ASSUME `~(q < 13)`)) in
  ACCEPT_TAC(DISJ_CASES (SPEC `q < 13` EXCLUDED_MIDDLE) small large));;

let INT_UNIVERSAL_RC2_124_NUM = prove
 (`!k:num.
     (k = 2 \/ k = 3 \/ k = 4 \/ k = 5 \/ k = 6 \/
      k = 8 \/ k = 10 \/ k = 11 \/ k = 12 \/ k = 13 \/ k = 14)
     ==> !n:num.
          0 < n
          ==> ?x y z w:int.
               x pow 2 + &2 * y pow 2 + &4 * z pow 2 +
               &4 * z * w + &k * w pow 2 = &n`,
  GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC(SIMP_RULE
    [INT_DOUBLE_TWO_MUL;
     INT_MUL_LZERO; INT_MUL_RZERO; INT_MUL_LID; INT_MUL_RID;
     INT_ADD_LID; INT_ADD_RID]
    (SPECL [`0`; `2`; `k:num`]
      INT_UNIVERSAL_124_CHILD_OF_MOD16)) THEN
  X_GEN_TAC `n:num` THEN STRIP_TAC THEN
  MATCH_MP_TAC(SPECL [`k:num`; `n:num`]
    INT_REPRESENTS_RC2_124_MOD16) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Packaging the explicit representation results as universality theorems.   *)
(* ------------------------------------------------------------------------- *)

let IQ_UNIVERSAL_124_CHILD_OF_NUM = prove
 (`!rb rc k:num.
     (!n:num.
        0 < n
        ==> ?x y z w:int.
             x pow 2 + &2 * y pow 2 + &4 * z pow 2 +
             &2 * &rb * y * w + &2 * &rc * z * w +
             &k * w pow 2 = &n)
     ==> iq_universal 4
          (iqmat4 (&1) (&0) (&0) (&0)
                  (&2) (&0) (&rb) (&4) (&rc) (&k))`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "all") THEN
  REWRITE_TAC[iq_universal] THEN
  X_GEN_TAC `m:int` THEN DISCH_TAC THEN
  MP_TAC(EQ_MP (SYM(SPEC `m:int` INT_OF_NUM_EXISTS))
    (MATCH_MP (SPECL [`&0:int`; `m:int`] INT_LT_IMP_LE)
      (ASSUME `&0 < m`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `n:num` SUBST_ALL_TAC) THEN
  REMOVE_THEN "all" (MP_TAC o SPEC `n:num`) THEN
  ANTS_TAC THENL
   [UNDISCH_TAC `&0 < &n` THEN REWRITE_TAC[INT_OF_NUM_LT];
    DISCH_THEN(X_CHOOSE_THEN `x:int`
      (X_CHOOSE_THEN `y:int`
        (X_CHOOSE_THEN `z:int` (X_CHOOSE_TAC `w:int`)))) THEN
    REWRITE_TAC[iq_represents] THEN
    EXISTS_TAC
     `\i:num.
        if i = 0 then (x:int) else if i = 1 then y else
        if i = 2 then z else w` THEN
    REWRITE_TAC[IQEVAL_MAT4] THEN
    CONV_TAC NUM_REDUCE_CONV THEN
    FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING]);;

let IQ_UNIVERSAL_DIAG124_NUM = prove
 (`!k:num.
     1 <= k /\ k <= 14
     ==> iq_universal 4
          (iqmat4 (&1) (&0) (&0) (&0)
                  (&2) (&0) (&0) (&4) (&0) (&k))`,
  GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC(SIMP_RULE
    [INT_MUL_LZERO; INT_MUL_RZERO; INT_MUL_LID; INT_MUL_RID;
     INT_ADD_LID; INT_ADD_RID]
    (SPECL [`0`; `0`; `k:num`] IQ_UNIVERSAL_124_CHILD_OF_NUM)) THEN
  MATCH_MP_TAC(SPEC `k:num` INT_UNIVERSAL_DIAG124_NUM) THEN
  ASM_REWRITE_TAC[]);;

let IQ_UNIVERSAL_ZC124_NUM = prove
 (`!k:num.
     1 <= k /\ k <= 14
     ==> iq_universal 4
          (iqmat4 (&1) (&0) (&0) (&0)
                  (&2) (&0) (&0) (&4) (&1) (&k))`,
  GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC(SIMP_RULE
    [INT_MUL_LZERO; INT_MUL_RZERO; INT_MUL_LID; INT_MUL_RID;
