let IQ_UNIVERSAL_OF_DIAG124_CHILD = prove
 (`!n A k.
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&0) (&0) (&4) (&0) k) A /\
     &1 <= k /\ k <= &14
     ==> iq_universal n A`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(EQ_MP (SYM(SPEC `k:int` INT_OF_NUM_EXISTS))
    (MATCH_MP (INT_ARITH `&1 <= k ==> &0 <= k`)
      (ASSUME `&1 <= k`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `c:num` SUBST_ALL_TAC) THEN
  SUBGOAL_THEN `1 <= c /\ c <= 14` ASSUME_TAC THENL
   [UNDISCH_TAC `&1 <= &c` THEN
    UNDISCH_TAC `&c <= &14` THEN
    REWRITE_TAC[INT_OF_NUM_LE] THEN ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `4`;
    `iqmat4 (&1) (&0) (&0) (&0)
            (&2) (&0) (&0) (&4) (&0) (&c)`;
    `A:num->num->int`] IQ_UNIVERSAL_OF_EMBEDS) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(SPEC `c:num` IQ_UNIVERSAL_DIAG124_NUM) THEN
  ASM_REWRITE_TAC[]);;

