   `c = 1 \/ c = 2 \/ c = 3 \/ c = 4 \/ c = 5 \/
    c = 6 \/ c = 9 \/ c = 10 \/ c = 13 \/ c = 14`
  ASSUME_TAC THENL
   [UNDISCH_TAC
     `&c = &1 \/ &c = &2 \/ &c = &3 \/ &c = &4 \/ &c = &5 \/
      &c = &6 \/ &c = &9 \/ &c = &10 \/ &c = &13 \/ &c = &14` THEN
    REWRITE_TAC[INT_OF_NUM_EQ];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `4`;
    `iqmat4 (&1) (&0) (&0) (&0)
            (&2) (&0) (&1) (&4) (&0) (&c)`;
    `A:num->num->int`] IQ_UNIVERSAL_OF_EMBEDS) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(SPEC `c:num` IQ_UNIVERSAL_YC124_NUM) THEN
  ASM_REWRITE_TAC[]);;

