    (X_CHOOSE_THEN `k:int`
      (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC))) THENL
   [MATCH_MP_TAC(ISPECL [`n:num`; `A:num->num->int`; `k:int`]
      IQ_UNIVERSAL_OF_DIAG124_CHILD) THEN
