let IQ_125_REDUCED_K_UPPER = prove
 (`!a qb rb qc rc k.
     (rb = &0 \/ rb = &1) /\
     (rc = -- &2 \/ rc = -- &1 \/ rc = &0 \/ rc = &1 \/ rc = &2) /\
     k = &10 - a pow 2 -
          &2 * qb pow 2 - &2 * qb * rb -
          &5 * qc pow 2 - &2 * qc * rc
     ==> k <= &10`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP (SPECL [`qb:int`; `rb:int`]
    INT_QUAD2_REM_NONNEG_125)
    (ASSUME `rb = &0 \/ rb = &1`)) THEN
  MP_TAC(MATCH_MP (SPECL [`qc:int`; `rc:int`]
    INT_QUAD5_BALANCED_NONNEG)
    (ASSUME
      `rc = -- &2 \/ rc = -- &1 \/ rc = &0 \/ rc = &1 \/ rc = &2`)) THEN
  MP_TAC(SPEC `a:int` INT_LE_POW_2) THEN
  ASM_INT_ARITH_TAC);;

let IQ_125_REDUCED_K_NONZERO = prove
 (`!n A a qb rb qc rc k.
     iq_positive n A /\
     (rb = &0 \/ rb = &1) /\
     (rc = -- &2 \/ rc = -- &1 \/ rc = &0 \/ rc = &1 \/ rc = &2) /\
     k = &10 - a pow 2 -
          &2 * qb pow 2 - &2 * qb * rb -
          &5 * qc pow 2 - &2 * qc * rc /\
     iq_embeds n 4
      (iqmat4 (&1) (&0) (&0) (&0)
              (&2) (&0) rb (&5) rc k) A
     ==> ~(k = &0)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)))) THEN
  DISCH_TAC THEN
  let emb0 = REWRITE_RULE [ASSUME `k = &0`]
    (ASSUME
      `iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&0) rb (&5) rc k) A`) in
  let rb0 = MATCH_MP
    (ISPECL [`n:num`; `A:num->num->int`;
      `rb:int`; `rc:int`] IQ_125_ZERO_FORCES_RB)
    (CONJ (ASSUME `iq_positive n A`)
      (CONJ (ASSUME `rb = &0 \/ rb = &1`) emb0)) in
  let rc0 = MATCH_MP
    (ISPECL [`n:num`; `A:num->num->int`;
      `rb:int`; `rc:int`] IQ_125_ZERO_FORCES_RC)
    (CONJ (ASSUME `iq_positive n A`)
      (CONJ
        (ASSUME
          `rc = -- &2 \/ rc = -- &1 \/ rc = &0 \/ rc = &1 \/ rc = &2`)
        emb0)) in
  ACCEPT_TAC
   (MP
    (NOT_ELIM(SPECL [`a:int`; `qb:int`; `qc:int`] INT_125_NOT_10))
    (MP (MP (MP (MP
      (INT_RING
        `k = &10 - a pow 2 -
             &2 * qb pow 2 - &2 * qb * rb -
             &5 * qc pow 2 - &2 * qc * rc
         ==> k = &0 ==> rb = &0 ==> rc = &0
         ==> a pow 2 + &2 * qb pow 2 + &5 * qc pow 2 = &10`)
      (ASSUME
        `k = &10 - a pow 2 -
             &2 * qb pow 2 - &2 * qb * rb -
             &5 * qc pow 2 - &2 * qc * rc`))
     (ASSUME `k = &0`))
    rb0)
   rc0)));;

let IQ_125_REDUCED_K_BOUNDS = prove
 (`!n A a qb rb qc rc k.
     iq_positive n A /\
     (rb = &0 \/ rb = &1) /\
     (rc = -- &2 \/ rc = -- &1 \/ rc = &0 \/ rc = &1 \/ rc = &2) /\
     k = &10 - a pow 2 -
          &2 * qb pow 2 - &2 * qb * rb -
          &5 * qc pow 2 - &2 * qc * rc /\
     iq_embeds n 4
      (iqmat4 (&1) (&0) (&0) (&0)
              (&2) (&0) rb (&5) rc k) A
     ==> &1 <= k /\ k <= &10`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  let knonneg = MATCH_MP
    (ISPECL [`n:num`; `A:num->num->int`;
      `rb:int`; `rc:int`; `k:int`] IQ_125_REDUCED_K_NONNEG)
    (CONJ (ASSUME `iq_positive n A`)
      (ASSUME
        `iq_embeds n 4
         (iqmat4 (&1) (&0) (&0) (&0)
                 (&2) (&0) rb (&5) rc k) A`)) in
  let knonzero = MATCH_MP
    (ISPECL [`n:num`; `A:num->num->int`; `a:int`; `qb:int`;
      `rb:int`; `qc:int`; `rc:int`; `k:int`]
      IQ_125_REDUCED_K_NONZERO)
    (CONJ (ASSUME `iq_positive n A`)
      (CONJ (ASSUME `rb = &0 \/ rb = &1`)
        (CONJ
          (ASSUME
            `rc = -- &2 \/ rc = -- &1 \/ rc = &0 \/ rc = &1 \/ rc = &2`)
          (CONJ
            (ASSUME
              `k = &10 - a pow 2 -
                   &2 * qb pow 2 - &2 * qb * rb -
                   &5 * qc pow 2 - &2 * qc * rc`)
            (ASSUME
              `iq_embeds n 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) rb (&5) rc k) A`))))) in
  let kupper = MATCH_MP
    (SPECL [`a:int`; `qb:int`; `rb:int`; `qc:int`; `rc:int`; `k:int`]
      IQ_125_REDUCED_K_UPPER)
    (CONJ (ASSUME `rb = &0 \/ rb = &1`)
      (CONJ
        (ASSUME
          `rc = -- &2 \/ rc = -- &1 \/ rc = &0 \/ rc = &1 \/ rc = &2`)
        (ASSUME
          `k = &10 - a pow 2 -
               &2 * qb pow 2 - &2 * qb * rb -
               &5 * qc pow 2 - &2 * qc * rc`))) in
  ACCEPT_TAC
   (CONJ
     (MP (MP
       (INT_ARITH `&0 <= k ==> ~(k = &0) ==> &1 <= k`)
       knonneg)
      knonzero)
     kupper));;

