  MAP_EVERY EXISTS_TAC [`rb:int`; `rc:int`; kval] THEN
  ACCEPT_TAC
   (CONJ (ASSUME `rb = &0 \/ rb = &1`)
     (CONJ
       (ASSUME
         `rc = -- &2 \/ rc = -- &1 \/ rc = &0 \/ rc = &1 \/ rc = &2`)
       (CONJ (CONJUNCT1 bounds)
         (CONJ (CONJUNCT2 bounds) (CONJ emb rep10))))));;

let IQ_EMBEDS_QUATERNARY_125 = prove
 (`!n A.
     iq_symmetric n A /\ iq_positive n A /\
     iq_embeds n 3
       (iqmat3 (&1) (&0) (&0) (&2) (&0) (&5)) A /\
     iq_represents n A (&10)
     ==> (?k. &1 <= k /\ k <= &10 /\
              iq_embeds n 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&0) (&5) (&0) k) A /\
              iq_represents 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&0) (&5) (&0) k) (&10)) \/
         (?k. &1 <= k /\ k <= &10 /\
              iq_embeds n 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&0) (&5) (&1) k) A /\
              iq_represents 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&0) (&5) (&1) k) (&10)) \/
         (?k. &1 <= k /\ k <= &10 /\
              iq_embeds n 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&0) (&5) (&2) k) A /\
              iq_represents 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&0) (&5) (&2) k) (&10)) \/
         (?k. &1 <= k /\ k <= &10 /\
              iq_embeds n 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&1) (&5) (&0) k) A /\
              iq_represents 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&1) (&5) (&0) k) (&10)) \/
         (?k. &1 <= k /\ k <= &10 /\
              iq_embeds n 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&1) (&5) (&1) k) A /\
              iq_represents 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&1) (&5) (&1) k) (&10)) \/
         (?k. &1 <= k /\ k <= &10 /\
              iq_embeds n 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&1) (&5) (&2) k) A /\
              iq_represents 4
               (iqmat4 (&1) (&0) (&0) (&0)
                       (&2) (&0) (&1) (&5) (&2) k) (&10))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`n:num`; `A:num->num->int`]
    IQ_EMBEDS_QUATERNARY_125_RAW) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `rb:int`
    (X_CHOOSE_THEN `rc:int`
      (X_CHOOSE_THEN `k:int`
        (CONJUNCTS_THEN2 ASSUME_TAC
          (CONJUNCTS_THEN2 ASSUME_TAC
            (CONJUNCTS_THEN2 ASSUME_TAC
              (CONJUNCTS_THEN2 ASSUME_TAC
                (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)))))))) THEN
  UNDISCH_TAC `rb = &0 \/ rb = &1` THEN
  DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  UNDISCH_TAC
   `rc = -- &2 \/ rc = -- &1 \/ rc = &0 \/ rc = &1 \/ rc = &2` THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THENL
   [DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
    EXISTS_TAC `k:int` THEN REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC IQ_EMBEDS_FLIP_125_NEG2 THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC IQ_REPRESENTS_FLIP_125_NEG2 THEN ASM_REWRITE_TAC[]];
    DISJ2_TAC THEN DISJ1_TAC THEN
    EXISTS_TAC `k:int` THEN REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC IQ_EMBEDS_FLIP_125_NEG1 THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC IQ_REPRESENTS_FLIP_125_NEG1 THEN ASM_REWRITE_TAC[]];
    DISJ1_TAC THEN EXISTS_TAC `k:int` THEN ASM_REWRITE_TAC[];
    DISJ2_TAC THEN DISJ1_TAC THEN
    EXISTS_TAC `k:int` THEN ASM_REWRITE_TAC[];
    DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
    EXISTS_TAC `k:int` THEN ASM_REWRITE_TAC[];
    DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN
    DISJ2_TAC THEN DISJ2_TAC THEN
    EXISTS_TAC `k:int` THEN REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC IQ_EMBEDS_FLIP_125_NEG2 THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC IQ_REPRESENTS_FLIP_125_NEG2 THEN ASM_REWRITE_TAC[]];
    DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN
    DISJ2_TAC THEN DISJ1_TAC THEN
    EXISTS_TAC `k:int` THEN REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC IQ_EMBEDS_FLIP_125_NEG1 THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC IQ_REPRESENTS_FLIP_125_NEG1 THEN ASM_REWRITE_TAC[]];
    DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN
    DISJ1_TAC THEN EXISTS_TAC `k:int` THEN ASM_REWRITE_TAC[];
    DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN
    DISJ2_TAC THEN DISJ1_TAC THEN
    EXISTS_TAC `k:int` THEN ASM_REWRITE_TAC[];
    DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN
    DISJ2_TAC THEN DISJ2_TAC THEN
    EXISTS_TAC `k:int` THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* The represented-10 certificate eliminates five reduced parameters.       *)
(* ------------------------------------------------------------------------- *)

let INT_SQ_LE_50_CASES = prove
 (`!a:int.
     a pow 2 <= &50
     ==> a = -- &7 \/ a = -- &6 \/ a = -- &5 \/ a = -- &4 \/
         a = -- &3 \/ a = -- &2 \/ a = -- &1 \/ a = &0 \/
         a = &1 \/ a = &2 \/ a = &3 \/ a = &4 \/
         a = &5 \/ a = &6 \/ a = &7`,
  GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `abs a < &8` ASSUME_TAC THENL
   [MP_TAC(SPECL [`a:int`; `&8:int`] INT_LT_SQUARE_ABS) THEN
    REWRITE_TAC[INT_ABS_NUM] THEN
    CONV_TAC NUM_REDUCE_CONV THEN ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `abs a <= &7` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC;
    MP_TAC(SPECL [`a:int`; `&7:int`] INT_ABS_BOUNDS) THEN
    ASM_REWRITE_TAC[] THEN INT_ARITH_TAC]);;

let INT_125_CHILD_NOT_10_TAC zw sum =
  let zw_bound = vsubst [zw,`q:int`] `q pow 2 <= &50` in
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN sum (LABEL_TAC "sum") THENL
   [FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING;
    ALL_TAC] THEN
  MP_TAC(SPEC `x:int` INT_LE_POW_2) THEN
  MP_TAC(SPEC `&2 * y + w:int` INT_LE_POW_2) THEN
  MP_TAC(SPEC zw INT_LE_POW_2) THEN
  MP_TAC(SPEC `w:int` INT_LE_POW_2) THEN
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `x pow 2 <= &10` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(&2 * y + w) pow 2 <= &20` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN zw_bound ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `w pow 2 <= &3` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(MATCH_MP INT_SQ_LE_10_CASES
    (ASSUME `x pow 2 <= &10`)) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  MP_TAC(MATCH_MP INT_SQ_LE_20_CASES
    (ASSUME `(&2 * y + w) pow 2 <= &20`)) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THEN
  MP_TAC(MATCH_MP INT_SQ_LE_50_CASES
    (ASSUME zw_bound)) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THEN
  MP_TAC(MATCH_MP INT_SQ_LE_3_CASES
    (ASSUME `w pow 2 <= &3`)) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  REMOVE_THEN "sum" MP_TAC THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC INT_REDUCE_CONV;;

let INT_RB1_RC0_K7_125_NOT_10 = prove
 (`!x y z w:int.
     ~(x pow 2 + &2 * y pow 2 + &5 * z pow 2 +
       &2 * y * w + &7 * w pow 2 = &10)`,
  INT_125_CHILD_NOT_10_TAC
   `&5 * z + &0 * w:int`
   `&10 * x pow 2 + &5 * (&2 * y + w) pow 2 +
    &2 * (&5 * z + &0 * w) pow 2 + &65 * w pow 2 = &100`);;

