let INT_RB1_RC2_K7_125_NOT_10 = prove
 (`!x y z w:int.
     ~(x pow 2 + &2 * y pow 2 + &5 * z pow 2 +
       &2 * y * w + &4 * z * w + &7 * w pow 2 = &10)`,
  INT_125_CHILD_NOT_10_TAC
   `&5 * z + &2 * w:int`
