let IQ_RB1_RC0_125_NOT_REPRESENTS_10 = prove
 (`!k:int.
     (k = &7 \/ k = &8)
     ==> ~iq_represents 4
          (iqmat4 (&1) (&0) (&0) (&0)
                  (&2) (&0) (&1) (&5) (&0) k) (&10)`,
  GEN_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[iq_represents] THEN
  DISCH_THEN(X_CHOOSE_TAC `v:num->int`) THEN
  SUBGOAL_THEN
   `v 0 pow 2 + &2 * v 1 pow 2 + &5 * v 2 pow 2 +
    &2 * v 1 * v 3 + k * v 3 pow 2 = &10`
  ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC) THEN REWRITE_TAC[IQEVAL_MAT4] THEN
    CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_RING;
    UNDISCH_TAC `k = &7 \/ k = &8` THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    ASM_MESON_TAC
     [INT_RB1_RC0_K7_125_NOT_10; INT_RB1_RC0_K8_125_NOT_10]]);;

let IQ_RB1_RC1_125_NOT_REPRESENTS_10 = prove
 (`!k:int.
     (k = &4 \/ k = &8)
     ==> ~iq_represents 4
          (iqmat4 (&1) (&0) (&0) (&0)
                  (&2) (&0) (&1) (&5) (&1) k) (&10)`,
  GEN_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[iq_represents] THEN
  DISCH_THEN(X_CHOOSE_TAC `v:num->int`) THEN
  SUBGOAL_THEN
   `v 0 pow 2 + &2 * v 1 pow 2 + &5 * v 2 pow 2 +
    &2 * v 1 * v 3 + &2 * v 2 * v 3 +
    k * v 3 pow 2 = &10`
  ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC) THEN REWRITE_TAC[IQEVAL_MAT4] THEN
    CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_RING;
    UNDISCH_TAC `k = &4 \/ k = &8` THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    ASM_MESON_TAC
     [INT_RB1_RC1_K4_125_NOT_10; INT_RB1_RC1_K8_125_NOT_10]]);;

let IQ_RB1_RC2_K7_125_NOT_REPRESENTS_10 = prove
 (`~iq_represents 4
      (iqmat4 (&1) (&0) (&0) (&0)
              (&2) (&0) (&1) (&5) (&2) (&7)) (&10)`,
  REWRITE_TAC[iq_represents] THEN
  DISCH_THEN(X_CHOOSE_TAC `v:num->int`) THEN
  MP_TAC(SPECL
    [`v 0:int`; `v 1:int`; `v 2:int`; `v 3:int`]
    INT_RB1_RC2_K7_125_NOT_10) THEN
  FIRST_X_ASSUM(MP_TAC) THEN REWRITE_TAC[IQEVAL_MAT4] THEN
  CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_RING);;

let IQ_RB1_RC2_K1_125_NOT_EMBEDS = prove
 (`!n A.
     iq_positive n A
     ==> ~iq_embeds n 4
          (iqmat4 (&1) (&0) (&0) (&0)
                  (&2) (&0) (&1) (&5) (&2) (&1)) A`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN DISCH_TAC THEN
  MP_TAC(MATCH_MP
    (ISPECL
      [`n:num`; `4`;
       `iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&0) (&1) (&5) (&2) (&1)`;
       `A:num->num->int`] IQ_EMBEDDED_NONNEG)
    (CONJ
      (ASSUME `iq_positive n A`)
      (ASSUME
       `iq_embeds n 4
        (iqmat4 (&1) (&0) (&0) (&0)
                (&2) (&0) (&1) (&5) (&2) (&1)) A`))) THEN
  DISCH_THEN(MP_TAC o SPEC
   `\i:num.
      if i = 1 then -- &5 else if i = 2 then -- &4 else
      if i = 3 then &10 else &0`) THEN
  REWRITE_TAC[IQEVAL_MAT4] THEN
  CONV_TAC NUM_REDUCE_CONV THEN INT_ARITH_TAC);;

let IQ_RB1_RC0_125_PARAMETER_CASES = prove
 (`!k:int.
     &1 <= k /\ k <= &10 /\
     iq_represents 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&0) (&1) (&5) (&0) k) (&10)
     ==> k = &1 \/ k = &2 \/ k = &3 \/ k = &4 \/
         k = &5 \/ k = &6 \/ k = &9 \/ k = &10`,
  GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `k = &1 \/ k = &2 \/ k = &3 \/ k = &4 \/ k = &5 \/
    k = &6 \/ k = &7 \/ k = &8 \/ k = &9 \/ k = &10`
  MP_TAC THENL
   [ASM_INT_ARITH_TAC;
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    ASM_MESON_TAC[IQ_RB1_RC0_125_NOT_REPRESENTS_10]]);;

let IQ_RB1_RC1_125_PARAMETER_CASES = prove
 (`!k:int.
     &1 <= k /\ k <= &10 /\
     iq_represents 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&0) (&1) (&5) (&1) k) (&10)
     ==> k = &1 \/ k = &2 \/ k = &3 \/ k = &5 \/
         k = &6 \/ k = &7 \/ k = &9 \/ k = &10`,
  GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `k = &1 \/ k = &2 \/ k = &3 \/ k = &4 \/ k = &5 \/
    k = &6 \/ k = &7 \/ k = &8 \/ k = &9 \/ k = &10`
  MP_TAC THENL
   [ASM_INT_ARITH_TAC;
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    ASM_MESON_TAC[IQ_RB1_RC1_125_NOT_REPRESENTS_10]]);;

let IQ_RB1_RC2_125_PARAMETER_CASES = prove
 (`!n A k.
     iq_positive n A /\
     &1 <= k /\ k <= &10 /\
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&0) (&1) (&5) (&2) k) A /\
     iq_represents 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&0) (&1) (&5) (&2) k) (&10)
     ==> k = &2 \/ k = &3 \/ k = &4 \/ k = &5 \/
         k = &6 \/ k = &8 \/ k = &9 \/ k = &10`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
  SUBGOAL_THEN
   `k = &1 \/ k = &2 \/ k = &3 \/ k = &4 \/ k = &5 \/
    k = &6 \/ k = &7 \/ k = &8 \/ k = &9 \/ k = &10`
  MP_TAC THENL
   [ASM_INT_ARITH_TAC;
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    ASM_MESON_TAC
     [IQ_RB1_RC2_K1_125_NOT_EMBEDS;
      IQ_RB1_RC2_K7_125_NOT_REPRESENTS_10]]);;

(* ------------------------------------------------------------------------- *)
(* Integral orthogonal shifts into the diagonal ternary subform.             *)
(* ------------------------------------------------------------------------- *)

let INT_REPRESENTS_DIAG125_SHIFT = prove
 (`!k s n:num.
     k * s EXP 2 <= n /\
     (?x y z:int.
        x pow 2 + &2 * y pow 2 + &5 * z pow 2 =
        &(n - k * s EXP 2))
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &5 * z pow 2 +
          &k * w pow 2 = &n`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `x:int`
      (X_CHOOSE_THEN `y:int`
        (X_CHOOSE_THEN `z:int` (LABEL_TAC "rep"))))) THEN
  MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`; `&s:int`] THEN
  SUBGOAL_THEN
   `&(n - k * s EXP 2) =
    (&n:int) - (&k:int) * (&s:int) pow 2`
  ASSUME_TAC THENL
   [ASM_SIMP_TAC[INT_OF_NUM_SUB; INT_OF_NUM_MUL; INT_OF_NUM_POW];
    REMOVE_THEN "rep" MP_TAC THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING]);;

let INT_REPRESENTS_RC1_125_SHIFT = prove
 (`!k s n:num.
     1 <= k /\ (25*k-5) * s EXP 2 <= n /\
     (?x y z:int.
        x pow 2 + &2 * y pow 2 + &5 * z pow 2 =
        &(n - (25*k-5) * s EXP 2))
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &5 * z pow 2 +
          &2 * z * w + &k * w pow 2 = &n`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `x:int`
        (X_CHOOSE_THEN `y:int`
          (X_CHOOSE_THEN `z:int` (LABEL_TAC "rep")))))) THEN
  MAP_EVERY EXISTS_TAC
   [`x:int`; `y:int`; `z - &s:int`; `&5 * &s:int`] THEN
  SUBGOAL_THEN `5 <= 25*k` ASSUME_TAC THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&(n - (25*k-5) * s EXP 2) =
    (&n:int) - (&25 * &k - &5) * (&s:int) pow 2`
  ASSUME_TAC THENL
   [ASM_SIMP_TAC[INT_OF_NUM_SUB; INT_OF_NUM_MUL; INT_OF_NUM_POW];
    REMOVE_THEN "rep" MP_TAC THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING]);;

let INT_REPRESENTS_RC2_125_SHIFT = prove
 (`!k s n:num.
     1 <= k /\ (25*k-20) * s EXP 2 <= n /\
     (?x y z:int.
        x pow 2 + &2 * y pow 2 + &5 * z pow 2 =
        &(n - (25*k-20) * s EXP 2))
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &5 * z pow 2 +
          &4 * z * w + &k * w pow 2 = &n`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `x:int`
        (X_CHOOSE_THEN `y:int`
          (X_CHOOSE_THEN `z:int` (LABEL_TAC "rep")))))) THEN
  MAP_EVERY EXISTS_TAC
   [`x:int`; `y:int`; `z - &2 * &s:int`; `&5 * &s:int`] THEN
  SUBGOAL_THEN `20 <= 25*k` ASSUME_TAC THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&(n - (25*k-20) * s EXP 2) =
    (&n:int) - (&25 * &k - &20) * (&s:int) pow 2`
  ASSUME_TAC THENL
   [ASM_SIMP_TAC[INT_OF_NUM_SUB; INT_OF_NUM_MUL; INT_OF_NUM_POW];
    REMOVE_THEN "rep" MP_TAC THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING]);;

let INT_REPRESENTS_RB1_125_SHIFT = prove
 (`!k s n:num.
     1 <= k /\ (4*k-2) * s EXP 2 <= n /\
     (?x y z:int.
        x pow 2 + &2 * y pow 2 + &5 * z pow 2 =
        &(n - (4*k-2) * s EXP 2))
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &5 * z pow 2 +
          &2 * y * w + &k * w pow 2 = &n`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `x:int`
        (X_CHOOSE_THEN `y:int`
          (X_CHOOSE_THEN `z:int` (LABEL_TAC "rep")))))) THEN
  MAP_EVERY EXISTS_TAC
   [`x:int`; `y - &s:int`; `z:int`; `&2 * &s:int`] THEN
  SUBGOAL_THEN `2 <= 4*k` ASSUME_TAC THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&(n - (4*k-2) * s EXP 2) =
    (&n:int) - (&4 * &k - &2) * (&s:int) pow 2`
  ASSUME_TAC THENL
   [ASM_SIMP_TAC[INT_OF_NUM_SUB; INT_OF_NUM_MUL; INT_OF_NUM_POW];
    REMOVE_THEN "rep" MP_TAC THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING]);;

let INT_REPRESENTS_RB1_RC1_125_SHIFT = prove
 (`!k s n:num.
     1 <= k /\ (100*k-70) * s EXP 2 <= n /\
     (?x y z:int.
        x pow 2 + &2 * y pow 2 + &5 * z pow 2 =
        &(n - (100*k-70) * s EXP 2))
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &5 * z pow 2 +
          &2 * y * w + &2 * z * w + &k * w pow 2 = &n`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `x:int`
        (X_CHOOSE_THEN `y:int`
          (X_CHOOSE_THEN `z:int` (LABEL_TAC "rep")))))) THEN
  MAP_EVERY EXISTS_TAC
   [`x:int`; `y - &5 * &s:int`; `z - &2 * &s:int`;
    `&10 * &s:int`] THEN
  SUBGOAL_THEN `70 <= 100*k` ASSUME_TAC THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&(n - (100*k-70) * s EXP 2) =
    (&n:int) - (&100 * &k - &70) * (&s:int) pow 2`
  ASSUME_TAC THENL
   [ASM_SIMP_TAC[INT_OF_NUM_SUB; INT_OF_NUM_MUL; INT_OF_NUM_POW];
    REMOVE_THEN "rep" MP_TAC THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING]);;

let INT_REPRESENTS_RB1_RC2_125_SHIFT = prove
 (`!k s n:num.
     2 <= k /\ (100*k-130) * s EXP 2 <= n /\
     (?x y z:int.
        x pow 2 + &2 * y pow 2 + &5 * z pow 2 =
        &(n - (100*k-130) * s EXP 2))
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &5 * z pow 2 +
          &2 * y * w + &4 * z * w + &k * w pow 2 = &n`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `x:int`
        (X_CHOOSE_THEN `y:int`
          (X_CHOOSE_THEN `z:int` (LABEL_TAC "rep")))))) THEN
  MAP_EVERY EXISTS_TAC
   [`x:int`; `y - &5 * &s:int`; `z - &4 * &s:int`;
    `&10 * &s:int`] THEN
  SUBGOAL_THEN `130 <= 100*k` ASSUME_TAC THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&(n - (100*k-130) * s EXP 2) =
    (&n:int) - (&100 * &k - &130) * (&s:int) pow 2`
  ASSUME_TAC THENL
   [ASM_SIMP_TAC[INT_OF_NUM_SUB; INT_OF_NUM_MUL; INT_OF_NUM_POW];
    REMOVE_THEN "rep" MP_TAC THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING]);;

(* ------------------------------------------------------------------------- *)
(* The local obstruction and the modulus-25 subtraction step.                *)
(* ------------------------------------------------------------------------- *)

let num_125_exception = new_definition
 `num_125_exception n <=>
    ?a u. n = 5 EXP (2*a+1) * u /\
          (u MOD 5 = 2 \/ u MOD 5 = 3)`;;

let NUM_MUL5_MOD25_2 = prove
 (`!u:num. u MOD 5 = 2 ==> (5*u) MOD 25 = 10`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(MATCH_MP (SPECL [`u:num`; `5`; `2`] NUM_DECOMPOSE_MOD)
    (CONJ (ARITH_RULE `~(5 = 0)`) (ASSUME `u MOD 5 = 2`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `q:num` SUBST_ALL_TAC) THEN
  REWRITE_TAC[ARITH_RULE `5 * (5*(q:num)+2) = 25*q+10`;
    MOD_MULT_ADD] THEN
  CONV_TAC NUM_REDUCE_CONV);;

let NUM_MUL5_MOD25_3 = prove
 (`!u:num. u MOD 5 = 3 ==> (5*u) MOD 25 = 15`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(MATCH_MP (SPECL [`u:num`; `5`; `3`] NUM_DECOMPOSE_MOD)
    (CONJ (ARITH_RULE `~(5 = 0)`) (ASSUME `u MOD 5 = 3`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `q:num` SUBST_ALL_TAC) THEN
  REWRITE_TAC[ARITH_RULE `5 * (5*(q:num)+3) = 25*q+15`;
    MOD_MULT_ADD] THEN
  CONV_TAC NUM_REDUCE_CONV);;

let NUM_125_HIGH_POWER_MOD25 = prove
 (`!b u:num. (5 EXP (2 * SUC b + 1) * u) MOD 25 = 0`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC
   [ARITH_RULE `2 * SUC b + 1 = SUC(SUC(2*b+1))`; EXP;
    ARITH_RULE `(5 * 5 * (q:num)) * u = 25 * (q*u)`;
    MOD_MULT]);;

let NUM_125_EXCEPTION_MOD25 = prove
 (`!n:num.
     num_125_exception n
     ==> n MOD 25 = 0 \/ n MOD 25 = 10 \/ n MOD 25 = 15`,
  GEN_TAC THEN REWRITE_TAC[num_125_exception] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:num`
    (X_CHOOSE_THEN `u:num`
      (CONJUNCTS_THEN2 (LABEL_TAC "eq") ASSUME_TAC))) THEN
  ASM_CASES_TAC `a = 0` THENL
   [UNDISCH_TAC `a = 0` THEN DISCH_THEN SUBST_ALL_TAC THEN
    REMOVE_THEN "eq" SUBST1_TAC THEN
    CONV_TAC NUM_REDUCE_CONV THEN
    ASM_MESON_TAC[NUM_MUL5_MOD25_2; NUM_MUL5_MOD25_3];
    MP_TAC(SPEC `a:num` num_CASES) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `b:num` SUBST_ALL_TAC) THEN
    DISJ1_TAC THEN REMOVE_THEN "eq" SUBST1_TAC THEN
    REWRITE_TAC[NUM_125_HIGH_POWER_MOD25]]);;

let NUM_125_EXCEPTION_NOT_DIV25 = prove
 (`!n:num.
     num_125_exception n /\ ~(25 divides n)
     ==> n MOD 25 = 10 \/ n MOD 25 = 15`,
  GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP (SPEC `n:num` NUM_125_EXCEPTION_MOD25)
    (ASSUME `num_125_exception n`)) THEN
  UNDISCH_TAC `~(25 divides n)` THEN
  REWRITE_TAC[DIVIDES_MOD] THEN CONV_TAC NUM_REDUCE_CONV THEN
  MESON_TAC[]);;

let NUM_AVOIDS_125_SUB_OF_RESIDUES = prove
 (`!n c:num.
     c <= n /\
     (n MOD 25 = 10 \/ n MOD 25 = 15) /\
     ~(((0 + c MOD 25) MOD 25 = n MOD 25) \/
       ((10 + c MOD 25) MOD 25 = n MOD 25) \/
       ((15 + c MOD 25) MOD 25 = n MOD 25))
     ==> ~num_125_exception (n - c)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  DISCH_THEN(fun th ->
    MP_TAC(MATCH_MP (SPEC `n - c:num` NUM_125_EXCEPTION_MOD25) th)) THEN
  DISCH_TAC THEN
  (SUBGOAL_THEN
    `((n - c) MOD 25 + c MOD 25) MOD 25 = n MOD 25`
   ASSUME_TAC THENL
    [REWRITE_TAC[MOD_ADD_MOD] THEN ASM_SIMP_TAC[SUB_ADD];
     ALL_TAC]) THEN
  ASM_MESON_TAC[]);;

let num_125_shift_good = new_definition
 `num_125_shift_good a r <=>
    ~(((0 + r) MOD 25 = a) \/
      ((10 + r) MOD 25 = a) \/
      ((15 + r) MOD 25 = a))`;;

let NUM_125_SHIFT_GOOD_ONE_OR_FOUR = prove
 (`!a r:num.
     (a = 10 \/ a = 15) /\ r < 25 /\ ~(r = 0)
     ==> num_125_shift_good a r \/
         num_125_shift_good a ((4*r) MOD 25)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
  SUBGOAL_THEN `(r:num) <= 24` ASSUME_TAC THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  UNDISCH_TAC `a = 10 \/ a = 15` THEN
  DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  NUM_RANGE_CASES_TAC `r:num` 24 THEN
  ASM_REWRITE_TAC[num_125_shift_good] THEN
  CONV_TAC NUM_REDUCE_CONV THEN ASM_ARITH_TAC);;

let NUM_AVOIDS_125_SUB_ONE_OR_FOUR = prove
 (`!n c:num.
     4*c <= n /\
     (n MOD 25 = 10 \/ n MOD 25 = 15) /\
     ~(c MOD 25 = 0)
     ==> ~num_125_exception (n - c) \/
         ~num_125_exception (n - 4*c)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
  SUBGOAL_THEN `(c:num) <= n` ASSUME_TAC THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(4*c) MOD 25 = (4 * (c MOD 25)) MOD 25`
  ASSUME_TAC THENL
   [CONV_TAC SYM_CONV THEN REWRITE_TAC[MOD_MULT_RMOD];
    ALL_TAC] THEN
  MP_TAC(SPECL [`n MOD 25`; `c MOD 25`]
   NUM_125_SHIFT_GOOD_ONE_OR_FOUR) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[MOD_LT_EQ_LT] THEN CONV_TAC NUM_REDUCE_CONV;
    DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
     [DISJ1_TAC THEN
      MATCH_MP_TAC(SPECL [`n:num`; `c:num`]
        NUM_AVOIDS_125_SUB_OF_RESIDUES) THEN
      ASM_REWRITE_TAC[GSYM num_125_shift_good];
      DISJ2_TAC THEN
      MATCH_MP_TAC(SPECL [`n:num`; `4*c:num`]
        NUM_AVOIDS_125_SUB_OF_RESIDUES) THEN
      ASM_REWRITE_TAC[GSYM num_125_shift_good]]]);;

(* All six completed-square coefficients are positive, at most 1000, and
   nonzero modulo 25 in the reduced parameter ranges. *)

let NUM_DIAG125_SHIFT_COEFF = prove
 (`!k:num.
     1 <= k /\ k <= 10
     ==> 0 < k /\ k <= 1000 /\ ~(k MOD 25 = 0)`,
  GEN_TAC THEN STRIP_TAC THEN
  NUM_RANGE_CASES_TAC `k:num` 10 THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN ASM_ARITH_TAC);;

let NUM_RC1_125_SHIFT_COEFF = prove
 (`!k:num.
     1 <= k /\ k <= 10
     ==> 0 < 25*k-5 /\ 25*k-5 <= 1000 /\
         ~((25*k-5) MOD 25 = 0)`,
  GEN_TAC THEN STRIP_TAC THEN
  NUM_RANGE_CASES_TAC `k:num` 10 THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN ASM_ARITH_TAC);;

let NUM_RC2_125_SHIFT_COEFF = prove
 (`!k:num.
     1 <= k /\ k <= 10
     ==> 0 < 25*k-20 /\ 25*k-20 <= 1000 /\
         ~((25*k-20) MOD 25 = 0)`,
  GEN_TAC THEN STRIP_TAC THEN
  NUM_RANGE_CASES_TAC `k:num` 10 THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN ASM_ARITH_TAC);;

let NUM_RB1_125_SHIFT_COEFF = prove
 (`!k:num.
     1 <= k /\ k <= 10
     ==> 0 < 4*k-2 /\ 4*k-2 <= 1000 /\
         ~((4*k-2) MOD 25 = 0)`,
  GEN_TAC THEN STRIP_TAC THEN
  NUM_RANGE_CASES_TAC `k:num` 10 THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN ASM_ARITH_TAC);;

let NUM_RB1_RC1_125_SHIFT_COEFF = prove
 (`!k:num.
     1 <= k /\ k <= 10
     ==> 0 < 100*k-70 /\ 100*k-70 <= 1000 /\
         ~((100*k-70) MOD 25 = 0)`,
  GEN_TAC THEN STRIP_TAC THEN
  NUM_RANGE_CASES_TAC `k:num` 10 THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN ASM_ARITH_TAC);;

let NUM_RB1_RC2_125_SHIFT_COEFF = prove
 (`!k:num.
     2 <= k /\ k <= 10
     ==> 0 < 100*k-130 /\ 100*k-130 <= 1000 /\
         ~((100*k-130) MOD 25 = 0)`,
  GEN_TAC THEN STRIP_TAC THEN
  NUM_RANGE_CASES_TAC `k:num` 10 THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN ASM_ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* A generic minimal-counterexample descent for all six child families.      *)
(* ------------------------------------------------------------------------- *)

let INT_REPRESENTS_125_CHILD_SCALE25 = prove
 (`!rb rc k n:num.
     (?x y z w:int.
        x pow 2 + &2 * y pow 2 + &5 * z pow 2 +
        &2 * &rb * y * w + &2 * &rc * z * w +
        &k * w pow 2 = &n)
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &5 * z pow 2 +
          &2 * &rb * y * w + &2 * &rc * z * w +
          &k * w pow 2 = &(25*n)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int`
      (X_CHOOSE_THEN `z:int` (X_CHOOSE_TAC `w:int`)))) THEN
  MAP_EVERY EXISTS_TAC
   [`&5*x:int`; `&5*y:int`; `&5*z:int`; `&5*w:int`] THEN
  FIRST_X_ASSUM(MP_TAC) THEN
  REWRITE_TAC[GSYM INT_OF_NUM_MUL] THEN CONV_TAC INT_RING);;

let NUM_125_CHILD_DESCENT = prove
 (`!R c.
     0 < c /\ ~(c MOD 25 = 0) /\
     (!m:num. R m ==> R (25*m)) /\
     (!m:num. ~num_125_exception m ==> R m) /\
     (!m s:num.
        c * s EXP 2 <= m /\
        ~num_125_exception (m - c * s EXP 2)
        ==> R m) /\
     (!m:num.
        0 < m /\ ~(m = 15) /\
        (m = 375 \/
         (m < 4*c /\ (m MOD 25 = 10 \/ m MOD 25 = 15)))
        ==> R m)
     ==> !m:num. 0 < m /\ ~(m = 15) ==> R m`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC num_WF THEN X_GEN_TAC `m:num` THEN
  DISCH_THEN(LABEL_TAC "ind") THEN STRIP_TAC THEN
  ASM_CASES_TAC `25 divides m` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `q:num` ASSUME_TAC o
      REWRITE_RULE[divides]) THEN
    ASM_CASES_TAC `q = 15` THENL
     [MATCH_MP_TAC(SPEC `m:num` (ASSUME
        `!m:num.
           0 < m /\ ~(m = 15) /\
           (m = 375 \/
            m < 4*c /\ (m MOD 25 = 10 \/ m MOD 25 = 15))
           ==> R m`)) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      SUBGOAL_THEN `q < m /\ 0 < q` STRIP_ASSUME_TAC THENL
       [ASM_ARITH_TAC;
        ALL_TAC] THEN
      ONCE_REWRITE_TAC[ASSUME `m = 25 * q`] THEN
      MATCH_MP_TAC(SPEC `q:num` (ASSUME
        `!m:num. R m ==> R (25*m)`)) THEN
      REMOVE_THEN "ind" (MP_TAC o SPEC `q:num`) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  ASM_CASES_TAC `num_125_exception m` THENL
   [MP_TAC(MATCH_MP (SPEC `m:num` NUM_125_EXCEPTION_NOT_DIV25)
      (CONJ (ASSUME `num_125_exception m`)
        (ASSUME `~(25 divides m)`))) THEN
    DISCH_THEN(LABEL_TAC "residue") THEN
    ASM_CASES_TAC `m < 4*c` THENL
     [MATCH_MP_TAC(SPEC `m:num` (ASSUME
        `!m:num.
           0 < m /\ ~(m = 15) /\
           (m = 375 \/
            m < 4*c /\ (m MOD 25 = 10 \/ m MOD 25 = 15))
           ==> R m`)) THEN
      ASM_REWRITE_TAC[];
      SUBGOAL_THEN `4*c <= m` ASSUME_TAC THENL
       [ASM_ARITH_TAC;
        ALL_TAC] THEN
      MP_TAC(MATCH_MP (SPECL [`m:num`; `c:num`]
        NUM_AVOIDS_125_SUB_ONE_OR_FOUR)
        (CONJ (ASSUME `4*c <= m`)
          (CONJ
            (ASSUME `m MOD 25 = 10 \/ m MOD 25 = 15`)
            (ASSUME `~(c MOD 25 = 0)`)))) THEN
      DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
       [MATCH_MP_TAC(SPECL [`m:num`; `1`] (ASSUME
          `!m s:num.
             c * s EXP 2 <= m /\
             ~num_125_exception (m - c * s EXP 2)
             ==> R m`)) THEN
        REWRITE_TAC[EXP_2; MULT_CLAUSES] THEN ASM_REWRITE_TAC[] THEN
        ASM_ARITH_TAC;
        MATCH_MP_TAC(SPECL [`m:num`; `2`] (ASSUME
          `!m s:num.
             c * s EXP 2 <= m /\
             ~num_125_exception (m - c * s EXP 2)
             ==> R m`)) THEN
        CONV_TAC NUM_REDUCE_CONV THEN
        ONCE_REWRITE_TAC[MULT_SYM] THEN ASM_REWRITE_TAC[]]];
    MATCH_MP_TAC(SPEC `m:num` (ASSUME
      `!m:num. ~num_125_exception m ==> R m`)) THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Kernel-checked finite certificates for the exceptional small targets.     *)
(* ------------------------------------------------------------------------- *)

let int125_num_of_int i =
  if i < 0
  then minus_num(num_of_string(string_of_int(-i)))
  else num_of_string(string_of_int i);;

let INT125_CERT_TAC rb rc k =
  fun (asl,goal) ->
    let _,bod = strip_exists goal in
    let _,rhs = dest_eq bod in
    let n = int_of_string(string_of_num(dest_intconst rhs)) in
    let bound =
      int_of_float(float_sqrt(float_of_int(8 * n))) + 2 in
    let signed i =
      if i = 0 then 0 else if i mod 2 = 1 then (i + 1) / 2 else -(i / 2) in
    let rec find_w iw =
      if iw > 2 * bound then failwith "INT125_CERT_TAC" else
      let w = signed iw in
      let rec find_z iz =
        if iz > 2 * bound then find_w (iw + 1) else
        let z = signed iz in
        let rec find_y iy =
          if iy > 2 * bound then find_z (iz + 1) else
          let y = signed iy in
          let r =
            n - 2*y*y - 5*z*z -
            2*rb*y*w - 2*rc*z*w - k*w*w in
          if r < 0 then find_y (iy + 1) else
          let x = int_of_float(float_sqrt(float_of_int r)) in
          if x*x = r then (x,y,z,w) else find_y (iy + 1) in
        find_y 0 in
      find_z 0 in
    let x,y,z,w = find_w 0 in
    (MAP_EVERY EXISTS_TAC
       (map (mk_intconst o int125_num_of_int) [x;y;z;w]) THEN
     CONV_TAC INT_REDUCE_CONV) (asl,goal);;

let INT125_BASE_TAC rb rc k hi10 hi15 =
  REMOVE_THEN "base"
   (DISJ_CASES_THEN2
     SUBST_ALL_TAC
     (CONJUNCTS_THEN2 ASSUME_TAC
       (DISJ_CASES_THEN ASSUME_TAC))) THENL
   [CONV_TAC NUM_REDUCE_CONV THEN INT125_CERT_TAC rb rc k;
    MP_TAC(MATCH_MP
      (SPECL [`m:num`; `25`; `10`] NUM_DECOMPOSE_MOD)
      (CONJ (ARITH_RULE `~(25 = 0)`)
        (ASSUME `m MOD 25 = 10`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `q:num` SUBST_ALL_TAC) THEN
    NUM_RANGE_CASES_THEN `q:num` hi10
     (TRY ASM_ARITH_TAC THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
      INT125_CERT_TAC rb rc k);
    MP_TAC(MATCH_MP
      (SPECL [`m:num`; `25`; `15`] NUM_DECOMPOSE_MOD)
      (CONJ (ARITH_RULE `~(25 = 0)`)
        (ASSUME `m MOD 25 = 15`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `q:num` SUBST_ALL_TAC) THEN
    NUM_RANGE_CASES_THEN `q:num` hi15
     (TRY ASM_ARITH_TAC THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
      INT125_CERT_TAC rb rc k)];;

let INT_REPRESENTS_DIAG125_BASE = prove
 (`!k m:num.
     1 <= k /\ k <= 10 /\ 0 < m /\ ~(m = 15) /\
     (m = 375 \/
      (m < 4*k /\ (m MOD 25 = 10 \/ m MOD 25 = 15)))
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &5 * z pow 2 +
          &k * w pow 2 = &m`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "base"))))) THEN
  SUBGOAL_THEN
   `k = 1 \/ k = 2 \/ k = 3 \/ k = 4 \/ k = 5 \/
    k = 6 \/ k = 7 \/ k = 8 \/ k = 9 \/ k = 10`
  MP_TAC THENL
   [ASM_ARITH_TAC;
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THENL
     [INT125_BASE_TAC 0 0 1 0 0;
      INT125_BASE_TAC 0 0 2 0 0;
      INT125_BASE_TAC 0 0 3 0 0;
      INT125_BASE_TAC 0 0 4 0 0;
      INT125_BASE_TAC 0 0 5 0 0;
      INT125_BASE_TAC 0 0 6 0 0;
      INT125_BASE_TAC 0 0 7 0 0;
      INT125_BASE_TAC 0 0 8 0 0;
      INT125_BASE_TAC 0 0 9 1 0;
      INT125_BASE_TAC 0 0 10 1 0]]);;

let INT_REPRESENTS_RC1_125_BASE = prove
 (`!k m:num.
     1 <= k /\ k <= 10 /\ 0 < m /\ ~(m = 15) /\
     (m = 375 \/
      (m < 4*(25*k-5) /\ (m MOD 25 = 10 \/ m MOD 25 = 15)))
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &5 * z pow 2 +
          &2 * z * w + &k * w pow 2 = &m`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "base"))))) THEN
  SUBGOAL_THEN
   `k = 1 \/ k = 2 \/ k = 3 \/ k = 4 \/ k = 5 \/
    k = 6 \/ k = 7 \/ k = 8 \/ k = 9 \/ k = 10`
  MP_TAC THENL
   [ASM_ARITH_TAC;
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THENL
     [INT125_BASE_TAC 0 1 1 2 2;
      INT125_BASE_TAC 0 1 2 6 6;
      INT125_BASE_TAC 0 1 3 10 10;
      INT125_BASE_TAC 0 1 4 14 14;
      INT125_BASE_TAC 0 1 5 18 18;
      INT125_BASE_TAC 0 1 6 22 22;
      INT125_BASE_TAC 0 1 7 26 26;
      INT125_BASE_TAC 0 1 8 30 30;
      INT125_BASE_TAC 0 1 9 34 34;
      INT125_BASE_TAC 0 1 10 38 38]]);;

