(* ------------------------------------------------------------------------- *)
(* Composition of regularity, descent, shifts, and the finite certificates.  *)
(* ------------------------------------------------------------------------- *)

let int125_child_rep = new_definition
 `int125_child_rep rb rc k n <=>
    ?x y z w:int.
      x pow 2 + &2 * y pow 2 + &5 * z pow 2 +
      &2 * &rb * y * w + &2 * &rc * z * w +
      &k * w pow 2 = &n`;;

let INT125_CHILD_REP_SCALE25 = prove
 (`!rb rc k n:num.
     int125_child_rep rb rc k n
     ==> int125_child_rep rb rc k (25*n)`,
  REWRITE_TAC[int125_child_rep] THEN
  MESON_TAC[INT_REPRESENTS_125_CHILD_SCALE25]);;

let INT125_CHILD_REP_OF_TERNARY = prove
 (`!rb rc k n:num.
     (?x y z:int.
        x pow 2 + &2 * y pow 2 + &5 * z pow 2 = &n)
     ==> int125_child_rep rb rc k n`,
  REPEAT GEN_TAC THEN REWRITE_TAC[int125_child_rep] THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int` (X_CHOOSE_TAC `z:int`))) THEN
  MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`; `&0:int`] THEN
  FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING);;

let INT125_CHILD_REP_DIAG = prove
 (`!k n:num.
     int125_child_rep 0 0 k n <=>
     ?x y z w:int.
       x pow 2 + &2 * y pow 2 + &5 * z pow 2 +
       &k * w pow 2 = &n`,
  REWRITE_TAC[int125_child_rep] THEN
  SIMP_TAC[INT_MUL_LZERO; INT_MUL_RZERO;
    INT_ADD_LID; INT_ADD_RID]);;

let INT_125_DOUBLE_TWO_MUL = INT_RING
 `!z w:int. &2 * &2 * z * w = &4 * z * w`;;

let INT125_CHILD_REP_RC1 = prove
 (`!k n:num.
     int125_child_rep 0 1 k n <=>
     ?x y z w:int.
       x pow 2 + &2 * y pow 2 + &5 * z pow 2 +
       &2 * z * w + &k * w pow 2 = &n`,
  REWRITE_TAC[int125_child_rep] THEN
  SIMP_TAC[INT_MUL_LZERO; INT_MUL_RZERO;
    INT_MUL_LID; INT_MUL_RID; INT_ADD_LID; INT_ADD_RID]);;

let INT125_CHILD_REP_RC2 = prove
