let INT_ALMOST_UNIVERSAL_125_CHILD_OF_REGULAR = prove
 (`!rb rc k c:num.
     (!n:num.
        ~num_125_exception n
        ==> ?x y z:int.
             x pow 2 + &2 * y pow 2 + &5 * z pow 2 = &n) /\
     0 < c /\ ~(c MOD 25 = 0) /\
     (!m s:num.
        c * s EXP 2 <= m /\
        (?x y z:int.
           x pow 2 + &2 * y pow 2 + &5 * z pow 2 =
           &(m - c * s EXP 2))
        ==> int125_child_rep rb rc k m) /\
     (!m:num.
        0 < m /\ ~(m = 15) /\
        (m = 375 \/
         (m < 4*c /\ (m MOD 25 = 10 \/ m MOD 25 = 15)))
        ==> int125_child_rep rb rc k m)
     ==> !m:num.
          0 < m /\ ~(m = 15)
          ==> int125_child_rep rb rc k m`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "regular")
    (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 (LABEL_TAC "shift") (LABEL_TAC "base"))))) THEN
  MATCH_MP_TAC(ISPECL
    [`int125_child_rep rb rc k`; `c:num`] NUM_125_CHILD_DESCENT) THEN
  REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[];
    MESON_TAC[INT125_CHILD_REP_SCALE25];
    X_GEN_TAC `m:num` THEN DISCH_TAC THEN
    MATCH_MP_TAC(SPECL [`rb:num`; `rc:num`; `k:num`; `m:num`]
      INT125_CHILD_REP_OF_TERNARY) THEN
    REMOVE_THEN "regular" (MP_TAC o SPEC `m:num`) THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`m:num`; `s:num`] THEN STRIP_TAC THEN
    REMOVE_THEN "shift" (MATCH_MP_TAC o SPECL [`m:num`; `s:num`]) THEN
    ASM_REWRITE_TAC[] THEN
    REMOVE_THEN "regular"
      (MP_TAC o SPEC `m - c * s EXP 2:num`) THEN
    ASM_REWRITE_TAC[];
    REMOVE_THEN "base" MATCH_ACCEPT_TAC]);;

let INT_ALMOST_UNIVERSAL_DIAG125_REP = prove
 (`(!n:num.
      ~num_125_exception n
      ==> ?x y z:int.
           x pow 2 + &2 * y pow 2 + &5 * z pow 2 = &n)
   ==> !k:num.
        1 <= k /\ k <= 10
        ==> !m:num.
             0 < m /\ ~(m = 15)
             ==> int125_child_rep 0 0 k m`,
  DISCH_THEN(LABEL_TAC "regular") THEN
  X_GEN_TAC `k:num` THEN DISCH_THEN(LABEL_TAC "krange") THEN
  MATCH_MP_TAC(SPECL [`0`; `0`; `k:num`; `k:num`]
    INT_ALMOST_UNIVERSAL_125_CHILD_OF_REGULAR) THEN
  REPEAT CONJ_TAC THENL
   [REMOVE_THEN "regular" MATCH_ACCEPT_TAC;
    ASM_MESON_TAC[NUM_DIAG125_SHIFT_COEFF];
    ASM_MESON_TAC[NUM_DIAG125_SHIFT_COEFF];
    MAP_EVERY X_GEN_TAC [`m:num`; `s:num`] THEN
    REWRITE_TAC[INT125_CHILD_REP_DIAG] THEN STRIP_TAC THEN
    MATCH_MP_TAC(SPECL [`k:num`; `s:num`; `m:num`]
      INT_REPRESENTS_DIAG125_SHIFT) THEN
    ASM_MESON_TAC[];
    X_GEN_TAC `m:num` THEN REWRITE_TAC[INT125_CHILD_REP_DIAG] THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(SPECL [`k:num`; `m:num`]
      INT_REPRESENTS_DIAG125_BASE) THEN
    ASM_REWRITE_TAC[]]);;

let INT_ALMOST_UNIVERSAL_RC1_125_REP = prove
 (`(!n:num.
      ~num_125_exception n
      ==> ?x y z:int.
           x pow 2 + &2 * y pow 2 + &5 * z pow 2 = &n)
   ==> !k:num.
        1 <= k /\ k <= 10
        ==> !m:num.
             0 < m /\ ~(m = 15)
             ==> int125_child_rep 0 1 k m`,
  DISCH_THEN(LABEL_TAC "regular") THEN
  X_GEN_TAC `k:num` THEN DISCH_THEN(LABEL_TAC "krange") THEN
  MATCH_MP_TAC(SPECL [`0`; `1`; `k:num`; `25*k-5`]
    INT_ALMOST_UNIVERSAL_125_CHILD_OF_REGULAR) THEN
  REPEAT CONJ_TAC THENL
   [REMOVE_THEN "regular" MATCH_ACCEPT_TAC;
    ASM_MESON_TAC[NUM_RC1_125_SHIFT_COEFF];
    ASM_MESON_TAC[NUM_RC1_125_SHIFT_COEFF];
    MAP_EVERY X_GEN_TAC [`m:num`; `s:num`] THEN
    REWRITE_TAC[INT125_CHILD_REP_RC1] THEN STRIP_TAC THEN
    MATCH_MP_TAC(SPECL [`k:num`; `s:num`; `m:num`]
      INT_REPRESENTS_RC1_125_SHIFT) THEN
    ASM_MESON_TAC[];
    X_GEN_TAC `m:num` THEN REWRITE_TAC[INT125_CHILD_REP_RC1] THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(SPECL [`k:num`; `m:num`]
      INT_REPRESENTS_RC1_125_BASE) THEN
    ASM_REWRITE_TAC[]]);;

let INT_ALMOST_UNIVERSAL_RC2_125_REP = prove
 (`(!n:num.
      ~num_125_exception n
      ==> ?x y z:int.
           x pow 2 + &2 * y pow 2 + &5 * z pow 2 = &n)
