let INT_ALMOST_UNIVERSAL_RB1_125_REP = prove
 (`(!n:num.
      ~num_125_exception n
      ==> ?x y z:int.
           x pow 2 + &2 * y pow 2 + &5 * z pow 2 = &n)
   ==> !k:num.
        (k = 1 \/ k = 2 \/ k = 3 \/ k = 4 \/
         k = 5 \/ k = 6 \/ k = 9 \/ k = 10)
        ==> !m:num.
             0 < m /\ ~(m = 15)
             ==> int125_child_rep 1 0 k m`,
  DISCH_THEN(LABEL_TAC "regular") THEN
  X_GEN_TAC `k:num` THEN DISCH_THEN(LABEL_TAC "krange") THEN
  SUBGOAL_THEN `1 <= k /\ k <= 10` (LABEL_TAC "bounds") THENL
   [REMOVE_THEN "krange" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(SPECL [`1`; `0`; `k:num`; `4*k-2`]
    INT_ALMOST_UNIVERSAL_125_CHILD_OF_REGULAR) THEN
  REPEAT CONJ_TAC THENL
   [REMOVE_THEN "regular" MATCH_ACCEPT_TAC;
    MP_TAC(MATCH_MP (SPEC `k:num` NUM_RB1_125_SHIFT_COEFF)
      (ASSUME `1 <= k /\ k <= 10`)) THEN MESON_TAC[];
    MP_TAC(MATCH_MP (SPEC `k:num` NUM_RB1_125_SHIFT_COEFF)
      (ASSUME `1 <= k /\ k <= 10`)) THEN MESON_TAC[];
    MAP_EVERY X_GEN_TAC [`m:num`; `s:num`] THEN
    REWRITE_TAC[INT125_CHILD_REP_RB1] THEN STRIP_TAC THEN
    MATCH_MP_TAC(SPECL [`k:num`; `s:num`; `m:num`]
      INT_REPRESENTS_RB1_125_SHIFT) THEN
    REPEAT CONJ_TAC THENL
     [MP_TAC(ASSUME `1 <= k /\ k <= 10`) THEN ARITH_TAC;
      ASM_REWRITE_TAC[];
      MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`] THEN
      ASM_REWRITE_TAC[]];
    X_GEN_TAC `m:num` THEN REWRITE_TAC[INT125_CHILD_REP_RB1] THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(SPECL [`k:num`; `m:num`]
      INT_REPRESENTS_RB1_125_BASE) THEN
    ASM_REWRITE_TAC[]]);;

