  X_GEN_TAC `k:num` THEN DISCH_THEN(LABEL_TAC "krange") THEN
  SUBGOAL_THEN `2 <= k /\ k <= 10` (LABEL_TAC "bounds") THENL
   [REMOVE_THEN "krange" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(SPECL [`1`; `2`; `k:num`; `100*k-130`]
    INT_ALMOST_UNIVERSAL_125_CHILD_OF_REGULAR) THEN
  REPEAT CONJ_TAC THENL
   [REMOVE_THEN "regular" MATCH_ACCEPT_TAC;
    MP_TAC(MATCH_MP (SPEC `k:num` NUM_RB1_RC2_125_SHIFT_COEFF)
      (ASSUME `2 <= k /\ k <= 10`)) THEN MESON_TAC[];
    MP_TAC(MATCH_MP (SPEC `k:num` NUM_RB1_RC2_125_SHIFT_COEFF)
      (ASSUME `2 <= k /\ k <= 10`)) THEN MESON_TAC[];
    MAP_EVERY X_GEN_TAC [`m:num`; `s:num`] THEN
    REWRITE_TAC[INT125_CHILD_REP_RB1_RC2] THEN STRIP_TAC THEN
    MATCH_MP_TAC(SPECL [`k:num`; `s:num`; `m:num`]
      INT_REPRESENTS_RB1_RC2_125_SHIFT) THEN
    REPEAT CONJ_TAC THENL
     [MP_TAC(ASSUME `2 <= k /\ k <= 10`) THEN ARITH_TAC;
      ASM_REWRITE_TAC[];
      MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`] THEN
      ASM_REWRITE_TAC[]];
    X_GEN_TAC `m:num` THEN REWRITE_TAC[INT125_CHILD_REP_RB1_RC2] THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(SPECL [`k:num`; `m:num`]
      INT_REPRESENTS_RB1_RC2_125_BASE) THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Positive binary forms of determinant 10 have two classes.                *)
(* ------------------------------------------------------------------------- *)

let INT_DISC10_NOT_FIRST3 = prove
 (`!a b:int. ~(&3 * a - b pow 2 = &10)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`b:int`; `&3:int`] INT_DIVISION) THEN
  ANTS_TAC THENL [INT_ARITH_TAC; STRIP_TAC] THEN
  MP_TAC(SPEC `b:int` INT_REM_3_CASES) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [SUBGOAL_THEN `&3 divides &10` MP_TAC THENL
     [REWRITE_TAC[int_divides] THEN
      EXISTS_TAC `a - &3 * (b div &3) pow 2` THEN
      MAP_EVERY UNDISCH_TAC
       [`&3 * a - b pow 2 = &10`;
        `b = b div &3 * &3 + b rem &3`;
        `b rem &3 = &0`] THEN
      CONV_TAC INT_RING;
      REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV];
    SUBGOAL_THEN `&3 divides &11` MP_TAC THENL
     [REWRITE_TAC[int_divides] THEN
      EXISTS_TAC
       `a - &3 * (b div &3) pow 2 - &2 * (b div &3)` THEN
      MAP_EVERY UNDISCH_TAC
       [`&3 * a - b pow 2 = &10`;
        `b = b div &3 * &3 + b rem &3`;
        `b rem &3 = &1`] THEN
      CONV_TAC INT_RING;
      REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV];
    SUBGOAL_THEN `&3 divides &14` MP_TAC THENL
     [REWRITE_TAC[int_divides] THEN
      EXISTS_TAC
       `a - &3 * (b div &3) pow 2 - &4 * (b div &3)` THEN
      MAP_EVERY UNDISCH_TAC
       [`&3 * a - b pow 2 = &10`;
        `b = b div &3 * &3 + b rem &3`;
        `b rem &3 = &2`] THEN
      CONV_TAC INT_RING;
      REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV]]);;

let BINARY_DISC10 = prove
 (`!A11. &0 < A11
   ==> !A12 A22.
         A11 * A22 - A12 pow 2 = &10
         ==> ((!n.
                 (?x y.
                    A11 * x pow 2 + &2 * A12 * x * y +
                    A22 * y pow 2 = n)
                 ==> ?u v:int. u pow 2 + &10 * v pow 2 = n) \/
              (!n.
                 (?x y.
                    A11 * x pow 2 + &2 * A12 * x * y +
                    A22 * y pow 2 = n)
                 ==> ?u v:int. &2 * u pow 2 + &5 * v pow 2 = n))`,
  ONCE_REWRITE_TAC[MESON[]
   `(!A11. &0 < A11 ==> P A11) <=>
    (!m A11. num_of_int A11 = m /\ &0 < A11 ==> P A11)`] THEN
  MATCH_MP_TAC num_WF THEN GEN_TAC THEN STRIP_TAC THEN
  GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN DISCH_TAC THEN
  ASM_CASES_TAC `A11 = &1` THENL
   [DISJ1_TAC THEN GEN_TAC THEN
    DISCH_THEN(X_CHOOSE_THEN `x:int` (X_CHOOSE_TAC `y:int`)) THEN
    MAP_EVERY EXISTS_TAC [`x + A12 * y:int`; `y:int`] THEN
    MP_TAC(ASSUME `A11 * A22 - A12 pow 2 = &10`) THEN
    MP_TAC(ASSUME
     `A11 * x pow 2 + &2 * A12 * x * y + A22 * y pow 2 = n`) THEN
    REWRITE_TAC[ASSUME `A11 = &1`] THEN CONV_TAC INT_RING;
    ALL_TAC] THEN
  ASM_CASES_TAC `A11 = &2` THENL
   [DISJ2_TAC THEN GEN_TAC THEN
    DISCH_THEN(X_CHOOSE_THEN `x:int` (X_CHOOSE_TAC `y:int`)) THEN
    SUBGOAL_THEN
     `&2 divides (A11 * A22 - A12 pow 2)` ASSUME_TAC THENL
     [REWRITE_TAC[int_divides] THEN EXISTS_TAC `&5:int` THEN
      MP_TAC(ASSUME `A11 * A22 - A12 pow 2 = &10`) THEN
      CONV_TAC INT_RING;
      ALL_TAC] THEN
    SUBGOAL_THEN `&2 divides A12` ASSUME_TAC THENL
     [UNDISCH_TAC `&2 divides (A11 * A22 - A12 pow 2)` THEN
      ASM_REWRITE_TAC
       [INT_2_DIVIDES_SUB; INT_2_DIVIDES_MUL; INT_2_DIVIDES_POW;
        INT_DIVIDES_REFL] THEN
      CONV_TAC NUM_REDUCE_CONV;
      ALL_TAC] THEN
    X_CHOOSE_TAC `q:int`
     (REWRITE_RULE[int_divides] (ASSUME `&2 divides A12`)) THEN
    SUBGOAL_THEN `A22 = &2 * q pow 2 + &5` ASSUME_TAC THENL
     [MP_TAC(ASSUME `A11 * A22 - A12 pow 2 = &10`) THEN
      REWRITE_TAC[ASSUME `A11 = &2`; ASSUME `A12 = &2 * q`] THEN
      CONV_TAC INT_RING;
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`x + q * y:int`; `y:int`] THEN
    MP_TAC(ASSUME
     `A11 * x pow 2 + &2 * A12 * x * y + A22 * y pow 2 = n`) THEN
    REWRITE_TAC
     [ASSUME `A11 = &2`; ASSUME `A12 = &2 * q`;
      ASSUME `A22 = &2 * q pow 2 + &5`] THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  ASM_CASES_TAC `A11 = &3` THENL
   [MP_TAC(ASSUME `A11 * A22 - A12 pow 2 = &10`) THEN
    REWRITE_TAC[ASSUME `A11 = &3`] THEN
    MESON_TAC[INT_DISC10_NOT_FIRST3];
    ALL_TAC] THEN
  MP_TAC(SPECL [`A12:int`; `A11:int`] INT_BALANCED_REM) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `b:int` (LABEL_TAC "balanced")) THEN
  ABBREV_TAC `r = --b:int` THEN
  ABBREV_TAC `A12' = A12 + A11 * r` THEN
  ABBREV_TAC `A22' = A11 * r pow 2 + &2 * A12 * r + A22` THEN
  SUBGOAL_THEN `abs A12' * &2 <= A11` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["A12'"; "r"] THEN
    REMOVE_THEN "balanced" MP_TAC THEN
    REWRITE_TAC[INT_ARITH
      `A12 + A11 * --b = A12 - A11 * b`];
    ALL_TAC] THEN
  SUBGOAL_THEN `A11 * A22' - A12' pow 2 = &10` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["A12'"; "A22'"] THEN
    UNDISCH_TAC `A11 * A22 - A12 pow 2 = &10` THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 < A22'` ASSUME_TAC THENL
   [SUBGOAL_THEN `&0 < A11 * A22'` MP_TAC THENL
     [SUBGOAL_THEN `A11 * A22' = &10 + A12' pow 2` SUBST1_TAC THENL
       [ASM_INT_ARITH_TAC;
        MP_TAC(SPEC `A12':int` INT_LE_POW_2) THEN INT_ARITH_TAC];
      ASM_SIMP_TAC[INT_LT_MUL_EQ]];
    ALL_TAC] THEN
  SUBGOAL_THEN `&4 <= A11` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `&40 < &3 * A11 pow 2` ASSUME_TAC THENL
   [SUBGOAL_THEN `&16 <= A11 pow 2` MP_TAC THENL
     [MP_TAC(SPECL [`2`; `&4:int`; `A11:int`] INT_POW_LE2) THEN
      ANTS_TAC THENL [ASM_INT_ARITH_TAC; CONV_TAC INT_REDUCE_CONV];
      INT_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `A22' < A11` ASSUME_TAC THENL
   [SUBGOAL_THEN `&4 * (A11 * A22') <= &40 + A11 pow 2`
    ASSUME_TAC THENL
     [SUBGOAL_THEN `A11 * A22' = &10 + A12' pow 2`
       (fun th -> REWRITE_TAC[th]) THENL
       [ASM_INT_ARITH_TAC;
        MP_TAC(MATCH_MP SQ_BOUND
          (ASSUME `abs A12' * &2 <= A11`)) THEN INT_ARITH_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `A11 * (&4 * A22') < A11 * (&4 * A11)` MP_TAC THENL
     [MATCH_MP_TAC INT_LET_TRANS THEN
      EXISTS_TAC `&40 + A11 pow 2` THEN
      CONJ_TAC THENL
       [ONCE_REWRITE_TAC[INT_RING
         `A11 * (&4 * A22') = &4 * (A11 * A22')`] THEN
        ASM_REWRITE_TAC[];
        ONCE_REWRITE_TAC[INT_RING
         `A11 * (&4 * A11) = &4 * A11 pow 2`] THEN
        ASM_INT_ARITH_TAC];
      ASM_SIMP_TAC[INT_LT_LMUL_EQ] THEN INT_ARITH_TAC];
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `num_of_int A22'`) THEN
  SUBGOAL_THEN `num_of_int A22' < m` ASSUME_TAC THENL
   [FIRST_X_ASSUM(SUBST1_TAC o SYM o
      check (fun th -> rand(concl th) = `m:num`)) THEN
    REWRITE_TAC[GSYM INT_OF_NUM_LT] THEN
    SUBGOAL_THEN
     `&(num_of_int A22') = A22' /\ &(num_of_int A11) = A11`
    (CONJUNCTS_THEN SUBST1_TAC) THENL
     [CONJ_TAC THEN MATCH_MP_TAC INT_OF_NUM_OF_INT THEN ASM_INT_ARITH_TAC;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPEC `A22':int`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`A12':int`; `A11:int`]) THEN
  ANTS_TAC THENL
   [MP_TAC(ASSUME `A11 * A22' - A12' pow 2 = &10`) THEN
    CONV_TAC INT_RING;
    DISCH_THEN(DISJ_CASES_THEN (LABEL_TAC "class")) THENL
     [DISJ1_TAC; DISJ2_TAC] THEN
    X_GEN_TAC `n:int` THEN
    DISCH_THEN(X_CHOOSE_THEN `x:int` (X_CHOOSE_TAC `y:int`)) THEN
    REMOVE_THEN "class" (MATCH_MP_TAC o SPEC `n:int`) THEN
    MAP_EVERY EXISTS_TAC [`y:int`; `x - r * y:int`] THEN
    MAP_EVERY EXPAND_TAC ["A12'"; "A22'"] THEN
    UNDISCH_TAC
     `A11 * x pow 2 + &2 * A12 * x * y + A22 * y pow 2 = n` THEN
    CONV_TAC INT_RING]);;

(* ------------------------------------------------------------------------- *)
(* The 2-adic type of <1,2,5>, expressed by a characteristic vector.         *)
(* ------------------------------------------------------------------------- *)

let ternary_type6 = new_definition
 `ternary_type6 a11 a12 a13 a22 a23 a33 <=>
    ?w1 w2 w3 q:int.
      (!x1 x2 x3.
         &2 divides
          (tqeval a11 a12 a13 a22 a23 a33 x1 x2 x3 -
           tqbilin a11 a12 a13 a22 a23 a33 x1 x2 x3 w1 w2 w3)) /\
      tqeval a11 a12 a13 a22 a23 a33 w1 w2 w3 = &8 * q + &6`;;

let CONJ_TYPE6 = prove
 (`!a11 a12 a13 a22 a23 a33 v1 v2 v3 c12 c13 c22 c23 c32 c33
     b11 b12 b13 b22 b23 b33:int.
     v1 * (c22 * c33 - c23 * c32) -
     c12 * (v2 * c33 - c23 * v3) +
     c13 * (v2 * c32 - c22 * v3) = &1 /\
     b11 = a11 * v1 pow 2 + &2 * a12 * v1 * v2 +
            &2 * a13 * v1 * v3 + a22 * v2 pow 2 +
            &2 * a23 * v2 * v3 + a33 * v3 pow 2 /\
     b22 = a11 * c12 pow 2 + &2 * a12 * c12 * c22 +
            &2 * a13 * c12 * c32 + a22 * c22 pow 2 +
            &2 * a23 * c22 * c32 + a33 * c32 pow 2 /\
     b33 = a11 * c13 pow 2 + &2 * a12 * c13 * c23 +
            &2 * a13 * c13 * c33 + a22 * c23 pow 2 +
            &2 * a23 * c23 * c33 + a33 * c33 pow 2 /\
     b12 = a11 * v1 * c12 + a12 * (v1 * c22 + v2 * c12) +
            a13 * (v1 * c32 + v3 * c12) +
            a22 * v2 * c22 + a23 * (v2 * c32 + v3 * c22) +
            a33 * v3 * c32 /\
     b13 = a11 * v1 * c13 + a12 * (v1 * c23 + v2 * c13) +
            a13 * (v1 * c33 + v3 * c13) +
            a22 * v2 * c23 + a23 * (v2 * c33 + v3 * c23) +
            a33 * v3 * c33 /\
     b23 = a11 * c12 * c13 + a12 * (c12 * c23 + c22 * c13) +
            a13 * (c12 * c33 + c32 * c13) +
            a22 * c22 * c23 + a23 * (c22 * c33 + c32 * c23) +
            a33 * c32 * c33 /\
     ternary_type6 a11 a12 a13 a22 a23 a33
     ==> ternary_type6 b11 b12 b13 b22 b23 b33`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[ternary_type6]) THEN
  DISCH_THEN(X_CHOOSE_THEN `w1:int` (X_CHOOSE_THEN `w2:int`
    (X_CHOOSE_THEN `w3:int` (X_CHOOSE_THEN `q:int` STRIP_ASSUME_TAC)))) THEN
  MP_TAC(SPECL
   [`v1:int`; `v2:int`; `v3:int`; `c12:int`; `c22:int`; `c32:int`;
    `c13:int`; `c23:int`; `c33:int`; `w1:int`; `w2:int`; `w3:int`]
   ADJ_PREIMAGE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `y1:int` (X_CHOOSE_THEN `y2:int`
    (X_CHOOSE_THEN `y3:int` STRIP_ASSUME_TAC))) THEN
  REWRITE_TAC[ternary_type6] THEN
  MAP_EVERY EXISTS_TAC [`y1:int`; `y2:int`; `y3:int`; `q:int`] THEN
  CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`z1:int`; `z2:int`; `z3:int`] THEN
    FIRST_X_ASSUM(MP_TAC o SPECL
     [`z1 * v1 + z2 * c12 + z3 * c13:int`;
      `z1 * v2 + z2 * c22 + z3 * c23:int`;
      `z1 * v3 + z2 * c32 + z3 * c33:int`] o
      check (fun th -> is_forall(concl th))) THEN
    REWRITE_TAC[int_divides] THEN
    DISCH_THEN(X_CHOOSE_TAC `d:int`) THEN EXISTS_TAC `d:int` THEN
    POP_ASSUM_LIST
     (fun ths -> MAP_EVERY MP_TAC (filter (is_eq o concl) ths)) THEN
    REWRITE_TAC[tqeval; tqbilin] THEN CONV_TAC INT_RING;
    POP_ASSUM_LIST
     (fun ths -> MAP_EVERY MP_TAC (filter (is_eq o concl) ths)) THEN
    REWRITE_TAC[tqeval; tqbilin] THEN CONV_TAC INT_RING]);;

let TERNARY_TYPE6_OF_CHARACTERISTIC = prove
 (`!a11 a12 a13 a22 a23 a33 w1 w2 w3 q:int.
     &2 divides (a11 - (a11 * w1 + a12 * w2 + a13 * w3)) /\
     &2 divides (a22 - (a12 * w1 + a22 * w2 + a23 * w3)) /\
     &2 divides (a33 - (a13 * w1 + a23 * w2 + a33 * w3)) /\
     tqeval a11 a12 a13 a22 a23 a33 w1 w2 w3 = &8 * q + &6
     ==> ternary_type6 a11 a12 a13 a22 a23 a33`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[ternary_type6] THEN
  MAP_EVERY EXISTS_TAC [`w1:int`; `w2:int`; `w3:int`; `q:int`] THEN
  ASM_REWRITE_TAC[] THEN MATCH_MP_TAC TERNARY_CHARACTERISTIC THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Type 6 selects the <2,5> binary class after splitting off a norm 1.       *)
(* ------------------------------------------------------------------------- *)

let INT_REM_8MUL_ADD6 = prove
 (`!x q:int. x = &8 * q + &6 ==> x rem &8 = &6`,
  REPEAT GEN_TAC THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[CONJUNCT1(CONJUNCT2 INT_REM_MUL_ADD)] THEN
  CONV_TAC INT_REDUCE_CONV);;

let INT_ODD_SQ_SQ_10_NOT_6MOD8 = prove
 (`!l u v q:int.
     ~(&2 divides l)
     ==> ~(l pow 2 + u pow 2 + &10 * v pow 2 = &8 * q + &6)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `l pow 2 rem &8 = &1` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[ODD_SQ_MOD_8];
    ALL_TAC] THEN
  MP_TAC(SPEC `u:int` SQ_MOD_8) THEN
  MP_TAC(SPEC `v:int` SQ_MOD_8) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THEN
  (SUBGOAL_THEN
    `(l pow 2 + u pow 2 + &10 * v pow 2) rem &8 = &6`
   ASSUME_TAC THENL
    [MATCH_MP_TAC(SPECL
      [`l pow 2 + u pow 2 + &10 * v pow 2`; `q:int`]
      INT_REM_8MUL_ADD6) THEN
     ASM_REWRITE_TAC[];
     ALL_TAC] THEN
   SUBGOAL_THEN
    `(l pow 2 + u pow 2 + &10 * v pow 2) rem &8 =
     (((l pow 2 rem &8 + u pow 2 rem &8) rem &8 +
       ((&10 rem &8) * (v pow 2 rem &8)) rem &8) rem &8)`
   ASSUME_TAC THENL
    [CONV_TAC INT_REM_DOWN_CONV THEN REWRITE_TAC[INT_ADD_ASSOC];
     ALL_TAC] THEN
   MP_TAC(ASSUME
    `(l pow 2 + u pow 2 + &10 * v pow 2) rem &8 = &6`) THEN
   MP_TAC(ASSUME
    `(l pow 2 + u pow 2 + &10 * v pow 2) rem &8 =
     (((l pow 2 rem &8 + u pow 2 rem &8) rem &8 +
       ((&10 rem &8) * (v pow 2 rem &8)) rem &8) rem &8)`) THEN
   ASM_REWRITE_TAC[] THEN CONV_TAC INT_REDUCE_CONV));;

let TYPE6_DISC10_BINARY_SECOND = prove
 (`!b12 b13 b22 b23 b33:int.
     &0 < b22 - b12 pow 2 /\
     &1 * (b22 * b33 - b23 pow 2) -
       b12 * (b12 * b33 - b23 * b13) +
       b13 * (b12 * b23 - b22 * b13) = &10 /\
     ternary_type6 (&1) b12 b13 b22 b23 b33
     ==> !n.
           (?x y.
              (b22 - b12 pow 2) * x pow 2 +
              &2 * (b23 - b12 * b13) * x * y +
              (b33 - b13 pow 2) * y pow 2 = n)
           ==> ?u v:int. &2 * u pow 2 + &5 * v pow 2 = n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `G11 = b22 - b12 pow 2` THEN
  ABBREV_TAC `G12 = b23 - b12 * b13` THEN
  ABBREV_TAC `G22 = b33 - b13 pow 2` THEN
  SUBGOAL_THEN `G11 * G22 - G12 pow 2 = &10` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["G11"; "G12"; "G22"] THEN
    UNDISCH_TAC
     `&1 * (b22 * b33 - b23 pow 2) -
      b12 * (b12 * b33 - b23 * b13) +
      b13 * (b12 * b23 - b22 * b13) = &10` THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  MP_TAC(SPEC `G11:int` BINARY_DISC10) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`G12:int`; `G22:int`]) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(DISJ_CASES_THEN2
    (LABEL_TAC "first") (LABEL_TAC "second")) THENL
   [ALL_TAC;
    REMOVE_THEN "second" MP_TAC THEN
    MAP_EVERY EXPAND_TAC ["G11"; "G12"; "G22"] THEN
    MESON_TAC[]] THEN
  MP_TAC(REWRITE_RULE[ternary_type6]
    (ASSUME `ternary_type6 (&1) b12 b13 b22 b23 b33`)) THEN
  DISCH_THEN(X_CHOOSE_THEN `w1:int` (X_CHOOSE_THEN `w2:int`
    (X_CHOOSE_THEN `w3:int` (X_CHOOSE_THEN `q:int`
      (CONJUNCTS_THEN2
        (LABEL_TAC "characteristic") (LABEL_TAC "norm6")))))) THEN
  ABBREV_TAC `l = w1 + b12 * w2 + b13 * w3` THEN
  SUBGOAL_THEN `~(&2 divides l)` ASSUME_TAC THENL
   [USE_THEN "characteristic" (fun th ->
      MP_TAC(SPECL [`&1:int`; `&0:int`; `&0:int`] th)) THEN
    SUBGOAL_THEN
     `tqeval (&1) b12 b13 b22 b23 b33 (&1) (&0) (&0) -
      tqbilin (&1) b12 b13 b22 b23 b33
        (&1) (&0) (&0) w1 w2 w3 = &1 - l`
    (fun th -> REWRITE_TAC[th]) THENL
     [EXPAND_TAC "l" THEN REWRITE_TAC[tqeval; tqbilin] THEN
      CONV_TAC INT_RING;
      REWRITE_TAC[INT_2_DIVIDES_SUB] THEN
      SUBGOAL_THEN `~(&2 divides (&1:int))` MP_TAC THENL
       [REWRITE_TAC[GSYM(CONJUNCT1 INT_REM_2_DIVIDES)] THEN
        CONV_TAC INT_REDUCE_CONV;
        MESON_TAC[]]];
    ALL_TAC] THEN
  REMOVE_THEN "first" (MP_TAC o SPEC
   `G11 * w2 pow 2 + &2 * G12 * w2 * w3 + G22 * w3 pow 2`) THEN
  ANTS_TAC THENL
   [MAP_EVERY EXISTS_TAC [`w2:int`; `w3:int`] THEN REFL_TAC;
    DISCH_THEN(X_CHOOSE_THEN `u:int`
      (X_CHOOSE_THEN `v:int` (LABEL_TAC "binary")))] THEN
  SUBGOAL_THEN
   `l pow 2 + u pow 2 + &10 * v pow 2 = &8 * q + &6`
  ASSUME_TAC THENL
   [REMOVE_THEN "norm6" MP_TAC THEN
    REMOVE_THEN "binary" MP_TAC THEN
    MAP_EVERY EXPAND_TAC ["l"; "G11"; "G12"; "G22"] THEN
    REWRITE_TAC[tqeval] THEN CONV_TAC INT_RING;
    MP_TAC(SPECL [`l:int`; `u:int`; `v:int`; `q:int`]
      INT_ODD_SQ_SQ_10_NOT_6MOD8) THEN
    ASM_REWRITE_TAC[]]);;

let TERNARY_DISC10_TYPE6_A11_1 = prove
 (`!a12 a13 a22 a23 a33 n:int.
     &0 < &1 * a22 - a12 pow 2 /\
     &1 * (a22 * a33 - a23 pow 2) -
       a12 * (a12 * a33 - a23 * a13) +
       a13 * (a12 * a23 - a22 * a13) = &10 /\
     ternary_type6 (&1) a12 a13 a22 a23 a33 /\
     (?x1 x2 x3.
        &1 * x1 pow 2 + a22 * x2 pow 2 + a33 * x3 pow 2 +
        &2 * a12 * x1 * x2 + &2 * a13 * x1 * x3 +
        &2 * a23 * x2 * x3 = n)
     ==> ?u v w:int. u pow 2 + &2 * v pow 2 + &5 * w pow 2 = n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `G11 = a22 - a12 pow 2` THEN
  ABBREV_TAC `G12 = a23 - a12 * a13` THEN
  ABBREV_TAC `G22 = a33 - a13 pow 2` THEN
  SUBGOAL_THEN `&0 < G11` ASSUME_TAC THENL
   [EXPAND_TAC "G11" THEN
    UNDISCH_TAC `&0 < &1 * a22 - a12 pow 2` THEN
    REWRITE_TAC[INT_MUL_LID];
    ALL_TAC] THEN
  ABBREV_TAC `L = x1 + a12 * x2 + a13 * x3` THEN
  MP_TAC(SPECL
   [`a12:int`; `a13:int`; `a22:int`; `a23:int`; `a33:int`]
   TYPE6_DISC10_BINARY_SECOND) THEN
  ASM_REWRITE_TAC[INT_MUL_LID] THEN
  DISCH_THEN(MP_TAC o SPEC `n - L pow 2`) THEN
  ANTS_TAC THENL
   [MAP_EVERY EXISTS_TAC [`x2:int`; `x3:int`] THEN
    MP_TAC(SPECL
     [`&1:int`; `a12:int`; `a13:int`; `a22:int`; `a23:int`; `a33:int`;
      `x1:int`; `x2:int`; `x3:int`] TERNARY_COMPLETE) THEN
    ASM_REWRITE_TAC[INT_MUL_LID] THEN
    MAP_EVERY EXPAND_TAC ["G11"; "G12"; "G22"; "L"] THEN
    INT_ARITH_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `v:int` (X_CHOOSE_TAC `w:int`)) THEN
  MAP_EVERY EXISTS_TAC [`L:int`; `v:int`; `w:int`] THEN
  UNDISCH_TAC `&2 * v pow 2 + &5 * w pow 2 = n - L pow 2` THEN
  INT_ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* Hermite reduction at determinant 10. A minimal value is 1 or 2.           *)
(* ------------------------------------------------------------------------- *)

let CUBE_GE_27 = prove
 (`!a:int. &3 <= a ==> &27 <= a pow 3`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC INT_LE_TRANS THEN EXISTS_TAC `&3 pow 3` THEN
  CONJ_TAC THENL
   [CONV_TAC INT_REDUCE_CONV;
    MATCH_MP_TAC INT_POW_LE2 THEN ASM_INT_ARITH_TAC]);;

let HERMITE_CUBE_DISC10 = prove
 (`!a G:int.
     &0 < a /\ &0 < G /\
     &3 * a pow 2 <= &4 * G /\ &3 * G pow 2 <= &4 * (&10 * a)
     ==> &27 * a pow 3 <= &640`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(&3 * a pow 2) pow 2 <= (&4 * G) pow 2` MP_TAC THENL
   [MATCH_MP_TAC INT_POW_LE2 THEN CONJ_TAC THENL
     [MATCH_MP_TAC INT_LE_MUL THEN REWRITE_TAC[INT_LE_POW_2] THEN
      INT_ARITH_TAC;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[INT_POW_MUL] THEN DISCH_TAC THEN
  MATCH_MP_TAC INT_LE_RCANCEL_IMP THEN EXISTS_TAC `a:int` THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MATCH_MP_TAC INT_LE_TRANS THEN
  EXISTS_TAC `&16 * (&3 * G pow 2)` THEN
  CONJ_TAC THENL
   [MP_TAC
     (ASSUME `&3 pow 2 * a pow 2 pow 2 <= &4 pow 2 * G pow 2`) THEN
    REWRITE_TAC[INT_ARITH `a pow 2 pow 2 = a pow 3 * a`; INT_POW_2] THEN
    INT_ARITH_TAC;
    MP_TAC(ASSUME `&3 * G pow 2 <= &4 * (&10 * a)`) THEN
    INT_ARITH_TAC]);;

let HERMITE_DISC10_LE2 = prove
 (`!b11 b12 b13 b22 b23 b33:int.
     &0 < b11 /\
     b11 * (b22 * b33 - b23 pow 2) -
       b12 * (b12 * b33 - b13 * b23) +
       b13 * (b12 * b23 - b13 * b22) = &10 /\
     &0 < b11 * b22 - b12 pow 2 /\
     (!x y z. ~(x = &0 /\ y = &0 /\ z = &0)
              ==> b11 <= b11 * x pow 2 + b22 * y pow 2 +
                         b33 * z pow 2 + &2 * b12 * x * y +
                         &2 * b13 * x * z + &2 * b23 * y * z)
     ==> b11 = &1 \/ b11 = &2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `G11 = b11 * b22 - b12 pow 2` THEN
  ABBREV_TAC `G12 = b11 * b23 - b12 * b13` THEN
  ABBREV_TAC `G22 = b11 * b33 - b13 pow 2` THEN
  SUBGOAL_THEN `G11 * G22 - G12 pow 2 = &10 * b11` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["G11"; "G12"; "G22"] THEN
    REWRITE_TAC[DISC_G] THEN
    MP_TAC
     (ASSUME
       `b11 * (b22 * b33 - b23 pow 2) -
        b12 * (b12 * b33 - b13 * b23) +
        b13 * (b12 * b23 - b13 * b22) = &10`) THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  MP_TAC(SPEC `&10 * b11:int` BINARY_HERMITE) THEN
  ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `G11:int`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`G12:int`; `G22:int`]) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:int`
    (X_CHOOSE_THEN `t:int` STRIP_ASSUME_TAC)) THEN
  ABBREV_TAC
   `Gst = G11 * s pow 2 + &2 * G12 * s * t + G22 * t pow 2` THEN
  MP_TAC(SPECL [`b12 * s + b13 * t:int`; `b11:int`]
    INT_BALANCED_REM) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `bb:int`) THEN
  ABBREV_TAC `x1 = --bb:int` THEN
  SUBGOAL_THEN
   `&4 * (b11 * x1 + b12 * s + b13 * t) pow 2 <= b11 pow 2`
  ASSUME_TAC THENL
   [MP_TAC(MATCH_MP SQ_BOUND
     (ASSUME
       `abs ((b12 * s + b13 * t) - b11 * bb) * &2 <= b11`)) THEN
    EXPAND_TAC "x1" THEN
    REWRITE_TAC
     [INT_ARITH
       `b11 * --bb + b12 * s + b13 * t =
        (b12 * s + b13 * t) - b11 * bb`] THEN
    INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `&3 * b11 pow 2 <= &4 * Gst` ASSUME_TAC THENL
   [MATCH_MP_TAC HERMITE_LOWER THEN
    MAP_EVERY EXISTS_TAC
     [`b12:int`; `b13:int`; `b22:int`; `b23:int`; `b33:int`;
      `x1:int`; `s:int`; `t:int`] THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [FIRST_X_ASSUM
       (fun th ->
         MP_TAC(SPECL [`x1:int`; `s:int`; `t:int`] th) THEN
         ANTS_TAC THENL
          [UNDISCH_TAC `~(s = &0 /\ t = &0)` THEN MESON_TAC[];
           ALL_TAC] THEN
         DISCH_THEN(fun th2 -> ACCEPT_TAC th2 ORELSE MP_TAC th2));
      EXPAND_TAC "Gst" THEN
      MP_TAC(SPECL
       [`b11:int`; `b12:int`; `b13:int`; `b22:int`; `b23:int`;
        `b33:int`; `x1:int`; `s:int`; `t:int`] TERNARY_COMPLETE) THEN
      MAP_EVERY (fun e -> UNDISCH_TAC e)
       [`b11 * b22 - b12 pow 2 = G11`;
        `b11 * b23 - b12 * b13 = G12`;
        `b11 * b33 - b13 pow 2 = G22`] THEN
      CONV_TAC INT_RING];
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 < Gst` ASSUME_TAC THENL
   [EXPAND_TAC "Gst" THEN
    MP_TAC(SPECL [`G11:int`; `G12:int`; `G22:int`]
      POSDEF_BINARY_CRITERION) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_INT_ARITH_TAC;
      ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`s:int`; `t:int`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`b11:int`; `Gst:int`] HERMITE_CUBE_DISC10) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  SUBGOAL_THEN `~(&3 <= b11)` ASSUME_TAC THENL
   [DISCH_TAC THEN MP_TAC(SPEC `b11:int` CUBE_GE_27) THEN
    ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `&27 * b11 pow 3 <= &640` THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  ASM_INT_ARITH_TAC);;

(* The binary short vector can be chosen primitive. This is the same
   reduce-and-swap descent as BINARY_HERMITE, with a Bezout certificate
   carried through each unimodular step. *)

let BINARY_HERMITE_PRIMITIVE = prove
 (`!D. &0 < D ==>
     !A11. &0 < A11
       ==> !A12 A22.
             A11 * A22 - A12 pow 2 = D
             ==> ?x y.
                   (?p q. x * p + y * q = &1) /\
                   &3 * (A11 * x pow 2 + &2 * A12 * x * y +
                         A22 * y pow 2) pow 2 <= &4 * D`,
  GEN_TAC THEN DISCH_TAC THEN
  ONCE_REWRITE_TAC[MESON[]
   `(!A11. &0 < A11 ==> P A11) <=>
    (!m A11. num_of_int A11 = m /\ &0 < A11 ==> P A11)`] THEN
  MATCH_MP_TAC num_WF THEN GEN_TAC THEN STRIP_TAC THEN
  GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`A12:int`; `A11:int`] INT_BALANCED_REM) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `b:int`) THEN
  ABBREV_TAC `r = --b:int` THEN
  ABBREV_TAC `A12' = A12 + A11 * r` THEN
  ABBREV_TAC `A22' = A11 * r pow 2 + &2 * A12 * r + A22` THEN
  SUBGOAL_THEN `abs A12' * &2 <= A11` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["A12'"; "r"] THEN
    UNDISCH_TAC `abs (A12 - A11 * b) * &2 <= A11` THEN
    REWRITE_TAC[INT_ARITH
      `A12 + A11 * --b = A12 - A11 * b`];
    ALL_TAC] THEN
  SUBGOAL_THEN `A11 * A22' - A12' pow 2 = D` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["A12'"; "A22'"] THEN
    UNDISCH_TAC `A11 * A22 - A12 pow 2 = D` THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 < A22'` ASSUME_TAC THENL
   [SUBGOAL_THEN `&0 < A11 * A22'` MP_TAC THENL
     [SUBGOAL_THEN `A11 * A22' = D + A12' pow 2` SUBST1_TAC THENL
       [ASM_INT_ARITH_TAC;
        MP_TAC(SPEC `A12':int` INT_LE_POW_2) THEN ASM_INT_ARITH_TAC];
      ASM_SIMP_TAC[INT_LT_MUL_EQ]];
    ALL_TAC] THEN
  ASM_CASES_TAC `&3 * A11 pow 2 <= &4 * D` THENL
   [MAP_EVERY EXISTS_TAC [`&1:int`; `&0:int`] THEN CONJ_TAC THENL
     [MAP_EVERY EXISTS_TAC [`&1:int`; `&0:int`] THEN
      CONV_TAC INT_RING;
      SUBGOAL_THEN
       `A11 * (&1:int) pow 2 + &2 * A12 * (&1) * (&0) +
        A22 * (&0) pow 2 = A11`
      SUBST1_TAC THENL
       [CONV_TAC INT_RING;
        FIRST_ASSUM ACCEPT_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN `A22' < A11` ASSUME_TAC THENL
   [SUBGOAL_THEN `&4 * (A11 * A22') <= &4 * D + A11 pow 2`
    ASSUME_TAC THENL
     [SUBGOAL_THEN `A11 * A22' = D + A12' pow 2`
       (fun th -> REWRITE_TAC[th]) THENL
       [ASM_INT_ARITH_TAC;
        MP_TAC(MATCH_MP SQ_BOUND
          (ASSUME `abs A12' * &2 <= A11`)) THEN INT_ARITH_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `&4 * D < &3 * A11 pow 2` ASSUME_TAC THENL
     [ASM_INT_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `A11 * (&4 * A22') < A11 * (&4 * A11)` MP_TAC THENL
     [MATCH_MP_TAC INT_LET_TRANS THEN
      EXISTS_TAC `&4 * D + A11 pow 2` THEN CONJ_TAC THENL
       [UNDISCH_TAC `&4 * (A11 * A22') <= &4 * D + A11 pow 2` THEN
        INT_ARITH_TAC;
        REWRITE_TAC[INT_POW_2] THEN
        UNDISCH_TAC `&4 * D < &3 * A11 pow 2` THEN
        REWRITE_TAC[INT_POW_2] THEN INT_ARITH_TAC];
      ASM_SIMP_TAC[INT_LT_LMUL_EQ] THEN INT_ARITH_TAC];
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `num_of_int A22'`) THEN
  SUBGOAL_THEN `num_of_int A22' < m` ASSUME_TAC THENL
   [FIRST_X_ASSUM(SUBST1_TAC o SYM o
      check (fun th -> rand(concl th) = `m:num`)) THEN
    REWRITE_TAC[GSYM INT_OF_NUM_LT] THEN
    SUBGOAL_THEN
     `&(num_of_int A22') = A22' /\ &(num_of_int A11) = A11`
    (CONJUNCTS_THEN SUBST1_TAC) THENL
     [CONJ_TAC THEN MATCH_MP_TAC INT_OF_NUM_OF_INT THEN ASM_INT_ARITH_TAC;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPEC `A22':int`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`A12':int`; `A11:int`]) THEN
  ANTS_TAC THENL
   [MP_TAC(ASSUME `A11 * A22' - A12' pow 2 = D`) THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `x':int`
    (X_CHOOSE_THEN `y':int`
      (CONJUNCTS_THEN2
        (X_CHOOSE_THEN `p:int` (X_CHOOSE_TAC `q:int`))
        ASSUME_TAC))) THEN
  MAP_EVERY EXISTS_TAC [`y' + r * x':int`; `x':int`] THEN
  CONJ_TAC THENL
   [MAP_EVERY EXISTS_TAC [`q:int`; `p - r * q:int`] THEN
    UNDISCH_TAC `x' * p + y' * q = &1` THEN CONV_TAC INT_RING;
    SUBGOAL_THEN
     `A11 * (y' + r * x') pow 2 +
      &2 * A12 * (y' + r * x') * x' + A22 * x' pow 2 =
      A22' * x' pow 2 + &2 * A12' * x' * y' + A11 * y' pow 2`
    SUBST1_TAC THENL
     [MAP_EVERY EXPAND_TAC ["A22'"; "A12'"] THEN CONV_TAC INT_RING;
      ASM_REWRITE_TAC[]]]);;

let INT_SQ_SQ_5_NOT_3MOD8 = prove
 (`!x y z q:int.
     ~(x pow 2 + y pow 2 + &5 * z pow 2 = &8 * q + &3)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPEC `x:int` SQ_MOD_8) THEN
  MP_TAC(SPEC `y:int` SQ_MOD_8) THEN
  MP_TAC(SPEC `z:int` SQ_MOD_8) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THEN
  (SUBGOAL_THEN
    `(x pow 2 + y pow 2 + &5 * z pow 2) rem &8 = &3`
   ASSUME_TAC THENL
    [MATCH_MP_TAC(SPECL
      [`x pow 2 + y pow 2 + &5 * z pow 2`; `q:int`]
      (prove
       (`!a q:int. a = &8 * q + &3 ==> a rem &8 = &3`,
        REPEAT GEN_TAC THEN DISCH_THEN SUBST1_TAC THEN
        REWRITE_TAC[CONJUNCT1(CONJUNCT2 INT_REM_MUL_ADD)] THEN
        CONV_TAC INT_REDUCE_CONV))) THEN
     ASM_REWRITE_TAC[];
     ALL_TAC] THEN
   SUBGOAL_THEN
    `(x pow 2 + y pow 2 + &5 * z pow 2) rem &8 =
     (((x pow 2 rem &8 + y pow 2 rem &8) rem &8 +
       ((&5 rem &8) * (z pow 2 rem &8)) rem &8) rem &8)`
   ASSUME_TAC THENL
    [CONV_TAC INT_REM_DOWN_CONV THEN REWRITE_TAC[INT_ADD_ASSOC];
     ALL_TAC] THEN
   MP_TAC(ASSUME
    `(x pow 2 + y pow 2 + &5 * z pow 2) rem &8 = &3`) THEN
   MP_TAC(ASSUME
    `(x pow 2 + y pow 2 + &5 * z pow 2) rem &8 =
     (((x pow 2 rem &8 + y pow 2 rem &8) rem &8 +
       ((&5 rem &8) * (z pow 2 rem &8)) rem &8) rem &8)`) THEN
   ASM_REWRITE_TAC[] THEN CONV_TAC INT_REDUCE_CONV));;

(* With minimal value 2, primitive Hermite reduction produces a rank-two
   Gram block of determinant 3, 4, or 5. *)

let HERMITE_DISC10_MIN2_PAIR = prove
 (`!b12 b13 b22 b23 b33:int.
     &2 * (b22 * b33 - b23 pow 2) -
       b12 * (b12 * b33 - b13 * b23) +
       b13 * (b12 * b23 - b13 * b22) = &10 /\
     &0 < &2 * b22 - b12 pow 2 /\
     (!x y z. ~(x = &0 /\ y = &0 /\ z = &0)
              ==> &2 <= &2 * x pow 2 + b22 * y pow 2 +
                         b33 * z pow 2 + &2 * b12 * x * y +
                         &2 * b13 * x * z + &2 * b23 * y * z)
     ==> ?x y z.
           (?p q. y * p + z * q = &1) /\
           ((&2 * x pow 2 + b22 * y pow 2 + b33 * z pow 2 +
              &2 * b12 * x * y + &2 * b13 * x * z +
              &2 * b23 * y * z = &2 /\
             (&2 * x + b12 * y + b13 * z) pow 2 = &1 /\
             (&2 * b22 - b12 pow 2) * y pow 2 +
             &2 * (&2 * b23 - b12 * b13) * y * z +
             (&2 * b33 - b13 pow 2) * z pow 2 = &3) \/
            (&2 * x pow 2 + b22 * y pow 2 + b33 * z pow 2 +
              &2 * b12 * x * y + &2 * b13 * x * z +
              &2 * b23 * y * z = &2 /\
             &2 * x + b12 * y + b13 * z = &0 /\
             (&2 * b22 - b12 pow 2) * y pow 2 +
             &2 * (&2 * b23 - b12 * b13) * y * z +
             (&2 * b33 - b13 pow 2) * z pow 2 = &4) \/
            (&2 * x pow 2 + b22 * y pow 2 + b33 * z pow 2 +
              &2 * b12 * x * y + &2 * b13 * x * z +
              &2 * b23 * y * z = &3 /\
             (&2 * x + b12 * y + b13 * z) pow 2 = &1 /\
             (&2 * b22 - b12 pow 2) * y pow 2 +
             &2 * (&2 * b23 - b12 * b13) * y * z +
             (&2 * b33 - b13 pow 2) * z pow 2 = &5))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `G11 = &2 * b22 - b12 pow 2` THEN
  ABBREV_TAC `G12 = &2 * b23 - b12 * b13` THEN
  ABBREV_TAC `G22 = &2 * b33 - b13 pow 2` THEN
  SUBGOAL_THEN `G11 * G22 - G12 pow 2 = &20` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["G11"; "G12"; "G22"] THEN
    REWRITE_TAC[DISC_G] THEN
    MP_TAC(ASSUME
     `&2 * (b22 * b33 - b23 pow 2) -
      b12 * (b12 * b33 - b13 * b23) +
      b13 * (b12 * b23 - b13 * b22) = &10`) THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  MP_TAC(SPEC `&20:int` BINARY_HERMITE_PRIMITIVE) THEN
  CONV_TAC INT_REDUCE_CONV THEN
  DISCH_THEN(MP_TAC o SPEC `G11:int`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`G12:int`; `G22:int`]) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:int`
    (X_CHOOSE_THEN `t:int`
      (CONJUNCTS_THEN2
        (X_CHOOSE_THEN `p:int` (X_CHOOSE_TAC `q:int`))
        ASSUME_TAC))) THEN
  ABBREV_TAC
   `Gst = G11 * s pow 2 + &2 * G12 * s * t + G22 * t pow 2` THEN
  SUBGOAL_THEN `&3 * Gst pow 2 <= &4 * &20` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`b12 * s + b13 * t:int`; `&2:int`]
    INT_BALANCED_REM) THEN
  CONV_TAC INT_REDUCE_CONV THEN
  DISCH_THEN(X_CHOOSE_TAC `bb:int`) THEN
  ABBREV_TAC `x1 = --bb:int` THEN
  ABBREV_TAC
   `Fst = &2 * x1 pow 2 + b22 * s pow 2 + b33 * t pow 2 +
          &2 * b12 * x1 * s + &2 * b13 * x1 * t +
          &2 * b23 * s * t` THEN
  ABBREV_TAC `l = &2 * x1 + b12 * s + b13 * t` THEN
  SUBGOAL_THEN `&4 * l pow 2 <= &4` ASSUME_TAC THENL
   [MP_TAC(MATCH_MP SQ_BOUND
     (ASSUME `abs ((b12 * s + b13 * t) - &2 * bb) * &2 <= &2`)) THEN
    MAP_EVERY EXPAND_TAC ["l"; "x1"] THEN
    REWRITE_TAC[INT_ARITH
      `&2 * --bb + b12 * s + b13 * t =
       (b12 * s + b13 * t) - &2 * bb`] THEN
    INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `&2 <= Fst` ASSUME_TAC THENL
   [EXPAND_TAC "Fst" THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
    DISCH_TAC THEN UNDISCH_TAC `s * p + t * q = &1` THEN
    ASM_REWRITE_TAC[] THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `&2 * Fst = l pow 2 + Gst` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["Fst"; "l"; "Gst"; "G11"; "G12"; "G22"] THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN `&3 <= Gst` ASSUME_TAC THENL
   [UNDISCH_TAC `&2 <= Fst` THEN
    UNDISCH_TAC `&4 * l pow 2 <= &4` THEN
    UNDISCH_TAC `&2 * Fst = l pow 2 + Gst` THEN
    MP_TAC(SPEC `l:int` INT_LE_POW_2) THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `Gst <= &5` ASSUME_TAC THENL
   [ASM_CASES_TAC `Gst <= &5` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `&36 <= Gst pow 2` ASSUME_TAC THENL
     [MP_TAC(SPECL [`2`; `&6:int`; `Gst:int`] INT_POW_LE2) THEN
      ANTS_TAC THENL [ASM_INT_ARITH_TAC; CONV_TAC INT_REDUCE_CONV];
      UNDISCH_TAC `&3 * Gst pow 2 <= &4 * &20` THEN
      ASM_INT_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `l pow 2 = &0 \/ l pow 2 = &1`
  (LABEL_TAC "lsqcases") THENL
   [UNDISCH_TAC `&4 * l pow 2 <= &4` THEN
    MP_TAC(SPEC `l:int` INT_LE_POW_2) THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `l = &0 \/ l pow 2 = &1`
  (LABEL_TAC "lcases") THENL
   [REMOVE_THEN "lsqcases" MP_TAC THEN
    REWRITE_TAC[INT_POW_EQ_0] THEN CONV_TAC NUM_REDUCE_CONV THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `Fst <= &3` ASSUME_TAC THENL
   [UNDISCH_TAC `Gst <= &5` THEN
    UNDISCH_TAC `&4 * l pow 2 <= &4` THEN
    UNDISCH_TAC `&2 * Fst = l pow 2 + Gst` THEN
    INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `Fst = &2 \/ Fst = &3`
  (LABEL_TAC "Fcases") THENL
   [ASM_CASES_TAC `Fst = &2` THENL
     [ASM_REWRITE_TAC[];
      DISJ2_TAC THEN
      SUBGOAL_THEN `&2 < Fst` ASSUME_TAC THENL
       [ASM_INT_ARITH_TAC;
        UNDISCH_TAC `&2 < Fst` THEN
        REWRITE_TAC[INT_LT_DISCRETE] THEN ASM_INT_ARITH_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(Fst = &2 /\ l pow 2 = &1 /\ Gst = &3) \/
    (Fst = &2 /\ l = &0 /\ Gst = &4) \/
    (Fst = &3 /\ l pow 2 = &1 /\ Gst = &5)`
  (LABEL_TAC "shortcases") THENL
   [REMOVE_THEN "lcases" (DISJ_CASES_THEN ASSUME_TAC) THEN
    REMOVE_THEN "Fcases" (DISJ_CASES_THEN ASSUME_TAC) THEN
    UNDISCH_TAC `&3 <= Gst` THEN UNDISCH_TAC `Gst <= &5` THEN
    UNDISCH_TAC `&4 * l pow 2 <= &4` THEN
    UNDISCH_TAC `&2 <= Fst` THEN
    UNDISCH_TAC `&2 * Fst = l pow 2 + Gst` THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_REDUCE_CONV THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`x1:int`; `s:int`; `t:int`] THEN
  CONJ_TAC THENL
   [MAP_EVERY EXISTS_TAC [`p:int`; `q:int`] THEN ASM_REWRITE_TAC[];
    REMOVE_THEN "shortcases" MP_TAC THEN
    MAP_EVERY EXPAND_TAC ["Fst"; "l"; "Gst"; "G11"; "G12"; "G22"] THEN
    REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* The three possible minimum-2 blocks and Dickson's congruence exclusions. *)
(* ------------------------------------------------------------------------- *)

let DISC10_BLOCK3_EVEN_VALUE = prove
 (`!l c e f n:int.
     l pow 2 = &1 /\
     &2 * (&2 * f - e pow 2) -
       l * (l * f - c * e) + c * (l * e - &2 * c) = &10 /\
     (?x y z.
        &2 * x pow 2 + &2 * y pow 2 + f * z pow 2 +
        &2 * l * x * y + &2 * c * x * z + &2 * e * y * z = n)
     ==> &2 divides n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?h:int. f = &2 * h` STRIP_ASSUME_TAC THENL
   [MP_TAC(SPEC `f:int` INT_PARITY_WITNESS) THEN
    DISCH_THEN(DISJ_CASES_THEN
      (X_CHOOSE_THEN `h:int` ASSUME_TAC)) THENL
     [EXISTS_TAC `h:int` THEN ASM_REWRITE_TAC[];
      SUBGOAL_THEN `&2 divides (&7:int)` MP_TAC THENL
       [REWRITE_TAC[int_divides] THEN
        EXISTS_TAC
         `&3 * h - e pow 2 + l * c * e - c pow 2` THEN
        MAP_EVERY UNDISCH_TAC
         [`l pow 2 = &1`;
          `f = &2 * h + &1`;
          `&2 * (&2 * f - e pow 2) -
           l * (l * f - c * e) + c * (l * e - &2 * c) = &10`] THEN
        CONV_TAC INT_RING;
        REWRITE_TAC[GSYM INT_REM_EQ_0] THEN
        CONV_TAC INT_REDUCE_CONV]];
    ALL_TAC] THEN
  REWRITE_TAC[int_divides] THEN
  EXISTS_TAC
   `x pow 2 + y pow 2 + h * z pow 2 +
    l * x * y + c * x * z + e * y * z:int` THEN
  MAP_EVERY UNDISCH_TAC
   [`f = &2 * h`;
    `&2 * x pow 2 + &2 * y pow 2 + f * z pow 2 +
     &2 * l * x * y + &2 * c * x * z + &2 * e * y * z = n`] THEN
  CONV_TAC INT_RING);;

let INT_BLOCK5_CANONICAL_NOT6MOD16 = prove
 (`!l x y z q:int.
     l pow 2 = &1
     ==> ~(&2 * x pow 2 + &3 * y pow 2 + &2 * z pow 2 +
           &2 * l * x * y = &16 * q + &6)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN DISCH_TAC THEN
  MP_TAC(SPEC `y:int` INT_PARITY_WITNESS) THEN
  DISCH_THEN(DISJ_CASES_THEN
    (X_CHOOSE_THEN `t:int` ASSUME_TAC)) THENL
   [MP_TAC(SPECL [`x + l * t:int`; `z:int`; `t:int`; `q:int`]
      INT_SQ_SQ_5_NOT_3MOD8) THEN
    MAP_EVERY UNDISCH_TAC
     [`l pow 2 = &1`; `y = &2 * t`;
      `&2 * x pow 2 + &3 * y pow 2 + &2 * z pow 2 +
       &2 * l * x * y = &16 * q + &6`] THEN
    CONV_TAC INT_RING;
    SUBGOAL_THEN `&2 divides (&3:int)` MP_TAC THENL
     [REWRITE_TAC[int_divides] THEN
      EXISTS_TAC
       `&8 * q + &3 - x pow 2 - z pow 2 -
        &3 * (&2 * t pow 2 + &2 * t) -
        l * x * (&2 * t + &1):int` THEN
      MAP_EVERY UNDISCH_TAC
       [`y = &2 * t + &1`;
        `&2 * x pow 2 + &3 * y pow 2 + &2 * z pow 2 +
         &2 * l * x * y = &16 * q + &6`] THEN
      CONV_TAC INT_RING;
      REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV]]);;

let DISC10_BLOCK4_NOT6MOD16 = prove
 (`!c e f q:int.
     &2 * (&2 * f - e pow 2) + c * (--(&2 * c)) = &10
     ==> ~(?x y z.
              &2 * x pow 2 + &2 * y pow 2 + f * z pow 2 +
              &2 * c * x * z + &2 * e * y * z = &16 * q + &6)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `&2 * f - c pow 2 - e pow 2 = &5` ASSUME_TAC THENL
   [UNDISCH_TAC
     `&2 * (&2 * f - e pow 2) + c * --(&2 * c) = &10` THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN `?h:int. f = &2 * h + &1` STRIP_ASSUME_TAC THENL
   [MP_TAC(SPEC `e:int` INT_PARITY_WITNESS) THEN
    MP_TAC(SPEC `c:int` INT_PARITY_WITNESS) THEN
    DISCH_THEN(DISJ_CASES_THEN
      (X_CHOOSE_THEN `C:int` ASSUME_TAC)) THEN
    DISCH_THEN(DISJ_CASES_THEN
      (X_CHOOSE_THEN `E:int` ASSUME_TAC)) THENL
     [SUBGOAL_THEN `&2 divides (&5:int)` MP_TAC THENL
       [REWRITE_TAC[int_divides] THEN
        EXISTS_TAC
         `f - &2 * C pow 2 - &2 * E pow 2` THEN
        MAP_EVERY UNDISCH_TAC
         [`c = &2 * C`; `e = &2 * E`;
          `&2 * f - c pow 2 - e pow 2 = &5`] THEN
        CONV_TAC INT_RING;
        REWRITE_TAC[GSYM INT_REM_EQ_0] THEN
        CONV_TAC INT_REDUCE_CONV];
      EXISTS_TAC `C pow 2 + E pow 2 + E + &1:int` THEN
      MAP_EVERY UNDISCH_TAC
       [`c = &2 * C`; `e = &2 * E + &1`;
        `&2 * f - c pow 2 - e pow 2 = &5`] THEN
      CONV_TAC INT_RING;
      EXISTS_TAC `C pow 2 + C + E pow 2 + &1:int` THEN
      MAP_EVERY UNDISCH_TAC
       [`c = &2 * C + &1`; `e = &2 * E`;
        `&2 * f - c pow 2 - e pow 2 = &5`] THEN
      CONV_TAC INT_RING;
      SUBGOAL_THEN `&2 divides (&5:int)` MP_TAC THENL
       [REWRITE_TAC[int_divides] THEN
        EXISTS_TAC
         `f - (&2 * C pow 2 + &2 * C) -
              (&2 * E pow 2 + &2 * E) - &1:int` THEN
        MAP_EVERY UNDISCH_TAC
         [`c = &2 * C + &1`; `e = &2 * E + &1`;
          `&2 * f - c pow 2 - e pow 2 = &5`] THEN
        CONV_TAC INT_RING;
        REWRITE_TAC[GSYM INT_REM_EQ_0] THEN
        CONV_TAC INT_REDUCE_CONV]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int` (X_CHOOSE_THEN `z:int` ASSUME_TAC))) THEN
  MP_TAC(SPEC `z:int` INT_PARITY_WITNESS) THEN
  DISCH_THEN(DISJ_CASES_THEN
    (X_CHOOSE_THEN `Z:int` ASSUME_TAC)) THENL
   [MP_TAC(SPECL
     [`x + c * Z:int`; `y + e * Z:int`; `Z:int`; `q:int`]
     INT_SQ_SQ_5_NOT_3MOD8) THEN
    MAP_EVERY UNDISCH_TAC
     [`&2 * f - c pow 2 - e pow 2 = &5`;
      `z = &2 * Z`;
      `&2 * x pow 2 + &2 * y pow 2 + f * z pow 2 +
       &2 * c * x * z + &2 * e * y * z = &16 * q + &6`] THEN
    CONV_TAC INT_RING;
    SUBGOAL_THEN `&2 divides (&1:int)` MP_TAC THENL
     [REWRITE_TAC[int_divides] THEN
      EXISTS_TAC
       `&8 * q + &3 - x pow 2 - y pow 2 -
        h * z pow 2 - c * x * z - e * y * z -
        (&2 * Z pow 2 + &2 * Z):int` THEN
      MAP_EVERY UNDISCH_TAC
       [`f = &2 * h + &1`; `z = &2 * Z + &1`;
        `&2 * x pow 2 + &2 * y pow 2 + f * z pow 2 +
         &2 * c * x * z + &2 * e * y * z = &16 * q + &6`] THEN
      CONV_TAC INT_RING;
      REWRITE_TAC[INT_DIVIDES_ONE] THEN INT_ARITH_TAC]]);;

let DISC10_BLOCK5_NOT6MOD16 = prove
 (`!l c e f q:int.
     l pow 2 = &1 /\
     &2 * (&3 * f - e pow 2) -
       l * (l * f - c * e) + c * (l * e - &3 * c) = &10
     ==> ~(?x y z.
              &2 * x pow 2 + &3 * y pow 2 + f * z pow 2 +
              &2 * l * x * y + &2 * c * x * z +
              &2 * e * y * z = &16 * q + &6)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `r = l * c - &2 * e` THEN
  ABBREV_TAC `A = &3 * c pow 2 - &2 * l * c * e + &2 * e pow 2` THEN
  SUBGOAL_THEN `A = &5 * (f - &2)` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["A"] THEN
    MAP_EVERY UNDISCH_TAC
     [`l pow 2 = &1`;
      `&2 * (&3 * f - e pow 2) -
       l * (l * f - c * e) + c * (l * e - &3 * c) = &10`] THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN `&5 divides (&3 * r pow 2)` ASSUME_TAC THENL
    [REWRITE_TAC[int_divides] THEN
    EXISTS_TAC `(f - &2) + &2 * e * (e - l * c):int` THEN
    EXPAND_TAC "r" THEN
    MAP_EVERY UNDISCH_TAC
     [`l pow 2 = &1`; `A = &5 * (f - &2)`] THEN
    EXPAND_TAC "A" THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN `int_prime(&5)` ASSUME_TAC THENL
   [REWRITE_TAC[INT_PRIME] THEN
    ACCEPT_TAC(EQT_ELIM(PRIME_CONV `prime 5`));
    ALL_TAC] THEN
  SUBGOAL_THEN `&5 divides r` ASSUME_TAC THENL
   [MP_TAC(MATCH_MP (SPECL [`&5:int`; `&3:int`; `r pow 2`]
      INT_PRIME_DIVPROD)
      (CONJ (ASSUME `int_prime(&5)`)
            (ASSUME `&5 divides (&3 * r pow 2)`))) THEN
    DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
     [UNDISCH_TAC `&5 divides (&3:int)` THEN
      REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV;
      MATCH_MP_TAC(SPECL [`2`; `&5:int`; `r:int`] INT_PRIME_DIVPOW) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `&5 divides (--(&3 * c) + l * e)` ASSUME_TAC THENL
   [REWRITE_TAC[int_divides] THEN
    X_CHOOSE_TAC `R:int`
     (REWRITE_RULE[int_divides] (ASSUME `&5 divides r`)) THEN
    EXISTS_TAC `--(&3 * l * R) - l * e:int` THEN
    MAP_EVERY UNDISCH_TAC
     [`l pow 2 = &1`; `l * c - &2 * e = r`; `r = &5 * R`] THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  X_CHOOSE_TAC `P:int`
   (REWRITE_RULE[int_divides]
     (ASSUME `&5 divides (--(&3 * c) + l * e)`)) THEN
  X_CHOOSE_TAC `Q:int`
   (REWRITE_RULE[int_divides] (ASSUME `&5 divides r`)) THEN
  SUBGOAL_THEN
   `&2 * P + l * Q = --c /\ l * P + &3 * Q = --e`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC
     [`l pow 2 = &1`;
      `--(&3 * c) + l * e = &5 * P`;
      `l * c - &2 * e = r`; `r = &5 * Q`] THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  ABBREV_TAC
   `f' = &2 * P pow 2 + &3 * Q pow 2 + f +
         &2 * l * P * Q + &2 * c * P + &2 * e * Q` THEN
  SUBGOAL_THEN `f' = &2` ASSUME_TAC THENL
   [SUBGOAL_THEN `&5 * f' = &10` MP_TAC THENL
     [MAP_EVERY EXPAND_TAC ["f'"] THEN
      MAP_EVERY UNDISCH_TAC
       [`l pow 2 = &1`;
        `&2 * (&3 * f - e pow 2) -
         l * (l * f - c * e) + c * (l * e - &3 * c) = &10`;
        `&2 * P + l * Q = --c`;
        `l * P + &3 * Q = --e`] THEN
      CONV_TAC INT_RING;
      INT_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&2 * P pow 2 + &3 * Q pow 2 + &2 * l * P * Q + &2 = f`
  (LABEL_TAC "fcoeff") THENL
   [UNDISCH_TAC `f' = &2` THEN EXPAND_TAC "f'" THEN
    MAP_EVERY UNDISCH_TAC
     [`&2 * P + l * Q = --c`; `l * P + &3 * Q = --e`] THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int` (X_CHOOSE_THEN `z:int` ASSUME_TAC))) THEN
  SUBGOAL_THEN
   `&2 * (x - P * z) pow 2 + &3 * (y - Q * z) pow 2 +
    &2 * z pow 2 + &2 * l * (x - P * z) * (y - Q * z) =
    &2 * x pow 2 + &3 * y pow 2 + f * z pow 2 +
    &2 * l * x * y + &2 * c * x * z + &2 * e * y * z`
  ASSUME_TAC THENL
   [TRANS_TAC EQ_TRANS
     `&2 * x pow 2 + &3 * y pow 2 + &2 * l * x * y +
      &2 * --(&2 * P + l * Q) * x * z +
      &2 * --(l * P + &3 * Q) * y * z +
      (&2 * P pow 2 + &3 * Q pow 2 + &2 * l * P * Q + &2) *
      z pow 2` THEN
    CONJ_TAC THENL
     [CONV_TAC INT_RING;
      REWRITE_TAC
       [ASSUME `&2 * P + l * Q = --c`;
        ASSUME `l * P + &3 * Q = --e`;
        ASSUME
         `&2 * P pow 2 + &3 * Q pow 2 + &2 * l * P * Q + &2 = f`] THEN
      CONV_TAC INT_RING];
    ALL_TAC] THEN
  MP_TAC(SPECL
   [`l:int`; `x - P * z:int`; `y - Q * z:int`; `z:int`; `q:int`]
   INT_BLOCK5_CANONICAL_NOT6MOD16) THEN
  ASM_REWRITE_TAC[]);;

let DISC10_MIN2_EXCLUDED = prove
 (`!b12 b13 b22 b23 b33 a m:int.
     &2 * (b22 * b33 - b23 pow 2) -
       b12 * (b12 * b33 - b13 * b23) +
       b13 * (b12 * b23 - b13 * b22) = &10 /\
     &0 < &2 * b22 - b12 pow 2 /\
     (!x y z. ~(x = &0 /\ y = &0 /\ z = &0)
              ==> &2 <= &2 * x pow 2 + b22 * y pow 2 +
                         b33 * z pow 2 + &2 * b12 * x * y +
                         &2 * b13 * x * z + &2 * b23 * y * z) /\
     ~(&2 divides a) /\
     (?x y z.
        &2 * x pow 2 + b22 * y pow 2 + b33 * z pow 2 +
        &2 * b12 * x * y + &2 * b13 * x * z +
        &2 * b23 * y * z = a) /\
     (?x y z.
        &2 * x pow 2 + b22 * y pow 2 + b33 * z pow 2 +
        &2 * b12 * x * y + &2 * b13 * x * z +
        &2 * b23 * y * z = &16 * m + &6)
     ==> F`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL
   [`b12:int`; `b13:int`; `b22:int`; `b23:int`; `b33:int`]
   HERMITE_DISC10_MIN2_PAIR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `r:int`
    (X_CHOOSE_THEN `s:int`
      (X_CHOOSE_THEN `t:int`
        (CONJUNCTS_THEN2
          (X_CHOOSE_THEN `p:int` (X_CHOOSE_TAC `q:int`))
          (LABEL_TAC "cases"))))) THEN
  ABBREV_TAC `l = &2 * r + b12 * s + b13 * t` THEN
  ABBREV_TAC
   `d = &2 * r pow 2 + b22 * s pow 2 + b33 * t pow 2 +
        &2 * b12 * r * s + &2 * b13 * r * t +
        &2 * b23 * s * t` THEN
  ABBREV_TAC `c = --(b12 * q) + b13 * p` THEN
  ABBREV_TAC
   `e = --(b12 * r * q) + b13 * r * p - b22 * s * q +
        b23 * s * p - b23 * t * q + b33 * t * p` THEN
  ABBREV_TAC
   `f = b22 * q pow 2 + b33 * p pow 2 - &2 * b23 * p * q` THEN
  SUBGOAL_THEN
   `&2 * (d * f - e pow 2) -
    l * (l * f - c * e) + c * (l * e - d * c) = &10`
  ASSUME_TAC THENL
   [TRANS_TAC EQ_TRANS
     `(&2 * (b22 * b33 - b23 pow 2) -
       b12 * (b12 * b33 - b13 * b23) +
       b13 * (b12 * b23 - b13 * b22)) *
      (s * p + t * q) pow 2` THEN
    CONJ_TAC THENL
     [REWRITE_TAC
       [GSYM(ASSUME `&2 * r + b12 * s + b13 * t = l`);
        GSYM(ASSUME
         `&2 * r pow 2 + b22 * s pow 2 + b33 * t pow 2 +
          &2 * b12 * r * s + &2 * b13 * r * t +
          &2 * b23 * s * t = d`);
        GSYM(ASSUME `--(b12 * q) + b13 * p = c`);
        GSYM(ASSUME
         `--(b12 * r * q) + b13 * r * p - b22 * s * q +
          b23 * s * p - b23 * t * q + b33 * t * p = e`);
        GSYM(ASSUME
         `b22 * q pow 2 + b33 * p pow 2 - &2 * b23 * p * q = f`)] THEN
      CONV_TAC INT_RING;
      REWRITE_TAC
       [ASSUME
         `&2 * (b22 * b33 - b23 pow 2) -
          b12 * (b12 * b33 - b13 * b23) +
          b13 * (b12 * b23 - b13 * b22) = &10`;
