(* Dickson's constructed form has coefficients
     [a,0,1; 2 beta,4t; 8h].
   The characteristic vector (0,1,1) gives its type at 2. *)

let TERNARY_TYPE6_DICKSON = prove
 (`!a beta t h b:int.
     ~(&2 divides a) /\ beta = &8 * b + &3
     ==> ternary_type6 a (&0) (&1) (&2 * beta) (&4 * t) (&8 * h)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP (SPEC `a:int` INT_ODD_FORM)
    (ASSUME `~(&2 divides a)`)) THEN
  DISCH_THEN(X_CHOOSE_TAC `r:int`) THEN
  MATCH_MP_TAC(SPECL
   [`a:int`; `&0:int`; `&1:int`; `&2 * beta:int`; `&4 * t:int`;
    `&8 * h:int`; `&0:int`; `&1:int`; `&1:int`;
    `&2 * b + h + t:int`] TERNARY_TYPE6_OF_CHARACTERISTIC) THEN
  REWRITE_TAC[tqeval; INT_MUL_LZERO; INT_MUL_RZERO; INT_ADD_LID;
    INT_ADD_RID; INT_MUL_LID; INT_MUL_RID] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[int_divides] THEN EXISTS_TAC `r:int` THEN
    UNDISCH_TAC `a = &2 * r + &1` THEN CONV_TAC INT_RING;
    REWRITE_TAC[int_divides] THEN EXISTS_TAC `--(&2 * t):int` THEN
    CONV_TAC INT_RING;
    REWRITE_TAC[int_divides] THEN EXISTS_TAC `--(&2 * t):int` THEN
    CONV_TAC INT_RING;
    UNDISCH_TAC `beta = &8 * b + &3` THEN CONV_TAC INT_RING]);;

let LEMMA_125 = prove
 (`!a k beta t h n:int.
     &0 < a /\ &0 < beta /\ ~(&2 divides a) /\
     beta = &8 * a * k - &5 /\
     beta * h = t pow 2 + k /\
     (?x y z.
        a * x pow 2 + (&2 * beta) * y pow 2 + (&8 * h) * z pow 2 +
        &2 * x * z + &2 * (&4 * t) * y * z = n)
     ==> ?u v w:int. u pow 2 + &2 * v pow 2 + &5 * w pow 2 = n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC TERNARY_DISC10_TYPE6_SPECIAL THEN
  MAP_EVERY EXISTS_TAC
   [`a:int`; `&0:int`; `&1:int`; `&2 * beta:int`; `&4 * t:int`;
    `&8 * h:int`; `a:int`; `a * k - &1:int`] THEN
  REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    REWRITE_TAC[INT_POW_2; INT_MUL_LZERO; INT_SUB_RZERO] THEN
    MATCH_MP_TAC INT_LT_MUL THEN ASM_REWRITE_TAC[] THEN
    ASM_INT_ARITH_TAC;
    MAP_EVERY UNDISCH_TAC
     [`beta = &8 * a * k - &5`; `beta * h = t pow 2 + k`] THEN
    CONV_TAC INT_RING;
    MATCH_MP_TAC(SPECL
     [`a:int`; `beta:int`; `t:int`; `h:int`; `a * k - &1:int`]
     TERNARY_TYPE6_DICKSON) THEN
    ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `beta = &8 * a * k - &5` THEN
    CONV_TAC INT_RING;
    ASM_REWRITE_TAC[];
    MAP_EVERY EXISTS_TAC [`&1:int`; `&0:int`; `&0:int`] THEN
    CONV_TAC INT_RING;
    MAP_EVERY EXISTS_TAC [`&0:int`; `&1:int`; `&0:int`] THEN
    UNDISCH_TAC `beta = &8 * a * k - &5` THEN
    CONV_TAC INT_RING;
    MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`] THEN
    UNDISCH_TAC
     `a * x pow 2 + (&2 * beta) * y pow 2 + (&8 * h) * z pow 2 +
      &2 * x * z + &2 * (&4 * t) * y * z = n` THEN
    CONV_TAC INT_RING]);;

(* ------------------------------------------------------------------------- *)
(* Dickson's Dirichlet progression beta = 8 a (10j+3) - 5.                 *)
(* ------------------------------------------------------------------------- *)

let COPRIME_5_OF_10 = prove
 (`!a:num. coprime(10,a) ==> coprime(5,a)`,
  GEN_TAC THEN
  REWRITE_TAC[ARITH_RULE `10 = 2 * 5`; COPRIME_LMUL] THEN
  MESON_TAC[]);;

let COPRIME_125_OFFSET_A = prove
 (`!a:num.
     1 <= a /\ coprime(10,a)
     ==> coprime(24*a-5,a)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `coprime(5,a)` ASSUME_TAC THENL
   [MATCH_MP_TAC COPRIME_5_OF_10 THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[COPRIME] THEN X_GEN_TAC `d:num` THEN EQ_TAC THENL
   [STRIP_TAC THEN
    SUBGOAL_THEN `d divides 24*a` ASSUME_TAC THENL
     [MATCH_MP_TAC(SPECL [`d:num`; `a:num`; `24`] DIVIDES_LMUL) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `d divides 5` ASSUME_TAC THENL
     [SUBGOAL_THEN `5 = 24*a - (24*a-5)` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        MATCH_MP_TAC(SPECL [`d:num`; `24*a`; `24*a-5`] DIVIDES_SUB) THEN
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    MP_TAC(SPEC `d:num`
      (REWRITE_RULE[COPRIME] (ASSUME `coprime(5,a)`))) THEN
    ASM_REWRITE_TAC[];
    DISCH_TAC THEN ASM_REWRITE_TAC[DIVIDES_1]]);;

let COPRIME_125_OFFSET_80 = prove
 (`!a:num.
     1 <= a /\ coprime(10,a)
     ==> coprime(24*a-5,80)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `ODD(24*a-5)` ASSUME_TAC THENL
   [REWRITE_TAC[ODD_EXISTS] THEN EXISTS_TAC `12*a-3` THEN
    ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~(5 divides a)` ASSUME_TAC THENL
   [MATCH_MP_TAC(fst(EQ_IMP_RULE
      (MATCH_MP (SPECL [`5`; `a:num`] PRIME_COPRIME_EQ)
        (EQT_ELIM(PRIME_CONV `prime 5`))))) THEN
    MATCH_MP_TAC COPRIME_5_OF_10 THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(5 divides (24*a-5))` ASSUME_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `5 divides 24*a` ASSUME_TAC THENL
     [SUBGOAL_THEN `24*a = (24*a-5)+5` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        MATCH_MP_TAC DIVIDES_ADD THEN ASM_REWRITE_TAC[DIVIDES_REFL]];
      ALL_TAC] THEN
    MP_TAC(ASSUME `5 divides 24*a`) THEN
    REWRITE_TAC[MATCH_MP (SPEC `5` PRIME_DIVPROD_EQ)
      (EQT_ELIM(PRIME_CONV `prime 5`))] THEN
    ASM_REWRITE_TAC[] THEN
    CONV_TAC(RAND_CONV DIVIDES_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[ARITH_RULE `80 = 2*2*2*2*5`; COPRIME_RMUL] THEN
  ASM_REWRITE_TAC[CONJUNCT2 COPRIME_2] THEN
  ONCE_REWRITE_TAC[COPRIME_SYM] THEN
  ASM_REWRITE_TAC[MATCH_MP (SPEC `5` PRIME_COPRIME_EQ)
    (EQT_ELIM(PRIME_CONV `prime 5`))]);;

let COPRIME_DIRICHLET_125 = prove
 (`!a:num.
     1 <= a /\ coprime(10,a)
     ==> coprime(24*a-5,80*a)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[COPRIME_RMUL] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC COPRIME_125_OFFSET_80 THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC COPRIME_125_OFFSET_A THEN ASM_REWRITE_TAC[]]);;

let DIRICHLET_PRIME_125 = prove
 (`!a:num.
     1 <= a /\ coprime(10,a)
     ==> ?p. prime p /\ (p == 24*a-5) (mod (80*a))`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC DIRICHLET_PRIME_CONG THEN
  ASM_SIMP_TAC[COPRIME_DIRICHLET_125] THEN ASM_ARITH_TAC);;

let COPRIME_5_10J3 = prove
 (`!j:num. coprime(5,10*j+3)`,
  GEN_TAC THEN REWRITE_TAC[COPRIME_BEZOUT] THEN
  MAP_EVERY EXISTS_TAC [`2`; `4*j+1`] THEN
  DISJ2_TAC THEN ARITH_TAC);;

let SQUARE_MOD_5 = prove
 (`!n. (n EXP 2 == 0) (mod 5) \/
       (n EXP 2 == 1) (mod 5) \/
       (n EXP 2 == 4) (mod 5)`,
  GEN_TAC THEN SIMP_TAC[CONG; ARITH_EQ] THEN
  ONCE_REWRITE_TAC[GSYM MOD_EXP_MOD] THEN
  MP_TAC(SPECL [`n:num`; `5`] DIVISION) THEN REWRITE_TAC[ARITH] THEN
  DISCH_THEN(MP_TAC o CONJUNCT2) THEN
  SIMP_TAC[LT; ARITH; ARITH_RULE
   `~(m = 0) ==> (n < m <=> n = m - 1 \/ n < m - 1)`] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST1_TAC) THEN
  CONV_TAC NUM_REDUCE_CONV);;

let NO_SQUARE_3_MOD_5 = prove
 (`~(?x:num. (x EXP 2 == 3) (mod 5))`,
  REWRITE_TAC[NOT_EXISTS_THM] THEN X_GEN_TAC `x:num` THEN DISCH_TAC THEN
  MP_TAC(SPEC `x:num` SQUARE_MOD_5) THEN
  MP_TAC(ASSUME `(x EXP 2 == 3) (mod 5)`) THEN
  REWRITE_TAC[CONG] THEN CONV_TAC NUM_REDUCE_CONV THEN ARITH_TAC);;

let JACOBI_3_5 = prove
 (`jacobi(3,5) = -- &1`,
  MP_TAC(MATCH_MP (SPECL [`3`; `5`] JACOBI_PRIME)
    (EQT_ELIM(PRIME_CONV `prime 5`))) THEN
  REWRITE_TAC[NO_SQUARE_3_MOD_5] THEN
  CONV_TAC(DEPTH_CONV DIVIDES_CONV) THEN REWRITE_TAC[]);;

let JACOBI_5_10J3 = prove
 (`!j:num. jacobi(5,10*j+3) = -- &1`,
  GEN_TAC THEN
  SUBGOAL_THEN `ODD(10*j+3)` ASSUME_TAC THENL
   [REWRITE_TAC[ODD_ADD; ODD_MULT; ARITH];
    ALL_TAC] THEN
  SUBGOAL_THEN `jacobi(10*j+3,5) = -- &1` ASSUME_TAC THENL
   [TRANS_TAC EQ_TRANS `jacobi(3,5)` THEN CONJ_TAC THENL
     [MATCH_MP_TAC JACOBI_CONG THEN NUMBER_TAC;
      REWRITE_TAC[JACOBI_3_5]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`5`; `10*j+3`] JACOBI_RECIPROCITY) THEN
  ASM_REWRITE_TAC[COPRIME_5_10J3; NUM_REDUCE_CONV `ODD 5`] THEN
  REWRITE_TAC[ARITH_RULE `(5-1) DIV 2 = 2`; EVEN_MULT;
    INT_POW_NEG; INT_POW_ONE; NUM_REDUCE_CONV `EVEN 2`] THEN
  INT_ARITH_TAC);;

let CONG_BETA_NEG5_125 = prove
 (`!a j beta:num.
     1 <= a /\ beta = 8*a*(10*j+3)-5
     ==> (beta == 5*((10*j+3)-1)) (mod (10*j+3))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `5*((10*j+3)-1) = 5*(10*j+3)-5`
  SUBST1_TAC THENL
   [ARITH_TAC;
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC CONG_SUB THEN
    REPEAT CONJ_TAC THENL
     [NUMBER_TAC;
      REWRITE_TAC[CONG_REFL];
      ASM_ARITH_TAC;
      ARITH_TAC]]);;

let JACOBI_BETA_10J3 = prove
 (`!a j beta:num.
     1 <= a /\ beta = 8*a*(10*j+3)-5
     ==> jacobi(beta,10*j+3) =
         --(-- &1 pow (((10*j+3)-1) DIV 2))`,
  REPEAT STRIP_TAC THEN
  TRANS_TAC EQ_TRANS `jacobi(5*((10*j+3)-1),10*j+3)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC JACOBI_CONG THEN
    MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
      CONG_BETA_NEG5_125) THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[JACOBI_LMUL; JACOBI_5_10J3] THEN
    SUBGOAL_THEN `ODD(10*j+3)` ASSUME_TAC THENL
     [REWRITE_TAC[ODD_ADD; ODD_MULT; ARITH];
      ASM_SIMP_TAC[JACOBI_MINUS1] THEN INT_ARITH_TAC]]);;

let CONG_BETA_3MOD4_125 = prove
 (`!a j beta:num.
     1 <= a /\ beta = 8*a*(10*j+3)-5
     ==> (beta == 3) (mod 4)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `beta = (2*a*(10*j+3)-2)*4+3`
  SUBST1_TAC THENL
   [ASM_ARITH_TAC;
    REWRITE_TAC[CONG] THEN SIMP_TAC[MOD_MULT_ADD] THEN
    CONV_TAC NUM_REDUCE_CONV]);;

let COPRIME_BETA_10J3 = prove
  (`!a j beta:num.
     1 <= a /\ beta = 8*a*(10*j+3)-5
     ==> coprime(beta,10*j+3)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `jacobi(beta,10*j+3) = --(-- &1 pow (((10*j+3)-1) DIV 2))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
      JACOBI_BETA_10J3) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`beta:num`; `10*j+3`] JACOBI_EQ_0) THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[INT_NEG_EQ_0; INT_POW_EQ_0] THEN
  CONV_TAC INT_REDUCE_CONV);;

let JACOBI_NEGK_BETA_125 = prove
 (`!a j beta:num.
     1 <= a /\ beta = 8*a*(10*j+3)-5
     ==> jacobi((10*j+3)*(beta-1),beta) = &1`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `k:num = 10*j+3` THEN
  SUBGOAL_THEN `ODD k` ASSUME_TAC THENL
   [EXPAND_TAC "k" THEN REWRITE_TAC[ODD_ADD; ODD_MULT; ARITH];
    ALL_TAC] THEN
  SUBGOAL_THEN `(beta == 3) (mod 4)` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
      CONG_BETA_3MOD4_125) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `ODD beta` ASSUME_TAC THENL
   [MATCH_MP_TAC ODD_OF_3MOD4 THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `coprime(beta:num,k)` ASSUME_TAC THENL
   [ACCEPT_TAC(MATCH_MP
     (REWRITE_RULE[ASSUME `10*j+3 = (k:num)`]
       (SPECL [`a:num`; `j:num`; `beta:num`] COPRIME_BETA_10J3))
     (CONJ (ASSUME `1 <= a`)
           (ASSUME `beta:num = 8*a*k-5`)));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `jacobi(beta,k) = --(-- &1 pow ((k-1) DIV 2))`
  ASSUME_TAC THENL
   [ACCEPT_TAC(MATCH_MP
     (REWRITE_RULE[ASSUME `10*j+3 = (k:num)`]
       (SPECL [`a:num`; `j:num`; `beta:num`] JACOBI_BETA_10J3))
     (CONJ (ASSUME `1 <= a`)
           (ASSUME `beta:num = 8*a*k-5`)));
    ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `q:num` o MATCH_MP CONG_3_MOD_4 o
    check (fun th -> concl th = `(beta == 3) (mod 4)`)) THEN
  SUBGOAL_THEN `(beta-1) DIV 2 = 2*q+1` ASSUME_TAC THENL
   [ONCE_REWRITE_TAC[ASSUME `beta:num = 4*q+3`] THEN
    REWRITE_TAC[ARITH_RULE `((4*q+3)-1) DIV 2 = 2*q+1`];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `-- &1 pow (((beta-1) DIV 2) * ((k-1) DIV 2)) =
    -- &1 pow ((k-1) DIV 2)`
  ASSUME_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[INT_POW_NEG; INT_POW_ONE; EVEN_MULT; EVEN_ADD; ARITH];
    ALL_TAC] THEN
  SUBGOAL_THEN `jacobi(k,beta) = -- &1` ASSUME_TAC THENL
   [MP_TAC(SPECL [`beta:num`; `k:num`] JACOBI_RECIPROCITY) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    ONCE_REWRITE_TAC[ASSUME `beta:num = 8*a*k-5`] THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[INT_POW_NEG; INT_POW_ONE] THEN
    COND_CASES_TAC THEN CONV_TAC INT_REDUCE_CONV;
    ALL_TAC] THEN
  REWRITE_TAC[JACOBI_LMUL] THEN
  ONCE_REWRITE_TAC[ASSUME `jacobi(k,beta) = -- &1`] THEN
  MP_TAC(MATCH_MP (SPEC `beta:num` JACOBI_M1_3MOD4)
    (ASSUME `(beta == 3) (mod 4)`)) THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  CONV_TAC INT_REDUCE_CONV);;

let QR_125 = prove
 (`!a j beta:num.
     1 <= a /\ prime beta /\ beta = 8*a*(10*j+3)-5
     ==> ?t. (t EXP 2 + (10*j+3) == 0) (mod beta)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC JACOBI_NEGATIVE_SQUARE THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
    JACOBI_NEGK_BETA_125) THEN
  ASM_REWRITE_TAC[]);;

let RESIDUE_125 = prove
 (`!a:num.
     1 <= a /\ coprime(10,a)
     ==> ?j t.
           (8*a*(10*j+3)-5) divides (t EXP 2 + (10*j+3))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPEC `a:num` DIRICHLET_PRIME_125) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `beta:num` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `?j. beta = 80*a*j + (24*a-5)`
  (X_CHOOSE_TAC `j:num`) THENL
   [MP_TAC(SPECL [`80*a`; `24*a-5`; `beta:num`] CONG_CASE) THEN
    ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MONO_EXISTS THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `beta = 8*a*(10*j+3)-5`
  ASSUME_TAC THENL
   [UNDISCH_TAC `beta = 80*a*j + (24*a-5)` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
   (SPECL [`a:num`; `j:num`; `beta:num`] QR_125)
   (CONJ (ASSUME `1 <= a`)
    (CONJ (ASSUME `prime beta`)
          (ASSUME `beta = 8*a*(10*j+3)-5`)))) THEN
  DISCH_THEN(X_CHOOSE_TAC `t:num`) THEN
  MAP_EVERY EXISTS_TAC [`j:num`; `t:num`] THEN
  ONCE_REWRITE_TAC[GSYM
    (ASSUME `beta = 8*a*(10*j+3)-5`)] THEN
  MP_TAC(ASSUME `(t EXP 2 + (10*j+3) == 0) (mod beta)`) THEN
  REWRITE_TAC[CONG_0_DIVIDES]);;

let REGULAR_125_COPRIME10 = prove
 (`!a:num.
     1 <= a /\ coprime(10,a)
     ==> ?u v w:int. u pow 2 + &2*v pow 2 + &5*w pow 2 = &a`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `ODD a` ASSUME_TAC THENL
   [MP_TAC(ASSUME `coprime(10,a)`) THEN
    REWRITE_TAC[ARITH_RULE `10 = 2*5`; COPRIME_LMUL;
      CONJUNCT1 COPRIME_2] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPEC `a:num` RESIDUE_125) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `j:num` (X_CHOOSE_TAC `t:num`)) THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `h:num` o REWRITE_RULE[divides]) THEN
  MATCH_MP_TAC(SPECL
   [`&a:int`; `&(10*j+3):int`; `&(8*a*(10*j+3)-5):int`;
    `&t:int`; `&h:int`; `&a:int`] LEMMA_125) THEN
  REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[INT_OF_NUM_LT] THEN ASM_ARITH_TAC;
    REWRITE_TAC[INT_OF_NUM_LT] THEN ASM_ARITH_TAC;
    REWRITE_TAC[GSYM num_divides; DIVIDES_2; GSYM NOT_ODD] THEN
    ASM_REWRITE_TAC[];
    SUBGOAL_THEN `5 <= 8*a*(10*j+3)` ASSUME_TAC THENL
     [ASM_ARITH_TAC;
      ASM_SIMP_TAC[INT_OF_NUM_SUB; INT_OF_NUM_MUL; INT_OF_NUM_ADD] THEN
      CONV_TAC INT_RING];
    FIRST_X_ASSUM(MP_TAC o AP_TERM `int_of_num`) THEN
    REWRITE_TAC[INT_OF_NUM_ADD; INT_OF_NUM_MUL; INT_OF_NUM_POW] THEN
    DISCH_TAC THEN ASM_REWRITE_TAC[];
    MAP_EVERY EXISTS_TAC [`&1:int`; `&0:int`; `&0:int`] THEN
    CONV_TAC INT_RING]);;

let BINARY_DISC5 = prove
 (`!A11. &0 < A11
   ==> !A12 A22.
         A11 * A22 - A12 pow 2 = &5
         ==> ((!n.
                 (?x y.
                    A11 * x pow 2 + &2 * A12 * x * y +
                    A22 * y pow 2 = n)
                 ==> ?u v:int. u pow 2 + &5 * v pow 2 = n) \/
              (!n.
                 (?x y.
                    A11 * x pow 2 + &2 * A12 * x * y +
                    A22 * y pow 2 = n)
                 ==> ?u v:int.
                       &2 * u pow 2 + &2 * u * v + &3 * v pow 2 = n))`,
  ONCE_REWRITE_TAC[MESON[]
   `(!A11. &0 < A11 ==> P A11) <=>
    (!m A11. num_of_int A11 = m /\ &0 < A11 ==> P A11)`] THEN
  MATCH_MP_TAC num_WF THEN GEN_TAC THEN STRIP_TAC THEN
  GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN DISCH_TAC THEN
  ASM_CASES_TAC `A11 = &1` THENL
   [DISJ1_TAC THEN GEN_TAC THEN
    DISCH_THEN(X_CHOOSE_THEN `x:int` (X_CHOOSE_TAC `y:int`)) THEN
    MAP_EVERY EXISTS_TAC [`x + A12 * y:int`; `y:int`] THEN
    MP_TAC(ASSUME `A11 * A22 - A12 pow 2 = &5`) THEN
    MP_TAC(ASSUME
     `A11 * x pow 2 + &2 * A12 * x * y + A22 * y pow 2 = n`) THEN
    REWRITE_TAC[ASSUME `A11 = &1`] THEN CONV_TAC INT_RING;
    ALL_TAC] THEN
  ASM_CASES_TAC `A11 = &2` THENL
   [DISJ2_TAC THEN GEN_TAC THEN
    DISCH_THEN(X_CHOOSE_THEN `x:int` (X_CHOOSE_TAC `y:int`)) THEN
    SUBGOAL_THEN `~(&2 divides A12)` ASSUME_TAC THENL
     [DISCH_THEN(X_CHOOSE_TAC `q:int` o REWRITE_RULE[int_divides]) THEN
      SUBGOAL_THEN `&2 divides &5` MP_TAC THENL
       [REWRITE_TAC[int_divides] THEN
        EXISTS_TAC `A22 - &2 * (q:int) pow 2` THEN
        MP_TAC(ASSUME `A11 * A22 - A12 pow 2 = &5`) THEN
        REWRITE_TAC[ASSUME `A11 = &2`; ASSUME `A12 = &2 * q`] THEN
        CONV_TAC INT_RING;
        REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV];
      ALL_TAC] THEN
    MP_TAC(MATCH_MP (SPEC `A12:int` INT_ODD_FORM)
      (ASSUME `~(&2 divides A12)`)) THEN
    DISCH_THEN(X_CHOOSE_TAC `q:int`) THEN
    SUBGOAL_THEN `A22 = &2 * q pow 2 + &2 * q + &3`
    ASSUME_TAC THENL
     [MP_TAC(ASSUME `A11 * A22 - A12 pow 2 = &5`) THEN
      REWRITE_TAC
       [ASSUME `A11 = &2`; ASSUME `A12 = &2 * q + &1`] THEN
      CONV_TAC INT_RING;
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`x + q * y:int`; `y:int`] THEN
    MP_TAC(ASSUME
     `A11 * x pow 2 + &2 * A12 * x * y + A22 * y pow 2 = n`) THEN
    REWRITE_TAC
     [ASSUME `A11 = &2`; ASSUME `A12 = &2 * q + &1`;
      ASSUME `A22 = &2 * q pow 2 + &2 * q + &3`] THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  MP_TAC(SPECL [`A12:int`; `A11:int`] INT_BALANCED_REM) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `b:int` (LABEL_TAC "balanced")) THEN
  ABBREV_TAC `r = --b:int` THEN
  ABBREV_TAC `A12' = A12 + A11 * r` THEN
  ABBREV_TAC `A22' = A11 * r pow 2 + &2 * A12 * r + A22` THEN
  SUBGOAL_THEN `abs A12' * &2 <= A11` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["A12'"; "r"] THEN
    REMOVE_THEN "balanced" MP_TAC THEN
    REWRITE_TAC[INT_ARITH
      `A12 + A11 * --b = A12 - A11 * b`];
    ALL_TAC] THEN
  SUBGOAL_THEN `A11 * A22' - A12' pow 2 = &5` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["A12'"; "A22'"] THEN
    UNDISCH_TAC `A11 * A22 - A12 pow 2 = &5` THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
