    ALL_TAC] THEN
  SUBGOAL_THEN `A22' < A11` ASSUME_TAC THENL
   [SUBGOAL_THEN `&4 * (A11 * A22') <= &20 + A11 pow 2`
    ASSUME_TAC THENL
