let TERNARY_DISC5_A11_1_GLOBAL = prove
 (`!a12 a13 a22 a23 a33:int.
     &0 < &1 * a22 - a12 pow 2 /\
     &1 * (a22 * a33 - a23 pow 2) -
       a12 * (a12 * a33 - a23 * a13) +
       a13 * (a12 * a23 - a22 * a13) = &5
     ==> ((!n.
             (?x1 x2 x3.
                &1 * x1 pow 2 + a22 * x2 pow 2 + a33 * x3 pow 2 +
                &2 * a12 * x1 * x2 + &2 * a13 * x1 * x3 +
                &2 * a23 * x2 * x3 = n)
             ==> ?u v w:int. u pow 2 + v pow 2 + &5 * w pow 2 = n) \/
          (!n.
             (?x1 x2 x3.
                &1 * x1 pow 2 + a22 * x2 pow 2 + a33 * x3 pow 2 +
                &2 * a12 * x1 * x2 + &2 * a13 * x1 * x3 +
                &2 * a23 * x2 * x3 = n)
             ==> ?u v w:int.
                   u pow 2 + &2 * v pow 2 + &2 * v * w +
                   &3 * w pow 2 = n))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `G11 = a22 - a12 pow 2` THEN
  ABBREV_TAC `G12 = a23 - a12 * a13` THEN
  ABBREV_TAC `G22 = a33 - a13 pow 2` THEN
  SUBGOAL_THEN `&0 < G11` ASSUME_TAC THENL
   [EXPAND_TAC "G11" THEN
    UNDISCH_TAC `&0 < &1 * a22 - a12 pow 2` THEN
    REWRITE_TAC[INT_MUL_LID];
    ALL_TAC] THEN
  SUBGOAL_THEN `G11 * G22 - G12 pow 2 = &5` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["G11"; "G12"; "G22"] THEN
    UNDISCH_TAC
     `&1 * (a22 * a33 - a23 pow 2) -
      a12 * (a12 * a33 - a23 * a13) +
      a13 * (a12 * a23 - a22 * a13) = &5` THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  MP_TAC(SPEC `G11:int` BINARY_DISC5) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`G12:int`; `G22:int`]) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(DISJ_CASES_THEN (LABEL_TAC "class")) THENL
   [DISJ1_TAC; DISJ2_TAC] THEN
  (X_GEN_TAC `n:int` THEN
   DISCH_THEN(X_CHOOSE_THEN `x1:int`
    (X_CHOOSE_THEN `x2:int` (X_CHOOSE_TAC `x3:int`))) THEN
   ABBREV_TAC `L = x1 + a12 * x2 + a13 * x3` THEN
   (REMOVE_THEN "class" (MP_TAC o SPEC `n - L pow 2`) THEN
    ANTS_TAC THENL
     [MAP_EVERY EXISTS_TAC [`x2:int`; `x3:int`] THEN
      MP_TAC(SPECL
       [`&1:int`; `a12:int`; `a13:int`; `a22:int`; `a23:int`; `a33:int`;
        `x1:int`; `x2:int`; `x3:int`] TERNARY_COMPLETE) THEN
      ASM_REWRITE_TAC[INT_MUL_LID] THEN INT_ARITH_TAC;
      ALL_TAC]) THEN
   DISCH_THEN(X_CHOOSE_THEN `v:int`
    (X_CHOOSE_THEN `w:int` (LABEL_TAC "binaryrep"))) THEN
   MAP_EVERY EXISTS_TAC [`L:int`; `v:int`; `w:int`] THEN
   REMOVE_THEN "binaryrep" MP_TAC THEN INT_ARITH_TAC));;

let TERNARY_DISC5_A11_1_SECOND = prove
 (`!a12 a13 a22 a23 a33 q n:int.
     &0 < &1 * a22 - a12 pow 2 /\
     &1 * (a22 * a33 - a23 pow 2) -
       a12 * (a12 * a33 - a23 * a13) +
       a13 * (a12 * a23 - a22 * a13) = &5 /\
     (?x1 x2 x3.
        &1 * x1 pow 2 + a22 * x2 pow 2 + a33 * x3 pow 2 +
        &2 * a12 * x1 * x2 + &2 * a13 * x1 * x3 +
        &2 * a23 * x2 * x3 = &8 * q + &3) /\
     (?x1 x2 x3.
        &1 * x1 pow 2 + a22 * x2 pow 2 + a33 * x3 pow 2 +
        &2 * a12 * x1 * x2 + &2 * a13 * x1 * x3 +
        &2 * a23 * x2 * x3 = n)
     ==> ?u v w:int.
           u pow 2 + &2 * v pow 2 + &2 * v * w + &3 * w pow 2 = n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL
   [`a12:int`; `a13:int`; `a22:int`; `a23:int`; `a33:int`]
   TERNARY_DISC5_A11_1_GLOBAL) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(DISJ_CASES_THEN (LABEL_TAC "class")) THENL
   [REMOVE_THEN "class" (fun th ->
      MP_TAC(MATCH_MP (SPEC `&8 * q + &3` th)
       (ASSUME
        `?x1 x2 x3.
           &1 * x1 pow 2 + a22 * x2 pow 2 + a33 * x3 pow 2 +
           &2 * a12 * x1 * x2 + &2 * a13 * x1 * x3 +
           &2 * a23 * x2 * x3 = &8 * q + &3`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `u:int`
     (X_CHOOSE_THEN `v:int` (X_CHOOSE_TAC `w:int`))) THEN
    MP_TAC(SPECL [`u:int`; `v:int`; `w:int`; `q:int`]
      INT_SQ_SQ_5_NOT_3MOD8) THEN
    ASM_REWRITE_TAC[];
    REMOVE_THEN "class" (fun th ->
      MATCH_ACCEPT_TAC(MATCH_MP (SPEC `n:int` th)
       (ASSUME
        `?x1 x2 x3.
           &1 * x1 pow 2 + a22 * x2 pow 2 + a33 * x3 pow 2 +
           &2 * a12 * x1 * x2 + &2 * a13 * x1 * x3 +
           &2 * a23 * x2 * x3 = n`)))]);;

let REP_125_DOUBLE_OF_T = prove
 (`!n:int.
     (?u v w:int.
        u pow 2 + &2 * v pow 2 + &2 * v * w + &3 * w pow 2 = n)
