    REWRITE_TAC[INT_ENTIRE] THEN INT_ARITH_TAC;
    STRIP_TAC THEN ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING]);;

let DISC5_BLOCK2_FALSE = prove
 (`!l c e f:int.
     l pow 2 = &1 /\
     &2 * (&2 * f - e pow 2) -
       l * (l * f - c * e) + c * (l * e - &2 * c) = &5
     ==> F`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPEC `l:int` INT_SQ_EQ_ONE) THEN ASM_REWRITE_TAC[] THEN
