     `&2 * (&2 * f - e pow 2) -
      l * (l * f - c * e) + c * (l * e - &2 * c) = &5`) THEN
    REWRITE_TAC[ASSUME `l = &1`] THEN CONV_TAC INT_RING;
    MP_TAC(SPECL
     [`&2 * f - c pow 2`; `&2 * e + c`] INT_DISC10_NOT_FIRST3) THEN
    MP_TAC(ASSUME
     `&2 * (&2 * f - e pow 2) -
      l * (l * f - c * e) + c * (l * e - &2 * c) = &5`) THEN
    REWRITE_TAC[ASSUME `l = -- &1`] THEN CONV_TAC INT_RING]);;

let HERMITE_CUBE_DISC5 = prove
 (`!a G:int.
     &0 < a /\ &0 < G /\
     &3 * a pow 2 <= &4 * G /\ &3 * G pow 2 <= &4 * (&5 * a)
     ==> &27 * a pow 3 <= &320`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(&3 * a pow 2) pow 2 <= (&4 * G) pow 2` MP_TAC THENL
   [MATCH_MP_TAC INT_POW_LE2 THEN CONJ_TAC THENL
     [MATCH_MP_TAC INT_LE_MUL THEN REWRITE_TAC[INT_LE_POW_2] THEN
      INT_ARITH_TAC;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[INT_POW_MUL] THEN DISCH_TAC THEN
  MATCH_MP_TAC INT_LE_RCANCEL_IMP THEN EXISTS_TAC `a:int` THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MATCH_MP_TAC INT_LE_TRANS THEN
  EXISTS_TAC `&16 * (&3 * G pow 2)` THEN
  CONJ_TAC THENL
   [MP_TAC
     (ASSUME `&3 pow 2 * a pow 2 pow 2 <= &4 pow 2 * G pow 2`) THEN
    REWRITE_TAC[INT_ARITH `a pow 2 pow 2 = a pow 3 * a`; INT_POW_2] THEN
    INT_ARITH_TAC;
    MP_TAC(ASSUME `&3 * G pow 2 <= &4 * (&5 * a)`) THEN
    INT_ARITH_TAC]);;

let HERMITE_DISC5_LE2 = prove
 (`!b11 b12 b13 b22 b23 b33:int.
     &0 < b11 /\
     b11 * (b22 * b33 - b23 pow 2) -
       b12 * (b12 * b33 - b13 * b23) +
       b13 * (b12 * b23 - b13 * b22) = &5 /\
     &0 < b11 * b22 - b12 pow 2 /\
     (!x y z. ~(x = &0 /\ y = &0 /\ z = &0)
              ==> b11 <= b11 * x pow 2 + b22 * y pow 2 +
                         b33 * z pow 2 + &2 * b12 * x * y +
                         &2 * b13 * x * z + &2 * b23 * y * z)
     ==> b11 = &1 \/ b11 = &2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `G11 = b11 * b22 - b12 pow 2` THEN
  ABBREV_TAC `G12 = b11 * b23 - b12 * b13` THEN
