    MP_TAC(ASSUME
     `&2 * (b22 * b33 - b23 pow 2) -
      b12 * (b12 * b33 - b13 * b23) +
      b13 * (b12 * b23 - b13 * b22) = &5`) THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  MP_TAC(SPEC `&10:int` BINARY_HERMITE_PRIMITIVE) THEN
  CONV_TAC INT_REDUCE_CONV THEN
  DISCH_THEN(MP_TAC o SPEC `G11:int`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`G12:int`; `G22:int`]) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:int`
    (X_CHOOSE_THEN `t:int`
      (CONJUNCTS_THEN2
        (X_CHOOSE_THEN `p:int` (X_CHOOSE_TAC `q:int`))
        ASSUME_TAC))) THEN
  ABBREV_TAC
   `Gst = G11 * s pow 2 + &2 * G12 * s * t + G22 * t pow 2` THEN
  SUBGOAL_THEN `&3 * Gst pow 2 <= &4 * &10` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
