    INT_BALANCED_REM) THEN
  CONV_TAC INT_REDUCE_CONV THEN
  DISCH_THEN(X_CHOOSE_TAC `bb:int`) THEN
  ABBREV_TAC `x1 = --bb:int` THEN
  ABBREV_TAC
   `Fst = &2 * x1 pow 2 + b22 * s pow 2 + b33 * t pow 2 +
          &2 * b12 * x1 * s + &2 * b13 * x1 * t +
          &2 * b23 * s * t` THEN
  ABBREV_TAC `l = &2 * x1 + b12 * s + b13 * t` THEN
  SUBGOAL_THEN `&4 * l pow 2 <= &4` ASSUME_TAC THENL
   [MP_TAC(MATCH_MP SQ_BOUND
     (ASSUME `abs ((b12 * s + b13 * t) - &2 * bb) * &2 <= &2`)) THEN
    MAP_EVERY EXPAND_TAC ["l"; "x1"] THEN
    REWRITE_TAC[INT_ARITH
      `&2 * --bb + b12 * s + b13 * t =
       (b12 * s + b13 * t) - &2 * bb`] THEN
    INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `&2 <= Fst` ASSUME_TAC THENL
   [EXPAND_TAC "Fst" THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
    DISCH_TAC THEN UNDISCH_TAC `s * p + t * q = &1` THEN
    ASM_REWRITE_TAC[] THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `&2 * Fst = l pow 2 + Gst` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["Fst"; "l"; "Gst"; "G11"; "G12"; "G22"] THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN `&3 <= Gst` ASSUME_TAC THENL
   [UNDISCH_TAC `&2 <= Fst` THEN
    UNDISCH_TAC `&4 * l pow 2 <= &4` THEN
    UNDISCH_TAC `&2 * Fst = l pow 2 + Gst` THEN
    MP_TAC(SPEC `l:int` INT_LE_POW_2) THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `Gst <= &3` ASSUME_TAC THENL
   [ASM_CASES_TAC `Gst <= &3` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `&16 <= Gst pow 2` ASSUME_TAC THENL
     [MP_TAC(SPECL [`2`; `&4:int`; `Gst:int`] INT_POW_LE2) THEN
      ANTS_TAC THENL [ASM_INT_ARITH_TAC; CONV_TAC INT_REDUCE_CONV];
      UNDISCH_TAC `&3 * Gst pow 2 <= &4 * &10` THEN
