  (LABEL_TAC "lsqcases") THENL
   [UNDISCH_TAC `&4 * l pow 2 <= &4` THEN
    MP_TAC(SPEC `l:int` INT_LE_POW_2) THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `Fst = &2 /\ l pow 2 = &1` STRIP_ASSUME_TAC THENL
   [REMOVE_THEN "lsqcases" (DISJ_CASES_THEN ASSUME_TAC) THEN
    UNDISCH_TAC `&2 <= Fst` THEN
    UNDISCH_TAC `&2 * Fst = l pow 2 + Gst` THEN
    ASM_REWRITE_TAC[] THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`x1:int`; `s:int`; `t:int`] THEN
  REPEAT CONJ_TAC THENL
   [MAP_EVERY EXISTS_TAC [`p:int`; `q:int`] THEN ASM_REWRITE_TAC[];
    EXPAND_TAC "Fst" THEN ASM_REWRITE_TAC[];
    EXPAND_TAC "l" THEN ASM_REWRITE_TAC[];
    EXPAND_TAC "Gst" THEN
    MAP_EVERY EXPAND_TAC ["G11"; "G12"; "G22"] THEN
    ASM_REWRITE_TAC[]]);;

let DISC5_MIN2_EXCLUDED = prove
 (`!b12 b13 b22 b23 b33:int.
     &2 * (b22 * b33 - b23 pow 2) -
       b12 * (b12 * b33 - b13 * b23) +
       b13 * (b12 * b23 - b13 * b22) = &5 /\
     &0 < &2 * b22 - b12 pow 2 /\
     (!x y z. ~(x = &0 /\ y = &0 /\ z = &0)
              ==> &2 <= &2 * x pow 2 + b22 * y pow 2 +
                         b33 * z pow 2 + &2 * b12 * x * y +
                         &2 * b13 * x * z + &2 * b23 * y * z)
     ==> F`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL
   [`b12:int`; `b13:int`; `b22:int`; `b23:int`; `b33:int`]
   HERMITE_DISC5_MIN2_PAIR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `r:int`
    (X_CHOOSE_THEN `s:int`
      (X_CHOOSE_THEN `t:int`
        (CONJUNCTS_THEN2
          (X_CHOOSE_THEN `p:int` (X_CHOOSE_TAC `q:int`))
          STRIP_ASSUME_TAC)))) THEN
  ABBREV_TAC `l = &2 * r + b12 * s + b13 * t` THEN
  ABBREV_TAC
   `d = &2 * r pow 2 + b22 * s pow 2 + b33 * t pow 2 +
        &2 * b12 * r * s + &2 * b13 * r * t +
        &2 * b23 * s * t` THEN
  ABBREV_TAC `c = --(b12 * q) + b13 * p` THEN
  ABBREV_TAC
   `e = --(b12 * r * q) + b13 * r * p - b22 * s * q +
        b23 * s * p - b23 * t * q + b33 * t * p` THEN
  ABBREV_TAC
   `f = b22 * q pow 2 + b33 * p pow 2 - &2 * b23 * p * q` THEN
  SUBGOAL_THEN `d = &2 /\ l pow 2 = &1` STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["d"; "l"] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&2 * (d * f - e pow 2) -
    l * (l * f - c * e) + c * (l * e - d * c) = &5`
  ASSUME_TAC THENL
   [TRANS_TAC EQ_TRANS
     `(&2 * (b22 * b33 - b23 pow 2) -
       b12 * (b12 * b33 - b13 * b23) +
       b13 * (b12 * b23 - b13 * b22)) *
      (s * p + t * q) pow 2` THEN
    CONJ_TAC THENL
     [REWRITE_TAC
       [GSYM(ASSUME `&2 * r + b12 * s + b13 * t = l`);
        GSYM(ASSUME
         `&2 * r pow 2 + b22 * s pow 2 + b33 * t pow 2 +
          &2 * b12 * r * s + &2 * b13 * r * t +
          &2 * b23 * s * t = d`);
        GSYM(ASSUME `--(b12 * q) + b13 * p = c`);
        GSYM(ASSUME
         `--(b12 * r * q) + b13 * r * p - b22 * s * q +
          b23 * s * p - b23 * t * q + b33 * t * p = e`);
        GSYM(ASSUME
         `b22 * q pow 2 + b33 * p pow 2 - &2 * b23 * p * q = f`)] THEN
      CONV_TAC INT_RING;
      ASM_REWRITE_TAC[] THEN CONV_TAC INT_REDUCE_CONV];
    ALL_TAC] THEN
  MATCH_MP_TAC(SPECL [`l:int`; `c:int`; `e:int`; `f:int`]
    DISC5_BLOCK2_FALSE) THEN
  CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    UNDISCH_TAC
     `&2 * (d * f - e pow 2) -
      l * (l * f - c * e) + c * (l * e - d * c) = &5` THEN
    REWRITE_TAC[ASSUME `d = &2`]]);;

