 (`!a j beta:num.
     1 <= a /\ beta = 8*a*(20*j+1)-5
     ==> (beta == 5*((20*j+1)-1)) (mod (20*j+1))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `5*((20*j+1)-1) = 5*(20*j+1)-5`
  SUBST1_TAC THENL
   [ARITH_TAC;
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC CONG_SUB THEN
    REPEAT CONJ_TAC THENL
     [NUMBER_TAC;
      REWRITE_TAC[CONG_REFL];
      ASM_ARITH_TAC;
      ARITH_TAC]]);;

let JACOBI_BETA_20J1 = prove
 (`!a j beta:num.
     1 <= a /\ beta = 8*a*(20*j+1)-5
     ==> jacobi(beta,20*j+1) = &1`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(20*j+1 == 1) (mod 4)` ASSUME_TAC THENL
   [NUMBER_TAC;
    ALL_TAC] THEN
  TRANS_TAC EQ_TRANS `jacobi(5*((20*j+1)-1),20*j+1)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC JACOBI_CONG THEN
    MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
      CONG_BETA_NEG5_125_DOUBLE) THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[JACOBI_LMUL; JACOBI_5_20J1] THEN
    ASM_SIMP_TAC[JACOBI_M1_1MOD4] THEN CONV_TAC INT_REDUCE_CONV]);;

let COPRIME_BETA_20J1 = prove
 (`!a j beta:num.
     1 <= a /\ beta = 8*a*(20*j+1)-5
     ==> coprime(beta,20*j+1)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `jacobi(beta,20*j+1) = &1` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
      JACOBI_BETA_20J1) THEN
    ASM_REWRITE_TAC[];
    MP_TAC(SPECL [`beta:num`; `20*j+1`] JACOBI_EQ_0) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_REDUCE_CONV]);;

let CONG_BETA_3MOD8_125_DOUBLE = prove
 (`!a j beta:num.
     1 <= a /\ beta = 8*a*(20*j+1)-5
     ==> (beta == 3) (mod 8)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `beta = (a*(20*j+1)-1)*8+3`
  SUBST1_TAC THENL
   [ASM_ARITH_TAC;
    REWRITE_TAC[CONG] THEN SIMP_TAC[MOD_MULT_ADD] THEN
    CONV_TAC NUM_REDUCE_CONV]);;

let JACOBI_K_BETA_125_DOUBLE = prove
 (`!a j beta:num.
     1 <= a /\ beta = 8*a*(20*j+1)-5
     ==> jacobi(20*j+1,beta) = &1`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(beta == 3) (mod 8)` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
      CONG_BETA_3MOD8_125_DOUBLE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(beta == 3) (mod 4)` ASSUME_TAC THENL
   [MATCH_MP_TAC CONG_MOD_8_IMP_MOD_4 THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `ODD beta` ASSUME_TAC THENL
   [MATCH_MP_TAC ODD_OF_3MOD4 THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `jacobi(beta,20*j+1) = &1` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
      JACOBI_BETA_20J1) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `coprime(beta,20*j+1)` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
      COPRIME_BETA_20J1) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `coprime(20*j+1,beta)` ASSUME_TAC THENL
   [ONCE_REWRITE_TAC[COPRIME_SYM] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`20*j+1`; `beta:num`] JACOBI_FLIP_1MOD4) THEN
  ASM_REWRITE_TAC[ODD_ADD; ODD_MULT; ARITH] THEN
  ANTS_TAC THENL [NUMBER_TAC; INT_ARITH_TAC]);;

let JACOBI_NEG8K_BETA_125_DOUBLE = prove
 (`!a j beta:num.
     1 <= a /\ beta = 8*a*(20*j+1)-5
     ==> jacobi((8*(20*j+1))*(beta-1),beta) = &1`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(beta == 3) (mod 8)` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
      CONG_BETA_3MOD8_125_DOUBLE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(beta == 3) (mod 4)` ASSUME_TAC THENL
   [MATCH_MP_TAC CONG_MOD_8_IMP_MOD_4 THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `jacobi(20*j+1,beta) = &1` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
      JACOBI_K_BETA_125_DOUBLE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `jacobi(8,beta) = -- &1` ASSUME_TAC THENL
   [REWRITE_TAC[ARITH_RULE `8 = 2 EXP 3`; JACOBI_LEXP] THEN
    ASM_SIMP_TAC[JACOBI_2_3MOD8] THEN CONV_TAC INT_REDUCE_CONV;
    ALL_TAC] THEN
  REWRITE_TAC[ARITH_RULE
   `(8*k)*(beta-1) = 2*2*2*k*(beta-1)`; JACOBI_LMUL] THEN
  ASM_SIMP_TAC[JACOBI_2_3MOD8; JACOBI_M1_3MOD4] THEN
  CONV_TAC INT_REDUCE_CONV);;

let QR_125_DOUBLE = prove
 (`!a j beta:num.
     1 <= a /\ prime beta /\ beta = 8*a*(20*j+1)-5
     ==> ?t. (t EXP 2 + 8*(20*j+1) == 0) (mod beta)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC JACOBI_NEGATIVE_SQUARE THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
    JACOBI_NEG8K_BETA_125_DOUBLE) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Dirichlet progression beta = 8 a (20j+1) - 5.                           *)
(* ------------------------------------------------------------------------- *)

let COPRIME_125_DOUBLE_OFFSET_A = prove
 (`!a:num.
     1 <= a /\ ~(5 divides a)
     ==> coprime(8*a-5,a)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `coprime(5,a)` ASSUME_TAC THENL
   [MP_TAC(MATCH_MP (SPECL [`5`; `a:num`] PRIME_COPRIME_EQ)
      (EQT_ELIM(PRIME_CONV `prime 5`))) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[COPRIME] THEN X_GEN_TAC `d:num` THEN EQ_TAC THENL
   [STRIP_TAC THEN
    SUBGOAL_THEN `d divides 8*a` ASSUME_TAC THENL
     [MATCH_MP_TAC(SPECL [`d:num`; `a:num`; `8`] DIVIDES_LMUL) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `d divides 5` ASSUME_TAC THENL
     [SUBGOAL_THEN `5 = 8*a - (8*a-5)` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        MATCH_MP_TAC(SPECL [`d:num`; `8*a`; `8*a-5`] DIVIDES_SUB) THEN
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    MP_TAC(SPEC `d:num`
      (REWRITE_RULE[COPRIME] (ASSUME `coprime(5,a)`))) THEN
    ASM_REWRITE_TAC[];
    DISCH_TAC THEN ASM_REWRITE_TAC[DIVIDES_1]]);;

let COPRIME_125_DOUBLE_OFFSET_160 = prove
 (`!a:num.
     1 <= a /\ ~(5 divides a)
     ==> coprime(8*a-5,160)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `ODD(8*a-5)` ASSUME_TAC THENL
   [REWRITE_TAC[ODD_EXISTS] THEN EXISTS_TAC `4*a-3` THEN
    ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~(5 divides (8*a-5))` ASSUME_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `5 divides 8*a` ASSUME_TAC THENL
     [SUBGOAL_THEN `8*a = (8*a-5)+5` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        MATCH_MP_TAC DIVIDES_ADD THEN ASM_REWRITE_TAC[DIVIDES_REFL]];
      ALL_TAC] THEN
    MP_TAC(ASSUME `5 divides 8*a`) THEN
    REWRITE_TAC[MATCH_MP (SPEC `5` PRIME_DIVPROD_EQ)
      (EQT_ELIM(PRIME_CONV `prime 5`))] THEN
    ASM_REWRITE_TAC[] THEN
    CONV_TAC(RAND_CONV DIVIDES_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[ARITH_RULE `160 = 2*2*2*2*2*5`; COPRIME_RMUL] THEN
  ASM_REWRITE_TAC[CONJUNCT2 COPRIME_2] THEN
  ONCE_REWRITE_TAC[COPRIME_SYM] THEN
  ASM_REWRITE_TAC[MATCH_MP (SPEC `5` PRIME_COPRIME_EQ)
    (EQT_ELIM(PRIME_CONV `prime 5`))]);;

let COPRIME_DIRICHLET_125_DOUBLE = prove
 (`!a:num.
     1 <= a /\ ~(5 divides a)
     ==> coprime(8*a-5,160*a)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[COPRIME_RMUL] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC COPRIME_125_DOUBLE_OFFSET_160 THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC COPRIME_125_DOUBLE_OFFSET_A THEN ASM_REWRITE_TAC[]]);;

let DIRICHLET_PRIME_125_DOUBLE = prove
 (`!a:num.
     1 <= a /\ ~(5 divides a)
     ==> ?p. prime p /\ (p == 8*a-5) (mod (160*a))`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC DIRICHLET_PRIME_CONG THEN
  ASM_SIMP_TAC[COPRIME_DIRICHLET_125_DOUBLE] THEN ASM_ARITH_TAC);;

let RESIDUE_125_DOUBLE = prove
 (`!a:num.
     1 <= a /\ ~(5 divides a)
     ==> ?j t.
           (8*a*(20*j+1)-5) divides
           (t EXP 2 + 8*(20*j+1))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPEC `a:num` DIRICHLET_PRIME_125_DOUBLE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `beta:num` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `?j. beta = 160*a*j + (8*a-5)`
  (X_CHOOSE_TAC `j:num`) THENL
   [MP_TAC(SPECL [`160*a`; `8*a-5`; `beta:num`] CONG_CASE) THEN
    ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MONO_EXISTS THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `beta = 8*a*(20*j+1)-5`
  ASSUME_TAC THENL
   [UNDISCH_TAC `beta = 160*a*j + (8*a-5)` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
   (SPECL [`a:num`; `j:num`; `beta:num`] QR_125_DOUBLE)
   (CONJ (ASSUME `1 <= a`)
    (CONJ (ASSUME `prime beta`)
          (ASSUME `beta = 8*a*(20*j+1)-5`)))) THEN
  DISCH_THEN(X_CHOOSE_TAC `t:num`) THEN
  MAP_EVERY EXISTS_TAC [`j:num`; `t:num`] THEN
  ONCE_REWRITE_TAC[GSYM
    (ASSUME `beta = 8*a*(20*j+1)-5`)] THEN
  MP_TAC(ASSUME
   `(t EXP 2 + 8*(20*j+1) == 0) (mod beta)`) THEN
  REWRITE_TAC[CONG_0_DIVIDES]);;

let REGULAR_125_DOUBLE_COPRIME5 = prove
 (`!a:num.
     1 <= a /\ ~(5 divides a)
     ==> ?u v w:int.
           u pow 2 + &2*v pow 2 + &5*w pow 2 = &2 * &a`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPEC `a:num` RESIDUE_125_DOUBLE) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `j:num` (X_CHOOSE_TAC `t:num`)) THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `h:num` o REWRITE_RULE[divides]) THEN
  SUBGOAL_THEN `5 <= 8*a*(20*j+1)` ASSUME_TAC THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(SPECL
   [`&a:int`; `&(20*j+1):int`; `&(8*a*(20*j+1)-5):int`;
    `&t:int`; `&h:int`] LEMMA_125_DOUBLE) THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[INT_OF_NUM_LT] THEN ASM_ARITH_TAC;
    REWRITE_TAC[INT_OF_NUM_LT] THEN ASM_ARITH_TAC;
    ASM_SIMP_TAC[INT_OF_NUM_SUB; INT_OF_NUM_MUL; INT_OF_NUM_ADD] THEN
    CONV_TAC INT_RING;
    FIRST_X_ASSUM(MP_TAC o AP_TERM `int_of_num`) THEN
    ASM_SIMP_TAC
     [INT_OF_NUM_SUB; INT_OF_NUM_ADD; INT_OF_NUM_MUL;
      INT_OF_NUM_POW]]);;

let LEMMA_125_T_FIVE = prove
 (`!a t beta r c s:int.
     &0 < a /\ &0 < beta /\
     beta = &8 * t * a - &5 /\
     (&5 * a) * (beta * c - r pow 2) - beta * s pow 2 = &5
     ==> ?u v w:int.
           u pow 2 + &2 * v pow 2 + &2 * v * w + &3 * w pow 2 =
           &5 * a`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC TERNARY_DISC5_SECOND THEN
  MAP_EVERY EXISTS_TAC
   [`&5 * a:int`; `&0:int`; `s:int`; `beta:int`; `r:int`; `c:int`;
    `t * a - &1:int`] THEN
  REPEAT CONJ_TAC THENL
   [ASM_INT_ARITH_TAC;
    REWRITE_TAC[INT_POW_2; INT_MUL_LZERO; INT_SUB_RZERO] THEN
    MATCH_MP_TAC INT_LT_MUL THEN ASM_INT_ARITH_TAC;
    UNDISCH_TAC
     `(&5 * a) * (beta * c - r pow 2) - beta * s pow 2 = &5` THEN
    CONV_TAC INT_RING;
    MAP_EVERY EXISTS_TAC [`&0:int`; `&1:int`; `&0:int`] THEN
    UNDISCH_TAC `beta = &8 * t * a - &5` THEN CONV_TAC INT_RING;
    MAP_EVERY EXISTS_TAC [`&1:int`; `&0:int`; `&0:int`] THEN
    CONV_TAC INT_RING]);;

let LEMMA_125_T_FIVE_PLUS = prove
 (`!a t beta r p c:int.
     &0 < a /\ &0 < beta /\
     beta = &8 * t * a - &5 /\
     beta * p = &8 * t + &5 * r pow 2 /\
     &5 * c = p + &4 * a + &4
     ==> ?u v w:int.
           u pow 2 + &2 * v pow 2 + &2 * v * w + &3 * w pow 2 =
           &5 * a`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC(SPECL
   [`a:int`; `t:int`; `beta:int`; `r:int`; `c:int`;
    `&1 + &2 * a:int`] LEMMA_125_T_FIVE) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY UNDISCH_TAC
   [`beta = &8 * t * a - &5`;
    `beta * p = &8 * t + &5 * r pow 2`;
    `&5 * c = p + &4 * a + &4`] THEN
  CONV_TAC INT_RING);;

let LEMMA_125_T_FIVE_MINUS = prove
 (`!a t beta r p c:int.
     &0 < a /\ &0 < beta /\
     beta = &8 * t * a - &5 /\
     beta * p = &8 * t + &5 * r pow 2 /\
     &5 * c = p + &4 * a - &4
     ==> ?u v w:int.
           u pow 2 + &2 * v pow 2 + &2 * v * w + &3 * w pow 2 =
           &5 * a`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC(SPECL
   [`a:int`; `t:int`; `beta:int`; `r:int`; `c:int`;
    `&1 - &2 * a:int`] LEMMA_125_T_FIVE) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY UNDISCH_TAC
   [`beta = &8 * t * a - &5`;
    `beta * p = &8 * t + &5 * r pow 2`;
    `&5 * c = p + &4 * a - &4`] THEN
  CONV_TAC INT_RING);;

let JACOBI_4_5 = prove
 (`jacobi(4,5) = &1`,
  REWRITE_TAC[ARITH_RULE `4 = 2 EXP 2`; CONJUNCT1 JACOBI_SQUARED] THEN
  SUBGOAL_THEN `coprime(2,5)` ASSUME_TAC THENL
   [REWRITE_TAC[COPRIME_BEZOUT] THEN
    MAP_EVERY EXISTS_TAC [`3`; `1`] THEN DISJ1_TAC THEN ARITH_TAC;
    ASM_REWRITE_TAC[]]);;

let CONG_2_MOD_5_CASE = prove
 (`!a:num. (a == 2) (mod 5) ==> ?q. a = 5*q+2`,
  MESON_TAC[CONG_CASE; MULT_SYM; ARITH_RULE `2 < 5`]);;

let CONG_3_MOD_5_CASE = prove
 (`!a:num. (a == 3) (mod 5) ==> ?q. a = 5*q+3`,
  MESON_TAC[CONG_CASE; MULT_SYM; ARITH_RULE `3 < 5`]);;

let CONG_BETA_1MOD5_125_FIVE = prove
 (`!a j beta:num.
     (a == 2) (mod 5) /\ beta = 8*a*(20*j+1)-5
     ==> (beta == 1) (mod 5)`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `q:num` o MATCH_MP CONG_2_MOD_5_CASE) THEN
  SUBGOAL_THEN
   `beta = 5*(160*q*j+8*q+64*j+2)+1`
  SUBST1_TAC THENL
   [ASM_REWRITE_TAC[] THEN ARITH_TAC;
    REWRITE_TAC[CONG] THEN SIMP_TAC[MOD_MULT_ADD] THEN
    CONV_TAC NUM_REDUCE_CONV]);;

let CONG_BETA_4MOD5_125_FIVE = prove
 (`!a j beta:num.
     (a == 3) (mod 5) /\ beta = 8*a*(20*j+1)-5
     ==> (beta == 4) (mod 5)`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `q:num` o MATCH_MP CONG_3_MOD_5_CASE) THEN
  SUBGOAL_THEN
   `beta = 5*(160*q*j+8*q+96*j+3)+4`
  SUBST1_TAC THENL
   [ASM_REWRITE_TAC[] THEN ARITH_TAC;
    REWRITE_TAC[CONG] THEN SIMP_TAC[MOD_MULT_ADD] THEN
    CONV_TAC NUM_REDUCE_CONV]);;

let JACOBI_BETA_5_125_FIVE_PLUS = prove
 (`!a j beta:num.
     (a == 2) (mod 5) /\
     beta = 8*a*(20*j+1)-5
     ==> jacobi(beta,5) = &1`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(beta == 1) (mod 5)` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
      CONG_BETA_1MOD5_125_FIVE) THEN
    ASM_REWRITE_TAC[];
    MP_TAC(SPECL [`beta:num`; `1`; `5`] JACOBI_CONG) THEN
    ASM_REWRITE_TAC[JACOBI_1]]);;

let JACOBI_BETA_5_125_FIVE_MINUS = prove
 (`!a j beta:num.
     (a == 3) (mod 5) /\
     beta = 8*a*(20*j+1)-5
     ==> jacobi(beta,5) = &1`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(beta == 4) (mod 5)` ASSUME_TAC THENL
