let JACOBI_BETA_5_125_FIVE = prove
 (`!a j beta:num.
     1 <= a /\
     ((a == 2) (mod 5) \/ (a == 3) (mod 5)) /\
     beta = 8*a*(20*j+1)-5
     ==> jacobi(beta,5) = &1`,
