   [JACOBI_BETA_5_125_FIVE_PLUS; JACOBI_BETA_5_125_FIVE_MINUS]);;

let JACOBI_5_BETA_OF_3MOD8 = prove
 (`!beta:num.
     (beta == 3) (mod 8) /\ jacobi(beta,5) = &1
     ==> jacobi(5,beta) = &1`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(beta == 3) (mod 4)` ASSUME_TAC THENL
   [MATCH_MP_TAC CONG_MOD_8_IMP_MOD_4 THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `ODD beta` ASSUME_TAC THENL
   [MATCH_MP_TAC ODD_OF_3MOD4 THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `coprime(beta,5)` ASSUME_TAC THENL
   [ASM_CASES_TAC `coprime(beta,5)` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`beta:num`; `5`] JACOBI_EQ_0) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN `coprime(5,beta)` ASSUME_TAC THENL
   [ONCE_REWRITE_TAC[COPRIME_SYM] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`5`; `beta:num`] JACOBI_FLIP_1MOD4) THEN
  ASM_REWRITE_TAC[NUM_REDUCE_CONV `ODD 5`] THEN
  ANTS_TAC THENL [NUMBER_TAC; INT_ARITH_TAC]);;

let JACOBI_5_BETA_125_FIVE = prove
 (`!a j beta:num.
     1 <= a /\
     ((a == 2) (mod 5) \/ (a == 3) (mod 5)) /\
     beta = 8*a*(20*j+1)-5
     ==> jacobi(5,beta) = &1`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC JACOBI_5_BETA_OF_3MOD8 THEN CONJ_TAC THENL
   [MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
      CONG_BETA_3MOD8_125_DOUBLE) THEN
    ASM_MESON_TAC[];
    MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
      JACOBI_BETA_5_125_FIVE) THEN
    ASM_MESON_TAC[]]);;

let JACOBI_NEG40_OF_3MOD8 = prove
 (`!t beta:num.
     (beta == 3) (mod 8) /\
     jacobi(t,beta) = &1 /\
     jacobi(5,beta) = &1
     ==> jacobi((40*t)*(beta-1),beta) = &1`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(beta == 3) (mod 4)` ASSUME_TAC THENL
   [MATCH_MP_TAC CONG_MOD_8_IMP_MOD_4 THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `jacobi(8,beta) = -- &1` ASSUME_TAC THENL
   [REWRITE_TAC[ARITH_RULE `8 = 2 EXP 3`; JACOBI_LEXP] THEN
    ASM_SIMP_TAC[JACOBI_2_3MOD8] THEN CONV_TAC INT_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN `jacobi(40,beta) = -- &1` ASSUME_TAC THENL
   [MP_TAC(CONV_RULE
      (LAND_CONV (RAND_CONV (LAND_CONV NUM_REDUCE_CONV)))
      (SPECL [`5`; `8`; `beta:num`] JACOBI_LMUL)) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_REDUCE_CONV;
    ALL_TAC] THEN
  REWRITE_TAC[JACOBI_LMUL] THEN
  ASM_SIMP_TAC[JACOBI_M1_3MOD4] THEN CONV_TAC INT_REDUCE_CONV);;

let JACOBI_NEG40T_BETA_125_FIVE = prove
 (`!a j beta:num.
