    MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
      JACOBI_K_BETA_125_DOUBLE) THEN
    ASM_MESON_TAC[];
    MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
      JACOBI_5_BETA_125_FIVE) THEN
