    JACOBI_NEG40T_BETA_125_FIVE) THEN
  ASM_MESON_TAC[]);;

let COPRIME_5_2 = prove
 (`coprime(5,2)`,
  REWRITE_TAC[COPRIME_BEZOUT] THEN
