    (EQT_ELIM(PRIME_CONV `prime 5`))) THEN
  ASM_SIMP_TAC[COPRIME_5_OF_CONG_2_OR_3]);;

let COPRIME_5_BETA_125_FIVE = prove
 (`!a j beta:num.
     1 <= a /\
     ((a == 2) (mod 5) \/ (a == 3) (mod 5)) /\
     beta = 8*a*(20*j+1)-5
     ==> coprime(5,beta)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
