      JACOBI_BETA_5_125_FIVE) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `coprime(beta,5)` ASSUME_TAC THENL
   [ASM_CASES_TAC `coprime(beta,5)` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`beta:num`; `5`] JACOBI_EQ_0) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_REDUCE_CONV;
    ALL_TAC] THEN
  ONCE_REWRITE_TAC[COPRIME_SYM] THEN ASM_REWRITE_TAC[]);;

let DICKSON_RESIDUE_LIFT_125_FIVE = prove
 (`!t beta:num.
     coprime(5,beta) /\
     (?x. (x EXP 2 + 40*t == 0) (mod beta))
     ==> ?r p. beta*p = 8*t + 5*r EXP 2`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_TAC `x:num`)) THEN
  MP_TAC(SPECL [`5`; `x:num`; `beta:num`] CONG_SOLVE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `r:num`) THEN
  SUBGOAL_THEN
   `((5*r) EXP 2 + 40*t == 0) (mod beta)`
  ASSUME_TAC THENL
   [MATCH_MP_TAC CONG_TRANS THEN EXISTS_TAC `x EXP 2 + 40*t` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC CONG_ADD THEN CONJ_TAC THENL
       [MATCH_MP_TAC CONG_EXP THEN ASM_REWRITE_TAC[];
        REWRITE_TAC[CONG_REFL]];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(5*(8*t+5*r EXP 2) == 5*0) (mod beta)`
  ASSUME_TAC THENL
   [REWRITE_TAC
     [ARITH_RULE `5*(8*t+5*r EXP 2) = (5*r) EXP 2 + 40*t`;
      MULT_CLAUSES] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(8*t+5*r EXP 2 == 0) (mod beta)` ASSUME_TAC THENL
   [MP_TAC(MATCH_MP
      (SPECL [`5`; `beta:num`; `8*t+5*r EXP 2`; `0`]
        CONG_MULT_LCANCEL_EQ)
      (ASSUME `coprime(5,beta)`)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ASSUME `(8*t+5*r EXP 2 == 0) (mod beta)`) THEN
  REWRITE_TAC[CONG_0_DIVIDES; divides] THEN
  DISCH_THEN(X_CHOOSE_TAC `p:num`) THEN
  MAP_EVERY EXISTS_TAC [`r:num`; `p:num`] THEN ASM_ARITH_TAC);;

let CONG_DICKSON_RHS_3 = prove
 (`!j r:num.
     (8*(20*j+1) + 5*r EXP 2 == 3) (mod 5)`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
   `8*(20*j+1) + 5*r EXP 2 = 5*(32*j+r EXP 2+1)+3`
  SUBST1_TAC THENL
   [ARITH_TAC;
    REWRITE_TAC[CONG] THEN SIMP_TAC[MOD_MULT_ADD] THEN
    CONV_TAC NUM_REDUCE_CONV]);;

let CONG_DICKSON_P_3 = prove
 (`!a j beta r p:num.
     (a == 2) (mod 5) /\
     beta = 8*a*(20*j+1)-5 /\
     beta*p = 8*(20*j+1) + 5*r EXP 2
     ==> (p == 3) (mod 5)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(beta == 1) (mod 5)` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
      CONG_BETA_1MOD5_125_FIVE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(beta*p == 1*p) (mod 5)` MP_TAC THENL
   [MATCH_MP_TAC CONG_MULT THEN
    CONJ_TAC THENL
     [ACCEPT_TAC(ASSUME `(beta == 1) (mod 5)`);
      REWRITE_TAC[CONG_REFL]];
    REWRITE_TAC[MULT_CLAUSES] THEN DISCH_TAC] THEN
  SUBGOAL_THEN `(beta*p == 3) (mod 5)` ASSUME_TAC THENL
   [ONCE_REWRITE_TAC
     [ASSUME `beta*p = 8*(20*j+1) + 5*r EXP 2`] THEN
    REWRITE_TAC[CONG_DICKSON_RHS_3];
    ALL_TAC] THEN
  MATCH_MP_TAC CONG_TRANS THEN EXISTS_TAC `(beta:num)*p` THEN
  CONJ_TAC THENL
   [ONCE_REWRITE_TAC[CONG_SYM] THEN
    ACCEPT_TAC(ASSUME `(beta*p == p) (mod 5)`);
    ACCEPT_TAC(ASSUME `(beta*p == 3) (mod 5)`)]);;

let CONG_DICKSON_P_2 = prove
 (`!a j beta r p:num.
     (a == 3) (mod 5) /\
     beta = 8*a*(20*j+1)-5 /\
     beta*p = 8*(20*j+1) + 5*r EXP 2
