    ALL_TAC] THEN
  SUBGOAL_THEN `(4*(4*p) == 4*3) (mod 5)` ASSUME_TAC THENL
   [MATCH_MP_TAC CONG_MULT THEN CONJ_TAC THENL
     [REWRITE_TAC[CONG_REFL];
      ACCEPT_TAC(ASSUME `(4*p == 3) (mod 5)`)];
    ALL_TAC] THEN
  MATCH_MP_TAC CONG_TRANS THEN EXISTS_TAC `4*(4*(p:num))` THEN
  CONJ_TAC THENL
   [SUBGOAL_THEN `4*(4*p) = 5*(3*p)+p` SUBST1_TAC THENL
     [ARITH_TAC;
      REWRITE_TAC[CONG] THEN SIMP_TAC[MOD_MULT_ADD]];
    MATCH_MP_TAC CONG_TRANS THEN EXISTS_TAC `4*3:num` THEN
    CONJ_TAC THENL
     [ACCEPT_TAC(ASSUME `(4*(4*p) == 4*3) (mod 5)`);
      REWRITE_TAC[CONG] THEN CONV_TAC NUM_REDUCE_CONV]]);;

let DICKSON_DATA_125_T_FIVE = prove
 (`!a:num.
     1 <= a /\ ((a == 2) (mod 5) \/ (a == 3) (mod 5))
     ==> ?j beta r p.
           prime beta /\
           beta = 8*a*(20*j+1)-5 /\
           beta*p = 8*(20*j+1) + 5*r EXP 2`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `~(5 divides a)` ASSUME_TAC THENL
   [MATCH_MP_TAC NOT_DIVIDES_5_OF_CONG_2_OR_3 THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPEC `a:num` DIRICHLET_PRIME_125_DOUBLE) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `beta:num` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `?j. beta = 160*a*j + (8*a-5)`
  (X_CHOOSE_TAC `j:num`) THENL
   [MP_TAC(SPECL [`160*a`; `8*a-5`; `beta:num`] CONG_CASE) THEN
    ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MONO_EXISTS THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `beta = 8*a*(20*j+1)-5` ASSUME_TAC THENL
   [UNDISCH_TAC `beta = 160*a*j + (8*a-5)` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?x. (x EXP 2 + 40*(20*j+1) == 0) (mod beta)`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`] QR_125_T_FIVE) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `coprime(5,beta)` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
      COPRIME_5_BETA_125_FIVE) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`20*j+1`; `beta:num`] DICKSON_RESIDUE_LIFT_125_FIVE) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      EXISTS_TAC `x:num` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `r:num` (X_CHOOSE_TAC `p:num`)) THEN
  MAP_EVERY EXISTS_TAC [`j:num`; `beta:num`; `r:num`; `p:num`] THEN
  REPEAT CONJ_TAC THENL
   [ACCEPT_TAC(ASSUME `prime beta`);
    ACCEPT_TAC(ASSUME `beta = 8*a*(20*j+1)-5`);
    ACCEPT_TAC
     (ASSUME `beta*p = 8*(20*j+1) + 5*r EXP 2`)]);;

