let DICKSON_ODD_RESIDUE_LIFT_125_G_FIVE = prove
 (`!t beta:num.
     ODD beta /\ coprime(10,beta) /\
     (?x. (x EXP 2 + 80*t == 0) (mod beta))
     ==> ?r p. ODD r /\ beta*p = 8*t + 10*r EXP 2`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_TAC `x:num`))) THEN
  MP_TAC(SPECL [`10`; `x:num`; `beta:num`] CONG_SOLVE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `r0:num`) THEN
  SUBGOAL_THEN
   `?r:num. ODD r /\ (10*r == x) (mod beta)`
  (X_CHOOSE_THEN `r:num` STRIP_ASSUME_TAC) THENL
   [ASM_CASES_TAC `ODD r0` THENL
     [EXISTS_TAC `r0:num` THEN ASM_REWRITE_TAC[];
      EXISTS_TAC `r0+beta:num` THEN CONJ_TAC THENL
       [ASM_REWRITE_TAC[ODD_ADD];
        MATCH_MP_TAC CONG_TRANS THEN EXISTS_TAC `10*r0:num` THEN
        CONJ_TAC THENL
         [NUMBER_TAC;
          ASM_REWRITE_TAC[]]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((10*r) EXP 2 + 80*t == 0) (mod beta)`
  ASSUME_TAC THENL
   [MATCH_MP_TAC CONG_TRANS THEN EXISTS_TAC `x EXP 2 + 80*t` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC CONG_ADD THEN CONJ_TAC THENL
       [MATCH_MP_TAC CONG_EXP THEN ASM_REWRITE_TAC[];
        REWRITE_TAC[CONG_REFL]];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(10*(8*t+10*r EXP 2) == 10*0) (mod beta)`
  ASSUME_TAC THENL
   [REWRITE_TAC
     [ARITH_RULE
       `10*(8*t+10*r EXP 2) = (10*r) EXP 2 + 80*t`;
      MULT_CLAUSES] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(8*t+10*r EXP 2 == 0) (mod beta)` ASSUME_TAC THENL
   [MP_TAC(MATCH_MP
      (SPECL [`10`; `beta:num`; `8*t+10*r EXP 2`; `0`]
        CONG_MULT_LCANCEL_EQ)
      (ASSUME `coprime(10,beta)`)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ASSUME `(8*t+10*r EXP 2 == 0) (mod beta)`) THEN
  REWRITE_TAC[CONG_0_DIVIDES; divides] THEN
  DISCH_THEN(X_CHOOSE_TAC `p:num`) THEN
  MAP_EVERY EXISTS_TAC [`r:num`; `p:num`] THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

