    REWRITE_RULE[ODD_EXISTS] o check (fun th -> concl th = `ODD a`)) THEN
  SUBGOAL_THEN `(5*(7*a+c+2) == 5*6) (mod 8)` ASSUME_TAC THENL
   [MATCH_MP_TAC CONG_TRANS THEN EXISTS_TAC `p:num` THEN
