        CONG_MULT_LCANCEL_EQ)
      (EQT_ELIM(COPRIME_CONV `coprime(5,8)`))) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(7*a+c+2) MOD 8 = 6` ASSUME_TAC THENL
   [MP_TAC(ASSUME `(7*a+c+2 == 6) (mod 8)`) THEN
