let TERNARY_TYPE6_DICKSON_G_FIVE = prove
 (`!a beta r c s q:int.
     &2 divides s /\
     &5 * a + c + &2 * s = &8 * q + &6
     ==> ternary_type6
          (&5 * a) (&0) s (&2 * beta) (&2 * r) c`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC(SPECL
   [`&5 * a:int`; `&0:int`; `s:int`; `&2 * beta:int`; `&2 * r:int`;
    `c:int`; `&1:int`; `&0:int`; `&1:int`; `q:int`]
   TERNARY_TYPE6_OF_CHARACTERISTIC) THEN
  REWRITE_TAC[tqeval; INT_MUL_LZERO; INT_MUL_RZERO;
    INT_ADD_LID; INT_ADD_RID; INT_MUL_LID; INT_MUL_RID] THEN
  REPEAT CONJ_TAC THENL
   [UNDISCH_TAC `&2 divides s` THEN REWRITE_TAC[int_divides] THEN
    DISCH_THEN(X_CHOOSE_TAC `d:int`) THEN EXISTS_TAC `--d:int` THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING;
    REWRITE_TAC[int_divides] THEN EXISTS_TAC `beta-r:int` THEN
    CONV_TAC INT_RING;
    UNDISCH_TAC `&2 divides s` THEN REWRITE_TAC[int_divides] THEN
    DISCH_THEN(X_CHOOSE_TAC `d:int`) THEN EXISTS_TAC `--d:int` THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING;
    MP_TAC(ASSUME `&5 * a + c + &2 * s = &8 * q + &6`) THEN
    CONV_TAC INT_RING]);;

