let LEMMA_125_G_FIVE_PLUS = prove
 (`!a t beta r p c q:int.
     &0 < a /\ &0 < beta /\ ~(&2 divides a) /\
     beta = &8 * t * a - &5 /\
     beta * p = &8 * t + &10 * r pow 2 /\
     &5 * c + &2 = p + a /\
     &3 * a + c + &2 = &8 * q + &6
     ==> ?u v w:int.
           u pow 2 + &2 * v pow 2 + &5 * w pow 2 = &5 * a`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `&2 divides (&1-a)` ASSUME_TAC THENL
   [MP_TAC(MATCH_MP (SPEC `a:int` INT_ODD_FORM)
      (ASSUME `~(&2 divides a)`)) THEN
    DISCH_THEN(X_CHOOSE_TAC `d:int`) THEN
    REWRITE_TAC[int_divides] THEN EXISTS_TAC `--d:int` THEN
    MP_TAC(ASSUME `a = &2 * d + &1`) THEN CONV_TAC INT_RING;
    ALL_TAC] THEN
  MATCH_MP_TAC TERNARY_DISC10_TYPE6_SPECIAL THEN
  MAP_EVERY EXISTS_TAC
   [`&5 * a:int`; `&0:int`; `&1 - a:int`; `&2 * beta:int`;
    `&2 * r:int`; `c:int`; `&5 * a:int`; `t * a - &1:int`] THEN
  REPEAT CONJ_TAC THENL
   [ASM_INT_ARITH_TAC;
    REWRITE_TAC[INT_POW_2; INT_MUL_LZERO; INT_SUB_RZERO] THEN
    MATCH_MP_TAC INT_LT_MUL THEN ASM_INT_ARITH_TAC;
    MAP_EVERY UNDISCH_TAC
     [`beta = &8 * t * a - &5`;
      `beta * p = &8 * t + &10 * r pow 2`;
      `&5 * c + &2 = p + a`] THEN
    CONV_TAC INT_RING;
    MATCH_MP_TAC(SPECL
     [`a:int`; `beta:int`; `r:int`; `c:int`; `&1-a:int`; `q:int`]
     TERNARY_TYPE6_DICKSON_G_FIVE) THEN
    CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      MP_TAC(ASSUME `&3 * a + c + &2 = &8 * q + &6`) THEN
      CONV_TAC INT_RING];
    ASM_REWRITE_TAC[INT_2_DIVIDES_MUL; INT_NOT_2_DIVIDES_5_125];
    MAP_EVERY EXISTS_TAC [`&1:int`; `&0:int`; `&0:int`] THEN
    CONV_TAC INT_RING;
    MAP_EVERY EXISTS_TAC [`&0:int`; `&1:int`; `&0:int`] THEN
    UNDISCH_TAC `beta = &8 * t * a - &5` THEN CONV_TAC INT_RING;
    MAP_EVERY EXISTS_TAC [`&1:int`; `&0:int`; `&0:int`] THEN
    CONV_TAC INT_RING]);;

