let DICKSON_DATA_125_G_FIVE = prove
 (`!a:num.
     1 <= a /\ ODD a /\
     ((a == 1) (mod 5) \/ (a == 4) (mod 5))
     ==> ?j beta r p.
           prime beta /\ ODD r /\
           beta = 8*a*(20*j+1)-5 /\
           beta*p = 8*(20*j+1) + 10*r EXP 2`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
  SUBGOAL_THEN `~(5 divides a)` ASSUME_TAC THENL
   [UNDISCH_TAC `(a == 1) (mod 5) \/ (a == 4) (mod 5)` THEN
    REWRITE_TAC[CONG; DIVIDES_MOD] THEN
    CONV_TAC NUM_REDUCE_CONV THEN ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(SPEC `a:num` DIRICHLET_PRIME_125_DOUBLE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `beta:num` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `?j. beta = 160*a*j + (8*a-5)`
  (X_CHOOSE_TAC `j:num`) THENL
   [MP_TAC(SPECL [`160*a`; `8*a-5`; `beta:num`] CONG_CASE) THEN
    ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MONO_EXISTS THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `beta = 8*a*(20*j+1)-5` ASSUME_TAC THENL
   [UNDISCH_TAC `beta = 160*a*j + (8*a-5)` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?x. (x EXP 2 + 80*(20*j+1) == 0) (mod beta)`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
      QR_125_G_FIVE) THEN
    REPEAT CONJ_TAC THENL
     [ACCEPT_TAC(ASSUME `1 <= a`);
      ACCEPT_TAC(ASSUME `prime beta`);
      ACCEPT_TAC
       (ASSUME `(a == 1) (mod 5) \/ (a == 4) (mod 5)`);
      ACCEPT_TAC(ASSUME `beta = 8*a*(20*j+1)-5`)];
    ALL_TAC] THEN
  SUBGOAL_THEN `coprime(10,beta)` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
      COPRIME_10_BETA_125_G_FIVE) THEN
    REPEAT CONJ_TAC THENL
     [ACCEPT_TAC(ASSUME `1 <= a`);
      ACCEPT_TAC
       (ASSUME `(a == 1) (mod 5) \/ (a == 4) (mod 5)`);
      ACCEPT_TAC(ASSUME `beta = 8*a*(20*j+1)-5`)];
    ALL_TAC] THEN
  SUBGOAL_THEN `ODD beta` ASSUME_TAC THENL
   [MATCH_MP_TAC ODD_OF_3MOD4 THEN
    MATCH_MP_TAC CONG_MOD_8_IMP_MOD_4 THEN
    MATCH_MP_TAC(SPECL [`a:num`; `j:num`; `beta:num`]
      CONG_BETA_3MOD8_125_DOUBLE) THEN
    CONJ_TAC THENL
     [ACCEPT_TAC(ASSUME `1 <= a`);
      ACCEPT_TAC(ASSUME `beta = 8*a*(20*j+1)-5`)];
    ALL_TAC] THEN
  MP_TAC(SPECL [`20*j+1`; `beta:num`]
    DICKSON_ODD_RESIDUE_LIFT_125_G_FIVE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ACCEPT_TAC(ASSUME `ODD beta`);
      ACCEPT_TAC(ASSUME `coprime(10,beta)`);
      MAP_EVERY EXISTS_TAC [`x:num`] THEN
      ACCEPT_TAC
       (ASSUME `(x EXP 2 + 80*(20*j+1) == 0) (mod beta)`)];
    DISCH_THEN(X_CHOOSE_THEN `r:num`
      (X_CHOOSE_THEN `p:num` STRIP_ASSUME_TAC))] THEN
  MAP_EVERY EXISTS_TAC [`j:num`; `beta:num`; `r:num`; `p:num`] THEN
  REPEAT CONJ_TAC THENL
   [ACCEPT_TAC(ASSUME `prime beta`);
    ACCEPT_TAC(ASSUME `ODD r`);
    ACCEPT_TAC(ASSUME `beta = 8*a*(20*j+1)-5`);
    ACCEPT_TAC(ASSUME
      `beta*p = 8*(20*j+1) + 10*r EXP 2`)]);;

