           u pow 2 + &2*v pow 2 + &5*w pow 2 = &5 * &a`,
  MESON_TAC
   [REGULAR_125_ODD_FIVE_PLUS; REGULAR_125_ODD_FIVE_MINUS]);;

let INT_REPRESENTS_125_SCALE25 = prove
 (`!n:num.
     (?x y z:int.
        x pow 2 + &2 * y pow 2 + &5 * z pow 2 = &n)
     ==> ?x y z:int.
          x pow 2 + &2 * y pow 2 + &5 * z pow 2 = &(25*n)`,
  GEN_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int` (X_CHOOSE_TAC `z:int`))) THEN
  MAP_EVERY EXISTS_TAC [`&5*x:int`; `&5*y:int`; `&5*z:int`] THEN
  FIRST_X_ASSUM(MP_TAC) THEN
  REWRITE_TAC[GSYM INT_OF_NUM_MUL] THEN CONV_TAC INT_RING);;

let EXP_125_SCALE25 = prove
 (`!a:num. 5 EXP (2*SUC a+1) = 25 * 5 EXP (2*a+1)`,
  GEN_TAC THEN
  ONCE_REWRITE_TAC[ARITH_RULE `2*SUC a+1 = 2+(2*a+1)`] THEN
  REWRITE_TAC[EXP_ADD] THEN CONV_TAC NUM_REDUCE_CONV THEN ARITH_TAC);;

let NUM_125_EXCEPTION_SCALE25 = prove
 (`!n:num.
     num_125_exception n
     ==> num_125_exception (25*n)`,
  GEN_TAC THEN REWRITE_TAC[num_125_exception] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:num`
    (X_CHOOSE_THEN `u:num` STRIP_ASSUME_TAC)) THEN
  MAP_EVERY EXISTS_TAC [`SUC a`; `u:num`] THEN
  ASM_REWRITE_TAC[] THEN
  ONCE_REWRITE_TAC[EXP_125_SCALE25] THEN
  ARITH_TAC);;

let COPRIME_10_OF_ODD_NOT5 = prove
 (`!n:num.
     ODD n /\ ~(5 divides n)
     ==> coprime(10,n)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[ARITH_RULE `10 = 2*5`; COPRIME_LMUL] THEN
  CONJ_TAC THENL
   [ASM_REWRITE_TAC[CONJUNCT1 COPRIME_2];
    MATCH_MP_TAC(snd(EQ_IMP_RULE
      (MATCH_MP (SPECL [`5`; `n:num`] PRIME_COPRIME_EQ)
        (EQT_ELIM(PRIME_CONV `prime 5`))))) THEN
    ASM_REWRITE_TAC[]]);;

let CONG_HALF_1_MOD5 = prove
 (`!a b:num.
     a = 2*b /\ (a == 1) (mod 5)
     ==> (b == 3) (mod 5)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(2*b == 2*3) (mod 5)` ASSUME_TAC THENL
   [MATCH_MP_TAC CONG_TRANS THEN EXISTS_TAC `1` THEN CONJ_TAC THENL
     [ONCE_REWRITE_TAC[GSYM(ASSUME `a = 2*b`)] THEN
      ASM_REWRITE_TAC[];
      REWRITE_TAC[CONG] THEN CONV_TAC NUM_REDUCE_CONV];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
    (SPECL [`2`; `5`; `b:num`; `3`] CONG_MULT_LCANCEL_EQ)
    (EQT_ELIM(COPRIME_CONV `coprime(2,5)`))) THEN
  ASM_REWRITE_TAC[]);;

let CONG_HALF_4_MOD5 = prove
 (`!a b:num.
     a = 2*b /\ (a == 4) (mod 5)
     ==> (b == 2) (mod 5)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(2*b == 2*2) (mod 5)` ASSUME_TAC THENL
   [MATCH_MP_TAC CONG_TRANS THEN EXISTS_TAC `4` THEN CONJ_TAC THENL
     [ONCE_REWRITE_TAC[GSYM(ASSUME `a = 2*b`)] THEN
      ASM_REWRITE_TAC[];
      REWRITE_TAC[CONG] THEN CONV_TAC NUM_REDUCE_CONV];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
    (SPECL [`2`; `5`; `b:num`; `2`] CONG_MULT_LCANCEL_EQ)
    (EQT_ELIM(COPRIME_CONV `coprime(2,5)`))) THEN
  ASM_REWRITE_TAC[]);;

let CONG_HALF_1_OR_4_MOD5 = prove
 (`!a b:num.
     a = 2*b /\
     ((a == 1) (mod 5) \/ (a == 4) (mod 5))
     ==> (b == 2) (mod 5) \/ (b == 3) (mod 5)`,
  MESON_TAC[CONG_HALF_1_MOD5; CONG_HALF_4_MOD5]);;

let NUM_125_UNIT_ALLOWED = prove
 (`!a:num.
     ~(5 divides a) /\
     ~num_125_exception (5*a)
     ==> (a == 1) (mod 5) \/ (a == 4) (mod 5)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `~(a MOD 5 = 0)` ASSUME_TAC THENL
   [UNDISCH_TAC `~(5 divides a)` THEN
    REWRITE_TAC[DIVIDES_MOD] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN `~(a MOD 5 = 2 \/ a MOD 5 = 3)` ASSUME_TAC THENL
   [DISCH_TAC THEN
    UNDISCH_TAC `~num_125_exception (5*a)` THEN
    REWRITE_TAC[num_125_exception] THEN
    MAP_EVERY EXISTS_TAC [`0`; `a:num`] THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  REWRITE_TAC[CONG] THEN CONV_TAC NUM_REDUCE_CONV THEN
  MP_TAC(SPEC `a MOD 5`
    (ARITH_RULE
      `!r:num. r < 5
               ==> r = 0 \/ r = 1 \/ r = 2 \/ r = 3 \/ r = 4`)) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[MOD_LT_EQ] THEN ARITH_TAC;
    ASM_MESON_TAC[]]);;

let REGULAR_125_NOT_EXCEPTION_NOT25 = prove
 (`!n:num.
     ~num_125_exception n /\ ~(25 divides n)
     ==> ?x y z:int.
           x pow 2 + &2 * y pow 2 + &5 * z pow 2 = &n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_CASES_TAC `n = 0` THENL
   [MAP_EVERY EXISTS_TAC [`&0:int`; `&0:int`; `&0:int`] THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING;
    ALL_TAC] THEN
  ASM_CASES_TAC `5 divides n` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `a:num` ASSUME_TAC o
      REWRITE_RULE[divides]) THEN
    SUBGOAL_THEN `1 <= a` ASSUME_TAC THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~(5 divides a)` ASSUME_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `b:num` ASSUME_TAC o
        REWRITE_RULE[divides]) THEN
      UNDISCH_TAC `~(25 divides n)` THEN REWRITE_TAC[divides] THEN
      EXISTS_TAC `b:num` THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(a == 1) (mod 5) \/ (a == 4) (mod 5)`
    ASSUME_TAC THENL
     [MATCH_MP_TAC NUM_125_UNIT_ALLOWED THEN
      ASM_REWRITE_TAC[] THEN
      ONCE_REWRITE_TAC[GSYM(ASSUME `n = 5*a`)] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_CASES_TAC `ODD a` THENL
     [MP_TAC(SPEC `a:num` REGULAR_125_ODD_FIVE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ONCE_REWRITE_TAC[ASSUME `n = 5*a`] THEN
      REWRITE_TAC[INT_OF_NUM_MUL];
      SUBGOAL_THEN `EVEN a` ASSUME_TAC THENL
       [ASM_REWRITE_TAC[GSYM NOT_ODD];
        ALL_TAC] THEN
      FIRST_X_ASSUM(X_CHOOSE_THEN `b:num` ASSUME_TAC o
        REWRITE_RULE[EVEN_EXISTS]) THEN
      SUBGOAL_THEN `1 <= b` ASSUME_TAC THENL
       [ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(b == 2) (mod 5) \/ (b == 3) (mod 5)`
      ASSUME_TAC THENL
       [MATCH_MP_TAC(SPECL [`a:num`; `b:num`]
          CONG_HALF_1_OR_4_MOD5) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(SPEC `b:num` REGULAR_T_125_FIVE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        MP_TAC(MATCH_MP (SPEC `&5 * &b:int` REP_125_DOUBLE_OF_T) th)) THEN
      DISCH_THEN(X_CHOOSE_THEN `x:int`
        (X_CHOOSE_THEN `y:int`
          (X_CHOOSE_THEN `z:int` (LABEL_TAC "rep")))) THEN
      MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`] THEN
      SUBGOAL_THEN `n = 2 * (5*b)` ASSUME_TAC THENL
       [ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `&n:int = &2 * (&5 * &b)` ASSUME_TAC THENL
       [MP_TAC(AP_TERM `\r:num. &r:int`
          (ASSUME `n = 2 * (5*b)`)) THEN
        REWRITE_TAC[INT_OF_NUM_MUL];
        REMOVE_THEN "rep" MP_TAC THEN ASM_REWRITE_TAC[]]];
    ASM_CASES_TAC `ODD n` THENL
     [MATCH_MP_TAC REGULAR_125_COPRIME10 THEN
      CONJ_TAC THENL
       [ASM_ARITH_TAC;
        MATCH_MP_TAC COPRIME_10_OF_ODD_NOT5 THEN ASM_REWRITE_TAC[]];
      SUBGOAL_THEN `EVEN n` ASSUME_TAC THENL
       [ASM_REWRITE_TAC[GSYM NOT_ODD];
        ALL_TAC] THEN
      FIRST_X_ASSUM(X_CHOOSE_THEN `a:num` ASSUME_TAC o
        REWRITE_RULE[EVEN_EXISTS]) THEN
      SUBGOAL_THEN `1 <= a` ASSUME_TAC THENL
       [ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `~(5 divides a)` ASSUME_TAC THENL
       [DISCH_THEN(X_CHOOSE_THEN `b:num` ASSUME_TAC o
          REWRITE_RULE[divides]) THEN
        UNDISCH_TAC `~(5 divides n)` THEN REWRITE_TAC[divides] THEN
        EXISTS_TAC `2*b:num` THEN ASM_ARITH_TAC;
        ALL_TAC] THEN
      MP_TAC(SPEC `a:num` REGULAR_125_DOUBLE_COPRIME5) THEN
      ASM_REWRITE_TAC[] THEN
      ONCE_REWRITE_TAC[ASSUME `n = 2*a`] THEN
      REWRITE_TAC[INT_OF_NUM_MUL]]]);;

let REGULAR_125_NOT_EXCEPTION = prove
 (`!n:num.
     ~num_125_exception n
     ==> ?x y z:int.
           x pow 2 + &2 * y pow 2 + &5 * z pow 2 = &n`,
  MATCH_MP_TAC num_WF THEN X_GEN_TAC `n:num` THEN
  DISCH_THEN(LABEL_TAC "ih") THEN DISCH_THEN(LABEL_TAC "avoid") THEN
  ASM_CASES_TAC `25 divides n` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `q:num` ASSUME_TAC o
      REWRITE_RULE[divides]) THEN
    ASM_CASES_TAC `n = 0` THENL
     [MAP_EVERY EXISTS_TAC [`&0:int`; `&0:int`; `&0:int`] THEN
      REWRITE_TAC[ASSUME `n = 0`] THEN CONV_TAC INT_REDUCE_CONV;
      ALL_TAC] THEN
    SUBGOAL_THEN `(q:num) < n` ASSUME_TAC THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~num_125_exception q` ASSUME_TAC THENL
     [REMOVE_THEN "avoid" MP_TAC THEN
      ONCE_REWRITE_TAC[ASSUME `n = 25*q`] THEN
      MESON_TAC[NUM_125_EXCEPTION_SCALE25];
      ALL_TAC] THEN
    ONCE_REWRITE_TAC[ASSUME `n = 25*q`] THEN
    MATCH_MP_TAC INT_REPRESENTS_125_SCALE25 THEN
    REMOVE_THEN "ih" (MP_TAC o SPEC `q:num`) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC REGULAR_125_NOT_EXCEPTION_NOT25 THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Positive binary forms of determinant 7 have two classes.                 *)
(* ------------------------------------------------------------------------- *)

let INT_DISC7_NOT_FIRST3 = prove
 (`!a b:int. ~(&3 * a - b pow 2 = &7)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`b:int`; `&3:int`] INT_DIVISION) THEN
  ANTS_TAC THENL [INT_ARITH_TAC; STRIP_TAC] THEN
  MP_TAC(SPEC `b:int` INT_REM_3_CASES) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [SUBGOAL_THEN `&3 divides (&7:int)` MP_TAC THENL
     [REWRITE_TAC[int_divides] THEN
      EXISTS_TAC `a - &3 * (b div &3) pow 2` THEN
      MAP_EVERY UNDISCH_TAC
       [`&3 * a - b pow 2 = &7`;
        `b = b div &3 * &3 + b rem &3`;
        `b rem &3 = &0`] THEN
      CONV_TAC INT_RING;
      REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV];
    SUBGOAL_THEN `&3 divides (&8:int)` MP_TAC THENL
     [REWRITE_TAC[int_divides] THEN
      EXISTS_TAC
       `a - &3 * (b div &3) pow 2 - &2 * (b div &3)` THEN
      MAP_EVERY UNDISCH_TAC
       [`&3 * a - b pow 2 = &7`;
        `b = b div &3 * &3 + b rem &3`;
        `b rem &3 = &1`] THEN
      CONV_TAC INT_RING;
      REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV];
    SUBGOAL_THEN `&3 divides (&11:int)` MP_TAC THENL
     [REWRITE_TAC[int_divides] THEN
      EXISTS_TAC
       `a - &3 * (b div &3) pow 2 - &4 * (b div &3)` THEN
      MAP_EVERY UNDISCH_TAC
       [`&3 * a - b pow 2 = &7`;
        `b = b div &3 * &3 + b rem &3`;
        `b rem &3 = &2`] THEN
      CONV_TAC INT_RING;
      REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV]]);;

let BINARY_DISC7 = prove
 (`!A11. &0 < A11
   ==> !A12 A22.
         A11 * A22 - A12 pow 2 = &7
         ==> ((!n.
                 (?x y.
                    A11 * x pow 2 + &2 * A12 * x * y +
                    A22 * y pow 2 = n)
                 ==> ?u v:int. u pow 2 + &7 * v pow 2 = n) \/
              (!n.
                 (?x y.
                    A11 * x pow 2 + &2 * A12 * x * y +
                    A22 * y pow 2 = n)
                 ==> ?u v:int.
                       &2 * u pow 2 + &2 * u * v + &4 * v pow 2 = n))`,
  ONCE_REWRITE_TAC[MESON[]
   `(!A11. &0 < A11 ==> P A11) <=>
    (!m A11. num_of_int A11 = m /\ &0 < A11 ==> P A11)`] THEN
  MATCH_MP_TAC num_WF THEN GEN_TAC THEN STRIP_TAC THEN
  GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN DISCH_TAC THEN
  ASM_CASES_TAC `A11 = &1` THENL
   [DISJ1_TAC THEN GEN_TAC THEN
    DISCH_THEN(X_CHOOSE_THEN `x:int` (X_CHOOSE_TAC `y:int`)) THEN
    MAP_EVERY EXISTS_TAC [`x + A12 * y:int`; `y:int`] THEN
    MP_TAC(ASSUME `A11 * A22 - A12 pow 2 = &7`) THEN
    MP_TAC(ASSUME
     `A11 * x pow 2 + &2 * A12 * x * y + A22 * y pow 2 = n`) THEN
    REWRITE_TAC[ASSUME `A11 = &1`] THEN CONV_TAC INT_RING;
    ALL_TAC] THEN
  ASM_CASES_TAC `A11 = &2` THENL
   [DISJ2_TAC THEN GEN_TAC THEN
    DISCH_THEN(X_CHOOSE_THEN `x:int` (X_CHOOSE_TAC `y:int`)) THEN
    SUBGOAL_THEN `~(&2 divides A12)` ASSUME_TAC THENL
     [DISCH_THEN(X_CHOOSE_TAC `q:int` o REWRITE_RULE[int_divides]) THEN
      SUBGOAL_THEN `&2 divides (&7:int)` MP_TAC THENL
       [REWRITE_TAC[int_divides] THEN
        EXISTS_TAC `A22 - &2 * (q:int) pow 2` THEN
        MP_TAC(ASSUME `A11 * A22 - A12 pow 2 = &7`) THEN
        REWRITE_TAC[ASSUME `A11 = &2`; ASSUME `A12 = &2 * q`] THEN
        CONV_TAC INT_RING;
        REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV];
      ALL_TAC] THEN
    MP_TAC(MATCH_MP (SPEC `A12:int` INT_ODD_FORM)
      (ASSUME `~(&2 divides A12)`)) THEN
    DISCH_THEN(X_CHOOSE_TAC `q:int`) THEN
    SUBGOAL_THEN `A22 = &2 * q pow 2 + &2 * q + &4`
    ASSUME_TAC THENL
     [MP_TAC(ASSUME `A11 * A22 - A12 pow 2 = &7`) THEN
      REWRITE_TAC
       [ASSUME `A11 = &2`; ASSUME `A12 = &2 * q + &1`] THEN
      CONV_TAC INT_RING;
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`x + q * y:int`; `y:int`] THEN
    MP_TAC(ASSUME
     `A11 * x pow 2 + &2 * A12 * x * y + A22 * y pow 2 = n`) THEN
    REWRITE_TAC
     [ASSUME `A11 = &2`; ASSUME `A12 = &2 * q + &1`;
      ASSUME `A22 = &2 * q pow 2 + &2 * q + &4`] THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  ASM_CASES_TAC `A11 = &3` THENL
   [MP_TAC(ASSUME `A11 * A22 - A12 pow 2 = &7`) THEN
    REWRITE_TAC[ASSUME `A11 = &3`] THEN
    MESON_TAC[INT_DISC7_NOT_FIRST3];
    ALL_TAC] THEN
  MP_TAC(SPECL [`A12:int`; `A11:int`] INT_BALANCED_REM) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `b:int` (LABEL_TAC "balanced")) THEN
  ABBREV_TAC `r = --b:int` THEN
  ABBREV_TAC `A12' = A12 + A11 * r` THEN
  ABBREV_TAC `A22' = A11 * r pow 2 + &2 * A12 * r + A22` THEN
  SUBGOAL_THEN `abs A12' * &2 <= A11` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["A12'"; "r"] THEN
    REMOVE_THEN "balanced" MP_TAC THEN
    REWRITE_TAC[INT_ARITH
      `A12 + A11 * --b = A12 - A11 * b`];
    ALL_TAC] THEN
  SUBGOAL_THEN `A11 * A22' - A12' pow 2 = &7` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["A12'"; "A22'"] THEN
    UNDISCH_TAC `A11 * A22 - A12 pow 2 = &7` THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 < A22'` ASSUME_TAC THENL
   [SUBGOAL_THEN `&0 < A11 * A22'` MP_TAC THENL
     [SUBGOAL_THEN `A11 * A22' = &7 + A12' pow 2` SUBST1_TAC THENL
       [ASM_INT_ARITH_TAC;
        MP_TAC(SPEC `A12':int` INT_LE_POW_2) THEN INT_ARITH_TAC];
      ASM_SIMP_TAC[INT_LT_MUL_EQ]];
    ALL_TAC] THEN
  SUBGOAL_THEN `&4 <= A11` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `&28 < &3 * A11 pow 2` ASSUME_TAC THENL
   [SUBGOAL_THEN `&16 <= A11 pow 2` MP_TAC THENL
     [MP_TAC(SPECL [`2`; `&4:int`; `A11:int`] INT_POW_LE2) THEN
      ANTS_TAC THENL [ASM_INT_ARITH_TAC; CONV_TAC INT_REDUCE_CONV];
      INT_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `A22' < A11` ASSUME_TAC THENL
   [SUBGOAL_THEN `&4 * (A11 * A22') <= &28 + A11 pow 2`
    ASSUME_TAC THENL
     [SUBGOAL_THEN `A11 * A22' = &7 + A12' pow 2`
       (fun th -> REWRITE_TAC[th]) THENL
       [ASM_INT_ARITH_TAC;
        MP_TAC(MATCH_MP SQ_BOUND
          (ASSUME `abs A12' * &2 <= A11`)) THEN INT_ARITH_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `A11 * (&4 * A22') < A11 * (&4 * A11)` MP_TAC THENL
     [MATCH_MP_TAC INT_LET_TRANS THEN
      EXISTS_TAC `&28 + A11 pow 2` THEN
      CONJ_TAC THENL
       [UNDISCH_TAC `&4 * (A11 * A22') <= &28 + A11 pow 2` THEN
        INT_ARITH_TAC;
        REWRITE_TAC[INT_POW_2] THEN
        UNDISCH_TAC `&28 < &3 * A11 pow 2` THEN
        REWRITE_TAC[INT_POW_2] THEN INT_ARITH_TAC];
      ASM_SIMP_TAC[INT_LT_LMUL_EQ] THEN INT_ARITH_TAC];
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `num_of_int A22'`) THEN
  SUBGOAL_THEN `num_of_int A22' < m` ASSUME_TAC THENL
   [FIRST_X_ASSUM(SUBST1_TAC o SYM o
      check (fun th -> rand(concl th) = `m:num`)) THEN
    REWRITE_TAC[GSYM INT_OF_NUM_LT] THEN
    SUBGOAL_THEN `&(num_of_int A22') = A22' /\ &(num_of_int A11) = A11`
    (CONJUNCTS_THEN SUBST1_TAC) THENL
     [CONJ_TAC THEN MATCH_MP_TAC INT_OF_NUM_OF_INT THEN ASM_INT_ARITH_TAC;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPEC `A22':int`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`A12':int`; `A11:int`]) THEN
  ANTS_TAC THENL
   [MP_TAC(ASSUME `A11 * A22' - A12' pow 2 = &7`) THEN
    CONV_TAC INT_RING;
    DISCH_THEN(DISJ_CASES_THEN (LABEL_TAC "class")) THENL
     [DISJ1_TAC; DISJ2_TAC] THEN
    X_GEN_TAC `n:int` THEN
    DISCH_THEN(X_CHOOSE_THEN `x:int` (X_CHOOSE_TAC `y:int`)) THEN
    REMOVE_THEN "class" (MATCH_MP_TAC o SPEC `n:int`) THEN
    MAP_EVERY EXISTS_TAC [`y:int`; `x - r * y:int`] THEN
    MAP_EVERY EXPAND_TAC ["A12'"; "A22'"] THEN
    UNDISCH_TAC
     `A11 * x pow 2 + &2 * A12 * x * y + A22 * y pow 2 = n` THEN
    CONV_TAC INT_RING]);;

(* ------------------------------------------------------------------------- *)
(* The discriminant-seven genus has 2-adic oddity 1.                        *)
(* ------------------------------------------------------------------------- *)

let ternary_type1 = new_definition
 `ternary_type1 a11 a12 a13 a22 a23 a33 <=>
    ?w1 w2 w3 q:int.
      (!x1 x2 x3.
         &2 divides
          (tqeval a11 a12 a13 a22 a23 a33 x1 x2 x3 -
           tqbilin a11 a12 a13 a22 a23 a33 x1 x2 x3 w1 w2 w3)) /\
      tqeval a11 a12 a13 a22 a23 a33 w1 w2 w3 = &8 * q + &1`;;

let CONJ_TYPE1 = prove
 (`!a11 a12 a13 a22 a23 a33 v1 v2 v3 c12 c13 c22 c23 c32 c33
     b11 b12 b13 b22 b23 b33:int.
     v1 * (c22 * c33 - c23 * c32) -
     c12 * (v2 * c33 - c23 * v3) +
     c13 * (v2 * c32 - c22 * v3) = &1 /\
     b11 = a11 * v1 pow 2 + &2 * a12 * v1 * v2 +
            &2 * a13 * v1 * v3 + a22 * v2 pow 2 +
            &2 * a23 * v2 * v3 + a33 * v3 pow 2 /\
     b22 = a11 * c12 pow 2 + &2 * a12 * c12 * c22 +
            &2 * a13 * c12 * c32 + a22 * c22 pow 2 +
            &2 * a23 * c22 * c32 + a33 * c32 pow 2 /\
     b33 = a11 * c13 pow 2 + &2 * a12 * c13 * c23 +
            &2 * a13 * c13 * c33 + a22 * c23 pow 2 +
            &2 * a23 * c23 * c33 + a33 * c33 pow 2 /\
     b12 = a11 * v1 * c12 + a12 * (v1 * c22 + v2 * c12) +
            a13 * (v1 * c32 + v3 * c12) +
            a22 * v2 * c22 + a23 * (v2 * c32 + v3 * c22) +
            a33 * v3 * c32 /\
     b13 = a11 * v1 * c13 + a12 * (v1 * c23 + v2 * c13) +
            a13 * (v1 * c33 + v3 * c13) +
            a22 * v2 * c23 + a23 * (v2 * c33 + v3 * c23) +
            a33 * v3 * c33 /\
     b23 = a11 * c12 * c13 + a12 * (c12 * c23 + c22 * c13) +
            a13 * (c12 * c33 + c32 * c13) +
            a22 * c22 * c23 + a23 * (c22 * c33 + c32 * c23) +
            a33 * c32 * c33 /\
     ternary_type1 a11 a12 a13 a22 a23 a33
     ==> ternary_type1 b11 b12 b13 b22 b23 b33`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[ternary_type1]) THEN
  DISCH_THEN(X_CHOOSE_THEN `w1:int` (X_CHOOSE_THEN `w2:int`
    (X_CHOOSE_THEN `w3:int` (X_CHOOSE_THEN `q:int` STRIP_ASSUME_TAC)))) THEN
  MP_TAC(SPECL
   [`v1:int`; `v2:int`; `v3:int`; `c12:int`; `c22:int`; `c32:int`;
    `c13:int`; `c23:int`; `c33:int`; `w1:int`; `w2:int`; `w3:int`]
   ADJ_PREIMAGE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `y1:int` (X_CHOOSE_THEN `y2:int`
    (X_CHOOSE_THEN `y3:int` STRIP_ASSUME_TAC))) THEN
  REWRITE_TAC[ternary_type1] THEN
  MAP_EVERY EXISTS_TAC [`y1:int`; `y2:int`; `y3:int`; `q:int`] THEN
  CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`z1:int`; `z2:int`; `z3:int`] THEN
    FIRST_X_ASSUM(MP_TAC o SPECL
     [`z1 * v1 + z2 * c12 + z3 * c13:int`;
      `z1 * v2 + z2 * c22 + z3 * c23:int`;
      `z1 * v3 + z2 * c32 + z3 * c33:int`] o
      check (fun th -> is_forall(concl th))) THEN
    REWRITE_TAC[int_divides] THEN
    DISCH_THEN(X_CHOOSE_TAC `d:int`) THEN EXISTS_TAC `d:int` THEN
    POP_ASSUM_LIST
     (fun ths -> MAP_EVERY MP_TAC (filter (is_eq o concl) ths)) THEN
    REWRITE_TAC[tqeval; tqbilin] THEN CONV_TAC INT_RING;
    POP_ASSUM_LIST
     (fun ths -> MAP_EVERY MP_TAC (filter (is_eq o concl) ths)) THEN
    REWRITE_TAC[tqeval; tqbilin] THEN CONV_TAC INT_RING]);;

let TERNARY_TYPE1_OF_CHARACTERISTIC = prove
 (`!a11 a12 a13 a22 a23 a33 w1 w2 w3 q:int.
     &2 divides (a11 - (a11 * w1 + a12 * w2 + a13 * w3)) /\
     &2 divides (a22 - (a12 * w1 + a22 * w2 + a23 * w3)) /\
     &2 divides (a33 - (a13 * w1 + a23 * w2 + a33 * w3)) /\
     tqeval a11 a12 a13 a22 a23 a33 w1 w2 w3 = &8 * q + &1
     ==> ternary_type1 a11 a12 a13 a22 a23 a33`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[ternary_type1] THEN
  MAP_EVERY EXISTS_TAC [`w1:int`; `w2:int`; `w3:int`; `q:int`] THEN
  ASM_REWRITE_TAC[] THEN MATCH_MP_TAC TERNARY_CHARACTERISTIC THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Hermite reduction leaves only minima 1 and 2.                            *)
(* ------------------------------------------------------------------------- *)

let HERMITE_CUBE_DISC7 = prove
 (`!a G:int.
     &0 < a /\ &0 < G /\
     &3 * a pow 2 <= &4 * G /\ &3 * G pow 2 <= &4 * (&7 * a)
     ==> &27 * a pow 3 <= &448`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(&3 * a pow 2) pow 2 <= (&4 * G) pow 2` MP_TAC THENL
   [MATCH_MP_TAC INT_POW_LE2 THEN CONJ_TAC THENL
     [MATCH_MP_TAC INT_LE_MUL THEN REWRITE_TAC[INT_LE_POW_2] THEN
      INT_ARITH_TAC;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[INT_POW_MUL] THEN DISCH_TAC THEN
  MATCH_MP_TAC INT_LE_RCANCEL_IMP THEN EXISTS_TAC `a:int` THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MATCH_MP_TAC INT_LE_TRANS THEN
  EXISTS_TAC `&16 * (&3 * G pow 2)` THEN
  CONJ_TAC THENL
   [MP_TAC
     (ASSUME `&3 pow 2 * a pow 2 pow 2 <= &4 pow 2 * G pow 2`) THEN
    REWRITE_TAC[INT_ARITH `a pow 2 pow 2 = a pow 3 * a`; INT_POW_2] THEN
    INT_ARITH_TAC;
    MP_TAC(ASSUME `&3 * G pow 2 <= &4 * (&7 * a)`) THEN
    INT_ARITH_TAC]);;

let HERMITE_DISC7_LE2 = prove
 (`!b11 b12 b13 b22 b23 b33:int.
     &0 < b11 /\
     b11 * (b22 * b33 - b23 pow 2) -
       b12 * (b12 * b33 - b13 * b23) +
       b13 * (b12 * b23 - b13 * b22) = &7 /\
     &0 < b11 * b22 - b12 pow 2 /\
     (!x y z. ~(x = &0 /\ y = &0 /\ z = &0)
              ==> b11 <= b11 * x pow 2 + b22 * y pow 2 +
                         b33 * z pow 2 + &2 * b12 * x * y +
                         &2 * b13 * x * z + &2 * b23 * y * z)
     ==> b11 = &1 \/ b11 = &2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `G11 = b11 * b22 - b12 pow 2` THEN
  ABBREV_TAC `G12 = b11 * b23 - b12 * b13` THEN
  ABBREV_TAC `G22 = b11 * b33 - b13 pow 2` THEN
  SUBGOAL_THEN `G11 * G22 - G12 pow 2 = &7 * b11` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["G11"; "G12"; "G22"] THEN
    REWRITE_TAC[DISC_G] THEN
    MP_TAC
     (ASSUME
       `b11 * (b22 * b33 - b23 pow 2) -
        b12 * (b12 * b33 - b13 * b23) +
        b13 * (b12 * b23 - b13 * b22) = &7`) THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  MP_TAC(SPEC `&7 * b11:int` BINARY_HERMITE) THEN
  ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `G11:int`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`G12:int`; `G22:int`]) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:int`
    (X_CHOOSE_THEN `t:int` STRIP_ASSUME_TAC)) THEN
  ABBREV_TAC
   `Gst = G11 * s pow 2 + &2 * G12 * s * t + G22 * t pow 2` THEN
  MP_TAC(SPECL [`b12 * s + b13 * t:int`; `b11:int`]
    INT_BALANCED_REM) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `bb:int`) THEN
  ABBREV_TAC `x1 = --bb:int` THEN
  SUBGOAL_THEN
   `&4 * (b11 * x1 + b12 * s + b13 * t) pow 2 <= b11 pow 2`
  ASSUME_TAC THENL
   [MP_TAC(MATCH_MP SQ_BOUND
     (ASSUME
       `abs ((b12 * s + b13 * t) - b11 * bb) * &2 <= b11`)) THEN
    EXPAND_TAC "x1" THEN
    REWRITE_TAC
     [INT_ARITH
       `b11 * --bb + b12 * s + b13 * t =
        (b12 * s + b13 * t) - b11 * bb`] THEN
    INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `&3 * b11 pow 2 <= &4 * Gst` ASSUME_TAC THENL
   [MATCH_MP_TAC HERMITE_LOWER THEN
    MAP_EVERY EXISTS_TAC
     [`b12:int`; `b13:int`; `b22:int`; `b23:int`; `b33:int`;
      `x1:int`; `s:int`; `t:int`] THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [FIRST_X_ASSUM
       (fun th ->
         MP_TAC(SPECL [`x1:int`; `s:int`; `t:int`] th) THEN
         ANTS_TAC THENL
          [UNDISCH_TAC `~(s = &0 /\ t = &0)` THEN MESON_TAC[];
           ALL_TAC] THEN
         DISCH_THEN(fun th2 -> ACCEPT_TAC th2 ORELSE MP_TAC th2));
      EXPAND_TAC "Gst" THEN
      MP_TAC(SPECL
       [`b11:int`; `b12:int`; `b13:int`; `b22:int`; `b23:int`;
        `b33:int`; `x1:int`; `s:int`; `t:int`] TERNARY_COMPLETE) THEN
      MAP_EVERY (fun e -> UNDISCH_TAC e)
       [`b11 * b22 - b12 pow 2 = G11`;
        `b11 * b23 - b12 * b13 = G12`;
        `b11 * b33 - b13 pow 2 = G22`] THEN
      CONV_TAC INT_RING];
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 < Gst` ASSUME_TAC THENL
   [EXPAND_TAC "Gst" THEN
    MP_TAC(SPECL [`G11:int`; `G12:int`; `G22:int`]
      POSDEF_BINARY_CRITERION) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_INT_ARITH_TAC;
      ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`s:int`; `t:int`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`b11:int`; `Gst:int`] HERMITE_CUBE_DISC7) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  SUBGOAL_THEN `~(&3 <= b11)` ASSUME_TAC THENL
   [DISCH_TAC THEN MP_TAC(SPEC `b11:int` CUBE_GE_27) THEN
    ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `&27 * b11 pow 3 <= &448` THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  ASM_INT_ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* A norm-one vector splits off either binary determinant-seven class.       *)
(* ------------------------------------------------------------------------- *)

let TERNARY_DISC7_A11_1 = prove
 (`!a12 a13 a22 a23 a33 n:int.
     &0 < &1 * a22 - a12 pow 2 /\
     &1 * (a22 * a33 - a23 pow 2) -
       a12 * (a12 * a33 - a23 * a13) +
       a13 * (a12 * a23 - a22 * a13) = &7 /\
     (?x1 x2 x3.
        &1 * x1 pow 2 + a22 * x2 pow 2 + a33 * x3 pow 2 +
        &2 * a12 * x1 * x2 + &2 * a13 * x1 * x3 +
        &2 * a23 * x2 * x3 = n)
     ==> ((?u v w:int. u pow 2 + v pow 2 + &7 * w pow 2 = n) \/
          (?u v w:int.
             u pow 2 + &2 * v pow 2 + &2 * v * w +
             &4 * w pow 2 = n))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `G11 = a22 - a12 pow 2` THEN
  ABBREV_TAC `G12 = a23 - a12 * a13` THEN
  ABBREV_TAC `G22 = a33 - a13 pow 2` THEN
  SUBGOAL_THEN `&0 < G11` ASSUME_TAC THENL
   [EXPAND_TAC "G11" THEN
    UNDISCH_TAC `&0 < &1 * a22 - a12 pow 2` THEN
    REWRITE_TAC[INT_MUL_LID];
    ALL_TAC] THEN
  SUBGOAL_THEN `G11 * G22 - G12 pow 2 = &7` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["G11"; "G12"; "G22"] THEN
    UNDISCH_TAC
     `&1 * (a22 * a33 - a23 pow 2) -
      a12 * (a12 * a33 - a23 * a13) +
      a13 * (a12 * a23 - a22 * a13) = &7` THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  ABBREV_TAC `L = x1 + a12 * x2 + a13 * x3` THEN
  MP_TAC(SPEC `G11:int` BINARY_DISC7) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`G12:int`; `G22:int`]) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(DISJ_CASES_THEN (LABEL_TAC "class")) THENL
   [DISJ1_TAC; DISJ2_TAC] THEN
  (REMOVE_THEN "class" (MP_TAC o SPEC `n - L pow 2`) THEN
   ANTS_TAC THENL
    [MAP_EVERY EXISTS_TAC [`x2:int`; `x3:int`] THEN
     MP_TAC(SPECL
      [`&1:int`; `a12:int`; `a13:int`; `a22:int`; `a23:int`; `a33:int`;
       `x1:int`; `x2:int`; `x3:int`] TERNARY_COMPLETE) THEN
     ASM_REWRITE_TAC[INT_MUL_LID] THEN INT_ARITH_TAC;
     ALL_TAC]) THEN
  DISCH_THEN(X_CHOOSE_THEN `v:int` (X_CHOOSE_TAC `w:int`)) THEN
  MAP_EVERY EXISTS_TAC [`L:int`; `v:int`; `w:int`] THEN
  FIRST_X_ASSUM MP_TAC THEN INT_ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* If the minimum is two, primitive binary reduction leaves two cases.      *)
(* ------------------------------------------------------------------------- *)

let HERMITE_DISC7_MIN2_PAIR = prove
 (`!b12 b13 b22 b23 b33:int.
     &2 * (b22 * b33 - b23 pow 2) -
       b12 * (b12 * b33 - b13 * b23) +
       b13 * (b12 * b23 - b13 * b22) = &7 /\
     &0 < &2 * b22 - b12 pow 2 /\
     (!x y z. ~(x = &0 /\ y = &0 /\ z = &0)
              ==> &2 <= &2 * x pow 2 + b22 * y pow 2 +
                         b33 * z pow 2 + &2 * b12 * x * y +
                         &2 * b13 * x * z + &2 * b23 * y * z)
     ==> ?x y z.
           (?p q. y * p + z * q = &1) /\
           ((&2 * x pow 2 + b22 * y pow 2 + b33 * z pow 2 +
              &2 * b12 * x * y + &2 * b13 * x * z +
              &2 * b23 * y * z = &2 /\
             (&2 * x + b12 * y + b13 * z) pow 2 = &1 /\
             (&2 * b22 - b12 pow 2) * y pow 2 +
             &2 * (&2 * b23 - b12 * b13) * y * z +
             (&2 * b33 - b13 pow 2) * z pow 2 = &3) \/
            (&2 * x pow 2 + b22 * y pow 2 + b33 * z pow 2 +
              &2 * b12 * x * y + &2 * b13 * x * z +
              &2 * b23 * y * z = &2 /\
             &2 * x + b12 * y + b13 * z = &0 /\
             (&2 * b22 - b12 pow 2) * y pow 2 +
             &2 * (&2 * b23 - b12 * b13) * y * z +
             (&2 * b33 - b13 pow 2) * z pow 2 = &4))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `G11 = &2 * b22 - b12 pow 2` THEN
  ABBREV_TAC `G12 = &2 * b23 - b12 * b13` THEN
  ABBREV_TAC `G22 = &2 * b33 - b13 pow 2` THEN
  SUBGOAL_THEN `G11 * G22 - G12 pow 2 = &14` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["G11"; "G12"; "G22"] THEN
    REWRITE_TAC[DISC_G] THEN
    MP_TAC(ASSUME
     `&2 * (b22 * b33 - b23 pow 2) -
      b12 * (b12 * b33 - b13 * b23) +
      b13 * (b12 * b23 - b13 * b22) = &7`) THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  MP_TAC(SPEC `&14:int` BINARY_HERMITE_PRIMITIVE) THEN
  CONV_TAC INT_REDUCE_CONV THEN
  DISCH_THEN(MP_TAC o SPEC `G11:int`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`G12:int`; `G22:int`]) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:int`
    (X_CHOOSE_THEN `t:int`
      (CONJUNCTS_THEN2
        (X_CHOOSE_THEN `p:int` (X_CHOOSE_TAC `q:int`))
        ASSUME_TAC))) THEN
  ABBREV_TAC
   `Gst = G11 * s pow 2 + &2 * G12 * s * t + G22 * t pow 2` THEN
  SUBGOAL_THEN `&3 * Gst pow 2 <= &4 * &14` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`b12 * s + b13 * t:int`; `&2:int`]
    INT_BALANCED_REM) THEN
  CONV_TAC INT_REDUCE_CONV THEN
  DISCH_THEN(X_CHOOSE_TAC `bb:int`) THEN
  ABBREV_TAC `x1 = --bb:int` THEN
  ABBREV_TAC
   `Fst = &2 * x1 pow 2 + b22 * s pow 2 + b33 * t pow 2 +
          &2 * b12 * x1 * s + &2 * b13 * x1 * t +
          &2 * b23 * s * t` THEN
  ABBREV_TAC `l = &2 * x1 + b12 * s + b13 * t` THEN
  SUBGOAL_THEN `&4 * l pow 2 <= &4` ASSUME_TAC THENL
   [MP_TAC(MATCH_MP SQ_BOUND
     (ASSUME `abs ((b12 * s + b13 * t) - &2 * bb) * &2 <= &2`)) THEN
    MAP_EVERY EXPAND_TAC ["l"; "x1"] THEN
    REWRITE_TAC[INT_ARITH
      `&2 * --bb + b12 * s + b13 * t =
       (b12 * s + b13 * t) - &2 * bb`] THEN
    INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `&2 <= Fst` ASSUME_TAC THENL
   [EXPAND_TAC "Fst" THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
    DISCH_TAC THEN UNDISCH_TAC `s * p + t * q = &1` THEN
    ASM_REWRITE_TAC[] THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `&2 * Fst = l pow 2 + Gst` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["Fst"; "l"; "Gst"; "G11"; "G12"; "G22"] THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN `&3 <= Gst` ASSUME_TAC THENL
   [UNDISCH_TAC `&2 <= Fst` THEN
    UNDISCH_TAC `&4 * l pow 2 <= &4` THEN
    UNDISCH_TAC `&2 * Fst = l pow 2 + Gst` THEN
    MP_TAC(SPEC `l:int` INT_LE_POW_2) THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `Gst <= &4` ASSUME_TAC THENL
   [ASM_CASES_TAC `Gst <= &4` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `&25 <= Gst pow 2` ASSUME_TAC THENL
     [MP_TAC(SPECL [`2`; `&5:int`; `Gst:int`] INT_POW_LE2) THEN
      ANTS_TAC THENL [ASM_INT_ARITH_TAC; CONV_TAC INT_REDUCE_CONV];
      UNDISCH_TAC `&3 * Gst pow 2 <= &4 * &14` THEN
      ASM_INT_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `l pow 2 = &0 \/ l pow 2 = &1`
  (LABEL_TAC "lsqcases") THENL
   [UNDISCH_TAC `&4 * l pow 2 <= &4` THEN
    MP_TAC(SPEC `l:int` INT_LE_POW_2) THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `l = &0 \/ l pow 2 = &1`
  (LABEL_TAC "lcases") THENL
   [REMOVE_THEN "lsqcases" MP_TAC THEN
    REWRITE_TAC[INT_POW_EQ_0] THEN CONV_TAC NUM_REDUCE_CONV THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `Fst = &2` ASSUME_TAC THENL
   [UNDISCH_TAC `Gst <= &4` THEN
    UNDISCH_TAC `&4 * l pow 2 <= &4` THEN
    UNDISCH_TAC `&2 <= Fst` THEN
    UNDISCH_TAC `&2 * Fst = l pow 2 + Gst` THEN
    MP_TAC(SPEC `Gst:int` INT_LE_POW_2) THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(Fst = &2 /\ l pow 2 = &1 /\ Gst = &3) \/
    (Fst = &2 /\ l = &0 /\ Gst = &4)`
  (LABEL_TAC "shortcases") THENL
   [REMOVE_THEN "lcases" (DISJ_CASES_THEN ASSUME_TAC) THEN
    UNDISCH_TAC `&3 <= Gst` THEN UNDISCH_TAC `Gst <= &4` THEN
    UNDISCH_TAC `&2 * Fst = l pow 2 + Gst` THEN
    ASM_REWRITE_TAC[] THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`x1:int`; `s:int`; `t:int`] THEN
  CONJ_TAC THENL
   [MAP_EVERY EXISTS_TAC [`p:int`; `q:int`] THEN ASM_REWRITE_TAC[];
    REMOVE_THEN "shortcases" MP_TAC THEN
    MAP_EVERY EXPAND_TAC ["Fst"; "l"; "Gst"; "G11"; "G12"; "G22"] THEN
    REWRITE_TAC[]]);;

let INT_ODD_DET_KERNEL_MOD2 = prove
 (`!a11 a12 a13 a22 a23 a33 d x y z:int.
     d =
       a11 * (a22 * a33 - a23 pow 2) -
       a12 * (a12 * a33 - a13 * a23) +
       a13 * (a12 * a23 - a13 * a22) /\
     ~(&2 divides d) /\
     &2 divides (a11 * x + a12 * y + a13 * z) /\
     &2 divides (a12 * x + a22 * y + a23 * z) /\
     &2 divides (a13 * x + a23 * y + a33 * z)
     ==> &2 divides x /\ &2 divides y /\ &2 divides z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `r1:int` o REWRITE_RULE[int_divides] o
    check (fun th -> rand(concl th) =
      `a11 * x + a12 * y + a13 * z:int`)) THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `r2:int` o REWRITE_RULE[int_divides] o
    check (fun th -> rand(concl th) =
      `a12 * x + a22 * y + a23 * z:int`)) THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `r3:int` o REWRITE_RULE[int_divides] o
    check (fun th -> rand(concl th) =
      `a13 * x + a23 * y + a33 * z:int`)) THEN
  SUBGOAL_THEN `&2 divides d * x` ASSUME_TAC THENL
   [REWRITE_TAC[int_divides] THEN
    EXISTS_TAC
     `(a22 * a33 - a23 pow 2) * r1 +
      (a13 * a23 - a12 * a33) * r2 +
      (a12 * a23 - a13 * a22) * r3:int` THEN
    POP_ASSUM_LIST
     (fun ths -> MAP_EVERY MP_TAC (filter (is_eq o concl) ths)) THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN `&2 divides d * y` ASSUME_TAC THENL
   [REWRITE_TAC[int_divides] THEN
    EXISTS_TAC
     `(a13 * a23 - a12 * a33) * r1 +
      (a11 * a33 - a13 pow 2) * r2 +
      (a12 * a13 - a11 * a23) * r3:int` THEN
    POP_ASSUM_LIST
     (fun ths -> MAP_EVERY MP_TAC (filter (is_eq o concl) ths)) THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN `&2 divides d * z` ASSUME_TAC THENL
   [REWRITE_TAC[int_divides] THEN
    EXISTS_TAC
     `(a12 * a23 - a13 * a22) * r1 +
      (a12 * a13 - a11 * a23) * r2 +
      (a11 * a22 - a12 pow 2) * r3:int` THEN
    POP_ASSUM_LIST
     (fun ths -> MAP_EVERY MP_TAC (filter (is_eq o concl) ths)) THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [UNDISCH_TAC `&2 divides d * x`;
    UNDISCH_TAC `&2 divides d * y`;
    UNDISCH_TAC `&2 divides d * z`] THEN
  REWRITE_TAC[INT_2_DIVIDES_MUL] THEN ASM_MESON_TAC[]);;

let INT_CHARACTERISTIC_VALUES_CONG8 = prove
 (`!a11 a12 a13 a22 a23 a33 v1 v2 v3 w1 w2 w3:int.
     &2 divides (a11 - (a11 * v1 + a12 * v2 + a13 * v3)) /\
     &2 divides (a22 - (a12 * v1 + a22 * v2 + a23 * v3)) /\
     &2 divides (a33 - (a13 * v1 + a23 * v2 + a33 * v3)) /\
     &2 divides (w1 - v1) /\
     &2 divides (w2 - v2) /\
     &2 divides (w3 - v3)
     ==> &8 divides
          (tqeval a11 a12 a13 a22 a23 a33 w1 w2 w3 -
           tqeval a11 a12 a13 a22 a23 a33 v1 v2 v3)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `u1:int` o REWRITE_RULE[int_divides] o
    check (fun th -> rand(concl th) = `w1 - v1:int`)) THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `u2:int` o REWRITE_RULE[int_divides] o
    check (fun th -> rand(concl th) = `w2 - v2:int`)) THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `u3:int` o REWRITE_RULE[int_divides] o
    check (fun th -> rand(concl th) = `w3 - v3:int`)) THEN
  SUBGOAL_THEN
   `&2 divides
      (tqeval a11 a12 a13 a22 a23 a33 u1 u2 u3 -
       tqbilin a11 a12 a13 a22 a23 a33 u1 u2 u3 v1 v2 v3)`
  ASSUME_TAC THENL
   [MP_TAC(SPECL
     [`a11:int`; `a12:int`; `a13:int`; `a22:int`; `a23:int`; `a33:int`;
      `v1:int`; `v2:int`; `v3:int`] TERNARY_CHARACTERISTIC) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o SPECL [`u1:int`; `u2:int`; `u3:int`]) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `r:int` o REWRITE_RULE[int_divides] o
    check (fun th -> rand(concl th) =
      `tqeval a11 a12 a13 a22 a23 a33 u1 u2 u3 -
       tqbilin a11 a12 a13 a22 a23 a33 u1 u2 u3 v1 v2 v3:int`)) THEN
  REWRITE_TAC[int_divides] THEN
  EXISTS_TAC
   `r + tqbilin a11 a12 a13 a22 a23 a33
          u1 u2 u3 v1 v2 v3:int` THEN
  POP_ASSUM_LIST
   (fun ths -> MAP_EVERY MP_TAC (filter (is_eq o concl) ths)) THEN
  REWRITE_TAC[tqeval; tqbilin] THEN CONV_TAC INT_RING);;

let INT_DISC7_BLOCK_CHARACTERISTIC = prove
 (`!l c e f:int.
     l pow 2 = &1
     ==> &2 divides (&2 - (&2 * e + l * c + c)) /\
         &2 divides (&2 - (l * e + &2 * c + e)) /\
         &2 divides (f - (c * e + e * c + f))`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPEC `l:int` INT_SQ_EQ_ONE) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  REWRITE_TAC[int_divides] THEN REPEAT CONJ_TAC THENL
   [EXISTS_TAC `&1 - e - c:int`;
    EXISTS_TAC `&1 - c - e:int`;
    EXISTS_TAC `--(c * e):int`;
    EXISTS_TAC `&1 - e:int`;
    EXISTS_TAC `&1 - c:int`;
    EXISTS_TAC `--(c * e):int`] THEN
  CONV_TAC INT_RING);;

let INT_DISC7_BLOCK_ODDITY5 = prove
 (`!l c e f:int.
     l pow 2 = &1 /\
     &2 * (&2 * f - e pow 2) -
       l * (l * f - c * e) + c * (l * e - &2 * c) = &7
     ==> ?q.
          tqeval (&2) l c (&2) e f e c (&1) = &8 * q + &5`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(LABEL_TAC "det" o check
    (fun th -> is_eq(concl th) && rand(concl th) = `(&7:int)`)) THEN
  MP_TAC(SPEC `l:int` INT_SQ_EQ_ONE) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THENL
   [EXISTS_TAC `e pow 2 + c pow 2 - f + &2:int`;
    EXISTS_TAC `e pow 2 + c pow 2 + e * c - f + &2:int`] THEN
  REMOVE_THEN "det" MP_TAC THEN
  REWRITE_TAC[tqeval] THEN CONV_TAC INT_RING);;

let DISC7_BLOCK2_TYPE1_FALSE = prove
 (`!l c e f:int.
     l pow 2 = &1 /\
     &2 * (&2 * f - e pow 2) -
       l * (l * f - c * e) + c * (l * e - &2 * c) = &7 /\
     ternary_type1 (&2) l c (&2) e f
     ==> F`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[ternary_type1]) THEN
  DISCH_THEN(X_CHOOSE_THEN `w1:int` (X_CHOOSE_THEN `w2:int`
    (X_CHOOSE_THEN `w3:int` (X_CHOOSE_THEN `q:int`
      (CONJUNCTS_THEN2 (LABEL_TAC "char") (LABEL_TAC "oddity1")))))) THEN
  MP_TAC(MATCH_MP (SPECL [`l:int`; `c:int`; `e:int`; `f:int`]
    INT_DISC7_BLOCK_CHARACTERISTIC) (ASSUME `l pow 2 = &1`)) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "vchar1")
    (CONJUNCTS_THEN2 (LABEL_TAC "vchar2") (LABEL_TAC "vchar3"))) THEN
  SUBGOAL_THEN
   `&2 divides
      (&2 * (w1 - e) + l * (w2 - c) + c * (w3 - &1)) /\
    &2 divides
      (l * (w1 - e) + &2 * (w2 - c) + e * (w3 - &1)) /\
    &2 divides
      (c * (w1 - e) + e * (w2 - c) + f * (w3 - &1))`
  (LABEL_TAC "diffs") THENL
   [REMOVE_THEN "char" (fun th ->
      MP_TAC(SPECL [`&1:int`; `&0:int`; `&0:int`] th) THEN
      MP_TAC(SPECL [`&0:int`; `&1:int`; `&0:int`] th) THEN
      MP_TAC(SPECL [`&0:int`; `&0:int`; `&1:int`] th)) THEN
    REWRITE_TAC[tqeval; tqbilin] THEN
    DISCH_THEN(LABEL_TAC "wchar3") THEN
    DISCH_THEN(LABEL_TAC "wchar2") THEN
    DISCH_THEN(LABEL_TAC "wchar1") THEN
    REMOVE_THEN "wchar1"
     (X_CHOOSE_TAC `s1:int` o REWRITE_RULE[int_divides]) THEN
    REMOVE_THEN "wchar2"
     (X_CHOOSE_TAC `s2:int` o REWRITE_RULE[int_divides]) THEN
    REMOVE_THEN "wchar3"
     (X_CHOOSE_TAC `s3:int` o REWRITE_RULE[int_divides]) THEN
    REMOVE_THEN "vchar1"
     (X_CHOOSE_TAC `t1:int` o REWRITE_RULE[int_divides]) THEN
    REMOVE_THEN "vchar2"
     (X_CHOOSE_TAC `t2:int` o REWRITE_RULE[int_divides]) THEN
    REMOVE_THEN "vchar3"
     (X_CHOOSE_TAC `t3:int` o REWRITE_RULE[int_divides]) THEN
    REWRITE_TAC[int_divides] THEN CONJ_TAC THENL
     [EXISTS_TAC `t1 - s1:int` THEN
      POP_ASSUM_LIST
       (fun ths -> MAP_EVERY MP_TAC (filter (is_eq o concl) ths)) THEN
      CONV_TAC INT_RING;
      CONJ_TAC THENL
       [EXISTS_TAC `t2 - s2:int` THEN
        POP_ASSUM_LIST
         (fun ths -> MAP_EVERY MP_TAC (filter (is_eq o concl) ths)) THEN
        CONV_TAC INT_RING;
        EXISTS_TAC `t3 - s3:int` THEN
        POP_ASSUM_LIST
         (fun ths -> MAP_EVERY MP_TAC (filter (is_eq o concl) ths)) THEN
        CONV_TAC INT_RING]];
    ALL_TAC] THEN
  REMOVE_THEN "diffs" STRIP_ASSUME_TAC THEN
  SUBGOAL_THEN
   `&2 divides (w1 - e) /\
    &2 divides (w2 - c) /\
    &2 divides (w3 - &1)`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL
     [`&2:int`; `l:int`; `c:int`; `&2:int`; `e:int`; `f:int`;
      `&7:int`; `w1 - e:int`; `w2 - c:int`; `w3 - &1:int`]
     INT_ODD_DET_KERNEL_MOD2) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [UNDISCH_TAC
       `&2 * (&2 * f - e pow 2) -
        l * (l * f - c * e) + c * (l * e - &2 * c) = &7` THEN
      CONV_TAC INT_RING;
      REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP (SPECL [`l:int`; `c:int`; `e:int`; `f:int`]
    INT_DISC7_BLOCK_ODDITY5)
    (CONJ
      (ASSUME `l pow 2 = &1`)
      (ASSUME
       `&2 * (&2 * f - e pow 2) -
        l * (l * f - c * e) + c * (l * e - &2 * c) = &7`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `r:int` (LABEL_TAC "oddity5")) THEN
  SUBGOAL_THEN `&8 divides (&4:int)` MP_TAC THENL
   [SUBGOAL_THEN
     `&8 divides
        (tqeval (&2) l c (&2) e f w1 w2 w3 -
         tqeval (&2) l c (&2) e f e c (&1))`
    MP_TAC THENL
     [MATCH_MP_TAC(SPECL
       [`&2:int`; `l:int`; `c:int`; `&2:int`; `e:int`; `f:int`;
       `e:int`; `c:int`; `&1:int`; `w1:int`; `w2:int`; `w3:int`]
       INT_CHARACTERISTIC_VALUES_CONG8) THEN
      ASM_REWRITE_TAC[INT_MUL_RID];
      DISCH_THEN(X_CHOOSE_THEN `d:int` (fun dth ->
        REWRITE_TAC[int_divides] THEN
        EXISTS_TAC `q - r - d:int` THEN
        MP_TAC dth THEN
        MAP_EVERY UNDISCH_TAC
         [`tqeval (&2) l c (&2) e f w1 w2 w3 = &8 * q + &1`;
          `tqeval (&2) l c (&2) e f e c (&1) = &8 * r + &5`] THEN
        CONV_TAC INT_RING) o REWRITE_RULE[int_divides])];
    REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV]);;

(* ------------------------------------------------------------------------- *)
(* Hence a determinant-seven type-1 lattice cannot have minimum two.        *)
(* ------------------------------------------------------------------------- *)

let DISC7_MIN2_EXCLUDED = prove
 (`!b12 b13 b22 b23 b33:int.
     &2 * (b22 * b33 - b23 pow 2) -
       b12 * (b12 * b33 - b13 * b23) +
       b13 * (b12 * b23 - b13 * b22) = &7 /\
     &0 < &2 * b22 - b12 pow 2 /\
     (!x y z. ~(x = &0 /\ y = &0 /\ z = &0)
              ==> &2 <= &2 * x pow 2 + b22 * y pow 2 +
                         b33 * z pow 2 + &2 * b12 * x * y +
                         &2 * b13 * x * z + &2 * b23 * y * z) /\
     ternary_type1 (&2) b12 b13 b22 b23 b33
     ==> F`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL
   [`b12:int`; `b13:int`; `b22:int`; `b23:int`; `b33:int`]
   HERMITE_DISC7_MIN2_PAIR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `r:int`
    (X_CHOOSE_THEN `s:int`
      (X_CHOOSE_THEN `t:int`
        (CONJUNCTS_THEN2
          (X_CHOOSE_THEN `p:int` (X_CHOOSE_TAC `q:int`))
          (LABEL_TAC "cases"))))) THEN
  ABBREV_TAC `l = &2 * r + b12 * s + b13 * t` THEN
  ABBREV_TAC
   `d = &2 * r pow 2 + b22 * s pow 2 + b33 * t pow 2 +
        &2 * b12 * r * s + &2 * b13 * r * t +
        &2 * b23 * s * t` THEN
  ABBREV_TAC `c = --(b12 * q) + b13 * p` THEN
  ABBREV_TAC
   `e = --(b12 * r * q) + b13 * r * p - b22 * s * q +
        b23 * s * p - b23 * t * q + b33 * t * p` THEN
  ABBREV_TAC
   `f = b22 * q pow 2 + b33 * p pow 2 - &2 * b23 * p * q` THEN
  SUBGOAL_THEN
   `&2 * (d * f - e pow 2) -
    l * (l * f - c * e) + c * (l * e - d * c) = &7`
  (LABEL_TAC "det") THENL
   [TRANS_TAC EQ_TRANS
     `(&2 * (b22 * b33 - b23 pow 2) -
       b12 * (b12 * b33 - b13 * b23) +
       b13 * (b12 * b23 - b13 * b22)) *
      (s * p + t * q) pow 2` THEN
    CONJ_TAC THENL
     [MAP_EVERY EXPAND_TAC ["l"; "d"; "c"; "e"; "f"] THEN
      CONV_TAC INT_RING;
      ASM_REWRITE_TAC[] THEN CONV_TAC INT_REDUCE_CONV];
    ALL_TAC] THEN
  SUBGOAL_THEN `ternary_type1 (&2) l c d e f`
  (LABEL_TAC "type1") THENL
   [MATCH_MP_TAC CONJ_TYPE1 THEN
    MAP_EVERY EXISTS_TAC
     [`&2:int`; `b12:int`; `b13:int`; `b22:int`; `b23:int`; `b33:int`;
      `&1:int`; `&0:int`; `&0:int`;
      `r:int`; `&0:int`; `s:int`; `--q:int`; `t:int`; `p:int`] THEN
    REPEAT CONJ_TAC THENL
     [UNDISCH_TAC `s * p + t * q = &1` THEN CONV_TAC INT_RING;
      CONV_TAC INT_RING;
      EXPAND_TAC "d" THEN CONV_TAC INT_RING;
      EXPAND_TAC "f" THEN CONV_TAC INT_RING;
      EXPAND_TAC "l" THEN CONV_TAC INT_RING;
      EXPAND_TAC "c" THEN CONV_TAC INT_RING;
      EXPAND_TAC "e" THEN CONV_TAC INT_RING;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REMOVE_THEN "cases"
    (REPEAT_TCL DISJ_CASES_THEN STRIP_ASSUME_TAC) THENL
   [SUBGOAL_THEN `d = &2 /\ l pow 2 = &1` STRIP_ASSUME_TAC THENL
     [MAP_EVERY EXPAND_TAC ["d"; "l"] THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(SPECL [`l:int`; `c:int`; `e:int`; `f:int`]
        DISC7_BLOCK2_TYPE1_FALSE) THEN
      ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [REMOVE_THEN "det" (fun th -> MP_TAC th THEN ASM_REWRITE_TAC[]);
        REMOVE_THEN "type1" (fun th -> MP_TAC th THEN ASM_REWRITE_TAC[])]];
    SUBGOAL_THEN `d = &2 /\ l = &0` STRIP_ASSUME_TAC THENL
     [MAP_EVERY EXPAND_TAC ["d"; "l"] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `&2 divides (&7:int)` MP_TAC THENL
     [REWRITE_TAC[int_divides] THEN
      EXISTS_TAC `(&2 * f - e pow 2 - c pow 2):int` THEN
      REMOVE_THEN "det" MP_TAC THEN ASM_REWRITE_TAC[] THEN
      CONV_TAC INT_RING;
      REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV]]);;

(* ------------------------------------------------------------------------- *)
(* The determinant-seven type-1 genus consists of the two advertised forms. *)
(* ------------------------------------------------------------------------- *)

let TERNARY_DISC7_TYPE1 = prove
 (`!a11 a12 a13 a22 a23 a33 n:int.
     &0 < a11 /\
     &0 < a11 * a22 - a12 pow 2 /\
     a11 * (a22 * a33 - a23 pow 2) -
       a12 * (a12 * a33 - a13 * a23) +
       a13 * (a12 * a23 - a13 * a22) = &7 /\
     ternary_type1 a11 a12 a13 a22 a23 a33 /\
     (?x y z.
        a11 * x pow 2 + a22 * y pow 2 + a33 * z pow 2 +
        &2 * a12 * x * y + &2 * a13 * x * z +
        &2 * a23 * y * z = n)
     ==> ((?u v w:int. u pow 2 + v pow 2 + &7 * w pow 2 = n) \/
          (?u v w:int.
             u pow 2 + &2 * v pow 2 + &2 * v * w +
             &4 * w pow 2 = n))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!x y z. ~(x = &0 /\ y = &0 /\ z = &0)
            ==> &0 < a11 * x pow 2 + a22 * y pow 2 + a33 * z pow 2 +
                     &2 * a12 * x * y + &2 * a13 * x * z +
                     &2 * a23 * y * z`
  (LABEL_TAC "posdef") THENL
   [MATCH_MP_TAC TERNARY_POSDEF THEN ASM_REWRITE_TAC[] THEN
    ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL
   [`a11:int`; `a12:int`; `a13:int`; `a22:int`; `a23:int`; `a33:int`]
   TERNARY_MIN) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `v1:int`
    (X_CHOOSE_THEN `v2:int`
      (X_CHOOSE_THEN `v3:int`
        (CONJUNCTS_THEN2 (LABEL_TAC "vnonzero")
          (LABEL_TAC "amin"))))) THEN
  SUBGOAL_THEN `?p q r. v1 * p + v2 * q + v3 * r = &1`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC MIN_PRIMITIVE THEN
    MAP_EVERY EXISTS_TAC
     [`a11:int`; `a12:int`; `a13:int`; `a22:int`; `a23:int`; `a33:int`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`v1:int`; `v2:int`; `v3:int`] SL3_EXTEND) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c12:int`
    (X_CHOOSE_THEN `c13:int`
      (X_CHOOSE_THEN `c22:int`
        (X_CHOOSE_THEN `c23:int`
          (X_CHOOSE_THEN `c32:int`
            (X_CHOOSE_THEN `c33:int` (LABEL_TAC "detU"))))))) THEN
  ABBREV_TAC
   `b11 = a11 * v1 pow 2 + &2 * a12 * v1 * v2 +
          &2 * a13 * v1 * v3 + a22 * v2 pow 2 +
          &2 * a23 * v2 * v3 + a33 * v3 pow 2` THEN
  ABBREV_TAC
   `b22 = a11 * c12 pow 2 + &2 * a12 * c12 * c22 +
          &2 * a13 * c12 * c32 + a22 * c22 pow 2 +
          &2 * a23 * c22 * c32 + a33 * c32 pow 2` THEN
  ABBREV_TAC
   `b33 = a11 * c13 pow 2 + &2 * a12 * c13 * c23 +
          &2 * a13 * c13 * c33 + a22 * c23 pow 2 +
          &2 * a23 * c23 * c33 + a33 * c33 pow 2` THEN
  ABBREV_TAC
   `b12 = a11 * v1 * c12 + a12 * (v1 * c22 + v2 * c12) +
          a13 * (v1 * c32 + v3 * c12) + a22 * v2 * c22 +
          a23 * (v2 * c32 + v3 * c22) + a33 * v3 * c32` THEN
  ABBREV_TAC
   `b13 = a11 * v1 * c13 + a12 * (v1 * c23 + v2 * c13) +
          a13 * (v1 * c33 + v3 * c13) + a22 * v2 * c23 +
          a23 * (v2 * c33 + v3 * c23) + a33 * v3 * c33` THEN
  ABBREV_TAC
   `b23 = a11 * c12 * c13 + a12 * (c12 * c23 + c22 * c13) +
          a13 * (c12 * c33 + c32 * c13) + a22 * c22 * c23 +
          a23 * (c22 * c33 + c32 * c23) + a33 * c32 * c33` THEN
  SUBGOAL_THEN
   `!x y z. ~(x = &0 /\ y = &0 /\ z = &0)
            ==> b11 <= b11 * x pow 2 + b22 * y pow 2 +
                       b33 * z pow 2 + &2 * b12 * x * y +
                       &2 * b13 * x * z + &2 * b23 * y * z`
  (LABEL_TAC "bmin") THENL
   [MATCH_MP_TAC CONJ_MIN THEN
    MAP_EVERY EXISTS_TAC
     [`a11:int`; `a12:int`; `a13:int`; `a22:int`; `a23:int`; `a33:int`;
      `v1:int`; `v2:int`; `v3:int`; `c12:int`; `c13:int`;
      `c22:int`; `c23:int`; `c32:int`; `c33:int`] THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXPAND_TAC ["b11"; "b12"; "b13"; "b22"; "b23"; "b33"];
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 < b11` ASSUME_TAC THENL
   [MP_TAC(MATCH_MP
     (SPECL [`v1:int`; `v2:int`; `v3:int`]
       (ASSUME
        `!x y z. ~(x = &0 /\ y = &0 /\ z = &0)
                 ==> &0 < a11 * x pow 2 + a22 * y pow 2 +
                          a33 * z pow 2 + &2 * a12 * x * y +
                          &2 * a13 * x * z + &2 * a23 * y * z`))
     (ASSUME `~(v1 = &0 /\ v2 = &0 /\ v3 = &0)`)) THEN
    EXPAND_TAC "b11" THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `b11 * (b22 * b33 - b23 pow 2) -
    b12 * (b12 * b33 - b13 * b23) +
    b13 * (b12 * b23 - b13 * b22) = &7`
  (LABEL_TAC "bdet") THENL
   [TRANS_TAC EQ_TRANS
     `(a11 * (a22 * a33 - a23 pow 2) -
       a12 * (a12 * a33 - a13 * a23) +
       a13 * (a12 * a23 - a13 * a22)) *
      (v1 * (c22 * c33 - c23 * c32) -
       c12 * (v2 * c33 - c23 * v3) +
       c13 * (v2 * c32 - c22 * v3)) pow 2` THEN
    CONJ_TAC THENL
     [MAP_EVERY EXPAND_TAC
       ["b11"; "b12"; "b13"; "b22"; "b23"; "b33"] THEN
      CONV_TAC INT_RING;
      USE_THEN "detU" (fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC INT_REDUCE_CONV];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!x y z. ~(x = &0 /\ y = &0 /\ z = &0)
            ==> &0 < b11 * x pow 2 + b22 * y pow 2 +
                     b33 * z pow 2 + &2 * b12 * x * y +
                     &2 * b13 * x * z + &2 * b23 * y * z`
  (LABEL_TAC "bposdef") THENL
   [REPEAT STRIP_TAC THEN
    MATCH_MP_TAC INT_LTE_TRANS THEN EXISTS_TAC `b11:int` THEN
    ASM_REWRITE_TAC[] THEN USE_THEN "bmin" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 < b11 * b22 - b12 pow 2`
  (LABEL_TAC "bminor") THENL
   [MATCH_MP_TAC POSDEF_MINOR2 THEN
    MAP_EVERY EXISTS_TAC [`b13:int`; `b23:int`; `b33:int`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `ternary_type1 b11 b12 b13 b22 b23 b33`
  (LABEL_TAC "btype1") THENL
   [MATCH_MP_TAC CONJ_TYPE1 THEN
    MAP_EVERY EXISTS_TAC
     [`a11:int`; `a12:int`; `a13:int`; `a22:int`; `a23:int`; `a33:int`;
      `v1:int`; `v2:int`; `v3:int`; `c12:int`; `c13:int`;
      `c22:int`; `c23:int`; `c32:int`; `c33:int`] THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXPAND_TAC ["b11"; "b12"; "b13"; "b22"; "b23"; "b33"];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!r:int.
      (?x y z.
         a11 * x pow 2 + a22 * y pow 2 + a33 * z pow 2 +
         &2 * a12 * x * y + &2 * a13 * x * z +
         &2 * a23 * y * z = r)
      ==> ?x y z.
            b11 * x pow 2 + b22 * y pow 2 + b33 * z pow 2 +
            &2 * b12 * x * y + &2 * b13 * x * z +
            &2 * b23 * y * z = r`
  (LABEL_TAC "transfer") THENL
   [X_GEN_TAC `r0:int` THEN DISCH_TAC THEN
    MATCH_MP_TAC CONJ_REPS THEN
    MAP_EVERY EXISTS_TAC
     [`a11:int`; `a12:int`; `a13:int`; `a22:int`; `a23:int`; `a33:int`;
      `v1:int`; `v2:int`; `v3:int`; `c12:int`; `c13:int`;
      `c22:int`; `c23:int`; `c32:int`; `c33:int`] THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXPAND_TAC ["b11"; "b12"; "b13"; "b22"; "b23"; "b33"];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?x y z.
      a11 * x pow 2 + a22 * y pow 2 + a33 * z pow 2 +
      &2 * a12 * x * y + &2 * a13 * x * z +
      &2 * a23 * y * z = n`
  (LABEL_TAC "anrep") THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  USE_THEN "transfer" (fun tr ->
    USE_THEN "anrep" (fun th -> MP_TAC(MATCH_MP (SPEC `n:int` tr) th))) THEN
  DISCH_THEN(LABEL_TAC "bnrep") THEN
  MP_TAC(SPECL
   [`b11:int`; `b12:int`; `b13:int`; `b22:int`; `b23:int`; `b33:int`]
   HERMITE_DISC7_LE2) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
   [MATCH_MP_TAC TERNARY_DISC7_A11_1 THEN
    MAP_EVERY EXISTS_TAC
     [`b12:int`; `b13:int`; `b22:int`; `b23:int`; `b33:int`] THEN
    REPEAT CONJ_TAC THENL
     [REMOVE_THEN "bminor"
       (fun th -> MP_TAC th THEN ASM_REWRITE_TAC[INT_MUL_LID]);
      REMOVE_THEN "bdet"
       (fun th ->
         MP_TAC th THEN ASM_REWRITE_TAC[INT_MUL_LID] THEN
         CONV_TAC INT_RING);
      REMOVE_THEN "bnrep"
       (fun th -> MP_TAC th THEN ASM_REWRITE_TAC[INT_MUL_LID])];
    SUBGOAL_THEN `F` MP_TAC THENL
     [MATCH_MP_TAC(SPECL
       [`b12:int`; `b13:int`; `b22:int`; `b23:int`; `b33:int`]
       DISC7_MIN2_EXCLUDED) THEN
      REPEAT CONJ_TAC THENL
       [REMOVE_THEN "bdet"
         (fun th -> MP_TAC th THEN ASM_REWRITE_TAC[] THEN
           CONV_TAC INT_RING);
        REMOVE_THEN "bminor"
         (fun th -> MP_TAC th THEN ASM_REWRITE_TAC[]);
        REMOVE_THEN "bmin"
         (fun th -> MP_TAC th THEN ASM_REWRITE_TAC[]);
        REMOVE_THEN "btype1"
         (fun th -> MP_TAC th THEN ASM_REWRITE_TAC[])];
      MESON_TAC[]]]);;

let DIAG7_TO_CROSS124_YZ = prove
 (`!n x y z e:int.
     x pow 2 + y pow 2 + &7 * z pow 2 = n /\ y + z = &2 * e
     ==> ?u v w.
          u pow 2 + &2 * v pow 2 + &2 * v * w + &4 * w pow 2 = n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MAP_EVERY EXISTS_TAC [`x:int`; `z + e:int`; `z - e:int`] THEN
  MAP_EVERY UNDISCH_TAC
   [`x pow 2 + y pow 2 + &7 * z pow 2 = n`; `y + z = &2 * e`] THEN
  CONV_TAC INT_RING);;

let DIAG7_TO_CROSS124_XZ = prove
 (`!n x y z e:int.
     x pow 2 + y pow 2 + &7 * z pow 2 = n /\ x + z = &2 * e
     ==> ?u v w.
          u pow 2 + &2 * v pow 2 + &2 * v * w + &4 * w pow 2 = n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MAP_EVERY EXISTS_TAC [`y:int`; `z + e:int`; `z - e:int`] THEN
  MAP_EVERY UNDISCH_TAC
   [`x pow 2 + y pow 2 + &7 * z pow 2 = n`; `x + z = &2 * e`] THEN
  CONV_TAC INT_RING);;

let DIAG7_EEO_NOT_MOD4_01 = prove
 (`!a b c q:int.
     ~(((&2 * a) pow 2 + (&2 * b) pow 2 +
         &7 * (&2 * c + &1) pow 2 = &4 * q) \/
       ((&2 * a) pow 2 + (&2 * b) pow 2 +
         &7 * (&2 * c + &1) pow 2 = &4 * q + &1))`,
  REPEAT GEN_TAC THEN DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
   [SUBGOAL_THEN `&4 divides (&7:int)` MP_TAC THENL
     [REWRITE_TAC[int_divides] THEN
      EXISTS_TAC
       `q - a pow 2 - b pow 2 - &7 * c pow 2 - &7 * c:int` THEN
      FIRST_X_ASSUM MP_TAC THEN CONV_TAC INT_RING;
      REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV];
    SUBGOAL_THEN `&4 divides (&6:int)` MP_TAC THENL
     [REWRITE_TAC[int_divides] THEN
      EXISTS_TAC
       `q - a pow 2 - b pow 2 - &7 * c pow 2 - &7 * c:int` THEN
      FIRST_X_ASSUM MP_TAC THEN CONV_TAC INT_RING;
      REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV]]);;

let DIAG7_OOE_NOT_MOD4_01 = prove
 (`!a b c q:int.
     ~(((&2 * a + &1) pow 2 + (&2 * b + &1) pow 2 +
         &7 * (&2 * c) pow 2 = &4 * q) \/
       ((&2 * a + &1) pow 2 + (&2 * b + &1) pow 2 +
         &7 * (&2 * c) pow 2 = &4 * q + &1))`,
  REPEAT GEN_TAC THEN DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
   [SUBGOAL_THEN `&4 divides (&2:int)` MP_TAC THENL
     [REWRITE_TAC[int_divides] THEN
      EXISTS_TAC
       `(q - a pow 2 - a - b pow 2 - b - &7 * c pow 2):int` THEN
      FIRST_X_ASSUM MP_TAC THEN CONV_TAC INT_RING;
      REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV];
    SUBGOAL_THEN `&4 divides (&1:int)` MP_TAC THENL
     [REWRITE_TAC[int_divides] THEN
      EXISTS_TAC
       `(q - a pow 2 - a - b pow 2 - b - &7 * c pow 2):int` THEN
      FIRST_X_ASSUM MP_TAC THEN CONV_TAC INT_RING;
      REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV]]);;

let DIAG7_MOD4_PARITY = prove
 (`!x y z:int.
     (?q. x pow 2 + y pow 2 + &7 * z pow 2 = &4 * q \/
          x pow 2 + y pow 2 + &7 * z pow 2 = &4 * q + &1)
     ==> (?e. y + z = &2 * e) \/ (?e. x + z = &2 * e)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `q:int` ASSUME_TAC) THEN
  MP_TAC(SPEC `z:int` INT_PARITY_WITNESS) THEN
  MP_TAC(SPEC `y:int` INT_PARITY_WITNESS) THEN
  MP_TAC(SPEC `x:int` INT_PARITY_WITNESS) THEN
  DISCH_THEN(DISJ_CASES_THEN (X_CHOOSE_THEN `a:int` ASSUME_TAC)) THEN
  DISCH_THEN(DISJ_CASES_THEN (X_CHOOSE_THEN `b:int` ASSUME_TAC)) THEN
  DISCH_THEN(DISJ_CASES_THEN (X_CHOOSE_THEN `c:int` ASSUME_TAC)) THENL
   [DISJ1_TAC THEN EXISTS_TAC `b + c:int` THEN ASM_REWRITE_TAC[] THEN
    CONV_TAC INT_RING;
    SUBGOAL_THEN `F` MP_TAC THENL
     [MP_TAC(SPECL [`a:int`; `b:int`; `c:int`; `q:int`]
       DIAG7_EEO_NOT_MOD4_01) THEN ASM_MESON_TAC[];
      MESON_TAC[]];
    DISJ2_TAC THEN EXISTS_TAC `a + c:int` THEN ASM_REWRITE_TAC[] THEN
    CONV_TAC INT_RING;
    DISJ1_TAC THEN EXISTS_TAC `b + c + &1:int` THEN ASM_REWRITE_TAC[] THEN
    CONV_TAC INT_RING;
    DISJ1_TAC THEN EXISTS_TAC `b + c:int` THEN ASM_REWRITE_TAC[] THEN
    CONV_TAC INT_RING;
    DISJ2_TAC THEN EXISTS_TAC `a + c + &1:int` THEN ASM_REWRITE_TAC[] THEN
    CONV_TAC INT_RING;
    SUBGOAL_THEN `F` MP_TAC THENL
     [MP_TAC(SPECL [`a:int`; `b:int`; `c:int`; `q:int`]
       DIAG7_OOE_NOT_MOD4_01) THEN ASM_MESON_TAC[];
      MESON_TAC[]];
    DISJ1_TAC THEN EXISTS_TAC `b + c + &1:int` THEN ASM_REWRITE_TAC[] THEN
    CONV_TAC INT_RING]);;

let REPR_CROSS124_OF_DIAG7_MOD4 = prove
 (`!n:int.
     (?x y z. x pow 2 + y pow 2 + &7 * z pow 2 = n) /\
     (?q. n = &4 * q \/ n = &4 * q + &1)
     ==> ?x y z.
          x pow 2 + &2 * y pow 2 + &2 * y * z +
          &4 * z pow 2 = n`,
  GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2
    (X_CHOOSE_THEN `x:int`
      (X_CHOOSE_THEN `y:int`
        (X_CHOOSE_THEN `z:int` (LABEL_TAC "repr"))))
    (X_CHOOSE_THEN `q:int` (LABEL_TAC "mod4"))) THEN
  MP_TAC(SPECL [`x:int`; `y:int`; `z:int`] DIAG7_MOD4_PARITY) THEN
  ANTS_TAC THENL
   [EXISTS_TAC `q:int` THEN
    USE_THEN "repr" MP_TAC THEN USE_THEN "mod4" MP_TAC THEN
    MESON_TAC[];
    DISCH_THEN(DISJ_CASES_THEN
      (X_CHOOSE_THEN `e:int` ASSUME_TAC)) THENL
     [MATCH_MP_TAC(SPECL [`n:int`; `x:int`; `y:int`; `z:int`; `e:int`]
       DIAG7_TO_CROSS124_YZ) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(SPECL [`n:int`; `x:int`; `y:int`; `z:int`; `e:int`]
       DIAG7_TO_CROSS124_XZ) THEN
      ASM_REWRITE_TAC[]]]);;

let CROSS124_TO_DIAG7_YZ = prove
 (`!n x y z e:int.
     x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 = n /\
     y + z = &2 * e
     ==> ?u v w. u pow 2 + v pow 2 + &7 * w pow 2 = n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MAP_EVERY EXISTS_TAC [`x:int`; `e - &2 * z:int`; `e:int`] THEN
  MAP_EVERY UNDISCH_TAC
   [`x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 = n`;
    `y + z = &2 * e`] THEN
  CONV_TAC INT_RING);;

let CROSS124_TO_DIAG7_Y_EVEN = prove
 (`!n x y z e:int.
     x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 = n /\
     y = &2 * e
     ==> ?u v w. u pow 2 + v pow 2 + &7 * w pow 2 = n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MAP_EVERY EXISTS_TAC [`x:int`; `--e - &2 * z:int`; `--e:int`] THEN
  MAP_EVERY UNDISCH_TAC
   [`x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 = n`;
    `y = &2 * e`] THEN
  CONV_TAC INT_RING);;

let CROSS124_EOE_NOT_MOD4_01 = prove
 (`!a b c q:int.
     ~(((&2 * a) pow 2 + &2 * (&2 * b + &1) pow 2 +
         &2 * (&2 * b + &1) * (&2 * c) + &4 * (&2 * c) pow 2 = &4 * q) \/
       ((&2 * a) pow 2 + &2 * (&2 * b + &1) pow 2 +
         &2 * (&2 * b + &1) * (&2 * c) + &4 * (&2 * c) pow 2 =
         &4 * q + &1))`,
  REPEAT GEN_TAC THEN DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
   [SUBGOAL_THEN `&4 divides (&2:int)` MP_TAC THENL
     [REWRITE_TAC[int_divides] THEN
      EXISTS_TAC
       `(q - a pow 2 - &2 * b pow 2 - &2 * b -
          &2 * b * c - c - &4 * c pow 2):int` THEN
      FIRST_X_ASSUM MP_TAC THEN CONV_TAC INT_RING;
      REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV];
    SUBGOAL_THEN `&4 divides (&1:int)` MP_TAC THENL
     [REWRITE_TAC[int_divides] THEN
      EXISTS_TAC
       `(q - a pow 2 - &2 * b pow 2 - &2 * b -
          &2 * b * c - c - &4 * c pow 2):int` THEN
      FIRST_X_ASSUM MP_TAC THEN CONV_TAC INT_RING;
      REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV]]);;

let CROSS124_OOE_NOT_MOD4_01 = prove
 (`!a b c q:int.
     ~(((&2 * a + &1) pow 2 + &2 * (&2 * b + &1) pow 2 +
         &2 * (&2 * b + &1) * (&2 * c) + &4 * (&2 * c) pow 2 = &4 * q) \/
       ((&2 * a + &1) pow 2 + &2 * (&2 * b + &1) pow 2 +
         &2 * (&2 * b + &1) * (&2 * c) + &4 * (&2 * c) pow 2 =
         &4 * q + &1))`,
  REPEAT GEN_TAC THEN DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
   [SUBGOAL_THEN `&4 divides (&3:int)` MP_TAC THENL
     [REWRITE_TAC[int_divides] THEN
      EXISTS_TAC
       `(q - a pow 2 - a - &2 * b pow 2 - &2 * b -
          &2 * b * c - c - &4 * c pow 2):int` THEN
      FIRST_X_ASSUM MP_TAC THEN CONV_TAC INT_RING;
      REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV];
    SUBGOAL_THEN `&4 divides (&2:int)` MP_TAC THENL
     [REWRITE_TAC[int_divides] THEN
      EXISTS_TAC
       `(q - a pow 2 - a - &2 * b pow 2 - &2 * b -
          &2 * b * c - c - &4 * c pow 2):int` THEN
      FIRST_X_ASSUM MP_TAC THEN CONV_TAC INT_RING;
      REWRITE_TAC[GSYM INT_REM_EQ_0] THEN CONV_TAC INT_REDUCE_CONV]]);;

let REPR_DIAG7_OF_CROSS124_MOD4 = prove
 (`!n:int.
     (?x y z.
        x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 = n) /\
     (?q. n = &4 * q \/ n = &4 * q + &1)
     ==> ?x y z. x pow 2 + y pow 2 + &7 * z pow 2 = n`,
  GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2
    (X_CHOOSE_THEN `x:int`
      (X_CHOOSE_THEN `y:int`
        (X_CHOOSE_THEN `z:int` (LABEL_TAC "repr"))))
    (X_CHOOSE_THEN `q:int` (LABEL_TAC "mod4"))) THEN
  MP_TAC(SPEC `z:int` INT_PARITY_WITNESS) THEN
  MP_TAC(SPEC `y:int` INT_PARITY_WITNESS) THEN
  MP_TAC(SPEC `x:int` INT_PARITY_WITNESS) THEN
  DISCH_THEN(DISJ_CASES_THEN (X_CHOOSE_THEN `a:int` ASSUME_TAC)) THEN
  DISCH_THEN(DISJ_CASES_THEN (X_CHOOSE_THEN `b:int` ASSUME_TAC)) THEN
  DISCH_THEN(DISJ_CASES_THEN (X_CHOOSE_THEN `c:int` ASSUME_TAC)) THENL
   [MATCH_MP_TAC(SPECL [`n:int`; `x:int`; `y:int`; `z:int`; `b:int`]
      CROSS124_TO_DIAG7_Y_EVEN) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(SPECL [`n:int`; `x:int`; `y:int`; `z:int`; `b:int`]
      CROSS124_TO_DIAG7_Y_EVEN) THEN ASM_REWRITE_TAC[];
    SUBGOAL_THEN `F` MP_TAC THENL
     [MP_TAC(SPECL [`a:int`; `b:int`; `c:int`; `q:int`]
       CROSS124_EOE_NOT_MOD4_01) THEN
      USE_THEN "repr" MP_TAC THEN USE_THEN "mod4" MP_TAC THEN
      ASM_MESON_TAC[];
      MESON_TAC[]];
    MATCH_MP_TAC(SPECL
     [`n:int`; `x:int`; `y:int`; `z:int`; `b + c + &1:int`]
      CROSS124_TO_DIAG7_YZ) THEN ASM_REWRITE_TAC[] THEN
    CONV_TAC INT_RING;
    MATCH_MP_TAC(SPECL [`n:int`; `x:int`; `y:int`; `z:int`; `b:int`]
      CROSS124_TO_DIAG7_Y_EVEN) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(SPECL [`n:int`; `x:int`; `y:int`; `z:int`; `b:int`]
      CROSS124_TO_DIAG7_Y_EVEN) THEN ASM_REWRITE_TAC[];
    SUBGOAL_THEN `F` MP_TAC THENL
     [MP_TAC(SPECL [`a:int`; `b:int`; `c:int`; `q:int`]
       CROSS124_OOE_NOT_MOD4_01) THEN
      USE_THEN "repr" MP_TAC THEN USE_THEN "mod4" MP_TAC THEN
      ASM_MESON_TAC[];
      MESON_TAC[]];
    MATCH_MP_TAC(SPECL
     [`n:int`; `x:int`; `y:int`; `z:int`; `b + c + &1:int`]
      CROSS124_TO_DIAG7_YZ) THEN ASM_REWRITE_TAC[] THEN
    CONV_TAC INT_RING]);;

(* ------------------------------------------------------------------------- *)
(* Parity and odd-square facts used to identify the 2-adic genus.           *)
(* ------------------------------------------------------------------------- *)

let INT_ODD_SQUARE_8_WITNESS = prove
 (`!x:int. ~(&2 divides x) ==> ?q:int. x pow 2 = &8 * q + &1`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`(x pow 2):int`; `&8:int`] INT_DIVISION) THEN
  ANTS_TAC THENL [CONV_TAC INT_REDUCE_CONV; STRIP_TAC] THEN
  EXISTS_TAC `x pow 2 div &8` THEN
  UNDISCH_TAC
   `x pow 2 = x pow 2 div &8 * &8 + x pow 2 rem &8` THEN
  MP_TAC(MATCH_MP
   (snd(EQ_IMP_RULE(SPEC `x:int` ODD_SQ_MOD_8)))
   (ASSUME `~(&2 divides x)`)) THEN
  CONV_TAC INT_RING);;

let INT_DISC7_DIRICHLET_A11_PARITY = prove
 (`!a11 t D n:int.
     a11 * (&8 * D * n - &7) - t pow 2 = &8 * D
     ==> &2 divides (a11 - t)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPEC `t:int` INT_SQ_SUB_SELF_EVEN) THEN
  REWRITE_TAC[int_divides] THEN
  DISCH_THEN(X_CHOOSE_THEN `q:int` ASSUME_TAC) THEN
  REWRITE_TAC[int_divides] THEN
  EXISTS_TAC `(&4 * D - a11 * (&4 * D * n - &4) + q):int` THEN
  MAP_EVERY UNDISCH_TAC
   [`a11 * (&8 * D * n - &7) - t pow 2 = &8 * D`;
    `t pow 2 - t = &2 * q`] THEN
  CONV_TAC INT_RING);;

let DISC7_DIRICHLET_TYPE1 = prove
 (`!a11 t D n:int.
     a11 * (&8 * D * n - &7) - t pow 2 = &8 * D
     ==> ternary_type1
          a11 t (&1) (&8 * D * n - &7) (&0) n`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPEC `n:int` INT_PARITY_WITNESS) THEN
  DISCH_THEN(DISJ_CASES_THEN (X_CHOOSE_THEN `r:int` ASSUME_TAC)) THENL
   [MATCH_MP_TAC(SPECL
     [`a11:int`; `t:int`; `&1:int`; `&8 * D * n - &7:int`;
      `&0:int`; `n:int`; `&0:int`; `&1:int`; `&0:int`;
      `D * n - &1:int`] TERNARY_TYPE1_OF_CHARACTERISTIC) THEN
    REPEAT CONJ_TAC THENL
      [MP_TAC(SPECL [`a11:int`; `t:int`; `D:int`; `n:int`]
        INT_DISC7_DIRICHLET_A11_PARITY) THEN
      ASM_REWRITE_TAC[] THEN
      REWRITE_TAC
       [INT_MUL_RZERO; INT_MUL_RID; INT_ADD_LID; INT_ADD_RID];
      REWRITE_TAC[int_divides] THEN EXISTS_TAC `&0:int` THEN
      CONV_TAC INT_RING;
      REWRITE_TAC[int_divides] THEN EXISTS_TAC `r:int` THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING;
      REWRITE_TAC[tqeval] THEN CONV_TAC INT_RING];
    ALL_TAC] THEN
  MP_TAC(SPEC `t:int` INT_PARITY_WITNESS) THEN
  DISCH_THEN(DISJ_CASES_THEN (X_CHOOSE_THEN `s:int` ASSUME_TAC)) THENL
   [MP_TAC(SPEC `t + &1:int` INT_ODD_SQUARE_8_WITNESS) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[INT_2_DIVIDES_ADD] THEN
      REWRITE_TAC[INT_DIVIDES_ONE] THEN CONV_TAC INT_REDUCE_CONV THEN
      REWRITE_TAC[int_divides] THEN EXISTS_TAC `s:int` THEN
      CONV_TAC INT_RING;
      DISCH_THEN(X_CHOOSE_THEN `q:int` ASSUME_TAC)] THEN
    MATCH_MP_TAC(SPECL
     [`a11:int`; `t:int`; `&1:int`; `&8 * D * n - &7:int`;
      `&0:int`; `n:int`; `&1:int`; `&1:int`; `&0:int`;
      `q + D + (D * n - &1) * (&1 - a11):int`]
     TERNARY_TYPE1_OF_CHARACTERISTIC) THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[int_divides] THEN EXISTS_TAC `--s:int` THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING;
      REWRITE_TAC[int_divides] THEN EXISTS_TAC `--s:int` THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING;
      REWRITE_TAC[int_divides] THEN EXISTS_TAC `r:int` THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING;
      MAP_EVERY UNDISCH_TAC
       [`a11 * (&8 * D * n - &7) - t pow 2 = &8 * D`;
        `(t + &1) pow 2 = &8 * q + &1`] THEN
      REWRITE_TAC[tqeval] THEN CONV_TAC INT_RING];
    MP_TAC(SPEC `t:int` INT_ODD_SQUARE_8_WITNESS) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[INT_2_DIVIDES_ADD] THEN
      REWRITE_TAC[INT_DIVIDES_ONE] THEN CONV_TAC INT_REDUCE_CONV THEN
      REWRITE_TAC[int_divides] THEN EXISTS_TAC `s:int` THEN
      CONV_TAC INT_RING;
      DISCH_THEN(X_CHOOSE_THEN `q:int` ASSUME_TAC)] THEN
    MATCH_MP_TAC(SPECL
     [`a11:int`; `t:int`; `&1:int`; `&8 * D * n - &7:int`;
      `&0:int`; `n:int`; `&1:int`; `&0:int`; `&0:int`;
      `q + D - (D * n - &1) * a11:int`]
     TERNARY_TYPE1_OF_CHARACTERISTIC) THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[int_divides] THEN EXISTS_TAC `&0:int` THEN
      CONV_TAC INT_RING;
      REWRITE_TAC[int_divides] THEN
      EXISTS_TAC `(&4 * D * n - s - &4):int` THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING;
      REWRITE_TAC[int_divides] THEN EXISTS_TAC `r:int` THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING;
      MAP_EVERY UNDISCH_TAC
       [`a11 * (&8 * D * n - &7) - t pow 2 = &8 * D`;
        `t pow 2 = &8 * q + &1`] THEN
      REWRITE_TAC[tqeval] THEN CONV_TAC INT_RING]]);;

(* ------------------------------------------------------------------------- *)
(* Determinant-7 analogue of the matrix construction in LEMMA_1_7.          *)
(*                                                                           *)
(* The matrix                                                              *)
(*                                                                           *)
(*   [ a11   t   1 ]                                                        *)
(*   [  t   8Dn-7 0 ]                                                       *)
(*   [  1    0   n ]                                                        *)
(*                                                                           *)
(* has determinant 7 when a11(8Dn-7)-t^2=8D, and represents n on its last  *)
(* coordinate. The preceding theorem places it in the required 2-adic genus. *)
(* ------------------------------------------------------------------------- *)

let DISC7_DIRICHLET_GENUS_REPRESENTS = prove
 (`!n D t:int.
     &1 < n /\ &0 < D /\
     (&8 * D * n - &7) divides (t pow 2 + &8 * D)
     ==> (?x y z:int. x pow 2 + y pow 2 + &7 * z pow 2 = n) \/
         (?x y z:int.
            x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 = n)`,
  REPEAT STRIP_TAC THEN
  UNDISCH_TAC `(&8 * D * n - &7) divides (t pow 2 + &8 * D)` THEN
  REWRITE_TAC[int_divides] THEN
  DISCH_THEN(X_CHOOSE_THEN `a11:int` (LABEL_TAC "quotient")) THEN
  SUBGOAL_THEN `&0 < &8 * D * n - &7` ASSUME_TAC THENL
   [SUBGOAL_THEN `&1 * &2 <= D * n` MP_TAC THENL
     [MATCH_MP_TAC INT_LE_MUL2 THEN ASM_INT_ARITH_TAC;
      INT_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `a11 * (&8 * D * n - &7) - t pow 2 = &8 * D`
  ASSUME_TAC THENL
   [USE_THEN "quotient" MP_TAC THEN CONV_TAC INT_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 < a11` ASSUME_TAC THENL
   [SUBGOAL_THEN `&0 < a11 * (&8 * D * n - &7)` MP_TAC THENL
     [SUBGOAL_THEN
       `a11 * (&8 * D * n - &7) = t pow 2 + &8 * D`
      SUBST1_TAC THENL
       [ASM_INT_ARITH_TAC;
        MP_TAC(SPEC `t:int` INT_LE_POW_2) THEN ASM_INT_ARITH_TAC];
      ASM_SIMP_TAC[INT_LT_MUL_EQ]];
    ALL_TAC] THEN
  MATCH_MP_TAC(SPECL
   [`a11:int`; `t:int`; `&1:int`; `&8 * D * n - &7:int`;
    `&0:int`; `n:int`; `n:int`] TERNARY_DISC7_TYPE1) THEN
  REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    ASM_INT_ARITH_TAC;
    UNDISCH_TAC
     `a11 * (&8 * D * n - &7) - t pow 2 = &8 * D` THEN
    CONV_TAC INT_RING;
    MATCH_MP_TAC DISC7_DIRICHLET_TYPE1 THEN ASM_REWRITE_TAC[];
    MAP_EVERY EXISTS_TAC [`&0:int`; `&0:int`; `&1:int`] THEN
    CONV_TAC INT_RING]);;

(* ------------------------------------------------------------------------- *)
(* The Dirichlet progression p = 8n - 7 (mod 112n).                         *)
(* ------------------------------------------------------------------------- *)

let CONG_DISC7_OFFSET_7 = prove
 (`!n:num. 1 <= n ==> (8*n-7 == n) (mod 7)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `8*n-7 = (n-1)*7+n` SUBST1_TAC THENL
   [ASM_ARITH_TAC;
    REWRITE_TAC[CONG] THEN SIMP_TAC[MOD_MULT_ADD]]);;

let COPRIME_DISC7_OFFSET_N = prove
 (`!n:num.
     1 <= n /\ ~(7 divides n)
     ==> coprime(8*n-7,n)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[COPRIME] THEN X_GEN_TAC `d:num` THEN EQ_TAC THENL
   [STRIP_TAC THEN
    SUBGOAL_THEN `d divides 8*n` ASSUME_TAC THENL
     [MATCH_MP_TAC(SPECL [`d:num`; `n:num`; `8`] DIVIDES_LMUL) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `d divides 7` ASSUME_TAC THENL
     [SUBGOAL_THEN `7 = 8*n - (8*n-7)` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        MATCH_MP_TAC(SPECL [`d:num`; `8*n`; `8*n-7`] DIVIDES_SUB) THEN
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN `coprime(7,n)` ASSUME_TAC THENL
     [ASM_REWRITE_TAC[MATCH_MP (SPEC `7` PRIME_COPRIME_EQ)
       (EQT_ELIM(PRIME_CONV `prime 7`))];
      MP_TAC(SPEC `d:num`
        (REWRITE_RULE[COPRIME] (ASSUME `coprime(7,n)`))) THEN
      ASM_REWRITE_TAC[]];
    DISCH_TAC THEN ASM_REWRITE_TAC[DIVIDES_1]]);;

let COPRIME_DISC7_OFFSET_112 = prove
 (`!n:num.
     1 <= n /\ ~(7 divides n)
     ==> coprime(8*n-7,112)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `ODD(8*n-7)` ASSUME_TAC THENL
   [REWRITE_TAC[ODD_EXISTS] THEN EXISTS_TAC `4*n-4` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~(7 divides (8*n-7))` ASSUME_TAC THENL
   [MP_TAC(MATCH_MP (SPECL [`8*n-7`; `n:num`; `7`] CONG_DIVIDES)
      (MATCH_MP (SPEC `n:num` CONG_DISC7_OFFSET_7)
        (ASSUME `1 <= n`))) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[ARITH_RULE `112 = 2*2*2*2*7`; COPRIME_RMUL] THEN
  ASM_REWRITE_TAC[CONJUNCT2 COPRIME_2] THEN
  ONCE_REWRITE_TAC[COPRIME_SYM] THEN
  ASM_REWRITE_TAC[MATCH_MP (SPEC `7` PRIME_COPRIME_EQ)
    (EQT_ELIM(PRIME_CONV `prime 7`))]);;

let COPRIME_DIRICHLET_DISC7 = prove
 (`!n:num.
     1 <= n /\ ~(7 divides n)
     ==> coprime(8*n-7,112*n)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[COPRIME_RMUL] THEN CONJ_TAC THENL
   [MATCH_MP_TAC COPRIME_DISC7_OFFSET_112 THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC COPRIME_DISC7_OFFSET_N THEN ASM_REWRITE_TAC[]]);;

let DIRICHLET_PRIME_DISC7 = prove
 (`!n:num.
     1 <= n /\ ~(7 divides n)
     ==> ?p. prime p /\ (p == 8*n-7) (mod (112*n))`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC DIRICHLET_PRIME_CONG THEN
  ASM_SIMP_TAC[COPRIME_DIRICHLET_DISC7] THEN ASM_ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* The reciprocity calculation for D = 14j+1.                               *)
(* ------------------------------------------------------------------------- *)

let COPRIME_7_14J1 = prove
 (`!j:num. coprime(7,14*j+1)`,
  GEN_TAC THEN REWRITE_TAC[COPRIME_BEZOUT] THEN
  MAP_EVERY EXISTS_TAC [`1`; `2*j`] THEN DISJ2_TAC THEN ARITH_TAC);;

let CONG_14J1_7 = NUMBER_RULE
 `!j:num. (14*j+1 == 1) (mod 7)`;;

let CONG_NEG7_14J1 = prove
 (`!n j:num.
     1 <= n
     ==> (8*n*(14*j+1)-7 == 7*(14*j+1)-7) (mod (14*j+1))`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC CONG_SUB THEN
  REPEAT CONJ_TAC THENL
   [CONV_TAC NUMBER_RULE;
    REWRITE_TAC[CONG_REFL];
    ASM_ARITH_TAC;
    ARITH_TAC]);;

let JACOBI_7_14J1 = prove
 (`!j:num.
     jacobi(7,14*j+1) = --(&1) pow (((14*j+1)-1) DIV 2)`,
  GEN_TAC THEN
  SUBGOAL_THEN `ODD(14*j+1)` ASSUME_TAC THENL
   [REWRITE_TAC[ODD_ADD; ODD_MULT; ARITH];
    ALL_TAC] THEN
  SUBGOAL_THEN `coprime(7,14*j+1)` ASSUME_TAC THENL
   [REWRITE_TAC[COPRIME_7_14J1];
    ALL_TAC] THEN
  SUBGOAL_THEN `jacobi(14*j+1,7) = &1` ASSUME_TAC THENL
   [TRANS_TAC EQ_TRANS `jacobi(1,7)` THEN CONJ_TAC THENL
     [MATCH_MP_TAC JACOBI_CONG THEN REWRITE_TAC[CONG_14J1_7];
      REWRITE_TAC[JACOBI_1]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`7`; `14*j+1`] JACOBI_RECIPROCITY) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC
   [ARITH_RULE `3*k = k + 2*k`; INT_POW_ADD;
    INT_POW_NEG; EVEN_MULT; INT_POW_ONE; ARITH; INT_MUL_RID] THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(INT_RING `s * s = &1 /\ &1 = s * x ==> x = s`) THEN
  CONJ_TAC THENL
   [COND_CASES_TAC THEN CONV_TAC INT_REDUCE_CONV;
    ASM_MESON_TAC[]]);;

let JACOBI_NEG7_14J1 = prove
 (`!n j:num.
     1 <= n ==> jacobi(8*n*(14*j+1)-7,14*j+1) = &1`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `ODD(14*j+1)` ASSUME_TAC THENL
   [REWRITE_TAC[ODD_ADD; ODD_MULT; ARITH];
    ALL_TAC] THEN
  TRANS_TAC EQ_TRANS `jacobi(7*(14*j+1)-7,14*j+1)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC JACOBI_CONG THEN
    MATCH_MP_TAC CONG_NEG7_14J1 THEN ASM_REWRITE_TAC[];
    REWRITE_TAC
     [ARITH_RULE `7*h-7 = 7*(h-1)`; JACOBI_LMUL;
      JACOBI_7_14J1] THEN
    ASM_SIMP_TAC[JACOBI_MINUS1] THEN
    REWRITE_TAC
     [GSYM INT_POW_ADD; ARITH_RULE `k+k = 2*k`;
      INT_POW_NEG; EVEN_MULT; INT_POW_ONE; ARITH]]);;

let CONG_P_1MOD8_DISC7 = prove
 (`!n j p:num.
     1 <= n /\ p = 8*n*(14*j+1)-7
     ==> (p == 1) (mod 8)`,
  REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN REWRITE_TAC[CONG] THEN
  SUBGOAL_THEN
   `8*n*(14*j+1)-7 = (n*(14*j+1)-1)*8+1`
  SUBST1_TAC THENL
   [ASM_ARITH_TAC;
    SIMP_TAC[MOD_MULT_ADD] THEN CONV_TAC NUM_REDUCE_CONV]);;

let JACOBI_ONE_IMP_COPRIME = prove
 (`!a n:num. jacobi(a,n) = &1 ==> coprime(a,n)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`a:num`; `n:num`] JACOBI_EQ_0) THEN
  ASM_CASES_TAC `coprime(a,n)` THEN ASM_REWRITE_TAC[] THEN
  CONV_TAC INT_REDUCE_CONV);;

let QR_DISC7 = prove
 (`!n j p:num.
     1 <= n /\ prime p /\ p = 8*n*(14*j+1)-7
     ==> ?t. (t EXP 2 + 8*(14*j+1) == 0) (mod p)`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `D:num = 14*j+1` THEN
  SUBGOAL_THEN `ODD D` ASSUME_TAC THENL
   [EXPAND_TAC "D" THEN REWRITE_TAC[ODD_ADD; ODD_MULT; ARITH];
    ALL_TAC] THEN
  SUBGOAL_THEN `(p == 1) (mod 8)` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`n:num`; `j:num`; `p:num`]
      CONG_P_1MOD8_DISC7) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(p == 1) (mod 4)` ASSUME_TAC THENL
   [MATCH_MP_TAC CONG_MOD_8_IMP_MOD_4 THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `ODD p` ASSUME_TAC THENL
   [MATCH_MP_TAC ODD_OF_1MOD4 THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `jacobi(p,D) = &1` ASSUME_TAC THENL
   [EXPAND_TAC "D" THEN ONCE_REWRITE_TAC[ASSUME
      `p = 8*n*(14*j+1)-7`] THEN
    MATCH_MP_TAC(SPECL [`n:num`; `j:num`] JACOBI_NEG7_14J1) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASSUME_TAC(MATCH_MP
   (SPECL [`p:num`; `D:num`] JACOBI_ONE_IMP_COPRIME)
   (ASSUME `jacobi(p,D) = &1`)) THEN
  SUBGOAL_THEN `jacobi(D,p) = &1` ASSUME_TAC THENL
   [TRANS_TAC EQ_TRANS `jacobi(p,D)` THEN CONJ_TAC THENL
     [MATCH_MP_TAC JACOBI_FLIP_1MOD4 THEN ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `jacobi(8,p) = &1` ASSUME_TAC THENL
   [REWRITE_TAC[ARITH_RULE `8 = 2 EXP 3`; JACOBI_LEXP] THEN
    ASM_SIMP_TAC[JACOBI_2_1MOD8] THEN CONV_TAC INT_REDUCE_CONV;
    ALL_TAC] THEN
  MATCH_MP_TAC(SPECL [`p:num`; `8*D`] JACOBI_NEGATIVE_SQUARE) THEN
  CONJ_TAC THENL
   [MATCH_ACCEPT_TAC(ASSUME `prime p`);
    REWRITE_TAC[JACOBI_LMUL] THEN
    ONCE_REWRITE_TAC[ASSUME `jacobi(8,p) = &1`] THEN
    ONCE_REWRITE_TAC[ASSUME `jacobi(D,p) = &1`] THEN
    MP_TAC(MATCH_MP (SPEC `p:num` JACOBI_M1_1MOD4)
      (ASSUME `(p == 1) (mod 4)`)) THEN
    DISCH_THEN SUBST1_TAC THEN CONV_TAC INT_REDUCE_CONV]);;

let RESIDUE_DISC7 = prove
 (`!n:num.
     1 <= n /\ ~(7 divides n)
     ==> ?j t.
           (8*(14*j+1)*n-7) divides
           (t EXP 2 + 8*(14*j+1))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPEC `n:num` DIRICHLET_PRIME_DISC7) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `p:num` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `?j. p = 112*n*j + (8*n-7)`
  (X_CHOOSE_TAC `j:num`) THENL
   [MP_TAC(SPECL [`112*n`; `8*n-7`; `p:num`] CONG_CASE) THEN
    ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MONO_EXISTS THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `p = 8*n*(14*j+1)-7` ASSUME_TAC THENL
   [UNDISCH_TAC `p = 112*n*j + (8*n-7)` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
   (SPECL [`n:num`; `j:num`; `p:num`] QR_DISC7)
   (CONJ (ASSUME `1 <= n`)
    (CONJ (ASSUME `prime p`)
          (ASSUME `p = 8*n*(14*j+1)-7`)))) THEN
  DISCH_THEN(X_CHOOSE_TAC `t:num`) THEN
  MAP_EVERY EXISTS_TAC [`j:num`; `t:num`] THEN
  SUBGOAL_THEN `p = 8*(14*j+1)*n-7`
  (fun th -> REWRITE_TAC[GSYM th]) THENL
   [UNDISCH_TAC `p = 8*n*(14*j+1)-7` THEN ARITH_TAC;
    MP_TAC(ASSUME
     `(t EXP 2 + 8*(14*j+1) == 0) (mod p)`) THEN
    REWRITE_TAC[CONG_0_DIVIDES]]);;

(* ------------------------------------------------------------------------- *)
(* Transfer the natural-number residue to the integer ternary construction. *)
(* ------------------------------------------------------------------------- *)

let DISC7_GENUS_COPRIME7 = prove
 (`!n:num.
     1 < n /\ ~(7 divides n)
     ==> (?x y z:int. x pow 2 + y pow 2 + &7 * z pow 2 = &n) \/
         (?x y z:int.
            x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 = &n)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPEC `n:num` RESIDUE_DISC7) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `j:num` (X_CHOOSE_TAC `t:num`)) THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `h:num` o REWRITE_RULE[divides]) THEN
  MATCH_MP_TAC DISC7_DIRICHLET_GENUS_REPRESENTS THEN
  MAP_EVERY EXISTS_TAC [`&(14*j+1):int`; `&t:int`] THEN
  REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[INT_OF_NUM_LT];
    REWRITE_TAC[INT_OF_NUM_LT] THEN ARITH_TAC;
    REWRITE_TAC[int_divides] THEN EXISTS_TAC `&h:int` THEN
    FIRST_X_ASSUM(MP_TAC o AP_TERM `int_of_num`) THEN
    SUBGOAL_THEN `7 <= 8*(14*j+1)*n` ASSUME_TAC THENL
     [ASM_ARITH_TAC;
      ASM_SIMP_TAC
       [INT_OF_NUM_SUB; INT_OF_NUM_ADD; INT_OF_NUM_MUL;
        INT_OF_NUM_POW] THEN
      CONV_TAC INT_RING]]);;

(* ------------------------------------------------------------------------- *)
(* A second determinant-seven matrix. For an odd m, the matrix               *)
(*                                                                           *)
(*   [ a  t   7  ]                                                          *)
(*   [ t  p   0  ]                                                          *)
(*   [ 7  0  7m  ]                                                          *)
(*                                                                           *)
(* has oddity 1 when p = 1 (mod 8) and ap-t^2 is divisible by 8.            *)
(* ------------------------------------------------------------------------- *)

let DISC7_ODD_TYPE1 = prove
 (`!a t p E m u r:int.
     a * p - t pow 2 = &8 * E /\
     p = &8 * r + &1 /\
     m = &2 * u + &1
     ==> ternary_type1 a t (&7) p (&0) (&7 * m)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPEC `t:int` INT_PARITY_WITNESS) THEN
  DISCH_THEN(DISJ_CASES_THEN
    (X_CHOOSE_THEN `s:int` ASSUME_TAC)) THENL
   [MP_TAC(SPEC `t + &1:int` INT_ODD_SQUARE_8_WITNESS) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[INT_2_DIVIDES_ADD] THEN
      REWRITE_TAC[INT_DIVIDES_ONE] THEN CONV_TAC INT_REDUCE_CONV THEN
      REWRITE_TAC[int_divides] THEN EXISTS_TAC `s:int` THEN
      CONV_TAC INT_RING;
      DISCH_THEN(X_CHOOSE_THEN `h:int` ASSUME_TAC)] THEN
    MATCH_MP_TAC(SPECL
     [`a:int`; `t:int`; `&7:int`; `p:int`; `&0:int`; `&7 * m:int`;
      `&1:int`; `&1:int`; `&0:int`;
      `h + E - a * r + r:int`]
     TERNARY_TYPE1_OF_CHARACTERISTIC) THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[int_divides] THEN EXISTS_TAC `--s:int` THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING;
      REWRITE_TAC[int_divides] THEN EXISTS_TAC `--s:int` THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING;
      REWRITE_TAC[int_divides] THEN EXISTS_TAC `&7 * u:int` THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING;
      MAP_EVERY UNDISCH_TAC
       [`a * p - t pow 2 = &8 * E`;
        `p = &8 * r + &1`;
        `(t + &1) pow 2 = &8 * h + &1`] THEN
      REWRITE_TAC[tqeval] THEN CONV_TAC INT_RING];
    MP_TAC(SPEC `t:int` INT_ODD_SQUARE_8_WITNESS) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[INT_2_DIVIDES_ADD] THEN
      REWRITE_TAC[INT_DIVIDES_ONE] THEN CONV_TAC INT_REDUCE_CONV THEN
      REWRITE_TAC[int_divides] THEN EXISTS_TAC `s:int` THEN
      CONV_TAC INT_RING;
      DISCH_THEN(X_CHOOSE_THEN `h:int` ASSUME_TAC)] THEN
    MATCH_MP_TAC(SPECL
     [`a:int`; `t:int`; `&7:int`; `p:int`; `&0:int`; `&7 * m:int`;
      `&1:int`; `&0:int`; `&0:int`;
      `E - a * r + h:int`]
     TERNARY_TYPE1_OF_CHARACTERISTIC) THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[int_divides] THEN EXISTS_TAC `&0:int` THEN
      CONV_TAC INT_RING;
      REWRITE_TAC[int_divides] THEN EXISTS_TAC `&4 * r - s:int` THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING;
      REWRITE_TAC[int_divides] THEN EXISTS_TAC `&7 * u:int` THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING;
      MAP_EVERY UNDISCH_TAC
       [`a * p - t pow 2 = &8 * E`;
        `p = &8 * r + &1`;
        `t pow 2 = &8 * h + &1`] THEN
      REWRITE_TAC[tqeval] THEN CONV_TAC INT_RING]]);;

let DISC7_EVEN_TYPE1 = prove
 (`!a t p E m u r:int.
     a * p - t pow 2 = &8 * E /\
     p = &8 * r + &1 /\
     m = &2 * u
     ==> ternary_type1 a t (&7) p (&0) (&7 * m)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `&2 divides (a - t)` ASSUME_TAC THENL
   [MP_TAC(SPEC `t:int` INT_SQ_SUB_SELF_EVEN) THEN
    REWRITE_TAC[int_divides] THEN
    DISCH_THEN(X_CHOOSE_THEN `s:int` ASSUME_TAC) THEN
    REWRITE_TAC[int_divides] THEN
    EXISTS_TAC `&4 * E - &4 * a * r + s:int` THEN
    MAP_EVERY UNDISCH_TAC
     [`a * p - t pow 2 = &8 * E`;
      `p = &8 * r + &1`;
      `t pow 2 - t = &2 * s`] THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  MATCH_MP_TAC(SPECL
   [`a:int`; `t:int`; `&7:int`; `p:int`; `&0:int`; `&7 * m:int`;
    `&0:int`; `&1:int`; `&0:int`; `r:int`]
   TERNARY_TYPE1_OF_CHARACTERISTIC) THEN
  REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[INT_MUL_RZERO; INT_MUL_RID; INT_ADD_LID;
      INT_ADD_RID];
    REWRITE_TAC[int_divides] THEN EXISTS_TAC `&0:int` THEN
    CONV_TAC INT_RING;
    REWRITE_TAC[int_divides] THEN EXISTS_TAC `&7 * u:int` THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING;
    ASM_REWRITE_TAC[tqeval] THEN CONV_TAC INT_RING]);;

let DISC7_MATRIX_GENUS_REPRESENTS = prove
 (`!m E p t r:int.
     &0 < m /\ &0 < E /\ &0 < p /\
     p = &8 * r + &1 /\
     &8 * m * E - &7 * p = &1 /\
     p divides (t pow 2 + &8 * E)
     ==> (?x y z:int.
            x pow 2 + y pow 2 + &7 * z pow 2 = &7 * m) \/
         (?x y z:int.
            x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 =
            &7 * m)`,
  REPEAT STRIP_TAC THEN
  UNDISCH_TAC `p divides (t pow 2 + &8 * E)` THEN
  REWRITE_TAC[int_divides] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:int` (LABEL_TAC "quotient")) THEN
  SUBGOAL_THEN `a * p - t pow 2 = &8 * E` ASSUME_TAC THENL
   [USE_THEN "quotient" MP_TAC THEN CONV_TAC INT_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 < a` ASSUME_TAC THENL
   [SUBGOAL_THEN `&0 < a * p` MP_TAC THENL
     [SUBGOAL_THEN `a * p = t pow 2 + &8 * E` SUBST1_TAC THENL
       [ASM_INT_ARITH_TAC;
        MP_TAC(SPEC `t:int` INT_LE_POW_2) THEN ASM_INT_ARITH_TAC];
      ASM_SIMP_TAC[INT_LT_MUL_EQ]];
    ALL_TAC] THEN
  SUBGOAL_THEN `ternary_type1 a t (&7) p (&0) (&7 * m)`
  ASSUME_TAC THENL
   [MP_TAC(SPEC `m:int` INT_PARITY_WITNESS) THEN
    DISCH_THEN(DISJ_CASES_THEN
      (X_CHOOSE_THEN `u:int` ASSUME_TAC)) THENL
     [MATCH_MP_TAC DISC7_EVEN_TYPE1 THEN
      MAP_EVERY EXISTS_TAC [`E:int`; `u:int`; `r:int`] THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC DISC7_ODD_TYPE1 THEN
      MAP_EVERY EXISTS_TAC [`E:int`; `u:int`; `r:int`] THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MATCH_MP_TAC(SPECL
   [`a:int`; `t:int`; `&7:int`; `p:int`; `&0:int`; `&7 * m:int`;
    `&7 * m:int`] TERNARY_DISC7_TYPE1) THEN
  REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    SUBGOAL_THEN `&0 < a * p` MP_TAC THENL
     [MATCH_MP_TAC INT_LT_MUL THEN ASM_REWRITE_TAC[];
      ASM_INT_ARITH_TAC];
    MAP_EVERY UNDISCH_TAC
     [`a * p - t pow 2 = &8 * E`;
      `&8 * m * E - &7 * p = &1`] THEN
    CONV_TAC INT_RING;
    ASM_REWRITE_TAC[];
    MAP_EVERY EXISTS_TAC [`&0:int`; `&0:int`; `&1:int`] THEN
    CONV_TAC INT_RING]);;

(* ------------------------------------------------------------------------- *)
(* Dirichlet offsets for the three nonzero square classes modulo 7.          *)
(* ------------------------------------------------------------------------- *)

let CONG_1_MOD_7_CASE_DISC7 = prove
 (`!m:num. (m == 1) (mod 7) ==> ?q. m = 7*q+1`,
  MESON_TAC[CONG_CASE; MULT_SYM; ARITH_RULE `1 < 7`]);;

let CONG_2_MOD_7_CASE_DISC7 = prove
 (`!m:num. (m == 2) (mod 7) ==> ?q. m = 7*q+2`,
  MESON_TAC[CONG_CASE; MULT_SYM; ARITH_RULE `2 < 7`]);;

let CONG_4_MOD_7_CASE_DISC7 = prove
 (`!m:num. (m == 4) (mod 7) ==> ?q. m = 7*q+4`,
  MESON_TAC[CONG_CASE; MULT_SYM; ARITH_RULE `4 < 7`]);;

let DISC7_SQUARECLASS_OFFSET = prove
 (`!m:num.
     1 <= m /\
     ((m == 1) (mod 7) \/ (m == 2) (mod 7) \/ (m == 4) (mod 7))
     ==> ?e a.
           1 <= e /\ a < 8*m /\ (a == 1) (mod 8) /\
           7*a+1 = 8*m*e /\ coprime(a,8*m)`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `q:num` SUBST_ALL_TAC o
      MATCH_MP CONG_1_MOD_7_CASE_DISC7) THEN
    MAP_EVERY EXISTS_TAC [`1`; `8*q+1`] THEN
    REPEAT CONJ_TAC THENL
     [ARITH_TAC;
      ARITH_TAC;
      REWRITE_TAC[CONG; ARITH_RULE `8*q+1 = q*8+1`] THEN
      SIMP_TAC[MOD_MULT_ADD] THEN CONV_TAC NUM_REDUCE_CONV;
      ARITH_TAC;
      REWRITE_TAC[COPRIME_BEZOUT] THEN
      MAP_EVERY EXISTS_TAC [`1`; `7`] THEN DISJ2_TAC THEN ARITH_TAC];
    FIRST_X_ASSUM(X_CHOOSE_THEN `q:num` SUBST_ALL_TAC o
      MATCH_MP CONG_2_MOD_7_CASE_DISC7) THEN
    MAP_EVERY EXISTS_TAC [`4`; `32*q+9`] THEN
    REPEAT CONJ_TAC THENL
     [ARITH_TAC;
      ARITH_TAC;
      REWRITE_TAC
       [CONG; ARITH_RULE `32*q+9 = (4*q+1)*8+1`] THEN
      SIMP_TAC[MOD_MULT_ADD] THEN CONV_TAC NUM_REDUCE_CONV;
      ARITH_TAC;
      REWRITE_TAC[COPRIME_BEZOUT] THEN
      MAP_EVERY EXISTS_TAC [`4`; `7`] THEN DISJ2_TAC THEN ARITH_TAC];
    FIRST_X_ASSUM(X_CHOOSE_THEN `q:num` SUBST_ALL_TAC o
      MATCH_MP CONG_4_MOD_7_CASE_DISC7) THEN
    MAP_EVERY EXISTS_TAC [`2`; `16*q+9`] THEN
    REPEAT CONJ_TAC THENL
     [ARITH_TAC;
      ARITH_TAC;
      REWRITE_TAC
       [CONG; ARITH_RULE `16*q+9 = (2*q+1)*8+1`] THEN
      SIMP_TAC[MOD_MULT_ADD] THEN CONV_TAC NUM_REDUCE_CONV;
      ARITH_TAC;
      REWRITE_TAC[COPRIME_BEZOUT] THEN
      MAP_EVERY EXISTS_TAC [`2`; `7`] THEN DISJ2_TAC THEN ARITH_TAC]]);;

let DIRICHLET_PRIME_DISC7_MULTIPLE = prove
 (`!m:num.
     1 <= m /\
     ((m == 1) (mod 7) \/ (m == 2) (mod 7) \/ (m == 4) (mod 7))
     ==> ?e j p.
           1 <= e /\ prime p /\
           p = 8*m*j + ((8*m*e-1) DIV 7) /\
           (p == 1) (mod 8) /\
           7*p+1 = 8*m*(7*j+e)`,
  GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "class")) THEN
  MP_TAC(SPEC `m:num` DISC7_SQUARECLASS_OFFSET) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      USE_THEN "class" ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:num`
    (X_CHOOSE_THEN `a:num` STRIP_ASSUME_TAC)) THEN
  MP_TAC(SPECL [`8*m`; `a:num`] DIRICHLET_PRIME_CONG) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `p:num` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `?j. p = 8*m*j+a` (X_CHOOSE_TAC `j:num`) THENL
   [MP_TAC(SPECL [`8*m`; `a:num`; `p:num`] CONG_CASE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MONO_EXISTS THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `a = (8*m*e-1) DIV 7` ASSUME_TAC THENL
   [SUBGOAL_THEN `8*m*e-1 = 7*a` ASSUME_TAC THENL
     [ASM_ARITH_TAC;
      ASM_REWRITE_TAC[] THEN SIMP_TAC[DIV_MULT; ARITH]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(p == 1) (mod 8)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(X_CHOOSE_TAC `s:num` o MATCH_MP CONG_1_MOD_8 o
      check (fun th -> concl th = `(a == 1) (mod 8)`)) THEN
    SUBGOAL_THEN `p = (m*j+s)*8+1` SUBST1_TAC THENL
     [ASM_ARITH_TAC;
      REWRITE_TAC[CONG] THEN SIMP_TAC[MOD_MULT_ADD] THEN
      CONV_TAC NUM_REDUCE_CONV];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`e:num`; `j:num`; `p:num`] THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* The nonzero square classes modulo 7 have Jacobi symbol 1.                *)
(* ------------------------------------------------------------------------- *)

let JACOBI_2_7 = prove
 (`jacobi(2,7) = &1`,
  REWRITE_TAC[JACOBI_OF_2] THEN CONV_TAC NUM_REDUCE_CONV THEN
  CONV_TAC INT_REDUCE_CONV);;

let JACOBI_4_7 = prove
 (`jacobi(4,7) = &1`,
  REWRITE_TAC[ARITH_RULE `4 = 2 EXP 2`; CONJUNCT1 JACOBI_SQUARED] THEN
  SUBGOAL_THEN `coprime(2,7)` ASSUME_TAC THENL
   [REWRITE_TAC[COPRIME_BEZOUT] THEN
    MAP_EVERY EXISTS_TAC [`4`; `1`] THEN DISJ1_TAC THEN ARITH_TAC;
    ASM_REWRITE_TAC[]]);;

let JACOBI_DISC7_SQUARECLASS = prove
 (`!m:num.
     (m == 1) (mod 7) \/ (m == 2) (mod 7) \/ (m == 4) (mod 7)
     ==> jacobi(m,7) = &1`,
  GEN_TAC THEN DISCH_THEN(LABEL_TAC "class") THEN
  REMOVE_THEN "class" (REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [MP_TAC(SPECL [`m:num`; `1`; `7`] JACOBI_CONG) THEN
    ASM_REWRITE_TAC[JACOBI_1];
    MP_TAC(SPECL [`m:num`; `2`; `7`] JACOBI_CONG) THEN
    ASM_REWRITE_TAC[JACOBI_2_7];
    MP_TAC(SPECL [`m:num`; `4`; `7`] JACOBI_CONG) THEN
    ASM_REWRITE_TAC[JACOBI_4_7]]);;

let CONG_HALF_1_MOD7 = prove
 (`!u:num. (2*u == 1) (mod 7) ==> (u == 4) (mod 7)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC CONG_TRANS THEN
  EXISTS_TAC `8*u` THEN CONJ_TAC THENL
   [MATCH_ACCEPT_TAC(NUMBER_RULE `!u:num. (u == 8*u) (mod 7)`);
    MP_TAC(MATCH_MP (SPECL [`4`; `2*u`; `1`; `7`] CONG_LMUL)
      (ASSUME `(2*u == 1) (mod 7)`)) THEN
    REWRITE_TAC[ARITH_RULE `4 * (2*u) = 8*u`; MULT_CLAUSES]]);;

let CONG_HALF_2_MOD7 = prove
 (`!u:num. (2*u == 2) (mod 7) ==> (u == 1) (mod 7)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC CONG_TRANS THEN
  EXISTS_TAC `8*u` THEN CONJ_TAC THENL
   [MATCH_ACCEPT_TAC(NUMBER_RULE `!u:num. (u == 8*u) (mod 7)`);
    MATCH_MP_TAC CONG_TRANS THEN EXISTS_TAC `8` THEN CONJ_TAC THENL
     [MP_TAC(MATCH_MP (SPECL [`4`; `2*u`; `2`; `7`] CONG_LMUL)
        (ASSUME `(2*u == 2) (mod 7)`)) THEN
      REWRITE_TAC[ARITH_RULE `4 * (2*u) = 8*u`] THEN
      CONV_TAC NUM_REDUCE_CONV THEN MESON_TAC[];
      CONV_TAC NUMBER_RULE]]);;

let CONG_HALF_4_MOD7 = prove
 (`!u:num. (2*u == 4) (mod 7) ==> (u == 2) (mod 7)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC CONG_TRANS THEN
  EXISTS_TAC `8*u` THEN CONJ_TAC THENL
   [MATCH_ACCEPT_TAC(NUMBER_RULE `!u:num. (u == 8*u) (mod 7)`);
    MATCH_MP_TAC CONG_TRANS THEN EXISTS_TAC `16` THEN CONJ_TAC THENL
     [MP_TAC(MATCH_MP (SPECL [`4`; `2*u`; `4`; `7`] CONG_LMUL)
        (ASSUME `(2*u == 4) (mod 7)`)) THEN
      REWRITE_TAC[ARITH_RULE `4 * (2*u) = 8*u`] THEN
      CONV_TAC NUM_REDUCE_CONV THEN MESON_TAC[];
      CONV_TAC NUMBER_RULE]]);;

let DISC7_ODDPART_SQUARECLASS = prove
 (`!m u:num.
     (m = u \/ m = 2*u) /\
     ((m == 1) (mod 7) \/ (m == 2) (mod 7) \/ (m == 4) (mod 7))
     ==> (u == 1) (mod 7) \/ (u == 2) (mod 7) \/ (u == 4) (mod 7)`,
  MESON_TAC[CONG_HALF_1_MOD7; CONG_HALF_2_MOD7; CONG_HALF_4_MOD7]);;

let JACOBI_7_ODD_SQUARECLASS = prove
 (`!u:num.
     ODD u /\
     ((u == 1) (mod 7) \/ (u == 2) (mod 7) \/ (u == 4) (mod 7))
     ==> jacobi(7,u) = --(&1) pow ((u-1) DIV 2)`,
  GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "class")) THEN
  SUBGOAL_THEN `jacobi(u,7) = &1` ASSUME_TAC THENL
   [MATCH_MP_TAC JACOBI_DISC7_SQUARECLASS THEN
    USE_THEN "class" ACCEPT_TAC;
    ALL_TAC] THEN
  ASSUME_TAC(MATCH_MP
   (SPECL [`u:num`; `7`] JACOBI_ONE_IMP_COPRIME)
   (ASSUME `jacobi(u,7) = &1`)) THEN
  SUBGOAL_THEN `coprime(7,u)` ASSUME_TAC THENL
   [ONCE_REWRITE_TAC[COPRIME_SYM] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`7`; `u:num`] JACOBI_RECIPROCITY) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC
   [ARITH_RULE `3*k = k + 2*k`; INT_POW_ADD;
    INT_POW_NEG; EVEN_MULT; INT_POW_ONE; ARITH; INT_MUL_RID] THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(INT_RING `s * s = &1 /\ &1 = s * x ==> x = s`) THEN
  CONJ_TAC THENL
   [COND_CASES_TAC THEN CONV_TAC INT_REDUCE_CONV;
    ASM_MESON_TAC[]]);;

let JACOBI_P_ODDPART_DISC7 = prove
 (`!m u E p:num.
     1 <= u /\ ODD u /\ (m = u \/ m = 2*u) /\
     ((m == 1) (mod 7) \/ (m == 2) (mod 7) \/ (m == 4) (mod 7)) /\
     7*p+1 = 8*m*E
     ==> jacobi(p,u) = &1`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "part")
     (CONJUNCTS_THEN2 (LABEL_TAC "class") ASSUME_TAC)))) THEN
  SUBGOAL_THEN
   `(u == 1) (mod 7) \/ (u == 2) (mod 7) \/ (u == 4) (mod 7)`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`m:num`; `u:num`] DISC7_ODDPART_SQUARECLASS) THEN
    CONJ_TAC THENL
     [USE_THEN "part" ACCEPT_TAC;
      USE_THEN "class" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(7*p == u-1) (mod u)` ASSUME_TAC THENL
   [REWRITE_TAC[CONG_MINUS1] THEN DISJ2_TAC THEN
    ASM_REWRITE_TAC[] THEN
    REMOVE_THEN "part" (DISJ_CASES_THEN SUBST1_TAC) THEN
    REWRITE_TAC[divides] THENL
     [EXISTS_TAC `8*E` THEN CONV_TAC NUM_RING;
      EXISTS_TAC `16*E` THEN CONV_TAC NUM_RING];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `jacobi(7*p,u) = jacobi(u-1,u)`
  ASSUME_TAC THENL
   [MATCH_MP_TAC JACOBI_CONG THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `jacobi(7,u) = -- &1 pow ((u-1) DIV 2)`
  ASSUME_TAC THENL
   [MATCH_MP_TAC JACOBI_7_ODD_SQUARECLASS THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ASSUME `jacobi(7*p,u) = jacobi(u-1,u)`) THEN
  REWRITE_TAC[JACOBI_LMUL] THEN
  ONCE_REWRITE_TAC
   [ASSUME `jacobi(7,u) = -- &1 pow ((u-1) DIV 2)`] THEN
  ASM_SIMP_TAC[JACOBI_MINUS1] THEN DISCH_TAC THEN
  MATCH_MP_TAC(SPECL
   [`-- &1 pow ((u-1) DIV 2)`; `jacobi(p,u)`]
   (INT_RING `!s x:int. s*s = &1 /\ s*x = s ==> x = &1`)) THEN
  CONJ_TAC THENL
   [REWRITE_TAC
     [GSYM INT_POW_ADD; ARITH_RULE `k+k = 2*k`;
      INT_POW_NEG; EVEN_MULT; INT_POW_ONE; ARITH];
    ASM_REWRITE_TAC[]]);;

let QR_DISC7_MULTIPLE_CORE = prove
 (`!m u E p:num.
     1 <= u /\ ODD u /\ (m = u \/ m = 2*u) /\
     ((m == 1) (mod 7) \/ (m == 2) (mod 7) \/ (m == 4) (mod 7)) /\
     prime p /\ (p == 1) (mod 8) /\ 7*p+1 = 8*m*E
     ==> ?t. (t EXP 2 + 8*E == 0) (mod p)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "part")
     (CONJUNCTS_THEN2 (LABEL_TAC "class")
      (CONJUNCTS_THEN2 ASSUME_TAC
       (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)))))) THEN
  SUBGOAL_THEN `(p == 1) (mod 4)` ASSUME_TAC THENL
   [MATCH_MP_TAC CONG_MOD_8_IMP_MOD_4 THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `ODD p` ASSUME_TAC THENL
   [MATCH_MP_TAC ODD_OF_1MOD4 THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `jacobi(p,u) = &1` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`m:num`; `u:num`; `E:num`; `p:num`]
      JACOBI_P_ODDPART_DISC7) THEN
    REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      USE_THEN "part" ACCEPT_TAC;
      USE_THEN "class" ACCEPT_TAC;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  ASSUME_TAC(MATCH_MP
   (SPECL [`p:num`; `u:num`] JACOBI_ONE_IMP_COPRIME)
   (ASSUME `jacobi(p,u) = &1`)) THEN
  SUBGOAL_THEN `jacobi(u,p) = &1` ASSUME_TAC THENL
   [TRANS_TAC EQ_TRANS `jacobi(p,u)` THEN CONJ_TAC THENL
     [MATCH_MP_TAC JACOBI_FLIP_1MOD4 THEN ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `jacobi(m,p) = &1` ASSUME_TAC THENL
   [USE_THEN "part" DISJ_CASES_TAC THENL
     [ASM_REWRITE_TAC[];
      SUBST1_TAC(ASSUME `m = 2*u`) THEN
      REWRITE_TAC[JACOBI_LMUL] THEN
      ASM_SIMP_TAC[JACOBI_2_1MOD8] THEN CONV_TAC INT_REDUCE_CONV];
    ALL_TAC] THEN
  SUBGOAL_THEN `(8*m*E == 1) (mod p)` ASSUME_TAC THENL
   [REWRITE_TAC[CONG] THEN
    ONCE_REWRITE_TAC[GSYM(ASSUME `7*p+1 = 8*m*E`)] THEN
    SUBGOAL_THEN `7*p+1 = p*7+1` SUBST1_TAC THENL
     [ARITH_TAC;
      SIMP_TAC[MOD_MULT_ADD] THEN CONV_TAC NUM_REDUCE_CONV];
    ALL_TAC] THEN
  SUBGOAL_THEN `jacobi(8*m*E,p) = &1` ASSUME_TAC THENL
   [TRANS_TAC EQ_TRANS `jacobi(1,p)` THEN CONJ_TAC THENL
     [MATCH_MP_TAC JACOBI_CONG THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[JACOBI_1]];
    ALL_TAC] THEN
  SUBGOAL_THEN `jacobi(8*E,p) = &1` ASSUME_TAC THENL
   [MP_TAC(ASSUME `jacobi(8*m*E,p) = &1`) THEN
    REWRITE_TAC[ARITH_RULE `8*m*E = (8*E)*m`; JACOBI_LMUL] THEN
    ASM_REWRITE_TAC[] THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(SPECL [`p:num`; `8*E`] JACOBI_NEGATIVE_SQUARE) THEN
  CONJ_TAC THENL
   [MATCH_ACCEPT_TAC(ASSUME `prime p`);
    ONCE_REWRITE_TAC[JACOBI_LMUL] THEN
    ONCE_REWRITE_TAC[ASSUME `jacobi(8*E,p) = &1`] THEN
    MP_TAC(MATCH_MP (SPEC `p:num` JACOBI_M1_1MOD4)
      (ASSUME `(p == 1) (mod 4)`)) THEN
    DISCH_THEN SUBST1_TAC THEN CONV_TAC INT_REDUCE_CONV]);;

(* ------------------------------------------------------------------------- *)
(* Package the Dirichlet prime and transfer it to the determinant-7 matrix. *)
(* ------------------------------------------------------------------------- *)

let RESIDUE_DISC7_MULTIPLE_CORE = prove
 (`!m u:num.
     1 <= u /\ ODD u /\ (m = u \/ m = 2*u) /\
     ((m == 1) (mod 7) \/ (m == 2) (mod 7) \/ (m == 4) (mod 7))
     ==> ?E p t r.
           1 <= E /\ prime p /\ p = 8*r+1 /\
           7*p+1 = 8*m*E /\ p divides (t EXP 2 + 8*E)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "part") (LABEL_TAC "class")))) THEN
  SUBGOAL_THEN `1 <= m` ASSUME_TAC THENL
   [USE_THEN "part" DISJ_CASES_TAC THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(SPEC `m:num` DIRICHLET_PRIME_DISC7_MULTIPLE) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      USE_THEN "class" ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:num`
    (X_CHOOSE_THEN `j:num`
      (X_CHOOSE_THEN `p:num` STRIP_ASSUME_TAC))) THEN
  MP_TAC(SPECL [`m:num`; `u:num`; `7*j+e`; `p:num`]
    QR_DISC7_MULTIPLE_CORE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      USE_THEN "part" ACCEPT_TAC;
      USE_THEN "class" ACCEPT_TAC;
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `t:num`) THEN
  MP_TAC(MATCH_MP CONG_1_MOD_8 (ASSUME `(p == 1) (mod 8)`)) THEN
  DISCH_THEN(X_CHOOSE_TAC `r:num`) THEN
  MAP_EVERY EXISTS_TAC [`7*j+e`; `p:num`; `t:num`; `r:num`] THEN
  REPEAT CONJ_TAC THENL
   [ASM_ARITH_TAC;
    ASM_REWRITE_TAC[];
    MATCH_ACCEPT_TAC(ASSUME `p = 8*r+1`);
    ASM_REWRITE_TAC[];
    MP_TAC(ASSUME `(t EXP 2 + 8 * (7*j+e) == 0) (mod p)`) THEN
    REWRITE_TAC[CONG_0_DIVIDES]]);;

let DISC7_GENUS_REPRESENTS_7_CORE = prove
 (`!m u:num.
     1 <= u /\ ODD u /\ (m = u \/ m = 2*u) /\
     ((m == 1) (mod 7) \/ (m == 2) (mod 7) \/ (m == 4) (mod 7))
     ==> (?x y z:int.
            x pow 2 + y pow 2 + &7 * z pow 2 = &(7*m)) \/
         (?x y z:int.
            x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 =
            &(7*m))`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "core") THEN
  MP_TAC(SPECL [`m:num`; `u:num`] RESIDUE_DISC7_MULTIPLE_CORE) THEN
  ANTS_TAC THENL
   [USE_THEN "core" ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `E:num`
    (X_CHOOSE_THEN `p:num`
      (X_CHOOSE_THEN `t:num`
        (X_CHOOSE_THEN `r:num` STRIP_ASSUME_TAC)))) THEN
  ONCE_REWRITE_TAC[GSYM INT_OF_NUM_MUL] THEN
  MATCH_MP_TAC(SPECL
   [`&m:int`; `&E:int`; `&p:int`; `&t:int`; `&r:int`]
   DISC7_MATRIX_GENUS_REPRESENTS) THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[INT_OF_NUM_LT] THEN
    USE_THEN "core" MP_TAC THEN STRIP_TAC THEN
    ASM_ARITH_TAC;
    REWRITE_TAC[INT_OF_NUM_LT] THEN ASM_ARITH_TAC;
    REWRITE_TAC[INT_OF_NUM_LT] THEN
    MP_TAC(MATCH_MP PRIME_GE_2 (ASSUME `prime p`)) THEN ARITH_TAC;
    ASM_REWRITE_TAC[INT_OF_NUM_ADD; INT_OF_NUM_MUL];
    SUBGOAL_THEN `7*p <= 8*m*E` ASSUME_TAC THENL
     [ASM_ARITH_TAC;
      REWRITE_TAC[INT_OF_NUM_MUL] THEN
      ONCE_REWRITE_TAC[MATCH_MP
       (SPECL [`7*p`; `8*m*E`] INT_OF_NUM_SUB)
       (ASSUME `7*p <= 8*m*E`)] THEN
      REWRITE_TAC[INT_OF_NUM_EQ] THEN ASM_ARITH_TAC];
    MP_TAC(ASSUME `p divides (t EXP 2 + 8*E)`) THEN
    REWRITE_TAC
     [num_divides; INT_OF_NUM_ADD; INT_OF_NUM_MUL; INT_OF_NUM_POW]]);;

(* ------------------------------------------------------------------------- *)
(* Remove powers of four from the quotient m.                               *)
(* ------------------------------------------------------------------------- *)

let DISC7_GENUS_REP_MUL4 = prove
 (`!n:num.
     ((?x y z:int. x pow 2 + y pow 2 + &7 * z pow 2 = &n) \/
      (?x y z:int.
         x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 = &n))
     ==> (?x y z:int.
            x pow 2 + y pow 2 + &7 * z pow 2 = &(4*n)) \/
         (?x y z:int.
            x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 =
            &(4*n))`,
  GEN_TAC THEN
  DISCH_THEN(DISJ_CASES_THEN
   (X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int` (X_CHOOSE_TAC `z:int`)))) THENL
   [DISJ1_TAC THEN
    MAP_EVERY EXISTS_TAC [`&2*x:int`; `&2*y:int`; `&2*z:int`] THEN
    FIRST_X_ASSUM MP_TAC THEN
    REWRITE_TAC[GSYM INT_OF_NUM_MUL] THEN CONV_TAC INT_RING;
    DISJ2_TAC THEN
    MAP_EVERY EXISTS_TAC [`&2*x:int`; `&2*y:int`; `&2*z:int`] THEN
    FIRST_X_ASSUM MP_TAC THEN
    REWRITE_TAC[GSYM INT_OF_NUM_MUL] THEN CONV_TAC INT_RING]);;

let CONG_QUARTER_1_MOD7 = prove
 (`!q:num. (4*q == 1) (mod 7) ==> (q == 2) (mod 7)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC CONG_TRANS THEN
  EXISTS_TAC `8*q` THEN CONJ_TAC THENL
   [MATCH_ACCEPT_TAC(NUMBER_RULE `!q:num. (q == 8*q) (mod 7)`);
    MP_TAC(MATCH_MP (SPECL [`2`; `4*q`; `1`; `7`] CONG_LMUL)
      (ASSUME `(4*q == 1) (mod 7)`)) THEN
    REWRITE_TAC[ARITH_RULE `2 * (4*q) = 8*q`; MULT_CLAUSES]]);;

let CONG_QUARTER_2_MOD7 = prove
 (`!q:num. (4*q == 2) (mod 7) ==> (q == 4) (mod 7)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC CONG_TRANS THEN
  EXISTS_TAC `8*q` THEN CONJ_TAC THENL
   [MATCH_ACCEPT_TAC(NUMBER_RULE `!q:num. (q == 8*q) (mod 7)`);
    MP_TAC(MATCH_MP (SPECL [`2`; `4*q`; `2`; `7`] CONG_LMUL)
      (ASSUME `(4*q == 2) (mod 7)`)) THEN
    REWRITE_TAC[ARITH_RULE `2 * (4*q) = 8*q`] THEN
    CONV_TAC NUM_REDUCE_CONV THEN MESON_TAC[]]);;

let CONG_QUARTER_4_MOD7 = prove
 (`!q:num. (4*q == 4) (mod 7) ==> (q == 1) (mod 7)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC CONG_TRANS THEN
  EXISTS_TAC `8*q` THEN CONJ_TAC THENL
   [MATCH_ACCEPT_TAC(NUMBER_RULE `!q:num. (q == 8*q) (mod 7)`);
    MATCH_MP_TAC CONG_TRANS THEN EXISTS_TAC `8` THEN CONJ_TAC THENL
     [MP_TAC(MATCH_MP (SPECL [`2`; `4*q`; `4`; `7`] CONG_LMUL)
        (ASSUME `(4*q == 4) (mod 7)`)) THEN
      REWRITE_TAC[ARITH_RULE `2 * (4*q) = 8*q`] THEN
      CONV_TAC NUM_REDUCE_CONV THEN MESON_TAC[];
      CONV_TAC NUMBER_RULE]]);;

let DISC7_QUARTER_SQUARECLASS = prove
 (`!q:num.
     (4*q == 1) (mod 7) \/ (4*q == 2) (mod 7) \/ (4*q == 4) (mod 7)
     ==> (q == 1) (mod 7) \/ (q == 2) (mod 7) \/ (q == 4) (mod 7)`,
  MESON_TAC
   [CONG_QUARTER_1_MOD7; CONG_QUARTER_2_MOD7;
    CONG_QUARTER_4_MOD7]);;

let DISC7_ODDPART_NOT_DIV4 = prove
 (`!m:num.
     1 <= m /\ ~(4 divides m)
     ==> ?u. 1 <= u /\ ODD u /\ (m = u \/ m = 2*u)`,
  GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "not4")) THEN
  MP_TAC(SPEC `m:num` EVEN_OR_ODD) THEN
  DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "even") (LABEL_TAC "odd")) THENL
   [REMOVE_THEN "even"
     (X_CHOOSE_THEN `u:num` (LABEL_TAC "part") o
      REWRITE_RULE[EVEN_EXISTS]) THEN
    SUBGOAL_THEN `ODD u` ASSUME_TAC THENL
     [REWRITE_TAC[GSYM NOT_EVEN] THEN
      DISCH_THEN(LABEL_TAC "ueven") THEN
      REMOVE_THEN "ueven"
       (X_CHOOSE_THEN `k:num` (LABEL_TAC "upart") o
        REWRITE_RULE[EVEN_EXISTS]) THEN
      SUBGOAL_THEN `4 divides m` MP_TAC THENL
       [REWRITE_TAC[divides] THEN EXISTS_TAC `k:num` THEN
        MAP_EVERY UNDISCH_TAC [`m = 2*u`; `u = 2*k`] THEN ARITH_TAC;
        USE_THEN "not4" MP_TAC THEN MESON_TAC[]];
      ALL_TAC] THEN
    EXISTS_TAC `u:num` THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "part" MP_TAC THEN ASM_ARITH_TAC;
      ASM_REWRITE_TAC[];
      DISJ2_TAC THEN USE_THEN "part" ACCEPT_TAC];
    EXISTS_TAC `m:num` THEN ASM_REWRITE_TAC[]]);;

let DISC7_GENUS_REPRESENTS_7_SQUARECLASS = prove
 (`!m:num.
     1 <= m /\
     ((m == 1) (mod 7) \/ (m == 2) (mod 7) \/ (m == 4) (mod 7))
     ==> (?x y z:int.
            x pow 2 + y pow 2 + &7 * z pow 2 = &(7*m)) \/
         (?x y z:int.
            x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 =
            &(7*m))`,
  MATCH_MP_TAC num_WF THEN
  X_GEN_TAC `m:num` THEN DISCH_THEN(LABEL_TAC "ih") THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "class")) THEN
  ASM_CASES_TAC `4 divides m` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `q:num` SUBST_ALL_TAC o
      REWRITE_RULE[divides]) THEN
    SUBGOAL_THEN `1 <= q` ASSUME_TAC THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(q == 1) (mod 7) \/ (q == 2) (mod 7) \/ (q == 4) (mod 7)`
    ASSUME_TAC THENL
     [MATCH_MP_TAC DISC7_QUARTER_SQUARECLASS THEN
      USE_THEN "class" ACCEPT_TAC;
      ALL_TAC] THEN
    ONCE_REWRITE_TAC[ARITH_RULE `7 * (4*q) = 4 * (7*q)`] THEN
    MATCH_MP_TAC DISC7_GENUS_REP_MUL4 THEN
    USE_THEN "ih" (MP_TAC o SPEC `q:num`) THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]];
    MP_TAC(SPEC `m:num` DISC7_ODDPART_NOT_DIV4) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `u:num` STRIP_ASSUME_TAC)] THEN
    MATCH_MP_TAC(SPECL [`m:num`; `u:num`]
      DISC7_GENUS_REPRESENTS_7_CORE) THEN
    ASM_REWRITE_TAC[] THEN USE_THEN "class" ACCEPT_TAC]);;

(* ------------------------------------------------------------------------- *)
(* Descent by 49 and the full genus-regularity statement.                    *)
(* ------------------------------------------------------------------------- *)

let disc7_exception = new_definition
 `disc7_exception n <=>
    ?a b r:num.
      (r = 3 \/ r = 5 \/ r = 6) /\
      n = 49 EXP a * (49*b + 7*r)`;;

let DISC7_EXCEPTION_BASE = prove
 (`!m:num.
     m MOD 7 = 3 \/ m MOD 7 = 5 \/ m MOD 7 = 6
     ==> disc7_exception (7*m)`,
  GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THEN
  REWRITE_TAC[disc7_exception] THENL
   [MAP_EVERY EXISTS_TAC [`0`; `m DIV 7`; `3`];
    MAP_EVERY EXISTS_TAC [`0`; `m DIV 7`; `5`];
    MAP_EVERY EXISTS_TAC [`0`; `m DIV 7`; `6`]] THEN
  (CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    REWRITE_TAC[EXP; MULT_CLAUSES] THEN
    MP_TAC(SPECL [`m:num`; `7`] (CONJUNCT1 DIVISION_SIMP)) THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC]));;

let DISC7_EXCEPTION_MUL49 = prove
 (`!n:num. disc7_exception n ==> disc7_exception (49*n)`,
  GEN_TAC THEN REWRITE_TAC[disc7_exception] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:num`
    (X_CHOOSE_THEN `b:num`
      (X_CHOOSE_THEN `r:num` STRIP_ASSUME_TAC))) THEN
  MAP_EVERY EXISTS_TAC [`SUC a`; `b:num`; `r:num`] THEN
  ASM_REWRITE_TAC[EXP] THEN CONV_TAC NUM_RING);;

let DISC7_DESCENT_NOT_EXCEPTION = prove
 (`!n:num.
     49 divides n /\ ~disc7_exception n
     ==> ~disc7_exception (n DIV 49)`,
  GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2
    (LABEL_TAC "div49") (LABEL_TAC "avoid")) THEN
  REMOVE_THEN "div49"
   (X_CHOOSE_THEN `c:num` SUBST_ALL_TAC o REWRITE_RULE[divides]) THEN
  SIMP_TAC[DIV_MULT; ARITH] THEN DISCH_TAC THEN
  USE_THEN "avoid" MP_TAC THEN
  ASM_MESON_TAC[DISC7_EXCEPTION_MUL49]);;

let DISC7_GENUS_REP_MUL49 = prove
 (`!n:num.
     ((?x y z:int. x pow 2 + y pow 2 + &7 * z pow 2 = &n) \/
      (?x y z:int.
         x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 = &n))
     ==> (?x y z:int.
            x pow 2 + y pow 2 + &7 * z pow 2 = &(49*n)) \/
         (?x y z:int.
            x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 =
            &(49*n))`,
  GEN_TAC THEN
  DISCH_THEN(DISJ_CASES_THEN
   (X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int` (X_CHOOSE_TAC `z:int`)))) THENL
   [DISJ1_TAC THEN
    MAP_EVERY EXISTS_TAC [`&7*x:int`; `&7*y:int`; `&7*z:int`] THEN
    FIRST_X_ASSUM MP_TAC THEN
    REWRITE_TAC[GSYM INT_OF_NUM_MUL] THEN CONV_TAC INT_RING;
    DISJ2_TAC THEN
    MAP_EVERY EXISTS_TAC [`&7*x:int`; `&7*y:int`; `&7*z:int`] THEN
    FIRST_X_ASSUM MP_TAC THEN
    REWRITE_TAC[GSYM INT_OF_NUM_MUL] THEN CONV_TAC INT_RING]);;

let DIV49_LESS = prove
 (`!n:num. ~(n = 0) /\ 49 divides n ==> n DIV 49 < n`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `c:num` SUBST_ALL_TAC o
    REWRITE_RULE[divides]) THEN
  SUBGOAL_THEN `(49*c) DIV 49 = c` SUBST1_TAC THENL
   [SIMP_TAC[DIV_MULT; ARITH];
    ASM_ARITH_TAC]);;

let DIV49_POS = prove
 (`!n:num. 0 < n /\ 49 divides n ==> 0 < n DIV 49`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `c:num` SUBST_ALL_TAC o
    REWRITE_RULE[divides]) THEN
  SIMP_TAC[DIV_MULT; ARITH] THEN ASM_ARITH_TAC);;

let DISC7_GENUS_REP_DESCEND49 = prove
 (`!n:num.
     49 divides n /\
     ((?x y z:int.
         x pow 2 + y pow 2 + &7 * z pow 2 = &(n DIV 49)) \/
      (?x y z:int.
         x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 =
         &(n DIV 49)))
     ==> (?x y z:int.
            x pow 2 + y pow 2 + &7 * z pow 2 = &n) \/
         (?x y z:int.
            x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 = &n)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(MATCH_MP
   (SPEC `n DIV 49` DISC7_GENUS_REP_MUL49)
   (ASSUME
    `(?x y z:int.
       x pow 2 + y pow 2 + &7 * z pow 2 = &(n DIV 49)) \/
     (?x y z:int.
       x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 =
       &(n DIV 49))`)) THEN
  SUBGOAL_THEN `49 * (n DIV 49) = n`
  (fun th -> ASM_REWRITE_TAC[th]) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `c:num` SUBST1_TAC o
    REWRITE_RULE[divides]) THEN
  SIMP_TAC[DIV_MULT; ARITH]);;

let MOD7_SQUARECLASS_DISC7 = prove
 (`!m:num.
     m MOD 7 = 1 \/ m MOD 7 = 2 \/ m MOD 7 = 4
     ==> (m == 1) (mod 7) \/ (m == 2) (mod 7) \/ (m == 4) (mod 7)`,
  GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THEN
  REWRITE_TAC[CONG] THEN ASM_REWRITE_TAC[] THEN
  CONV_TAC NUM_REDUCE_CONV);;

let MOD7_ZERO_DISC7_DIV49 = prove
 (`!m:num. m MOD 7 = 0 ==> 49 divides (7*m)`,
  GEN_TAC THEN REWRITE_TAC[GSYM DIVIDES_MOD] THEN DISCH_TAC THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `q:num` SUBST1_TAC o
    REWRITE_RULE[divides]) THEN
  REWRITE_TAC[divides] THEN EXISTS_TAC `q:num` THEN ARITH_TAC);;

let DISC7_GENUS_REGULAR = prove
 (`!n:num.
     0 < n /\ ~disc7_exception n
     ==> (?x y z:int. x pow 2 + y pow 2 + &7 * z pow 2 = &n) \/
         (?x y z:int.
            x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 = &n)`,
  MATCH_MP_TAC num_WF THEN
  X_GEN_TAC `n:num` THEN DISCH_THEN(LABEL_TAC "ih") THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "avoid")) THEN
  ASM_CASES_TAC `n = 1` THENL
   [DISJ1_TAC THEN
    MAP_EVERY EXISTS_TAC [`&1:int`; `&0:int`; `&0:int`] THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING;
    ALL_TAC] THEN
  ASM_CASES_TAC `7 divides n` THENL
   [MP_TAC(REWRITE_RULE[divides] (ASSUME `7 divides n`)) THEN
    DISCH_THEN(X_CHOOSE_THEN `m:num` SUBST_ALL_TAC) THEN
    SUBGOAL_THEN `1 <= m` ASSUME_TAC THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `m MOD 7 = 0 \/ m MOD 7 = 1 \/ m MOD 7 = 2 \/
      m MOD 7 = 3 \/ m MOD 7 = 4 \/ m MOD 7 = 5 \/ m MOD 7 = 6`
    MP_TAC THENL
     [MP_TAC(SPECL [`m:num`; `7`] MOD_LT) THEN ARITH_TAC;
      ALL_TAC] THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
     [SUBGOAL_THEN `49 divides (7*m)` ASSUME_TAC THENL
       [MATCH_MP_TAC MOD7_ZERO_DISC7_DIV49 THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MATCH_MP_TAC DISC7_GENUS_REP_DESCEND49 THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "ih" (MP_TAC o SPEC `(7*m) DIV 49`) THEN
      ANTS_TAC THENL
       [MATCH_MP_TAC DIV49_LESS THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        DISCH_THEN MATCH_MP_TAC] THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC DIV49_POS THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        MATCH_MP_TAC DISC7_DESCENT_NOT_EXCEPTION THEN
        ASM_REWRITE_TAC[]];
      MATCH_MP_TAC DISC7_GENUS_REPRESENTS_7_SQUARECLASS THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MOD7_SQUARECLASS_DISC7 THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC DISC7_GENUS_REPRESENTS_7_SQUARECLASS THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MOD7_SQUARECLASS_DISC7 THEN
      ASM_REWRITE_TAC[];
      SUBGOAL_THEN `disc7_exception (7*m)` MP_TAC THENL
       [MATCH_MP_TAC DISC7_EXCEPTION_BASE THEN ASM_REWRITE_TAC[];
        USE_THEN "avoid" MP_TAC THEN MESON_TAC[]];
      MATCH_MP_TAC DISC7_GENUS_REPRESENTS_7_SQUARECLASS THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MOD7_SQUARECLASS_DISC7 THEN
      ASM_REWRITE_TAC[];
      SUBGOAL_THEN `disc7_exception (7*m)` MP_TAC THENL
       [MATCH_MP_TAC DISC7_EXCEPTION_BASE THEN ASM_REWRITE_TAC[];
        USE_THEN "avoid" MP_TAC THEN MESON_TAC[]];
      SUBGOAL_THEN `disc7_exception (7*m)` MP_TAC THENL
       [MATCH_MP_TAC DISC7_EXCEPTION_BASE THEN ASM_REWRITE_TAC[];
        USE_THEN "avoid" MP_TAC THEN MESON_TAC[]]];
    MATCH_MP_TAC DISC7_GENUS_COPRIME7 THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]);;

let DISC7_MOD4_WITNESS = prove
 (`!n:num.
     n MOD 4 = 0 \/ n MOD 4 = 1
     ==> ?q:int. &n = &4*q \/ &n = &4*q + &1`,
  GEN_TAC THEN DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
   [EXISTS_TAC `&(n DIV 4):int` THEN DISJ1_TAC THEN
    SUBGOAL_THEN `n = 4 * (n DIV 4)` ASSUME_TAC THENL
      [MP_TAC(SPECL [`n:num`; `4`] (CONJUNCT1 DIVISION_SIMP)) THEN
       ASM_REWRITE_TAC[] THEN ARITH_TAC;
      REWRITE_TAC[INT_OF_NUM_MUL; INT_OF_NUM_EQ] THEN
      MATCH_ACCEPT_TAC(ASSUME `n = 4 * (n DIV 4)`)];
    EXISTS_TAC `&(n DIV 4):int` THEN DISJ2_TAC THEN
    SUBGOAL_THEN `n = 4 * (n DIV 4) + 1` ASSUME_TAC THENL
     [MP_TAC(SPECL [`n:num`; `4`] (CONJUNCT1 DIVISION_SIMP)) THEN
      ASM_REWRITE_TAC[] THEN ARITH_TAC;
      REWRITE_TAC
       [INT_OF_NUM_ADD; INT_OF_NUM_MUL; INT_OF_NUM_EQ] THEN
      MATCH_ACCEPT_TAC(ASSUME `n = 4 * (n DIV 4) + 1`)]]);;

let DISC7_BOTH_REGULAR_MOD4 = prove
 (`!n:num.
     0 < n /\ ~disc7_exception n /\
     (n MOD 4 = 0 \/ n MOD 4 = 1)
     ==> (?x y z:int. x pow 2 + y pow 2 + &7 * z pow 2 = &n) /\
         (?x y z:int.
            x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 = &n)`,
  GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 (LABEL_TAC "avoid") (LABEL_TAC "mod4"))) THEN
  MP_TAC(SPEC `n:num` DISC7_MOD4_WITNESS) THEN
  ANTS_TAC THENL
   [USE_THEN "mod4" ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `q:int` (LABEL_TAC "mod4int"))] THEN
  MP_TAC(SPEC `n:num` DISC7_GENUS_REGULAR) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "avoid" ACCEPT_TAC;
    DISCH_THEN(DISJ_CASES_THEN (LABEL_TAC "repr"))] THENL
   [CONJ_TAC THENL
     [USE_THEN "repr" ACCEPT_TAC;
      MATCH_MP_TAC(SPEC `&n:int` REPR_CROSS124_OF_DIAG7_MOD4) THEN
      CONJ_TAC THENL
       [USE_THEN "repr" ACCEPT_TAC;
        EXISTS_TAC `q:int` THEN USE_THEN "mod4int" ACCEPT_TAC]];
    CONJ_TAC THENL
     [MATCH_MP_TAC(SPEC `&n:int` REPR_DIAG7_OF_CROSS124_MOD4) THEN
      CONJ_TAC THENL
       [USE_THEN "repr" ACCEPT_TAC;
        EXISTS_TAC `q:int` THEN USE_THEN "mod4int" ACCEPT_TAC];
      USE_THEN "repr" ACCEPT_TAC]]);;

(* The determinant-7 diagonal form gives the determinant-14 form
   x^2 + y^2 + 14z^2 after doubling. *)
let DIAG7_TO_117_DOUBLE = prove
 (`!n x y z:int.
     x pow 2 + y pow 2 + &7 * z pow 2 = n
     ==> ?a b c.
          a pow 2 + b pow 2 + &14 * c pow 2 = &2 * n`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MAP_EVERY EXISTS_TAC [`x + y:int`; `x - y:int`; `z:int`] THEN
  FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING);;

let INT_117_PAIR_TO_127 = prove
 (`!n a b c t:int.
     a pow 2 + b pow 2 + &14 * c pow 2 = n /\
     b - c = &3 * t
     ==> ?x y z.
          x pow 2 + &2 * y pow 2 + &7 * z pow 2 = n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MAP_EVERY EXISTS_TAC [`a:int`; `t - &2 * c:int`; `t + c:int`] THEN
  MAP_EVERY UNDISCH_TAC
   [`a pow 2 + b pow 2 + &14 * c pow 2 = n`;
    `b - c = &3 * t`] THEN
  CONV_TAC INT_RING);;

let INT_117_BAD_REM3 = prove
 (`!n a b c q:int.
     (a rem &3 = &0 /\ b rem &3 = &0 /\ c rem &3 = &1 \/
      a rem &3 = &1 /\ b rem &3 = &1 /\ c rem &3 = &0) /\
     (n = &3 * q \/ n = &3 * q + &1)
     ==> ~(a pow 2 + b pow 2 + &14 * c pow 2 = n)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2
    (DISJ_CASES_THEN STRIP_ASSUME_TAC)
    (DISJ_CASES_THEN ASSUME_TAC)) THEN
  DISCH_THEN(MP_TAC o AP_TERM `\u:int. u rem &3`) THEN
  ASM_REWRITE_TAC[] THEN
  (SUBGOAL_THEN
    `(a pow 2 + b pow 2 + &14 * c pow 2) rem &3 =
     ((a rem &3) pow 2 + (b rem &3) pow 2 +
      &14 * (c rem &3) pow 2) rem &3`
   SUBST1_TAC THENL
    [CONV_TAC INT_REM_DOWN_CONV THEN REFL_TAC;
     ASM_REWRITE_TAC[] THEN CONV_TAC INT_REDUCE_CONV THEN
     REWRITE_TAC
      [INT_RING `&3 * q + &1 = q * &3 + &1`;
       INT_RING `&3 * q = q * &3`;
       INT_REM_MUL; INT_REM_MUL_ADD] THEN
     CONV_TAC INT_REDUCE_CONV]));;

(* Pall's identity transfers x^2+y^2+14z^2 to x^2+2y^2+7z^2
   whenever the represented integer is 0 or 1 modulo 3. *)
let REPR_127_OF_117_MOD3 = prove
 (`!n:int.
     (?a b c. a pow 2 + b pow 2 + &14 * c pow 2 = n) /\
     (?q. n = &3 * q \/ n = &3 * q + &1)
     ==> ?x y z.
          x pow 2 + &2 * y pow 2 + &7 * z pow 2 = n`,
  GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2
    (X_CHOOSE_THEN `a:int`
      (X_CHOOSE_THEN `b:int`
        (X_CHOOSE_THEN `c:int` (LABEL_TAC "repr"))))
    (X_CHOOSE_THEN `q:int` (LABEL_TAC "mod3"))) THEN
  MP_TAC(SPEC `a:int` INT_SIGN_NORMALIZE_MOD3) THEN
  MP_TAC(SPEC `b:int` INT_SIGN_NORMALIZE_MOD3) THEN
  MP_TAC(SPEC `c:int` INT_SIGN_NORMALIZE_MOD3) THEN
  DISCH_THEN(X_CHOOSE_THEN `C:int`
    (CONJUNCTS_THEN2 (LABEL_TAC "Csq") (LABEL_TAC "Crem"))) THEN
  DISCH_THEN(X_CHOOSE_THEN `B:int`
    (CONJUNCTS_THEN2 (LABEL_TAC "Bsq") (LABEL_TAC "Brem"))) THEN
  DISCH_THEN(X_CHOOSE_THEN `A:int`
    (CONJUNCTS_THEN2 (LABEL_TAC "Asq") (LABEL_TAC "Arem"))) THEN
  SUBGOAL_THEN
   `A pow 2 + B pow 2 + &14 * C pow 2 = n`
  (LABEL_TAC "normalized") THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `B rem &3 = C rem &3` THENL
   [MP_TAC(MATCH_MP
      (SPECL [`B:int`; `C:int`] INT_SAME_REM_MOD3_DIVIDES_SUB)
      (ASSUME `B rem &3 = C rem &3`)) THEN
    REWRITE_TAC[int_divides] THEN
    DISCH_THEN(X_CHOOSE_THEN `t:int` (LABEL_TAC "pair")) THEN
    MATCH_MP_TAC(SPECL
      [`n:int`; `A:int`; `B:int`; `C:int`; `t:int`]
      INT_117_PAIR_TO_127) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `A rem &3 = C rem &3` THENL
   [MP_TAC(MATCH_MP
      (SPECL [`A:int`; `C:int`] INT_SAME_REM_MOD3_DIVIDES_SUB)
      (ASSUME `A rem &3 = C rem &3`)) THEN
    REWRITE_TAC[int_divides] THEN
    DISCH_THEN(X_CHOOSE_THEN `t:int` (LABEL_TAC "pair")) THEN
    MATCH_MP_TAC(SPECL
      [`n:int`; `B:int`; `A:int`; `C:int`; `t:int`]
      INT_117_PAIR_TO_127) THEN
    CONJ_TAC THENL
     [REMOVE_THEN "normalized" MP_TAC THEN INT_ARITH_TAC;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(A rem &3 = &0 /\ B rem &3 = &0 /\ C rem &3 = &1) \/
    (A rem &3 = &1 /\ B rem &3 = &1 /\ C rem &3 = &0)`
  ASSUME_TAC THENL
   [REMOVE_THEN "Arem" (DISJ_CASES_THEN ASSUME_TAC) THEN
    REMOVE_THEN "Brem" (DISJ_CASES_THEN ASSUME_TAC) THEN
    REMOVE_THEN "Crem" (DISJ_CASES_THEN ASSUME_TAC) THEN
    ASM_MESON_TAC[];
    MP_TAC(SPECL [`n:int`; `A:int`; `B:int`; `C:int`; `q:int`]
      INT_117_BAD_REM3) THEN
    ASM_REWRITE_TAC[]]);;

let INT_127_DOUBLE_PARITY = prove
 (`!n a b c:int.
     a pow 2 + &2 * b pow 2 + &7 * c pow 2 = &2 * n
     ==> ?t. a - c = &2 * t`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "repr") THEN
  MP_TAC(SPEC `c:int` INT_PARITY_WITNESS) THEN
  MP_TAC(SPEC `a:int` INT_PARITY_WITNESS) THEN
  DISCH_THEN(DISJ_CASES_THEN
    (X_CHOOSE_THEN `u:int` ASSUME_TAC)) THEN
  DISCH_THEN(DISJ_CASES_THEN
    (X_CHOOSE_THEN `v:int` ASSUME_TAC)) THENL
   [EXISTS_TAC `u - v:int` THEN ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING;
    SUBGOAL_THEN `&2 divides &1` MP_TAC THENL
     [REWRITE_TAC[int_divides] THEN
      EXISTS_TAC
       `n - &2 * (u pow 2) - b pow 2 -
        &14 * (v pow 2) - &14 * v - &3:int` THEN
      REMOVE_THEN "repr" MP_TAC THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING;
      REWRITE_TAC[INT_DIVIDES_ONE] THEN CONV_TAC INT_REDUCE_CONV];
    SUBGOAL_THEN `&2 divides &1` MP_TAC THENL
     [REWRITE_TAC[int_divides] THEN
      EXISTS_TAC
       `n - &2 * (u pow 2) - &2 * u - b pow 2 -
        &14 * (v pow 2):int` THEN
      REMOVE_THEN "repr" MP_TAC THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING;
      REWRITE_TAC[INT_DIVIDES_ONE] THEN CONV_TAC INT_REDUCE_CONV];
    EXISTS_TAC `u - v:int` THEN ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING]);;

(* This is Kaplansky's second doubling identity. *)
let REPR_CROSS124_OF_127_DOUBLE = prove
 (`!n:int.
     (?a b c.
        a pow 2 + &2 * b pow 2 + &7 * c pow 2 = &2 * n)
     ==> ?x y z.
          x pow 2 + &2 * y pow 2 + &2 * y * z +
          &4 * z pow 2 = n`,
  GEN_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `a:int`
    (X_CHOOSE_THEN `b:int`
      (X_CHOOSE_THEN `c:int` (LABEL_TAC "repr")))) THEN
  MP_TAC(MATCH_MP
    (SPECL [`n:int`; `a:int`; `b:int`; `c:int`]
      INT_127_DOUBLE_PARITY)
    (ASSUME
      `a pow 2 + &2 * b pow 2 + &7 * c pow 2 = &2 * n`)) THEN
  DISCH_THEN(X_CHOOSE_THEN `t:int` (LABEL_TAC "parity")) THEN
  MAP_EVERY EXISTS_TAC [`b:int`; `t:int`; `c:int`] THEN
  MATCH_MP_TAC(INT_ARITH `&2 * q = &2 * n ==> q = n`) THEN
  REMOVE_THEN "repr" MP_TAC THEN REMOVE_THEN "parity" MP_TAC THEN
  CONV_TAC INT_RING);;

let DISC7_DOUBLE_MOD3_WITNESS = prove
 (`!n:num.
     n MOD 3 = 0 \/ n MOD 3 = 2
     ==> ?q:int. &2 * &n = &3 * q \/ &2 * &n = &3 * q + &1`,
  GEN_TAC THEN DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
   [MP_TAC(MATCH_MP (SPECL [`n:num`; `3`; `0`] NUM_DECOMPOSE_MOD)
      (CONJ (ARITH_RULE `~(3 = 0)`) (ASSUME `n MOD 3 = 0`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `q:num` SUBST_ALL_TAC) THEN
    EXISTS_TAC `&(2 * q):int` THEN DISJ1_TAC THEN
    REWRITE_TAC[GSYM INT_OF_NUM_ADD; GSYM INT_OF_NUM_MUL;
      INT_OF_NUM_EQ] THEN ARITH_TAC;
    MP_TAC(MATCH_MP (SPECL [`n:num`; `3`; `2`] NUM_DECOMPOSE_MOD)
      (CONJ (ARITH_RULE `~(3 = 0)`) (ASSUME `n MOD 3 = 2`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `q:num` SUBST_ALL_TAC) THEN
    EXISTS_TAC `&(2 * q + 1):int` THEN DISJ2_TAC THEN
    REWRITE_TAC[GSYM INT_OF_NUM_ADD; GSYM INT_OF_NUM_MUL;
      INT_OF_NUM_EQ] THEN ARITH_TAC]);;

let DISC7_CROSS124_REGULAR_MOD3 = prove
 (`!n:num.
     0 < n /\ ~disc7_exception n /\
     (n MOD 3 = 0 \/ n MOD 3 = 2)
     ==> ?x y z:int.
          x pow 2 + &2 * y pow 2 + &2 * y * z +
          &4 * z pow 2 = &n`,
  GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "avoid") (LABEL_TAC "mod3"))) THEN
  MP_TAC(MATCH_MP (SPEC `n:num` DISC7_GENUS_REGULAR)
    (CONJ (ASSUME `0 < n`) (ASSUME `~disc7_exception n`))) THEN
  DISCH_THEN(DISJ_CASES_THEN
    (X_CHOOSE_THEN `x:int`
      (X_CHOOSE_THEN `y:int`
        (X_CHOOSE_THEN `z:int` (LABEL_TAC "genus"))))) THENL
   [MP_TAC(MATCH_MP
      (SPECL [`&n:int`; `x:int`; `y:int`; `z:int`]
        DIAG7_TO_117_DOUBLE)
      (ASSUME
        `x pow 2 + y pow 2 + &7 * z pow 2 = &n`)) THEN
    DISCH_THEN(LABEL_TAC "double117") THEN
    MP_TAC(MATCH_MP (SPEC `n:num` DISC7_DOUBLE_MOD3_WITNESS)
      (ASSUME `n MOD 3 = 0 \/ n MOD 3 = 2`)) THEN
    DISCH_THEN(X_CHOOSE_THEN `q:int` (LABEL_TAC "doublemod3")) THEN
    MATCH_MP_TAC REPR_CROSS124_OF_127_DOUBLE THEN
    MATCH_MP_TAC(SPEC `&2 * &n:int` REPR_127_OF_117_MOD3) THEN
    CONJ_TAC THENL
     [REMOVE_THEN "double117" MATCH_ACCEPT_TAC;
      EXISTS_TAC `q:int` THEN
      REMOVE_THEN "doublemod3" MATCH_ACCEPT_TAC];
    MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`] THEN
    REMOVE_THEN "genus" MATCH_ACCEPT_TAC]);;

let NUM_CROSS124_GOOD_RESIDUES = prove
 (`!n:num.
     ~(n MOD 12 = 7) /\ ~(n MOD 12 = 10)
     ==> n MOD 3 = 0 \/ n MOD 3 = 2 \/
         n MOD 4 = 0 \/ n MOD 4 = 1`,
  GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `n MOD 3 = (n MOD 12) MOD 3` ASSUME_TAC THENL
   [REWRITE_TAC[ARITH_RULE `12 = 3 * 4`; MOD_MOD];
    ALL_TAC] THEN
  SUBGOAL_THEN `n MOD 4 = (n MOD 12) MOD 4` ASSUME_TAC THENL
   [REWRITE_TAC[ARITH_RULE `12 = 4 * 3`; MOD_MOD];
    ALL_TAC] THEN
  SUBGOAL_THEN `n MOD 12 < 12` ASSUME_TAC THENL
   [REWRITE_TAC[MOD_LT_EQ] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  NUM_RANGE_CASES_TAC `n MOD 12` 11 THEN
  RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
  ASM_MESON_TAC[]);;

let DISC7_CROSS124_REGULAR = prove
 (`!n:num.
     0 < n /\ ~disc7_exception n /\
     ~(n MOD 12 = 7) /\ ~(n MOD 12 = 10)
     ==> ?x y z:int.
          x pow 2 + &2 * y pow 2 + &2 * y * z +
          &4 * z pow 2 = &n`,
  GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP (SPEC `n:num` NUM_CROSS124_GOOD_RESIDUES)
    (CONJ (ASSUME `~(n MOD 12 = 7)`)
      (ASSUME `~(n MOD 12 = 10)`))) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [MATCH_MP_TAC(SPEC `n:num` DISC7_CROSS124_REGULAR_MOD3) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(SPEC `n:num` DISC7_CROSS124_REGULAR_MOD3) THEN
    ASM_REWRITE_TAC[];
    MP_TAC(SPEC `n:num` DISC7_BOTH_REGULAR_MOD4) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      MESON_TAC[]];
    MP_TAC(SPEC `n:num` DISC7_BOTH_REGULAR_MOD4) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      MESON_TAC[]]]);;

let IQ_125_CHILD_REP_OF_NUM = prove
 (`!rb rc k m:num.
     int125_child_rep rb rc k m
     ==> iq_represents 4
          (iqmat4 (&1) (&0) (&0) (&0)
                  (&2) (&0) (&rb) (&5) (&rc) (&k)) (&m)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[int125_child_rep; iq_represents] THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int`
      (X_CHOOSE_THEN `z:int` (X_CHOOSE_TAC `w:int`)))) THEN
  EXISTS_TAC
   `\i:num.
      if i = 0 then (x:int) else if i = 1 then y else
      if i = 2 then z else w` THEN
  REWRITE_TAC[IQEVAL_MAT4] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING);;

let IQ_UNIVERSAL_OF_125_CHILD_ALMOST15 = prove
 (`!n A rb rc k.
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&0) (&rb) (&5) (&rc) (&k)) A /\
     (!m:num. 0 < m /\ ~(m = 15) ==> int125_child_rep rb rc k m) /\
     iq_represents n A (&15)
     ==> iq_universal n A`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "emb")
    (CONJUNCTS_THEN2 (LABEL_TAC "almost") (LABEL_TAC "fifteen"))) THEN
  REWRITE_TAC[iq_universal] THEN
  X_GEN_TAC `m:int` THEN DISCH_TAC THEN
  ASM_CASES_TAC `m = &15` THENL
   [REMOVE_THEN "fifteen" MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(EQ_MP (SYM(SPEC `m:int` INT_OF_NUM_EXISTS))
    (MATCH_MP (SPECL [`&0:int`; `m:int`] INT_LT_IMP_LE)
      (ASSUME `&0 < m`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `u:num` SUBST_ALL_TAC) THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `4`;
    `iqmat4 (&1) (&0) (&0) (&0)
            (&2) (&0) (&rb) (&5) (&rc) (&k)`;
    `A:num->num->int`; `&u:int`] IQ_REPRESENTS_OF_EMBEDS) THEN
  CONJ_TAC THENL
   [REMOVE_THEN "emb" MATCH_ACCEPT_TAC;
    MATCH_MP_TAC IQ_125_CHILD_REP_OF_NUM THEN
    REMOVE_THEN "almost" (MATCH_MP_TAC o SPEC `u:num`) THEN
    CONJ_TAC THENL
     [UNDISCH_TAC `&0 < &u` THEN REWRITE_TAC[INT_OF_NUM_LT];
      UNDISCH_TAC `~(&u = &15)` THEN REWRITE_TAC[INT_OF_NUM_EQ]]]);;

