let IQ_UNIVERSAL_OF_DIAG125_CHILD = prove
 (`!n A k.
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&0) (&0) (&5) (&0) k) A /\
     &1 <= k /\ k <= &10 /\
     iq_represents n A (&15)
     ==> iq_universal n A`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(EQ_MP (SYM(SPEC `k:int` INT_OF_NUM_EXISTS))
    (MATCH_MP (INT_ARITH `&1 <= k ==> &0 <= k`)
      (ASSUME `&1 <= k`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `c:num` SUBST_ALL_TAC) THEN
  SUBGOAL_THEN `1 <= c /\ c <= 10` ASSUME_TAC THENL
   [UNDISCH_TAC `&1 <= &c` THEN
    UNDISCH_TAC `&c <= &10` THEN
    REWRITE_TAC[INT_OF_NUM_LE] THEN ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `A:num->num->int`; `0`; `0`; `c:num`]
   IQ_UNIVERSAL_OF_125_CHILD_ALMOST15) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(SPEC `c:num` INT_ALMOST_UNIVERSAL_DIAG125) THEN
  ASM_REWRITE_TAC[]);;

