    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    ASM_REWRITE_TAC[iqgram; IQBILIN_MAT4; iqflip_cross125; iqrows4;
      iqmat4; iqsym] THEN
    CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_RING]);;

let IQ_REPRESENTS_FLIP_CROSS125 = prove
 (`!b c k t.
     iq_represents 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) b (&5) c k) t
     ==> iq_represents 4
          (iqmat4 (&1) (&0) (&0) (&0)
                  (&2) (&1) (--b) (&5) (--c) k) t`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[iq_represents] THEN
  DISCH_THEN(X_CHOOSE_TAC `v:num->int`) THEN
  EXISTS_TAC `\i:num. if i = 3 then --(v i) else v i` THEN
  FIRST_X_ASSUM(MP_TAC) THEN
  REWRITE_TAC[IQEVAL_MAT4] THEN
  CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_RING);;

let IQ_EMBEDS_REPRESENTS_FLIP_CROSS125 = prove
 (`!n A b c k t.
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) b (&5) c k) A /\
     iq_represents 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) b (&5) c k) t
     ==> iq_embeds n 4
          (iqmat4 (&1) (&0) (&0) (&0)
                  (&2) (&1) (--b) (&5) (--c) k) A /\
         iq_represents 4
          (iqmat4 (&1) (&0) (&0) (&0)
                  (&2) (&1) (--b) (&5) (--c) k) t`,
  MESON_TAC[IQ_EMBEDS_FLIP_CROSS125; IQ_REPRESENTS_FLIP_CROSS125]);;

let IQ_FLIP_CROSS125_02 = prove
 (`!n A k t.
