let IQ_EMBEDS_QUATERNARY_CROSS125_RAW = prove
 (`!n A.
     iq_symmetric n A /\ iq_positive n A /\
     iq_embeds n 3
       (iqmat3 (&1) (&0) (&0) (&2) (&1) (&5)) A /\
     iq_represents n A (&7)
     ==> ?rb rc k.
           ((rb = &0 /\ rc = &0) \/
            (rb = &1 /\ rc = &0) \/
            (rb = &0 /\ rc = -- &1) \/
            (rb = &1 /\ rc = -- &1) \/
            (rb = &0 /\ rc = -- &2) \/
            (rb = &0 /\ rc = &2) \/
            (rb = -- &1 /\ rc = &1) \/
            (rb = &0 /\ rc = &1) \/
            (rb = -- &1 /\ rc = &0)) /\
           iq_embeds n 4
             (iqmat4 (&1) (&0) (&0) (&0)
                     (&2) (&1) rb (&5) rc k) A /\
           iq_represents 4
             (iqmat4 (&1) (&0) (&0) (&0)
                     (&2) (&1) rb (&5) rc k) (&7)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL
   [`n:num`; `A:num->num->int`;
    `&1:int`; `&0:int`; `&0:int`; `&2:int`; `&1:int`; `&5:int`;
    `&7:int`] IQ_ESCALATE_MAT3) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:int`
    (X_CHOOSE_THEN `b:int`
      (X_CHOOSE_THEN `c:int` STRIP_ASSUME_TAC))) THEN
  MP_TAC(SPECL [`b:int`; `c:int`] INT_CROSS125_REMAINDER) THEN
  DISCH_THEN(X_CHOOSE_THEN `q:int`
    (X_CHOOSE_THEN `r:int`
      (X_CHOOSE_THEN `rb:int`
        (X_CHOOSE_THEN `rc:int`
          (CONJUNCTS_THEN2 ASSUME_TAC
            (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)))))) THEN
  let kval =
    `&7 - a pow 2 -
     &2 * q pow 2 - &2 * q * r - &5 * r pow 2 -
     &2 * q * rb - &2 * r * rc` in
  let source_emb = REWRITE_RULE
    [ASSUME `b = &2 * q + r + rb`;
     ASSUME `c = q + &5 * r + rc`]
    (ASSUME
      `iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) a
               (&2) (&1) b (&5) c (&7)) A`) in
  let emb = MATCH_MP
    (ISPECL
      [`n:num`; `A:num->num->int`; `a:int`; `q:int`; `r:int`;
       `rb:int`; `rc:int`; `&7:int`] IQ_EMBEDS_CLEAR_CROSS125)
    source_emb in
  let rep7 = MATCH_MP
    (SPECL
      [`a:int`; `q:int`; `r:int`; `rb:int`; `rc:int`; kval]
      IQ_CROSS125_REDUCED_REPRESENTS_7)
    (REFL kval) in
  MAP_EVERY EXISTS_TAC [`rb:int`; `rc:int`; kval] THEN
  ACCEPT_TAC
   (CONJ
     (ASSUME
       `(rb = &0 /\ rc = &0) \/
        (rb = &1 /\ rc = &0) \/
        (rb = &0 /\ rc = -- &1) \/
        (rb = &1 /\ rc = -- &1) \/
        (rb = &0 /\ rc = -- &2) \/
        (rb = &0 /\ rc = &2) \/
        (rb = -- &1 /\ rc = &1) \/
        (rb = &0 /\ rc = &1) \/
        (rb = -- &1 /\ rc = &0)`)
     (CONJ emb rep7)));;

let IQ_EMBEDS_QUATERNARY_CROSS125 = prove
 (`!n A.
     iq_symmetric n A /\ iq_positive n A /\
     iq_embeds n 3
       (iqmat3 (&1) (&0) (&0) (&2) (&1) (&5)) A /\
     iq_represents n A (&7)
     ==> (?k.
            iq_embeds n 4
              (iqmat4 (&1) (&0) (&0) (&0)
                      (&2) (&1) (&0) (&5) (&0) k) A /\
            iq_represents 4
              (iqmat4 (&1) (&0) (&0) (&0)
                      (&2) (&1) (&0) (&5) (&0) k) (&7)) \/
         (?k.
            iq_embeds n 4
              (iqmat4 (&1) (&0) (&0) (&0)
                      (&2) (&1) (&1) (&5) (&0) k) A /\
            iq_represents 4
              (iqmat4 (&1) (&0) (&0) (&0)
                      (&2) (&1) (&1) (&5) (&0) k) (&7)) \/
         (?k.
            iq_embeds n 4
              (iqmat4 (&1) (&0) (&0) (&0)
                      (&2) (&1) (&0) (&5) (-- &1) k) A /\
            iq_represents 4
              (iqmat4 (&1) (&0) (&0) (&0)
                      (&2) (&1) (&0) (&5) (-- &1) k) (&7)) \/
         (?k.
            iq_embeds n 4
              (iqmat4 (&1) (&0) (&0) (&0)
                      (&2) (&1) (&1) (&5) (-- &1) k) A /\
            iq_represents 4
              (iqmat4 (&1) (&0) (&0) (&0)
                      (&2) (&1) (&1) (&5) (-- &1) k) (&7)) \/
         (?k.
            iq_embeds n 4
              (iqmat4 (&1) (&0) (&0) (&0)
                      (&2) (&1) (&0) (&5) (-- &2) k) A /\
            iq_represents 4
              (iqmat4 (&1) (&0) (&0) (&0)
                      (&2) (&1) (&0) (&5) (-- &2) k) (&7))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`n:num`; `A:num->num->int`]
    IQ_EMBEDS_QUATERNARY_CROSS125_RAW) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `rb:int`
    (X_CHOOSE_THEN `rc:int`
      (X_CHOOSE_THEN `k:int`
        (CONJUNCTS_THEN2 ASSUME_TAC
          (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC))))) THEN
  UNDISCH_TAC
   `(rb = &0 /\ rc = &0) \/
    (rb = &1 /\ rc = &0) \/
    (rb = &0 /\ rc = -- &1) \/
    (rb = &1 /\ rc = -- &1) \/
    (rb = &0 /\ rc = -- &2) \/
    (rb = &0 /\ rc = &2) \/
    (rb = -- &1 /\ rc = &1) \/
    (rb = &0 /\ rc = &1) \/
    (rb = -- &1 /\ rc = &0)` THEN
  ASM_MESON_TAC
   [IQ_FLIP_CROSS125_02; IQ_FLIP_CROSS125_NEG11;
    IQ_FLIP_CROSS125_01; IQ_FLIP_CROSS125_NEG10]);;

(* The crossed ternary form is the index-three subform

     x^2 + (y + 2z)^2 + (y - z)^2.

   Completing the two displayed squares gives the determinant identity used
   in Bhargava's subtraction argument. *)
let INT_CROSS125_CHILD_DET_IDENTITY = prove
 (`!b c k x y z w:int.
     &9 *
       (x pow 2 + &2 * y pow 2 + &2 * y * z + &5 * z pow 2 +
        &2 * b * y * w + &2 * c * z * w + k * w pow 2) =
     (&3 * x) pow 2 +
     (&3 * (y + &2 * z) + (b + c) * w) pow 2 +
     (&3 * (y - z) + (&2 * b - c) * w) pow 2 +
     cross125_det b c k * w pow 2`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cross125_det] THEN CONV_TAC INT_RING);;

let INT_THREE_SQUARES_7MOD8_CORE = prove
 (`!a b c:int.
     (a = &0 \/ a = &1 \/ a = &4) /\
     (b = &0 \/ b = &1 \/ b = &4) /\
     (c = &0 \/ c = &1 \/ c = &4) /\
     (a + b + c) rem &8 = &7
     ==> F`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  POP_ASSUM MP_TAC THEN ASM_REWRITE_TAC[] THEN
  CONV_TAC INT_REDUCE_CONV);;

let INT_THREE_SQUARES_NOT_7MOD8 = prove
 (`!x y z q:int.
     ~(x pow 2 + y pow 2 + z pow 2 = &8 * q + &7)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC(SPECL
   [`x pow 2 rem &8`; `y pow 2 rem &8`; `z pow 2 rem &8`]
   INT_THREE_SQUARES_7MOD8_CORE) THEN
  REWRITE_TAC[SQ_MOD_8] THEN
  SUBGOAL_THEN
   `(x pow 2 rem &8 + y pow 2 rem &8 + z pow 2 rem &8) rem &8 =
    (x pow 2 + y pow 2 + z pow 2) rem &8`
  SUBST1_TAC THENL
   [CONV_TAC INT_REM_DOWN_CONV THEN REFL_TAC;
    ASM_REWRITE_TAC[INT_REM_MUL_ADD] THEN CONV_TAC INT_REDUCE_CONV]);;

let INT_CROSS125_NOT_7 = prove
 (`!x y z:int.
     ~(x pow 2 + &2 * y pow 2 + &2 * y * z + &5 * z pow 2 = &7)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`x:int`; `y + &2 * z:int`; `y - z:int`; `&0:int`]
    INT_THREE_SQUARES_NOT_7MOD8) THEN
  FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING);;

let IQ_CROSS125_DET_NONZERO_OF_REPRESENTS_7 = prove
 (`!b c k:int.
     iq_represents 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) b (&5) c k) (&7)
     ==> ~(cross125_det b c k = &0)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[iq_represents] THEN
  DISCH_THEN(X_CHOOSE_THEN `v:num->int` (LABEL_TAC "rep")) THEN
  DISCH_THEN(LABEL_TAC "det0") THEN
  SUBGOAL_THEN
   `(&3 * v 0) pow 2 +
    (&3 * (v 1 + &2 * v 2) + (b + c) * v 3) pow 2 +
    (&3 * (v 1 - v 2) + (&2 * b - c) * v 3) pow 2 =
    &8 * &7 + &7`
  ASSUME_TAC THENL
   [MP_TAC(SPECL
     [`b:int`; `c:int`; `k:int`; `v 0:int`; `v 1:int`;
      `v 2:int`; `v 3:int`] INT_CROSS125_CHILD_DET_IDENTITY) THEN
    REMOVE_THEN "rep" MP_TAC THEN
    REWRITE_TAC[IQEVAL_MAT4] THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_RING;
    MP_TAC(SPECL
     [`&3 * v 0:int`;
      `&3 * (v 1 + &2 * v 2) + (b + c) * v 3:int`;
      `&3 * (v 1 - v 2) + (&2 * b - c) * v 3:int`;
      `&7:int`] INT_THREE_SQUARES_NOT_7MOD8) THEN
    ASM_REWRITE_TAC[]]);;

let IQ_CROSS125_DET_NOT_DIV8_OF_REPRESENTS_7 = prove
 (`!b c k:int.
     iq_represents 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) b (&5) c k) (&7)
     ==> ~(&8 divides cross125_det b c k)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[iq_represents] THEN
  DISCH_THEN(X_CHOOSE_THEN `v:num->int` (LABEL_TAC "rep")) THEN
  REWRITE_TAC[int_divides] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:int` (LABEL_TAC "detdiv")) THEN
  SUBGOAL_THEN
   `(&3 * v 0) pow 2 +
    (&3 * (v 1 + &2 * v 2) + (b + c) * v 3) pow 2 +
    (&3 * (v 1 - v 2) + (&2 * b - c) * v 3) pow 2 =
    &8 * (&7 - d * v 3 pow 2) + &7`
  ASSUME_TAC THENL
   [MP_TAC(SPECL
     [`b:int`; `c:int`; `k:int`; `v 0:int`; `v 1:int`;
      `v 2:int`; `v 3:int`] INT_CROSS125_CHILD_DET_IDENTITY) THEN
    REMOVE_THEN "rep" MP_TAC THEN
    REWRITE_TAC[IQEVAL_MAT4] THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_RING;
    MP_TAC(SPECL
     [`&3 * v 0:int`;
      `&3 * (v 1 + &2 * v 2) + (b + c) * v 3:int`;
      `&3 * (v 1 - v 2) + (&2 * b - c) * v 3:int`;
      `(&7:int) - d * v 3 pow 2`] INT_THREE_SQUARES_NOT_7MOD8) THEN
    ASM_REWRITE_TAC[]]);;

let INT_CROSS125_ORTHOGONAL_VALUE = prove
 (`!b c k:int.
     &2 * (--(&5 * b - c)) pow 2 +
     &2 * (--(&5 * b - c)) * (b - &2 * c) +
     &2 * b * (--(&5 * b - c)) * &9 +
     &5 * (b - &2 * c) pow 2 +
     &2 * c * (b - &2 * c) * &9 +
     k * &81 =
     &9 * cross125_det b c k`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cross125_det] THEN CONV_TAC INT_RING);;

let IQ_CROSS125_DET_NONNEG = prove
 (`!n A b c k.
     iq_positive n A /\
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) b (&5) c k) A
     ==> &0 <= cross125_det b c k`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP
   (ISPECL
     [`n:num`; `4`;
      `iqmat4 (&1) (&0) (&0) (&0)
              (&2) (&1) b (&5) c k`;
      `A:num->num->int`] IQ_EMBEDDED_NONNEG)
   (CONJ
     (ASSUME `iq_positive n A`)
     (ASSUME
       `iq_embeds n 4
        (iqmat4 (&1) (&0) (&0) (&0)
                (&2) (&1) b (&5) c k) A`))) THEN
  DISCH_THEN(MP_TAC o SPEC
   `\i:num.
      if i = 1 then --(&5 * b - c) else
      if i = 2 then b - &2 * c else
      if i = 3 then &9 else &0`) THEN
  REWRITE_TAC[IQEVAL_MAT4] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  SIMP_TAC[INT_MUL_LZERO; INT_MUL_RZERO; INT_ADD_LID; INT_ADD_RID;
    INT_MUL_LID; INT_MUL_RID] THEN
  CONV_TAC INT_REDUCE_CONV THEN
  DISCH_TAC THEN
  MP_TAC(SPECL [`b:int`; `c:int`; `k:int`]
    INT_CROSS125_ORTHOGONAL_VALUE) THEN
  ASM_INT_ARITH_TAC);;

let IQ_CROSS125_DET_POSITIVE = prove
 (`!n A b c k.
     iq_positive n A /\
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) b (&5) c k) A /\
     iq_represents 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) b (&5) c k) (&7)
     ==> &0 < cross125_det b c k`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP
   (ISPECL [`n:num`; `A:num->num->int`; `b:int`; `c:int`; `k:int`]
     IQ_CROSS125_DET_NONNEG)
   (CONJ
     (ASSUME `iq_positive n A`)
     (ASSUME
       `iq_embeds n 4
        (iqmat4 (&1) (&0) (&0) (&0)
                (&2) (&1) b (&5) c k) A`))) THEN
  MP_TAC(MATCH_MP
   (SPECL [`b:int`; `c:int`; `k:int`]
     IQ_CROSS125_DET_NONZERO_OF_REPRESENTS_7)
   (ASSUME
     `iq_represents 4
      (iqmat4 (&1) (&0) (&0) (&0)
              (&2) (&1) b (&5) c k) (&7)`)) THEN
  INT_ARITH_TAC);;

let IQ_CROSS125_DET_LE_63 = prove
 (`!n A b c k.
     iq_positive n A /\
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) b (&5) c k) A /\
     iq_represents 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) b (&5) c k) (&7)
     ==> cross125_det b c k <= &63`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "pos")
    (CONJUNCTS_THEN2 (LABEL_TAC "emb") (LABEL_TAC "rep7"))) THEN
  SUBGOAL_THEN `&0 < cross125_det b c k` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`n:num`; `A:num->num->int`; `b:int`; `c:int`; `k:int`]
     IQ_CROSS125_DET_POSITIVE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ASSUME
    `iq_represents 4
      (iqmat4 (&1) (&0) (&0) (&0)
              (&2) (&1) b (&5) c k) (&7)`) THEN
  REWRITE_TAC[iq_represents] THEN
  DISCH_THEN(X_CHOOSE_THEN `v:num->int` (LABEL_TAC "rep")) THEN
  SUBGOAL_THEN `~(v 3 = &0)` ASSUME_TAC THENL
   [DISCH_TAC THEN
    MP_TAC(SPECL [`v 0:int`; `v 1:int`; `v 2:int`]
      INT_CROSS125_NOT_7) THEN
    REMOVE_THEN "rep" MP_TAC THEN
    REWRITE_TAC[IQEVAL_MAT4] THEN ASM_REWRITE_TAC[] THEN
    CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cross125_det b c k <= cross125_det b c k * v 3 pow 2`
  ASSUME_TAC THENL
   [GEN_REWRITE_TAC (LAND_CONV) [GSYM INT_MUL_RID] THEN
    MATCH_MP_TAC INT_LE_LMUL THEN
    CONJ_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[INT_ARITH `&1 <= x <=> &0 < x`] THEN
    ASM_SIMP_TAC[INT_LT_POW_2];
    ALL_TAC] THEN
  SUBGOAL_THEN `cross125_det b c k * v 3 pow 2 <= &63`
  ASSUME_TAC THENL
   [MP_TAC(SPECL
     [`b:int`; `c:int`; `k:int`; `v 0:int`; `v 1:int`;
      `v 2:int`; `v 3:int`] INT_CROSS125_CHILD_DET_IDENTITY) THEN
    MP_TAC(ASSUME
     `iqeval 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) b (&5) c k) v = &7`) THEN
    REWRITE_TAC[IQEVAL_MAT4] THEN CONV_TAC NUM_REDUCE_CONV THEN
    MP_TAC(ISPEC `&3 * v 0:int` INT_LE_POW_2) THEN
    MP_TAC(ISPEC
     `&3 * (v 1 + &2 * v 2) + (b + c) * v 3:int`
     INT_LE_POW_2) THEN
    MP_TAC(ISPEC
     `&3 * (v 1 - v 2) + (&2 * b - c) * v 3:int`
     INT_LE_POW_2) THEN
    INT_ARITH_TAC;
    ASM_INT_ARITH_TAC]);;

let INT_CROSS125_1_NEG1_8_NOT_7 = prove
 (`!x y z w:int.
     ~(x pow 2 + &2 * y pow 2 + &2 * y * z + &5 * z pow 2 +
       &2 * y * w - &2 * z * w + &8 * w pow 2 = &7)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "rep") THEN
  ASM_CASES_TAC `w = &0` THENL
   [MP_TAC(SPECL [`x:int`; `y:int`; `z:int`] INT_CROSS125_NOT_7) THEN
    REMOVE_THEN "rep" MP_TAC THEN ASM_REWRITE_TAC[] THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN `&1 <= w pow 2` ASSUME_TAC THENL
   [REWRITE_TAC[INT_ARITH `&1 <= q <=> &0 < q`] THEN
    ASM_SIMP_TAC[INT_LT_POW_2];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(&3 * x) pow 2 + (&3 * (y + &2 * z)) pow 2 +
    (&3 * (y - z) + &3 * w) pow 2 + &63 * w pow 2 = &63`
  ASSUME_TAC THENL
   [MP_TAC(SPECL
     [`&1:int`; `-- &1:int`; `&8:int`; `x:int`; `y:int`; `z:int`;
      `w:int`] INT_CROSS125_CHILD_DET_IDENTITY) THEN
    REMOVE_THEN "rep" MP_TAC THEN
    REWRITE_TAC[cross125_det] THEN CONV_TAC INT_REDUCE_CONV THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&0 <= (&3 * x) pow 2 /\
    &0 <= (&3 * (y + &2 * z)) pow 2 /\
    &0 <= (&3 * (y - z) + &3 * w) pow 2`
  STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[INT_LE_POW_2];
    ALL_TAC] THEN
  SUBGOAL_THEN `(&3 * (y + &2 * z)) pow 2 = &0` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(&3 * (y - z) + &3 * w) pow 2 = &0` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `w pow 2 = &1` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `y + &2 * z = &0` ASSUME_TAC THENL
   [MP_TAC(ASSUME `(&3 * (y + &2 * z)) pow 2 = &0`) THEN
    REWRITE_TAC[INT_POW_EQ_0] THEN CONV_TAC NUM_REDUCE_CONV THEN
    INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `y - z + w = &0` ASSUME_TAC THENL
   [MP_TAC(ASSUME `(&3 * (y - z) + &3 * w) pow 2 = &0`) THEN
    REWRITE_TAC[INT_POW_EQ_0] THEN CONV_TAC NUM_REDUCE_CONV THEN
    INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `w = &3 * z` ASSUME_TAC THENL
   [ASM_INT_ARITH_TAC;
    MP_TAC(MATCH_MP INT_SQ_LE_2_CASES
     (MATCH_MP (INT_ARITH `w pow 2 = &1 ==> w pow 2 <= &2`)
      (ASSUME `w pow 2 = &1`))) THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    (ASM_CASES_TAC `z = &0` THENL
      [ASM_INT_ARITH_TAC;
       SUBGOAL_THEN `z < &0 \/ &0 < z` MP_TAC THENL
        [ASM_INT_ARITH_TAC;
         DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THEN
         ASM_INT_ARITH_TAC]])]);;

let IQ_CROSS125_1_NEG1_8_NOT_REPRESENTS_7 = prove
 (`~iq_represents 4
      (iqmat4 (&1) (&0) (&0) (&0)
              (&2) (&1) (&1) (&5) (-- &1) (&8)) (&7)`,
  REWRITE_TAC[iq_represents] THEN
  DISCH_THEN(X_CHOOSE_THEN `v:num->int` (LABEL_TAC "rep")) THEN
  MP_TAC(SPECL [`v 0:int`; `v 1:int`; `v 2:int`; `v 3:int`]
    INT_CROSS125_1_NEG1_8_NOT_7) THEN
  REMOVE_THEN "rep" MP_TAC THEN
  REWRITE_TAC[IQEVAL_MAT4] THEN CONV_TAC NUM_REDUCE_CONV THEN
  CONV_TAC INT_RING);;

let IQ_CROSS125_DET_CONSTRAINTS = prove
 (`!n A b c k.
     iq_positive n A /\
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) b (&5) c k) A /\
     iq_represents 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) b (&5) c k) (&7)
     ==> &0 < cross125_det b c k /\
         cross125_det b c k <= &63 /\
         ~(&8 divides cross125_det b c k)`,
  MESON_TAC[IQ_CROSS125_DET_POSITIVE; IQ_CROSS125_DET_LE_63;
    IQ_CROSS125_DET_NOT_DIV8_OF_REPRESENTS_7]);;

let IQ_CROSS125_00_PARAMETER_CASES = prove
 (`!n A k.
     iq_positive n A /\
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) (&0) (&5) (&0) k) A /\
     iq_represents 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) (&0) (&5) (&0) k) (&7)
     ==> k = &1 \/ k = &2 \/ k = &3 \/ k = &4 \/
         k = &5 \/ k = &6 \/ k = &7`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`n:num`; `A:num->num->int`; `&0`; `&0`; `k:int`]
    IQ_CROSS125_DET_CONSTRAINTS) THEN
  ASM_REWRITE_TAC[cross125_det] THEN CONV_TAC INT_REDUCE_CONV THEN
  STRIP_TAC THEN ASM_INT_ARITH_TAC);;

let IQ_CROSS125_10_PARAMETER_CASES = prove
 (`!n A k.
     iq_positive n A /\
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) (&1) (&5) (&0) k) A /\
     iq_represents 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) (&1) (&5) (&0) k) (&7)
     ==> k = &1 \/ k = &2 \/ k = &3 \/ k = &4 \/
