     (`(&8:int) divides &9 * &5 - &1 - &4`,
      REWRITE_TAC[int_divides] THEN EXISTS_TAC `&5:int` THEN
      INT_ARITH_TAC)) THEN
    ASM_REWRITE_TAC[]]);;

let IQ_CROSS125_0_NEG1_PARAMETER_CASES = prove
 (`!n A k.
     iq_positive n A /\
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) (&0) (&5) (-- &1) k) A /\
