  STRIP_TAC THEN
  SUBGOAL_THEN
   `k = &1 \/ k = &2 \/ k = &3 \/ k = &4 \/
    k = &5 \/ k = &6 \/ k = &7`
  MP_TAC THENL
   [ASM_INT_ARITH_TAC;
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    ASM_REWRITE_TAC[] THEN
