let IQ_CROSS125_0_NEG2_PARAMETER_CASES = prove
 (`!n A k.
     iq_positive n A /\
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) (&0) (&5) (-- &2) k) A /\
     iq_represents 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) (&0) (&5) (-- &2) k) (&7)
     ==> k = &1 \/ k = &2 \/ k = &3 \/ k = &4 \/
         k = &5 \/ k = &6 \/ k = &7`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`n:num`; `A:num->num->int`; `&0`; `-- &2`; `k:int`]
    IQ_CROSS125_DET_CONSTRAINTS) THEN
  ASM_REWRITE_TAC[cross125_det] THEN CONV_TAC INT_REDUCE_CONV THEN
  STRIP_TAC THEN ASM_INT_ARITH_TAC);;

(* Multiplying the last coordinate by 9 clears the index-three denominator
   in the orthogonal complement. *)
let INT_CROSS125_CHILD_SHIFT9 = prove
 (`!b c k s x y z:int.
     x pow 2 +
     &2 * (y - (&5 * b - c) * s) pow 2 +
     &2 * (y - (&5 * b - c) * s) *
          (z + (b - &2 * c) * s) +
     &5 * (z + (b - &2 * c) * s) pow 2 +
     &2 * b * (y - (&5 * b - c) * s) * (&9 * s) +
     &2 * c * (z + (b - &2 * c) * s) * (&9 * s) +
     k * (&9 * s) pow 2 =
     x pow 2 + &2 * y pow 2 + &2 * y * z + &5 * z pow 2 +
     &9 * cross125_det b c k * s pow 2`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cross125_det] THEN CONV_TAC INT_RING);;

let INT_REPRESENTS_CROSS125_CHILD_SHIFT9 = prove
 (`!b c k s n:int.
     (?x y z:int.
        x pow 2 + &2 * y pow 2 + &2 * y * z + &5 * z pow 2 =
        n - &9 * cross125_det b c k * s pow 2)
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &2 * y * z + &5 * z pow 2 +
          &2 * b * y * w + &2 * c * z * w + k * w pow 2 = n`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int` (X_CHOOSE_TAC `z:int`))) THEN
  MAP_EVERY EXISTS_TAC
   [`x:int`;
    `y - (&5 * b - c) * s:int`;
    `z + (b - &2 * c) * s:int`;
    `&9 * s:int`] THEN
  MP_TAC(SPECL
   [`b:int`; `c:int`; `k:int`; `s:int`; `x:int`; `y:int`; `z:int`]
   INT_CROSS125_CHILD_SHIFT9) THEN
  FIRST_X_ASSUM(MP_TAC) THEN INT_ARITH_TAC);;

let INT_REPRESENTS_CROSS125_CHILD_SCALE4 = prove
 (`!b c k n:int.
     (?x y z w:int.
        x pow 2 + &2 * y pow 2 + &2 * y * z + &5 * z pow 2 +
        &2 * b * y * w + &2 * c * z * w + k * w pow 2 = n)
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &2 * y * z + &5 * z pow 2 +
          &2 * b * y * w + &2 * c * z * w + k * w pow 2 = &4 * n`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int`
      (X_CHOOSE_THEN `z:int` (X_CHOOSE_TAC `w:int`)))) THEN
  MAP_EVERY EXISTS_TAC
   [`&2 * x:int`; `&2 * y:int`; `&2 * z:int`; `&2 * w:int`] THEN
  FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING);;

(* ------------------------------------------------------------------------- *)
(* A generic almost-universality descent for the 32 admissible children.     *)
(* ------------------------------------------------------------------------- *)

let cross125_child_rep = new_definition
 `cross125_child_rep (b:int) c k (n:num) <=>
    ?x y z w:int.
      x pow 2 + &2 * y pow 2 + &2 * y * z + &5 * z pow 2 +
      &2 * b * y * w + &2 * c * z * w + k * w pow 2 = &n`;;

let CROSS125_CHILD_REP_SCALE4 = prove
 (`!b c k n.
     cross125_child_rep b c k n
     ==> cross125_child_rep b c k (4 * n)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cross125_child_rep] THEN
  DISCH_TAC THEN
  MP_TAC(MATCH_MP
    (SPECL [`b:int`; `c:int`; `k:int`; `&n:int`]
      INT_REPRESENTS_CROSS125_CHILD_SCALE4)
    (ASSUME
      `?x y z w:int.
        x pow 2 + &2 * y pow 2 + &2 * y * z + &5 * z pow 2 +
        &2 * b * y * w + &2 * c * z * w + k * w pow 2 = &n`)) THEN
  REWRITE_TAC[GSYM INT_OF_NUM_MUL]);;

let CROSS125_CHILD_REP_REGULAR = prove
 (`!b c k n.
     ~(?a m. n = 4 EXP a * (8 * m + 7))
     ==> cross125_child_rep b c k n`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[cross125_child_rep] THEN
  MP_TAC(MATCH_MP
    (SPEC `n:num` INT_REPRESENTS_CROSS125_OF_LEGENDRE)
    (ASSUME `~(?a m. n = 4 EXP a * (8 * m + 7))`)) THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int` (X_CHOOSE_TAC `z:int`))) THEN
  MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`; `&0:int`] THEN
  FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING);;

let NUM_CROSS125_SUB_AVOIDS = prove
 (`!n c:num.
     c <= n /\ n MOD 8 = 7 /\
     (c MOD 8 = 2 \/ c MOD 8 = 4 \/ c MOD 8 = 6)
     ==> ~(?a m. n - c = 4 EXP a * (8 * m + 7))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
  MATCH_MP_TAC(SPEC `n - c:num` THREE_SQUARES_AVOIDS_OF_MOD) THEN
  MP_TAC(MATCH_MP (SPECL [`n:num`; `8`; `7`] NUM_DECOMPOSE_MOD)
    (CONJ (ARITH_RULE `~(8 = 0)`) (ASSUME `n MOD 8 = 7`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `qn:num` SUBST_ALL_TAC) THEN
  UNDISCH_TAC `c MOD 8 = 2 \/ c MOD 8 = 4 \/ c MOD 8 = 6` THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [MP_TAC(MATCH_MP (SPECL [`c:num`; `8`; `2`] NUM_DECOMPOSE_MOD)
      (CONJ (ARITH_RULE `~(8 = 0)`) (ASSUME `c MOD 8 = 2`)));
    MP_TAC(MATCH_MP (SPECL [`c:num`; `8`; `4`] NUM_DECOMPOSE_MOD)
      (CONJ (ARITH_RULE `~(8 = 0)`) (ASSUME `c MOD 8 = 4`)));
    MP_TAC(MATCH_MP (SPECL [`c:num`; `8`; `6`] NUM_DECOMPOSE_MOD)
      (CONJ (ARITH_RULE `~(8 = 0)`) (ASSUME `c MOD 8 = 6`)))] THEN
  DISCH_THEN(X_CHOOSE_THEN `qc:num` SUBST_ALL_TAC) THENL
   [SUBGOAL_THEN
     `(8 * qn + 7) - (8 * qc + 2) = 8 * (qn - qc) + 5`
    SUBST1_TAC THENL [ASM_ARITH_TAC; ALL_TAC];
    SUBGOAL_THEN
     `(8 * qn + 7) - (8 * qc + 4) = 8 * (qn - qc) + 3`
    SUBST1_TAC THENL [ASM_ARITH_TAC; ALL_TAC];
    SUBGOAL_THEN
     `(8 * qn + 7) - (8 * qc + 6) = 8 * (qn - qc) + 1`
    SUBST1_TAC THENL [ASM_ARITH_TAC; ALL_TAC]] THEN
  (CONJ_TAC THENL
    [REWRITE_TAC
      [ARITH_RULE `8*q+r = 4*(2*q)+r`; MOD_MULT_ADD] THEN
     CONV_TAC NUM_REDUCE_CONV;
     REWRITE_TAC[MOD_MULT_ADD] THEN CONV_TAC NUM_REDUCE_CONV]));;

let INT_CROSS125_OFFSET_COERCE = prove
 (`!n d s:num.
     9 * d * s EXP 2 <= n
     ==> &(n - 9 * d * s EXP 2) =
         (&n:int) - &9 * &d * (&s:int) pow 2`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC EQ_TRANS THEN
  EXISTS_TAC `(&n:int) - &(9 * d * s EXP 2)` THEN
  CONJ_TAC THENL
   [MATCH_ACCEPT_TAC(SYM(MATCH_MP
      (SPECL [`9 * d * s EXP 2`; `n:num`] INT_OF_NUM_SUB)
      (ASSUME `9 * d * s EXP 2 <= n`)));
    REWRITE_TAC[INT_OF_NUM_MUL; INT_OF_NUM_POW] THEN
    CONV_TAC INT_RING]);;

let INT_CROSS125_CHILD_OFFSET_COERCE = prove
 (`!b c k n d s.
     cross125_det b c k = &d /\ 9 * d * s EXP 2 <= n
     ==> &(n - 9 * d * s EXP 2) =
         (&n:int) - &9 * cross125_det b c k * (&s:int) pow 2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP
    (SPECL [`n:num`; `d:num`; `s:num`] INT_CROSS125_OFFSET_COERCE)
    (ASSUME `9 * d * s EXP 2 <= n`)) THEN
  ASM_REWRITE_TAC[]);;

let CROSS125_CHILD_REP_RESIDUE7 = prove
 (`!b c k d s.
     cross125_det b c k = &d /\ 0 < d /\
     ((9 * d * s EXP 2) MOD 8 = 2 \/
      (9 * d * s EXP 2) MOD 8 = 4 \/
      (9 * d * s EXP 2) MOD 8 = 6) /\
     (!q:num.
        8 * q + 7 < 9 * d * s EXP 2 /\ ~(q = 1)
        ==> cross125_child_rep b c k (8 * q + 7))
     ==> !n:num.
          0 < n /\ n MOD 8 = 7 /\ ~(n = 15)
          ==> cross125_child_rep b c k n`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "det")
    (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 (LABEL_TAC "offsetmod") (LABEL_TAC "base")))) THEN
  X_GEN_TAC `n:num` THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP (SPECL [`n:num`; `8`; `7`] NUM_DECOMPOSE_MOD)
    (CONJ (ARITH_RULE `~(8 = 0)`) (ASSUME `n MOD 8 = 7`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `q:num` SUBST_ALL_TAC) THEN
  SUBGOAL_THEN `~(q = 1)` ASSUME_TAC THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  ASM_CASES_TAC `8 * q + 7 < 9 * d * s EXP 2` THENL
   [REMOVE_THEN "base" (MATCH_MP_TAC o SPEC `q:num`) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `9 * d * s EXP 2 <= 8 * q + 7` ASSUME_TAC THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[cross125_child_rep] THEN
  MATCH_MP_TAC(SPECL
    [`b:int`; `c:int`; `k:int`; `&s:int`; `&(8 * q + 7):int`]
    INT_REPRESENTS_CROSS125_CHILD_SHIFT9) THEN
  SUBGOAL_THEN
   `~(?a m.
       (8 * q + 7) - 9 * d * s EXP 2 = 4 EXP a * (8 * m + 7))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`8 * q + 7`; `9 * d * s EXP 2`]
      NUM_CROSS125_SUB_AVOIDS) THEN
    REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      REWRITE_TAC[MOD_MULT_ADD] THEN CONV_TAC NUM_REDUCE_CONV;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
    (SPEC `(8 * q + 7) - 9 * d * s EXP 2`
      INT_REPRESENTS_CROSS125_OF_LEGENDRE)
    (ASSUME
     `~(?a m.
        (8 * q + 7) - 9 * d * s EXP 2 =
        4 EXP a * (8 * m + 7))`)) THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int`
      (X_CHOOSE_THEN `z:int` (LABEL_TAC "tern")))) THEN
  MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`] THEN
  MP_TAC(MATCH_MP
    (SPECL
      [`b:int`; `c:int`; `k:int`; `8 * q + 7`; `d:num`; `s:num`]
      INT_CROSS125_CHILD_OFFSET_COERCE)
    (CONJ
      (ASSUME `cross125_det b c k = &d`)
      (ASSUME `9 * d * s EXP 2 <= 8 * q + 7`))) THEN
  REMOVE_THEN "tern" MP_TAC THEN CONV_TAC INT_RING);;

let CROSS125_CHILD_ALMOST15 = prove
 (`!b c k.
     cross125_child_rep b c k 60 /\
     (!n:num.
        0 < n /\ n MOD 8 = 7 /\ ~(n = 15)
        ==> cross125_child_rep b c k n)
     ==> !n:num.
          0 < n /\ ~(n = 15)
          ==> cross125_child_rep b c k n`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sixty")
    (LABEL_TAC "residue7")) THEN
  MATCH_MP_TAC num_WF THEN X_GEN_TAC `n:num` THEN
  DISCH_THEN(LABEL_TAC "ind") THEN STRIP_TAC THEN
  ASM_CASES_TAC `4 divides n` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `q:num` ASSUME_TAC o
      REWRITE_RULE[divides]) THEN
    ASM_CASES_TAC `q = 15` THENL
     [SUBGOAL_THEN `n = 60` SUBST_ALL_TAC THENL
       [ASM_ARITH_TAC;
        REMOVE_THEN "sixty" MATCH_ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `q < n /\ 0 < q` STRIP_ASSUME_TAC THENL
     [ASM_ARITH_TAC; ALL_TAC] THEN
    ONCE_REWRITE_TAC[ASSUME `n = 4 * q`] THEN
    MATCH_MP_TAC(SPECL [`b:int`; `c:int`; `k:int`; `q:num`]
      CROSS125_CHILD_REP_SCALE4) THEN
    REMOVE_THEN "ind" (MP_TAC o SPEC `q:num`) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `n MOD 8 = 7` THENL
   [REMOVE_THEN "residue7" (MATCH_MP_TAC o SPEC `n:num`) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(SPECL [`b:int`; `c:int`; `k:int`; `n:num`]
      CROSS125_CHILD_REP_REGULAR) THEN
    MATCH_MP_TAC(SPEC `n:num` THREE_SQUARES_AVOIDS_OF_MOD) THEN
    CONJ_TAC THENL
     [UNDISCH_TAC `~(4 divides n)` THEN REWRITE_TAC[DIVIDES_MOD];
      ASM_REWRITE_TAC[]]]);;

(* The search below is only a witness generator. Every returned quadruple is
   checked by INT_REDUCE_CONV before it enters the theorem. *)

let cross125_num_of_int i =
  if i < 0
  then minus_num(num_of_string(string_of_int(-i)))
  else num_of_string(string_of_int i);;

let CROSS125_CERT_TAC b c k =
  fun (asl,goal) ->
    let _,bod = strip_exists goal in
    let _,rhs = dest_eq bod in
    let n = int_of_string(string_of_num(dest_intconst rhs)) in
    let d = 9*k - (b+c)*(b+c) - (2*b-c)*(2*b-c) in
    let isqrt r = int_of_float(float_sqrt(float_of_int r)) in
    let signed i =
      if i = 0 then 0
      else if i mod 2 = 1 then (i + 1) / 2 else -(i / 2) in
    let check x y z w =
      x*x + 2*y*y + 2*y*z + 5*z*z +
      2*b*y*w + 2*c*z*w + k*w*w = n in
    let recover x w u v =
      let zn = u - v + (b - 2*c)*w
      and yn = u + 2*v - (5*b - c)*w in
      if zn mod 9 <> 0 || yn mod 9 <> 0 then None else
      let z = zn / 9 and y = yn / 9 in
      if check x y z w then Some(x,y,z,w) else None in
    let wmax = isqrt((9*n) / d) in
    let rec find_w iw =
      if iw > 2*wmax then failwith "CROSS125_CERT_TAC" else
      let w = signed iw in
      let rw = 9*n - d*w*w in
      if rw < 0 then find_w (iw+1) else
      let xmax = isqrt(rw / 9) in
      let rec find_x x =
        if x > xmax then find_w (iw+1) else
        let r = rw - 9*x*x in
        let umax = isqrt r in
        let rec find_u iu =
          if iu > 2*umax then find_x (x+1) else
          let u = signed iu in
          let v2 = r - u*u in
          if v2 < 0 then find_u (iu+1) else
          let v = isqrt v2 in
          if v*v <> v2 then find_u (iu+1) else
          match recover x w u v with
          | Some ans -> ans
          | None ->
              if v = 0 then find_u (iu+1) else
              match recover x w u (-v) with
              | Some ans -> ans
              | None -> find_u (iu+1) in
        find_u 0 in
      find_x 0 in
    let x,y,z,w = find_w 0 in
    (MAP_EVERY EXISTS_TAC
       (map (mk_intconst o cross125_num_of_int) [x;y;z;w]) THEN
     CONV_TAC INT_REDUCE_CONV) (asl,goal);;

(* For odd determinants take s = 2; for even determinants take s = 1. *)
let cross125_admissible = new_definition
 `cross125_admissible (b:int) c k (d:num) s <=>
    (b = &0 /\ c = &0 /\ k = &1 /\ d = 9 /\ s = 2) \/
    (b = &0 /\ c = &0 /\ k = &2 /\ d = 18 /\ s = 1) \/
    (b = &0 /\ c = &0 /\ k = &3 /\ d = 27 /\ s = 2) \/
    (b = &0 /\ c = &0 /\ k = &4 /\ d = 36 /\ s = 1) \/
    (b = &0 /\ c = &0 /\ k = &5 /\ d = 45 /\ s = 2) \/
    (b = &0 /\ c = &0 /\ k = &6 /\ d = 54 /\ s = 1) \/
    (b = &0 /\ c = &0 /\ k = &7 /\ d = 63 /\ s = 2) \/
    (b = &1 /\ c = &0 /\ k = &1 /\ d = 4 /\ s = 1) \/
    (b = &1 /\ c = &0 /\ k = &2 /\ d = 13 /\ s = 2) \/
    (b = &1 /\ c = &0 /\ k = &3 /\ d = 22 /\ s = 1) \/
    (b = &1 /\ c = &0 /\ k = &4 /\ d = 31 /\ s = 2) \/
    (b = &1 /\ c = &0 /\ k = &6 /\ d = 49 /\ s = 2) \/
    (b = &1 /\ c = &0 /\ k = &7 /\ d = 58 /\ s = 1) \/
    (b = &0 /\ c = -- &1 /\ k = &1 /\ d = 7 /\ s = 2) \/
    (b = &0 /\ c = -- &1 /\ k = &3 /\ d = 25 /\ s = 2) \/
    (b = &0 /\ c = -- &1 /\ k = &4 /\ d = 34 /\ s = 1) \/
    (b = &0 /\ c = -- &1 /\ k = &5 /\ d = 43 /\ s = 2) \/
    (b = &0 /\ c = -- &1 /\ k = &6 /\ d = 52 /\ s = 1) \/
    (b = &0 /\ c = -- &1 /\ k = &7 /\ d = 61 /\ s = 2) \/
    (b = &1 /\ c = -- &1 /\ k = &2 /\ d = 9 /\ s = 2) \/
    (b = &1 /\ c = -- &1 /\ k = &3 /\ d = 18 /\ s = 1) \/
    (b = &1 /\ c = -- &1 /\ k = &4 /\ d = 27 /\ s = 2) \/
    (b = &1 /\ c = -- &1 /\ k = &5 /\ d = 36 /\ s = 1) \/
    (b = &1 /\ c = -- &1 /\ k = &6 /\ d = 45 /\ s = 2) \/
    (b = &1 /\ c = -- &1 /\ k = &7 /\ d = 54 /\ s = 1) \/
    (b = &0 /\ c = -- &2 /\ k = &1 /\ d = 1 /\ s = 2) \/
    (b = &0 /\ c = -- &2 /\ k = &2 /\ d = 10 /\ s = 1) \/
    (b = &0 /\ c = -- &2 /\ k = &3 /\ d = 19 /\ s = 2) \/
    (b = &0 /\ c = -- &2 /\ k = &4 /\ d = 28 /\ s = 1) \/
    (b = &0 /\ c = -- &2 /\ k = &5 /\ d = 37 /\ s = 2) \/
    (b = &0 /\ c = -- &2 /\ k = &6 /\ d = 46 /\ s = 1) \/
    (b = &0 /\ c = -- &2 /\ k = &7 /\ d = 55 /\ s = 2)`;;

let CROSS125_ADMISSIBLE_DATA = prove
 (`!b c k d s.
     cross125_admissible b c k d s
     ==> cross125_det b c k = &d /\ 0 < d /\
         ((9 * d * s EXP 2) MOD 8 = 2 \/
          (9 * d * s EXP 2) MOD 8 = 4 \/
          (9 * d * s EXP 2) MOD 8 = 6)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cross125_admissible] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN STRIP_ASSUME_TAC) THEN
  ASM_REWRITE_TAC[cross125_det] THEN
  CONV_TAC INT_REDUCE_CONV THEN CONV_TAC NUM_REDUCE_CONV);;

let CROSS125_BASE_CASE_TAC b c k d s =
  let hi = (9*d*s*s - 8) / 8 in
  CONJ_TAC THENL
   [REWRITE_TAC[cross125_child_rep] THEN CROSS125_CERT_TAC b c k;
    X_GEN_TAC `q:num` THEN STRIP_TAC THEN
    NUM_RANGE_CASES_THEN `q:num` hi
     (TRY ASM_ARITH_TAC THEN
      REWRITE_TAC[cross125_child_rep] THEN
      CONV_TAC NUM_REDUCE_CONV THEN CROSS125_CERT_TAC b c k)];;

