let CROSS125_ADMISSIBLE_ALMOST15 = prove
 (`!b c k d s.
     cross125_admissible b c k d s
     ==> !n:num.
          0 < n /\ ~(n = 15)
          ==> cross125_child_rep b c k n`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "admissible") THEN
  MP_TAC(MATCH_MP
    (SPECL [`b:int`; `c:int`; `k:int`; `d:num`; `s:num`]
      CROSS125_ADMISSIBLE_BASE)
    (ASSUME `cross125_admissible b c k d s`)) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sixty") (LABEL_TAC "base")) THEN
  MP_TAC(MATCH_MP
    (SPECL [`b:int`; `c:int`; `k:int`; `d:num`; `s:num`]
      CROSS125_ADMISSIBLE_DATA)
    (ASSUME `cross125_admissible b c k d s`)) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "det")
    (CONJUNCTS_THEN2 (LABEL_TAC "dpos") (LABEL_TAC "offsetmod"))) THEN
  MATCH_MP_TAC(SPECL [`b:int`; `c:int`; `k:int`]
    CROSS125_CHILD_ALMOST15) THEN
  CONJ_TAC THENL
   [REMOVE_THEN "sixty" MATCH_ACCEPT_TAC;
    MATCH_MP_TAC(SPECL
      [`b:int`; `c:int`; `k:int`; `d:num`; `s:num`]
      CROSS125_CHILD_REP_RESIDUE7) THEN
    REPEAT CONJ_TAC THENL
     [REMOVE_THEN "det" MATCH_ACCEPT_TAC;
      REMOVE_THEN "dpos" MATCH_ACCEPT_TAC;
      REMOVE_THEN "offsetmod" MATCH_ACCEPT_TAC;
      REMOVE_THEN "base" MATCH_ACCEPT_TAC]]);;

let IQ_CROSS125_CHILD_REP_OF_NUM = prove
 (`!b c k m.
     cross125_child_rep b c k m
     ==> iq_represents 4
          (iqmat4 (&1) (&0) (&0) (&0)
                  (&2) (&1) b (&5) c k) (&m)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[cross125_child_rep; iq_represents] THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int`
      (X_CHOOSE_THEN `z:int` (X_CHOOSE_TAC `w:int`)))) THEN
  EXISTS_TAC
   `\i:num.
      if i = 0 then (x:int) else if i = 1 then y else
      if i = 2 then z else w` THEN
  REWRITE_TAC[IQEVAL_MAT4] THEN CONV_TAC NUM_REDUCE_CONV THEN
  FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING);;

let IQ_UNIVERSAL_OF_CROSS125_ADMISSIBLE_CHILD = prove
 (`!n A b c k d s.
     cross125_admissible b c k d s /\
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) b (&5) c k) A /\
     iq_represents n A (&15)
     ==> iq_universal n A`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "admissible")
    (CONJUNCTS_THEN2 (LABEL_TAC "emb") (LABEL_TAC "fifteen"))) THEN
  REWRITE_TAC[iq_universal] THEN
  X_GEN_TAC `m:int` THEN DISCH_TAC THEN
  ASM_CASES_TAC `m = &15` THENL
   [REMOVE_THEN "fifteen" MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(EQ_MP (SYM(SPEC `m:int` INT_OF_NUM_EXISTS))
    (MATCH_MP (SPECL [`&0:int`; `m:int`] INT_LT_IMP_LE)
      (ASSUME `&0 < m`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `u:num` SUBST_ALL_TAC) THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `4`;
    `iqmat4 (&1) (&0) (&0) (&0)
            (&2) (&1) b (&5) c k`;
    `A:num->num->int`; `&u:int`] IQ_REPRESENTS_OF_EMBEDS) THEN
  CONJ_TAC THENL
   [REMOVE_THEN "emb" MATCH_ACCEPT_TAC;
    MATCH_MP_TAC(SPECL [`b:int`; `c:int`; `k:int`; `u:num`]
      IQ_CROSS125_CHILD_REP_OF_NUM) THEN
    MATCH_MP_TAC(MATCH_MP
      (SPECL [`b:int`; `c:int`; `k:int`; `d:num`; `s:num`]
        CROSS125_ADMISSIBLE_ALMOST15)
      (ASSUME `cross125_admissible b c k d s`)) THEN
    CONJ_TAC THENL
     [UNDISCH_TAC `&0 < &u` THEN REWRITE_TAC[INT_OF_NUM_LT];
      UNDISCH_TAC `~(&u = &15)` THEN REWRITE_TAC[INT_OF_NUM_EQ]]]);;

let CROSS125_00_ADMISSIBLE = prove
 (`!k:int.
     k = &1 \/ k = &2 \/ k = &3 \/ k = &4 \/
     k = &5 \/ k = &6 \/ k = &7
     ==> ?d s. cross125_admissible (&0) (&0) k d s`,
  GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THENL
   [MAP_EVERY EXISTS_TAC [`9`; `2`];
    MAP_EVERY EXISTS_TAC [`18`; `1`];
    MAP_EVERY EXISTS_TAC [`27`; `2`];
    MAP_EVERY EXISTS_TAC [`36`; `1`];
    MAP_EVERY EXISTS_TAC [`45`; `2`];
    MAP_EVERY EXISTS_TAC [`54`; `1`];
    MAP_EVERY EXISTS_TAC [`63`; `2`]] THEN
  REWRITE_TAC[cross125_admissible]);;

