let CROSS125_0_NEG2_ADMISSIBLE = prove
 (`!k:int.
     k = &1 \/ k = &2 \/ k = &3 \/ k = &4 \/
     k = &5 \/ k = &6 \/ k = &7
     ==> ?d s. cross125_admissible (&0) (-- &2) k d s`,
