    EXISTS_TAC `k:int` THEN
    REPEAT(FIRST_X_ASSUM SUBST_ALL_TAC) THEN ASM_REWRITE_TAC[];
    DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN
    EXISTS_TAC `k:int` THEN
    REPEAT(FIRST_X_ASSUM SUBST_ALL_TAC) THEN
    MATCH_MP_TAC(CONV_RULE INT_REDUCE_CONV
