    EXISTS_TAC `k:int` THEN
    REPEAT(FIRST_X_ASSUM SUBST_ALL_TAC) THEN
    MATCH_MP_TAC(CONV_RULE INT_REDUCE_CONV
     (ISPECL
       [`n:num`; `A:num->num->int`; `&0`; `&1`; `k:int`; `&7:int`]
       IQ_EMBEDS_REPRESENTS_FLIP_CROSS124)) THEN
    ASM_REWRITE_TAC[];
    DISJ2_TAC THEN DISJ1_TAC THEN
    EXISTS_TAC `k:int` THEN
    REPEAT(FIRST_X_ASSUM SUBST_ALL_TAC) THEN
    MATCH_MP_TAC(CONV_RULE INT_REDUCE_CONV
     (ISPECL
       [`n:num`; `A:num->num->int`; `-- &1`; `&0`; `k:int`; `&7:int`]
