(* Two odd squares together with twice a square cannot sum to 8. *)
let INT_2SQ_TWO_ODD_NOT_8 = prove
 (`!x y z:int.
     ~(&2 * x pow 2 +
       (&2 * y + &1) pow 2 + (&2 * z + &1) pow 2 = &8)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `~(&2 divides &2 * y + &1) /\
    ~(&2 divides &2 * z + &1)`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[int_divides] THEN
      DISCH_THEN(X_CHOOSE_TAC `q:int`) THEN
      MP_TAC(SPEC `q - y:int` INT_TWO_MUL_NE_ONE) THEN
      ASM_INT_ARITH_TAC;
      REWRITE_TAC[int_divides] THEN
      DISCH_THEN(X_CHOOSE_TAC `q:int`) THEN
      MP_TAC(SPEC `q - z:int` INT_TWO_MUL_NE_ONE) THEN
      ASM_INT_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((&2 * y + &1) pow 2) rem &8 = &1 /\
    ((&2 * z + &1) pow 2) rem &8 = &1`
  STRIP_ASSUME_TAC THENL
   [ASM_REWRITE_TAC[ODD_SQ_MOD_8];
    ALL_TAC] THEN
  MP_TAC(SPEC `x:int` SQ_MOD_8) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THEN
  (SUBGOAL_THEN
   `(&2 * (x pow 2 rem &8) +
     ((&2 * y + &1) pow 2) rem &8 +
     ((&2 * z + &1) pow 2) rem &8) rem &8 =
    (&2 * x pow 2 +
     (&2 * y + &1) pow 2 + (&2 * z + &1) pow 2) rem &8`
  MP_TAC THENL
   [CONV_TAC INT_REM_DOWN_CONV THEN REFL_TAC;
    ASM_REWRITE_TAC[] THEN CONV_TAC INT_REDUCE_CONV]));;

let INT_CROSS124_BINARY_NOT_7 = prove
