   [MP_TAC(SPECL [`x:int`; `y - &1:int`; `w:int`]
      INT_2SQ_TWO_ODD_NOT_8);
    MP_TAC(SPECL [`x:int`; `y:int`; `w:int`] INT_122_NOT_7);
    MP_TAC(SPECL [`x:int`; `y:int`; `w - &1:int`]
      INT_2SQ_TWO_ODD_NOT_8)] THEN
  REMOVE_THEN "double" MP_TAC THEN CONV_TAC INT_RING);;

