let INT_CROSS124_1_NEG1_8_NOT_7 = prove
 (`!x y z w:int.
     ~(x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 +
       &2 * y * w - &2 * z * w + &8 * w pow 2 = &7)`,
