    &2 * (&7 * y + &5 * w) pow 2 +
    &2 * (&7 * y + &5 * w) * (&7 * z - &3 * w) +
    &4 * (&7 * z - &3 * w) pow 2 +
    &336 * w pow 2 = &343`
  (LABEL_TAC "detid") THENL
   [MP_TAC(SPECL
     [`&1:int`; `-- &1:int`; `&8:int`;
      `x:int`; `y:int`; `z:int`; `w:int`]
     INT_CROSS124_CHILD_DET_IDENTITY) THEN
    REMOVE_THEN "rep" MP_TAC THEN
    REWRITE_TAC[cross124_det] THEN CONV_TAC INT_REDUCE_CONV THEN
    CONV_TAC INT_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&0 <=
    &2 * (&7 * y + &5 * w) pow 2 +
    &2 * (&7 * y + &5 * w) * (&7 * z - &3 * w) +
    &4 * (&7 * z - &3 * w) pow 2`
  ASSUME_TAC THENL
   [MATCH_ACCEPT_TAC(SPECL
     [`&7 * y + &5 * w:int`; `&7 * z - &3 * w:int`]
     INT_CROSS124_BINARY_NONNEG);
    ALL_TAC] THEN
  SUBGOAL_THEN `w pow 2 = &1` ASSUME_TAC THENL
   [MP_TAC(SPEC `&7 * x:int` INT_LE_POW_2) THEN
    USE_THEN "detid" MP_TAC THEN ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `x = &0` ASSUME_TAC THENL
   [SUBGOAL_THEN `(&7 * x) pow 2 <= &7` ASSUME_TAC THENL
     [USE_THEN "detid" MP_TAC THEN ASM_INT_ARITH_TAC;
      ALL_TAC] THEN
    MP_TAC(MATCH_MP (SPEC `&7 * x:int` INT_SQ_LE_7_CASES)
      (ASSUME `(&7 * x) pow 2 <= &7`)) THEN
    ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&2 * (&7 * y + &5 * w) pow 2 +
    &2 * (&7 * y + &5 * w) * (&7 * z - &3 * w) +
    &4 * (&7 * z - &3 * w) pow 2 = &7`
  ASSUME_TAC THENL
   [REMOVE_THEN "detid" MP_TAC THEN ASM_REWRITE_TAC[] THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL
   [`&7 * y + &5 * w:int`; `&7 * z - &3 * w:int`]
   INT_CROSS124_BINARY_NOT_7) THEN
  ASM_REWRITE_TAC[]);;

