    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC IQ_CROSS124_1_NEG1_8_NOT_REPRESENTS_7 THEN
    ASM_REWRITE_TAC[]]);;

(* Multiplying the last coordinate by 7 clears the denominator in the
   orthogonal complement of the crossed <1,2,4> ternary sublattice. *)
let INT_CROSS124_CHILD_SHIFT7 = prove
 (`!b c k s x y z:int.
     x pow 2 +
     &2 * (y - (&4 * b - c) * s) pow 2 +
     &2 * (y - (&4 * b - c) * s) *
          (z + (b - &2 * c) * s) +
     &4 * (z + (b - &2 * c) * s) pow 2 +
     &2 * b * (y - (&4 * b - c) * s) * (&7 * s) +
     &2 * c * (z + (b - &2 * c) * s) * (&7 * s) +
     k * (&7 * s) pow 2 =
     x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 +
     &7 * cross124_det b c k * s pow 2`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cross124_det] THEN CONV_TAC INT_RING);;

let INT_REPRESENTS_CROSS124_CHILD_SHIFT7 = prove
 (`!b c k s n:int.
     (?x y z:int.
        x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 =
        n - &7 * cross124_det b c k * s pow 2)
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 +
          &2 * b * y * w + &2 * c * z * w + k * w pow 2 = n`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int` (X_CHOOSE_TAC `z:int`))) THEN
  MAP_EVERY EXISTS_TAC
   [`x:int`;
    `y - (&4 * b - c) * s:int`;
    `z + (b - &2 * c) * s:int`;
    `&7 * s:int`] THEN
  MP_TAC(SPECL
   [`b:int`; `c:int`; `k:int`; `s:int`; `x:int`; `y:int`; `z:int`]
   INT_CROSS124_CHILD_SHIFT7) THEN
  FIRST_X_ASSUM(MP_TAC) THEN INT_ARITH_TAC);;

(* The 7-adic exceptional squareclasses occupy only four residues modulo
   49. This one-way test is convenient for certified finite shift searches. *)
let DISC7_EXCEPTION_MOD49 = prove
 (`!n:num.
     disc7_exception n
     ==> n MOD 49 = 0 \/ n MOD 49 = 21 \/
         n MOD 49 = 35 \/ n MOD 49 = 42`,
  GEN_TAC THEN REWRITE_TAC[disc7_exception] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:num`
    (X_CHOOSE_THEN `b:num`
      (X_CHOOSE_THEN `r:num`
        (CONJUNCTS_THEN2 (LABEL_TAC "r") (LABEL_TAC "eq"))))) THEN
  ASM_CASES_TAC `a = 0` THENL
   [REMOVE_THEN "r" (REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    ASM_REWRITE_TAC[EXP; MULT_CLAUSES; MOD_MULT_ADD] THEN
    CONV_TAC NUM_REDUCE_CONV;
    MP_TAC(SPEC `a:num` num_CASES) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `d:num` SUBST_ALL_TAC) THEN
    DISJ1_TAC THEN ASM_REWRITE_TAC[EXP] THEN
    ONCE_REWRITE_TAC[ARITH_RULE `(49*a)*b = 49*(a*b)`] THEN
    REWRITE_TAC[MOD_MULT] THEN CONV_TAC NUM_REDUCE_CONV]);;

let DISC7_NOT_EXCEPTION_OF_MOD49 = prove
 (`!n:num.
     ~(n MOD 49 = 0) /\ ~(n MOD 49 = 21) /\
     ~(n MOD 49 = 35) /\ ~(n MOD 49 = 42)
     ==> ~disc7_exception n`,
  MESON_TAC[DISC7_EXCEPTION_MOD49]);;

let num_shift_rem = new_definition
 `num_shift_rem r c p =
    if c MOD p <= r then r - c MOD p else r + p - c MOD p`;;

let NUM_MOD_SUB_EXACT = prove
 (`!n c p:num.
     c <= n /\ ~(p = 0)
     ==> (n - c) MOD p = num_shift_rem (n MOD p) c p`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[num_shift_rem] THEN
  SUBGOAL_THEN
   `((n - c) MOD p + c MOD p) MOD p = n MOD p`
  ASSUME_TAC THENL
   [REWRITE_TAC[MOD_ADD_MOD] THEN ASM_SIMP_TAC[SUB_ADD];
    ALL_TAC] THEN
  MP_TAC(SPECL [`(n-c) MOD p`; `c MOD p`; `p:num`] MOD_ADD_CASES) THEN
  ANTS_TAC THENL
   [CONJ_TAC THEN REWRITE_TAC[MOD_LT_EQ] THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[] THEN
    COND_CASES_TAC THEN COND_CASES_TAC THEN ASM_ARITH_TAC]);;

let cross124_generic_offset = new_definition
 `cross124_generic_offset (m:num) <=>
    m = 1 \/ m = 2 \/ m = 4 \/ m = 5 \/ m = 6 \/ m = 7 \/
    m = 70 \/ m = 119 \/ m = 217 \/ m = 266 \/
    m = 35 \/ m = 133 \/ m = 182 \/ m = 280 \/ m = 329 \/
    m = 42 \/ m = 91 \/ m = 140 \/ m = 238 \/ m = 287`;;

let CROSS124_FINITE_SHIFT_TAC =
  FIRST
   (map
     (fun s ->
       EXISTS_TAC (mk_small_numeral s) THEN
       REWRITE_TAC[num_shift_rem] THEN
       CONV_TAC NUM_REDUCE_CONV THEN ACCEPT_TAC TRUTH)
     (1--9));;

let CROSS124_CONTR_FALSE_ASSUM_TAC (asl,w) =
  let _,th = find (fun (_,th) -> concl th = `F`) asl in
  CONTR_TAC th (asl,w);;

let CROSS124_BOUNDED_FINITE_SHIFT_SELECTOR_TAC =
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  NUM_RANGE_CASES_THEN `r12:num` 11
   (NUM_RANGE_CASES_THEN `r49:num` 48
     (RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
      TRY CROSS124_CONTR_FALSE_ASSUM_TAC THEN
      CROSS124_FINITE_SHIFT_TAC));;

let CROSS124_GENERIC_OFFSET_FINITE_SHIFT = prove
 (`!m r12 r49:num.
     cross124_generic_offset m /\
     r12 < 12 /\ r49 < 49 /\
     ~(r12 MOD 4 = 0) /\ ~(r49 = 0)
     ==> ?s.
          1 <= s /\ s <= 9 /\
          ~(num_shift_rem r12 (m * s EXP 2) 12 = 7) /\
          ~(num_shift_rem r12 (m * s EXP 2) 12 = 10) /\
          ~(num_shift_rem r49 (m * s EXP 2) 49 = 0) /\
          ~(num_shift_rem r49 (m * s EXP 2) 49 = 21) /\
          ~(num_shift_rem r49 (m * s EXP 2) 49 = 35) /\
          ~(num_shift_rem r49 (m * s EXP 2) 49 = 42)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cross124_generic_offset] THEN
  DISCH_THEN(CONJUNCTS_THEN2
    (REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) STRIP_ASSUME_TAC) THEN
  NUM_RANGE_CASES_THEN `r12:num` 11
   (NUM_RANGE_CASES_THEN `r49:num` 48
     (RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
      TRY CROSS124_CONTR_FALSE_ASSUM_TAC THEN
      CROSS124_FINITE_SHIFT_TAC)));;

let CROSS124_GENERIC_OFFSET_SHIFT = prove
 (`!m n:num.
     cross124_generic_offset m /\
     81 * m <= n /\
     ~(4 divides n) /\ ~(49 divides n)
     ==> ?s.
          1 <= s /\ s <= 9 /\ m * s EXP 2 <= n /\
          ~((n - m * s EXP 2) MOD 12 = 7) /\
          ~((n - m * s EXP 2) MOD 12 = 10) /\
          ~((n - m * s EXP 2) MOD 49 = 0) /\
          ~((n - m * s EXP 2) MOD 49 = 21) /\
          ~((n - m * s EXP 2) MOD 49 = 35) /\
          ~((n - m * s EXP 2) MOD 49 = 42)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL
   [`m:num`; `n MOD 12`; `n MOD 49`]
   CROSS124_GENERIC_OFFSET_FINITE_SHIFT) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      REWRITE_TAC[MOD_LT_EQ] THEN CONV_TAC NUM_REDUCE_CONV;
      REWRITE_TAC[MOD_LT_EQ] THEN CONV_TAC NUM_REDUCE_CONV;
      UNDISCH_TAC `~(4 divides n)` THEN
      REWRITE_TAC[DIVIDES_MOD; ARITH_RULE `12 = 4 * 3`; MOD_MOD];
      UNDISCH_TAC `~(49 divides n)` THEN REWRITE_TAC[DIVIDES_MOD]];
    DISCH_THEN(X_CHOOSE_THEN `s:num` STRIP_ASSUME_TAC)] THEN
  EXISTS_TAC `s:num` THEN
  SUBGOAL_THEN `m * s EXP 2 <= n` ASSUME_TAC THENL
   [MATCH_MP_TAC LE_TRANS THEN EXISTS_TAC `81 * m` THEN
    CONJ_TAC THENL
     [GEN_REWRITE_TAC RAND_CONV [MULT_SYM] THEN
      MATCH_MP_TAC LE_MULT2 THEN REWRITE_TAC[LE_REFL] THEN
      MP_TAC(SPECL [`s:num`; `9`; `2`] EXP_MONO_LE_IMP) THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(SPECL
   [`n:num`; `m * s EXP 2`; `12`] NUM_MOD_SUB_EXACT) THEN
  MP_TAC(SPECL
   [`n:num`; `m * s EXP 2`; `49`] NUM_MOD_SUB_EXACT) THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
  ASM_MESON_TAC[]);;

let cross124_child_rep = new_definition
 `cross124_child_rep (b:int) c k (n:num) <=>
    ?x y z w:int.
      x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 +
      &2 * b * y * w + &2 * c * z * w + k * w pow 2 = &n`;;

let CROSS124_CHILD_REP_SCALE = prove
 (`!b c k t n.
     cross124_child_rep b c k n
     ==> cross124_child_rep b c k (t EXP 2 * n)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cross124_child_rep] THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int`
      (X_CHOOSE_THEN `z:int` (X_CHOOSE_TAC `w:int`)))) THEN
  MAP_EVERY EXISTS_TAC
   [`&t * x:int`; `&t * y:int`; `&t * z:int`; `&t * w:int`] THEN
  FIRST_X_ASSUM(MP_TAC) THEN
  REWRITE_TAC[GSYM INT_OF_NUM_MUL; GSYM INT_OF_NUM_POW] THEN
  CONV_TAC INT_RING);;

let cross124_generic_child = new_definition
 `cross124_generic_child (b:int) c k (m:num) <=>
    (b = &0 /\ c = &0 /\ k = &1 /\ m = 1) \/
    (b = &0 /\ c = &0 /\ k = &2 /\ m = 2) \/
    (b = &0 /\ c = &0 /\ k = &4 /\ m = 4) \/
    (b = &0 /\ c = &0 /\ k = &5 /\ m = 5) \/
    (b = &0 /\ c = &0 /\ k = &6 /\ m = 6) \/
    (b = &0 /\ c = &0 /\ k = &7 /\ m = 7) \/
    (b = &1 /\ c = &0 /\ k = &2 /\ m = 70) \/
    (b = &1 /\ c = &0 /\ k = &3 /\ m = 119) \/
    (b = &1 /\ c = &0 /\ k = &5 /\ m = 217) \/
    (b = &1 /\ c = &0 /\ k = &6 /\ m = 266) \/
    (b = &0 /\ c = -- &1 /\ k = &1 /\ m = 35) \/
    (b = &0 /\ c = -- &1 /\ k = &3 /\ m = 133) \/
    (b = &0 /\ c = -- &1 /\ k = &4 /\ m = 182) \/
    (b = &0 /\ c = -- &1 /\ k = &6 /\ m = 280) \/
    (b = &0 /\ c = -- &1 /\ k = &7 /\ m = 329) \/
    (b = &1 /\ c = -- &1 /\ k = &2 /\ m = 42) \/
    (b = &1 /\ c = -- &1 /\ k = &3 /\ m = 91) \/
    (b = &1 /\ c = -- &1 /\ k = &4 /\ m = 140) \/
    (b = &1 /\ c = -- &1 /\ k = &6 /\ m = 238) \/
    (b = &1 /\ c = -- &1 /\ k = &7 /\ m = 287)`;;

let CROSS124_GENERIC_CHILD_DATA = prove
 (`!b c k m.
     cross124_generic_child b c k m
     ==> cross124_generic_offset m /\
         ((b = &0 /\ c = &0 /\ k = &m) \/
          &m = &7 * cross124_det b c k)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[cross124_generic_child] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN STRIP_ASSUME_TAC) THEN
  ASM_REWRITE_TAC[cross124_generic_offset; cross124_det] THEN
  CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_REDUCE_CONV);;

let INT_CROSS124_OFFSET_COERCE = prove
 (`!n m s:num.
     m * s EXP 2 <= n
     ==> &(n - m * s EXP 2) =
         (&n:int) - &m * (&s:int) pow 2`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC EQ_TRANS THEN
  EXISTS_TAC `(&n:int) - &(m * s EXP 2)` THEN
  CONJ_TAC THENL
   [MATCH_ACCEPT_TAC(SYM(MATCH_MP
      (SPECL [`m * s EXP 2`; `n:num`] INT_OF_NUM_SUB)
      (ASSUME `m * s EXP 2 <= n`)));
    REWRITE_TAC[INT_OF_NUM_MUL; INT_OF_NUM_POW] THEN
    CONV_TAC INT_RING]);;

let CROSS124_GENERIC_CHILD_REP_SHIFT = prove
 (`!b c k m s n.
     cross124_generic_child b c k m /\
     m * s EXP 2 <= n /\
     (?x y z:int.
        x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 =
        &(n - m * s EXP 2))
     ==> cross124_child_rep b c k n`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "child")
    (CONJUNCTS_THEN2 (LABEL_TAC "bound") (LABEL_TAC "tern"))) THEN
  MP_TAC(MATCH_MP
    (SPECL [`b:int`; `c:int`; `k:int`; `m:num`]
      CROSS124_GENERIC_CHILD_DATA)
    (ASSUME `cross124_generic_child b c k m`)) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (DISJ_CASES_THEN (LABEL_TAC "data"))) THEN
  MP_TAC(MATCH_MP
    (SPECL [`n:num`; `m:num`; `s:num`] INT_CROSS124_OFFSET_COERCE)
    (ASSUME `m * s EXP 2 <= n`)) THEN
  DISCH_THEN(LABEL_TAC "coerce") THEN
  REMOVE_THEN "tern"
   (X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int`
      (X_CHOOSE_THEN `z:int` (LABEL_TAC "tern")))) THENL
   [REWRITE_TAC[cross124_child_rep] THEN
    MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`; `&s:int`] THEN
    REMOVE_THEN "data" STRIP_ASSUME_TAC THEN ASM_REWRITE_TAC[] THEN
    REMOVE_THEN "tern" MP_TAC THEN REMOVE_THEN "coerce" MP_TAC THEN
    CONV_TAC INT_RING;
    REWRITE_TAC[cross124_child_rep] THEN
    MATCH_MP_TAC(SPECL
     [`b:int`; `c:int`; `k:int`; `&s:int`; `&n:int`]
     INT_REPRESENTS_CROSS124_CHILD_SHIFT7) THEN
    MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`] THEN
    REMOVE_THEN "tern" MP_TAC THEN REMOVE_THEN "coerce" MP_TAC THEN
    REMOVE_THEN "data" MP_TAC THEN CONV_TAC INT_RING]);;

let CROSS124_GENERIC_CHILD_REP_LARGE = prove
 (`!b c k m n.
     cross124_generic_child b c k m /\
     81 * m < n /\
     ~(4 divides n) /\ ~(49 divides n)
     ==> cross124_child_rep b c k n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP
    (SPECL [`b:int`; `c:int`; `k:int`; `m:num`]
      CROSS124_GENERIC_CHILD_DATA)
    (ASSUME `cross124_generic_child b c k m`)) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "offset") ASSUME_TAC) THEN
  MP_TAC(SPECL [`m:num`; `n:num`] CROSS124_GENERIC_OFFSET_SHIFT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    DISCH_THEN(X_CHOOSE_THEN `s:num` STRIP_ASSUME_TAC)] THEN
  SUBGOAL_THEN `m * s EXP 2 <= 81 * m` ASSUME_TAC THENL
   [GEN_REWRITE_TAC RAND_CONV [MULT_SYM] THEN
    MATCH_MP_TAC LE_MULT2 THEN REWRITE_TAC[LE_REFL] THEN
    MP_TAC(SPECL [`s:num`; `9`; `2`] EXP_MONO_LE_IMP) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN `0 < n - m * s EXP 2` ASSUME_TAC THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(SPECL
   [`b:int`; `c:int`; `k:int`; `m:num`; `s:num`; `n:num`]
   CROSS124_GENERIC_CHILD_REP_SHIFT) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(SPEC `n - m * s EXP 2` DISC7_CROSS124_REGULAR) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      MATCH_MP_TAC DISC7_NOT_EXCEPTION_OF_MOD49 THEN ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]];
    MESON_TAC[]]);;

let CROSS124_GENERIC_CHILD_REP_LARGE_OF_FINITE = prove
 (`!b c k m h n.
     cross124_generic_child b c k m /\
     (!r12 r49:num.
        r12 < 12 /\ r49 < 49 /\
        ~(r12 MOD 4 = 0) /\ ~(r49 = 0)
        ==> ?s.
             1 <= s /\ m * s EXP 2 <= h /\
             ~(num_shift_rem r12 (m * s EXP 2) 12 = 7) /\
             ~(num_shift_rem r12 (m * s EXP 2) 12 = 10) /\
             ~(num_shift_rem r49 (m * s EXP 2) 49 = 0) /\
             ~(num_shift_rem r49 (m * s EXP 2) 49 = 21) /\
             ~(num_shift_rem r49 (m * s EXP 2) 49 = 35) /\
             ~(num_shift_rem r49 (m * s EXP 2) 49 = 42)) /\
     h < n /\ ~(4 divides n) /\ ~(49 divides n)
     ==> cross124_child_rep b c k n`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "child")
    (CONJUNCTS_THEN2 (LABEL_TAC "finite") STRIP_ASSUME_TAC)) THEN
  REMOVE_THEN "finite" (MP_TAC o SPECL [`n MOD 12`; `n MOD 49`]) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [REWRITE_TAC[MOD_LT_EQ] THEN CONV_TAC NUM_REDUCE_CONV;
      REWRITE_TAC[MOD_LT_EQ] THEN CONV_TAC NUM_REDUCE_CONV;
      UNDISCH_TAC `~(4 divides n)` THEN
      REWRITE_TAC[DIVIDES_MOD; ARITH_RULE `12 = 4 * 3`; MOD_MOD];
      UNDISCH_TAC `~(49 divides n)` THEN REWRITE_TAC[DIVIDES_MOD]];
    DISCH_THEN(X_CHOOSE_THEN `s:num` STRIP_ASSUME_TAC)] THEN
  SUBGOAL_THEN `m * s EXP 2 <= n` ASSUME_TAC THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `0 < n - m * s EXP 2` ASSUME_TAC THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`n:num`; `m * s EXP 2`; `12`] NUM_MOD_SUB_EXACT) THEN
  MP_TAC(SPECL [`n:num`; `m * s EXP 2`; `49`] NUM_MOD_SUB_EXACT) THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
  REPEAT DISCH_TAC THEN
  MATCH_MP_TAC(SPECL
   [`b:int`; `c:int`; `k:int`; `m:num`; `s:num`; `n:num`]
   CROSS124_GENERIC_CHILD_REP_SHIFT) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(SPEC `n - m * s EXP 2` DISC7_CROSS124_REGULAR) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      MATCH_MP_TAC DISC7_NOT_EXCEPTION_OF_MOD49 THEN ASM_MESON_TAC[];
      ASM_MESON_TAC[];
      ASM_MESON_TAC[]];
    MESON_TAC[]]);;

let cross124_needs_check = new_definition
 `cross124_needs_check (n:num) <=>
    disc7_exception n \/ n MOD 12 = 7 \/ n MOD 12 = 10`;;

let CROSS124_CHILD_REP_REGULAR = prove
 (`!b c k n.
     0 < n /\ ~cross124_needs_check n
     ==> cross124_child_rep b c k n`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cross124_needs_check] THEN
  STRIP_TAC THEN REWRITE_TAC[cross124_child_rep] THEN
  MP_TAC(SPEC `n:num` DISC7_CROSS124_REGULAR) THEN
  ANTS_TAC THENL
   [ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `x:int`
      (X_CHOOSE_THEN `y:int` (X_CHOOSE_TAC `z:int`)))] THEN
  MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`; `&0:int`] THEN
  FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING);;

let CROSS124_GENERIC_CHILD_REP_OF_BASE = prove
 (`!b c k m.
     cross124_generic_child b c k m /\
     (!n:num.
        0 < n /\ n <= 81 * m /\
        ~(4 divides n) /\ ~(49 divides n) /\
        cross124_needs_check n
        ==> cross124_child_rep b c k n)
     ==> !n:num. 0 < n ==> cross124_child_rep b c k n`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2
    (LABEL_TAC "child") (LABEL_TAC "base")) THEN
  MATCH_MP_TAC num_WF THEN X_GEN_TAC `n:num` THEN
  DISCH_THEN(LABEL_TAC "ih") THEN DISCH_TAC THEN
  ASM_CASES_TAC `4 divides n` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `q:num` ASSUME_TAC o
      REWRITE_RULE[divides]) THEN
    SUBGOAL_THEN `q < n /\ 0 < q` STRIP_ASSUME_TAC THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `n = 2 EXP 2 * q` SUBST1_TAC THENL
     [UNDISCH_TAC `n = 4 * q` THEN CONV_TAC NUM_REDUCE_CONV;
      ALL_TAC] THEN
    MATCH_MP_TAC(SPECL
     [`b:int`; `c:int`; `k:int`; `2`; `q:num`]
     CROSS124_CHILD_REP_SCALE) THEN
    REMOVE_THEN "ih" (MP_TAC o SPEC `q:num`) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `49 divides n` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `q:num` ASSUME_TAC o
      REWRITE_RULE[divides]) THEN
    SUBGOAL_THEN `q < n /\ 0 < q` STRIP_ASSUME_TAC THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `n = 7 EXP 2 * q` SUBST1_TAC THENL
     [UNDISCH_TAC `n = 49 * q` THEN CONV_TAC NUM_REDUCE_CONV;
      ALL_TAC] THEN
    MATCH_MP_TAC(SPECL
     [`b:int`; `c:int`; `k:int`; `7`; `q:num`]
     CROSS124_CHILD_REP_SCALE) THEN
    REMOVE_THEN "ih" (MP_TAC o SPEC `q:num`) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `n <= 81 * m` THENL
   [ASM_CASES_TAC `cross124_needs_check n` THENL
     [REMOVE_THEN "base" (MATCH_MP_TAC o SPEC `n:num`) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(SPECL
       [`b:int`; `c:int`; `k:int`; `n:num`]
       CROSS124_CHILD_REP_REGULAR) THEN
      ASM_REWRITE_TAC[]];
    MATCH_MP_TAC(SPECL
     [`b:int`; `c:int`; `k:int`; `m:num`; `n:num`]
     CROSS124_GENERIC_CHILD_REP_LARGE) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]);;

let cross124_maybe_check = new_definition
 `cross124_maybe_check (n:num) <=>
    n MOD 12 = 7 \/ n MOD 12 = 10 \/
    n MOD 49 = 0 \/ n MOD 49 = 21 \/
    n MOD 49 = 35 \/ n MOD 49 = 42`;;

let CROSS124_NEEDS_IMP_MAYBE_CHECK = prove
 (`!n:num. cross124_needs_check n ==> cross124_maybe_check n`,
  GEN_TAC THEN
  REWRITE_TAC[cross124_needs_check; cross124_maybe_check] THEN
  DISCH_THEN(DISJ_CASES_THEN2
    (LABEL_TAC "exc") (DISJ_CASES_THEN ASSUME_TAC)) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(MATCH_MP
    (SPEC `n:num` DISC7_EXCEPTION_MOD49)
    (ASSUME `disc7_exception n`)) THEN
  MESON_TAC[]);;

let cross124_num_of_int i =
  if i < 0
  then minus_num(num_of_string(string_of_int(-i)))
  else num_of_string(string_of_int i);;

(* This search only generates witnesses. INT_REDUCE_CONV checks every
   returned quadruple before it enters a theorem. *)
let CROSS124_CERT_TAC b c k =
  fun (asl,goal) ->
    let _,bod = strip_exists goal in
    let _,rhs = dest_eq bod in
    let n = int_of_string(string_of_num(dest_intconst rhs)) in
    let d = 7*k - 4*b*b + 2*b*c - 2*c*c in
    let isqrt r = int_of_float(float_sqrt(float_of_int r)) in
    let signed i =
      if i = 0 then 0
      else if i mod 2 = 1 then (i + 1) / 2 else -(i / 2) in
    let check x y z w =
      x*x + 2*y*y + 2*y*z + 4*z*z +
      2*b*y*w + 2*c*z*w + k*w*w = n in
    let recover x w zz uu =
      if (uu - zz) mod 2 <> 0 then None else
      let yy = (uu - zz) / 2 in
      let yn = yy - (4*b - c)*w
      and zn = zz - (-b + 2*c)*w in
      if yn mod 7 <> 0 || zn mod 7 <> 0 then None else
      let y = yn / 7 and z = zn / 7 in
      if check x y z w then Some(x,y,z,w) else None in
    let wmax = isqrt((7*n) / d) in
    let rec find_w iw =
      if iw > 2*wmax then failwith "CROSS124_CERT_TAC" else
      let w = signed iw in
      let r = 49*n - 7*d*w*w in
      if r < 0 then find_w (iw + 1) else
      let xmax = isqrt(r / 49) in
      let rec find_x x =
        if x > xmax then find_w (iw + 1) else
        let t = 2*(r - 49*x*x) in
        let zmax = isqrt(t / 7) in
        let rec find_z iz =
          if iz > 2*zmax then find_x (x + 1) else
          let zz = signed iz in
          let u2 = t - 7*zz*zz in
          if u2 < 0 then find_z (iz + 1) else
          let u = isqrt u2 in
          if u*u <> u2 then find_z (iz + 1) else
          match recover x w zz u with
          | Some ans -> ans
          | None ->
              if u = 0 then find_z (iz + 1) else
              match recover x w zz (-u) with
              | Some ans -> ans
              | None -> find_z (iz + 1) in
        find_z 0 in
      find_x 0 in
    let x,y,z,w = find_w 0 in
    (MAP_EVERY EXISTS_TAC
       (map (mk_intconst o cross124_num_of_int) [x;y;z;w]) THEN
     CONV_TAC INT_REDUCE_CONV) (asl,goal);;

let CROSS124_BASE_TAC b c k hi =
  GEN_TAC THEN STRIP_TAC THEN
  NUM_RANGE_CASES_THEN `n:num` hi
   (TRY ASM_ARITH_TAC THEN
    RULE_ASSUM_TAC(REWRITE_RULE[cross124_maybe_check]) THEN
    RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
    TRY CROSS124_CONTR_FALSE_ASSUM_TAC THEN
    REWRITE_TAC[cross124_child_rep] THEN
    CONV_TAC NUM_REDUCE_CONV THEN CROSS124_CERT_TAC b c k);;

