 (`!n:num.
     0 < n /\ n <= 81 /\
     ~(4 divides n) /\ ~(49 divides n) /\
     cross124_maybe_check n
     ==> cross124_child_rep (&0) (&0) (&1) n`,
  CROSS124_BASE_TAC 0 0 1 81);;

