let CROSS124_GENERIC_CHILD_UNIVERSAL_OF_MAYBE_BASE = prove
 (`!b c k m.
     cross124_generic_child b c k m /\
     (!n:num.
        0 < n /\ n <= 81 * m /\
        ~(4 divides n) /\ ~(49 divides n) /\
        cross124_maybe_check n
        ==> cross124_child_rep b c k n)
     ==> !n:num. 0 < n ==> cross124_child_rep b c k n`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2
    (LABEL_TAC "child") (LABEL_TAC "base")) THEN
  MATCH_MP_TAC(SPECL
   [`b:int`; `c:int`; `k:int`; `m:num`]
   CROSS124_GENERIC_CHILD_REP_OF_BASE) THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `n:num` THEN STRIP_TAC THEN
  REMOVE_THEN "base" (MATCH_MP_TAC o SPEC `n:num`) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC CROSS124_NEEDS_IMP_MAYBE_CHECK THEN ASM_REWRITE_TAC[]);;

let CROSS124_GENERIC_CHILD_UNIVERSAL_OF_FINITE_BASE = prove
 (`!b c k m h.
     cross124_generic_child b c k m /\
     (!r12 r49:num.
        r12 < 12 /\ r49 < 49 /\
        ~(r12 MOD 4 = 0) /\ ~(r49 = 0)
        ==> ?s.
             1 <= s /\ m * s EXP 2 <= h /\
             ~(num_shift_rem r12 (m * s EXP 2) 12 = 7) /\
             ~(num_shift_rem r12 (m * s EXP 2) 12 = 10) /\
             ~(num_shift_rem r49 (m * s EXP 2) 49 = 0) /\
             ~(num_shift_rem r49 (m * s EXP 2) 49 = 21) /\
             ~(num_shift_rem r49 (m * s EXP 2) 49 = 35) /\
             ~(num_shift_rem r49 (m * s EXP 2) 49 = 42)) /\
     (!n:num.
        0 < n /\ n <= h /\
        ~(4 divides n) /\ ~(49 divides n) /\
        cross124_maybe_check n
        ==> cross124_child_rep b c k n)
     ==> !n:num. 0 < n ==> cross124_child_rep b c k n`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "child")
    (CONJUNCTS_THEN2 (LABEL_TAC "finite") (LABEL_TAC "base"))) THEN
  MATCH_MP_TAC num_WF THEN X_GEN_TAC `n:num` THEN
  DISCH_THEN(LABEL_TAC "ih") THEN DISCH_TAC THEN
  ASM_CASES_TAC `4 divides n` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `q:num` ASSUME_TAC o
      REWRITE_RULE[divides]) THEN
    SUBGOAL_THEN `q < n /\ 0 < q` STRIP_ASSUME_TAC THENL
     [ASM_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `n = 2 EXP 2 * q` SUBST1_TAC THENL
     [UNDISCH_TAC `n = 4 * q` THEN CONV_TAC NUM_REDUCE_CONV;
      ALL_TAC] THEN
    MATCH_MP_TAC(SPECL
     [`b:int`; `c:int`; `k:int`; `2`; `q:num`]
     CROSS124_CHILD_REP_SCALE) THEN
    REMOVE_THEN "ih" (MP_TAC o SPEC `q:num`) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `49 divides n` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `q:num` ASSUME_TAC o
      REWRITE_RULE[divides]) THEN
    SUBGOAL_THEN `q < n /\ 0 < q` STRIP_ASSUME_TAC THENL
     [ASM_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `n = 7 EXP 2 * q` SUBST1_TAC THENL
     [UNDISCH_TAC `n = 49 * q` THEN CONV_TAC NUM_REDUCE_CONV;
      ALL_TAC] THEN
    MATCH_MP_TAC(SPECL
     [`b:int`; `c:int`; `k:int`; `7`; `q:num`]
     CROSS124_CHILD_REP_SCALE) THEN
    REMOVE_THEN "ih" (MP_TAC o SPEC `q:num`) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `(n:num) <= h` THENL
   [ASM_CASES_TAC `cross124_maybe_check n` THENL
     [REMOVE_THEN "base"
       (fun th ->
         MATCH_ACCEPT_TAC(MATCH_MP (SPEC `n:num` th)
          (end_itlist CONJ
            [ASSUME `0 < (n:num)`;
             ASSUME `(n:num) <= h`;
             ASSUME `~(4 divides (n:num))`;
             ASSUME `~(49 divides (n:num))`;
             ASSUME `cross124_maybe_check (n:num)`])));
      MATCH_MP_TAC(SPECL
       [`b:int`; `c:int`; `k:int`; `n:num`]
       CROSS124_CHILD_REP_REGULAR) THEN
      ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[CROSS124_NEEDS_IMP_MAYBE_CHECK]];
    SUBGOAL_THEN `(h:num) < n` ASSUME_TAC THENL
     [REWRITE_TAC[GSYM NOT_LE] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(SPECL
     [`b:int`; `c:int`; `k:int`; `m:num`; `h:num`; `n:num`]
     CROSS124_GENERIC_CHILD_REP_LARGE_OF_FINITE) THEN
    ASM_REWRITE_TAC[]]);;

