(* Quotient/remainder splitting keeps the recursive case depth modest. *)
let CROSS124_QUOTIENT_BASE_TAC b c k hi =
  let qhi = hi / 100 in
  let qbound =
    mk_comb
     (mk_comb(`(<=):num->num->bool`,`q:num`),
      mk_small_numeral qhi) in
  GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `q = n DIV 100` THEN
  ABBREV_TAC `r = n MOD 100` THEN
  SUBGOAL_THEN `n = 100 * q + r` (LABEL_TAC "decomp") THENL
   [EXPAND_TAC "q" THEN EXPAND_TAC "r" THEN
    MP_TAC(SPECL [`n:num`; `100`] (CONJUNCT2 DIVISION_SIMP)) THEN
    ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `r < 100` ASSUME_TAC THENL
   [EXPAND_TAC "r" THEN REWRITE_TAC[MOD_LT_EQ] THEN
    CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN qbound ASSUME_TAC THENL
   [USE_THEN "decomp" MP_TAC THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  NUM_INTERVAL_CASES_THEN `q:num` 0 qhi
   (NUM_RANGE_CASES_THEN `r:num` 99
     (REMOVE_THEN "decomp" SUBST_ALL_TAC THEN
      TRY ASM_ARITH_TAC THEN
      RULE_ASSUM_TAC(REWRITE_RULE[cross124_maybe_check]) THEN
      RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
      TRY CROSS124_CONTR_FALSE_ASSUM_TAC THEN
      REWRITE_TAC[cross124_child_rep] THEN
      CONV_TAC NUM_REDUCE_CONV THEN CROSS124_CERT_TAC b c k));;

