(* The exceptional (1,0,4) child is Table 2's determinant-24 case.
   The following parity transformations show that its ternary complement
   represents every integer represented by x^2 + y^2 + 3z^2. *)

let INT_REPRESENTS_DET3_COMPLEMENT = prove
 (`!n a b c:int.
     a pow 2 + b pow 2 + &3 * c pow 2 = n
     ==> ?y z w.
          y pow 2 + y * z + &2 * z pow 2 +
          y * w + &2 * w pow 2 = n`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPEC `a:int` INT_PARITY_WITNESS) THEN
  MP_TAC(SPEC `b:int` INT_PARITY_WITNESS) THEN
  MP_TAC(SPEC `c:int` INT_PARITY_WITNESS) THEN
  DISCH_THEN(DISJ_CASES_THEN (X_CHOOSE_THEN `C:int` ASSUME_TAC)) THEN
  DISCH_THEN(DISJ_CASES_THEN (X_CHOOSE_THEN `B:int` ASSUME_TAC)) THEN
  DISCH_THEN(DISJ_CASES_THEN (X_CHOOSE_THEN `A:int` ASSUME_TAC)) THENL
   [MAP_EVERY EXISTS_TAC
     [`--b - c:int`; `c - A:int`; `c + A:int`];
    MAP_EVERY EXISTS_TAC
     [`--a - c:int`; `c - B:int`; `c + B:int`];
    MAP_EVERY EXISTS_TAC
     [`--b - c:int`; `c - A:int`; `c + A:int`];
    MAP_EVERY EXISTS_TAC
     [`--(&2 * A) + &2 * C - &1:int`;
      `A - B + C:int`; `A + B + C + &1:int`];
    MAP_EVERY EXISTS_TAC
     [`--b - c:int`; `c - A:int`; `c + A:int`];
    MAP_EVERY EXISTS_TAC
     [`--a - c:int`; `c - B:int`; `c + B:int`];
    MAP_EVERY EXISTS_TAC
     [`--b - c:int`; `c - A:int`; `c + A:int`];
    MP_TAC(SPEC `B:int` INT_PARITY_WITNESS) THEN
    MP_TAC(SPEC `C:int` INT_PARITY_WITNESS) THEN
    DISCH_THEN(DISJ_CASES_THEN (X_CHOOSE_THEN `Q:int` ASSUME_TAC)) THEN
    DISCH_THEN(DISJ_CASES_THEN (X_CHOOSE_THEN `P:int` ASSUME_TAC)) THENL
     [MAP_EVERY EXISTS_TAC
       [`--(&2 * A + &1) + &2 * Q - &2 * P:int`;
        `P - &5 * Q - &1:int`; `&3 * P + Q + &1:int`];
      MAP_EVERY EXISTS_TAC
       [`--(&2 * A + &1) - &2 * P - &2 * Q - &2:int`;
        `P + &5 * Q + &2:int`; `&3 * P - Q + &2:int`];
      MAP_EVERY EXISTS_TAC
       [`--(&2 * A + &1) - &2 * P - &2 * Q - &2:int`;
        `P + &5 * Q + &4:int`; `&3 * P - Q:int`];
      MAP_EVERY EXISTS_TAC
       [`--(&2 * A + &1) + &2 * Q - &2 * P:int`;
        `P - &5 * Q - &3:int`; `&3 * P + Q + &3:int`]]] THEN
  MAP_EVERY UNDISCH_TAC
   [`a pow 2 + b pow 2 + &3 * c pow 2 = n`] THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC INT_RING);;

let CROSS124_10_4_REP_OF_1226 = prove
 (`!n x a b c:int.
     x pow 2 + &2 * a pow 2 + &2 * b pow 2 + &6 * c pow 2 = n
     ==> ?x y z w:int.
          x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 +
          &2 * y * w + &4 * w pow 2 = n`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL
   [`(a:int) pow 2 + b pow 2 + &3 * c pow 2`;
    `a:int`; `b:int`; `c:int`] INT_REPRESENTS_DET3_COMPLEMENT) THEN
  REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `y:int`
    (X_CHOOSE_THEN `z:int` (X_CHOOSE_TAC `w:int`))) THEN
  MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`; `w:int`] THEN
  FIRST_X_ASSUM(MP_TAC o check (is_eq o concl)) THEN
  FIRST_X_ASSUM(MP_TAC o check (is_eq o concl)) THEN
  CONV_TAC INT_RING);;

let CROSS124_10_4_UNIVERSAL = prove
 (`!n:num. 0 < n ==> cross124_child_rep (&1) (&0) (&4) n`,
  REPEAT STRIP_TAC THEN
  MP_TAC IQ_UNIVERSAL_1226 THEN
  REWRITE_TAC[iq_universal; iq_represents] THEN
  DISCH_THEN(MP_TAC o SPEC `&n:int`) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[INT_OF_NUM_LT];
    DISCH_THEN(X_CHOOSE_THEN `v:num->int` (LABEL_TAC "rep"))] THEN
  REWRITE_TAC[cross124_child_rep] THEN
  MP_TAC(SPECL
   [`&n:int`; `v 0:int`; `v 1:int`; `v 2:int`; `v 3:int`]
   CROSS124_10_4_REP_OF_1226) THEN
  ANTS_TAC THENL
   [REMOVE_THEN "rep" MP_TAC THEN
    REWRITE_TAC[IQEVAL_DIAG4] THEN
    CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_RING;
    DISCH_THEN(X_CHOOSE_THEN `x:int`
      (X_CHOOSE_THEN `y:int`
        (X_CHOOSE_THEN `z:int`
          (X_CHOOSE_THEN `w:int` (LABEL_TAC "transferred")))))] THEN
  MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`; `w:int`] THEN
  REMOVE_THEN "transferred" MP_TAC THEN CONV_TAC INT_RING);;

(* Some reduced children are closed more economically by a different
   ternary sublattice than the original crossed <1,2,4>. *)

let iqselect013 = new_definition
 `iqselect013 i j =
    if i = 0 then (if j = 0 then &1 else &0)
    else if i = 1 then (if j = 1 then &1 else &0)
    else if i = 2 then (if j = 3 then &1 else &0)
    else &0`;;

let IQ_EMBEDS_CROSS124_SELECT013 = prove
 (`!n A b c k.
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) b (&4) c k) A
     ==> iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&2) b k) A`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `3`;
    `iqgram 4
      (iqmat4 (&1) (&0) (&0) (&0)
              (&2) (&1) b (&4) c k)
      iqselect013`;
    `iqmat3 (&1) (&0) (&0) (&2) b k`;
    `A:num->num->int`] IQ_EMBEDS_EQ) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC IQ_EMBEDS_CONGRUENCE THEN ASM_REWRITE_TAC[];
    REPEAT STRIP_TAC THEN
    (SUBGOAL_THEN `i = 0 \/ i = 1 \/ i = 2` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    (SUBGOAL_THEN `j = 0 \/ j = 1 \/ j = 2` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    ASM_REWRITE_TAC[iqgram; IQBILIN_MAT4; iqselect013;
      iqmat4; iqmat3; iqsym] THEN
    CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_RING]);;

let iqselect111_cross124 = new_definition
 `iqselect111_cross124 i j =
    if i = 0 then (if j = 0 then &1 else &0)
    else if i = 1 then (if j = 3 then &1 else &0)
    else if i = 2 then
      (if j = 1 then &1 else if j = 3 then -- &1 else &0)
    else &0`;;

let IQ_EMBEDS_CROSS124_10_1_EMBEDS_111 = prove
 (`!n A.
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) (&1) (&4) (&0) (&1)) A
     ==> iq_embeds n 3
          (iqmat3 (&1) (&0) (&0) (&1) (&0) (&1)) A`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `3`;
    `iqgram 4
      (iqmat4 (&1) (&0) (&0) (&0)
              (&2) (&1) (&1) (&4) (&0) (&1))
      iqselect111_cross124`;
    `iqmat3 (&1) (&0) (&0) (&1) (&0) (&1)`;
    `A:num->num->int`] IQ_EMBEDS_EQ) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC IQ_EMBEDS_CONGRUENCE THEN ASM_REWRITE_TAC[];
    REPEAT STRIP_TAC THEN
    (SUBGOAL_THEN `i = 0 \/ i = 1 \/ i = 2` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    (SUBGOAL_THEN `j = 0 \/ j = 1 \/ j = 2` MP_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    ASM_REWRITE_TAC[iqgram; IQBILIN_MAT4; iqselect111_cross124;
      iqmat4; iqmat3; iqsym] THEN
    CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC INT_RING]);;

let IQ_UNIVERSAL_OF_CROSS124_00_3_CHILD = prove
 (`!n A.
     iq_symmetric n A /\ iq_positive n A /\
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) (&0) (&4) (&0) (&3)) A /\
     iq_represents n A (&10)
     ==> iq_universal n A`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC(SPECL [`n:num`; `A:num->num->int`]
    IQ_UNIVERSAL_OF_EMBEDS_123) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `A:num->num->int`; `&0`; `&0`; `&3`]
   IQ_EMBEDS_CROSS124_SELECT013) THEN
  ASM_REWRITE_TAC[]);;

let IQ_UNIVERSAL_OF_CROSS124_10_1_CHILD = prove
 (`!n A.
     iq_symmetric n A /\ iq_positive n A /\
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) (&1) (&4) (&0) (&1)) A /\
     iq_represents n A (&7)
     ==> iq_universal n A`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC(SPECL [`n:num`; `A:num->num->int`]
    IQ_UNIVERSAL_OF_EMBEDS_111) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC IQ_EMBEDS_CROSS124_10_1_EMBEDS_111 THEN
  ASM_REWRITE_TAC[]);;

let IQ_UNIVERSAL_OF_CROSS124_0_NEG1_5_CHILD = prove
 (`!n A.
     iq_symmetric n A /\ iq_positive n A /\
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) (&0) (&4) (-- &1) (&5)) A /\
     iq_represents n A (&10) /\
     iq_represents n A (&15)
     ==> iq_universal n A`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC(SPECL [`n:num`; `A:num->num->int`]
    IQ_UNIVERSAL_OF_EMBEDS_125) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `A:num->num->int`; `&0`; `-- &1`; `&5`]
   IQ_EMBEDS_CROSS124_SELECT013) THEN
  ASM_REWRITE_TAC[]);;

let IQ_UNIVERSAL_OF_CROSS124_1_NEG1_5_CHILD = prove
 (`!n A.
     iq_symmetric n A /\ iq_positive n A /\
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) (&1) (&4) (-- &1) (&5)) A /\
     iq_represents n A (&7) /\
     iq_represents n A (&15)
     ==> iq_universal n A`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC(SPECL [`n:num`; `A:num->num->int`]
    IQ_UNIVERSAL_OF_EMBEDS_CROSS125) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `A:num->num->int`; `&1`; `-- &1`; `&5`]
   IQ_EMBEDS_CROSS124_SELECT013) THEN
  ASM_REWRITE_TAC[]);;

(* The exceptional (1,0,7) form contains twice the crossed <1,2,5>
   ternary form, with an orthogonal complement of norm 90. *)

let INT_CROSS124_10_7_TABLE2_IDENTITY = prove
 (`!a b c s:int.
     (-- &2 * b - c) pow 2 +
     &2 * (--a - c - s) pow 2 +
     &2 * (--a - c - s) * (c + &4 * s) +
     &4 * (c + &4 * s) pow 2 +
     &2 * (--a - c - s) * (c - &2 * s) +
     &7 * (c - &2 * s) pow 2 =
     &2 * (a pow 2 + &2 * b pow 2 + &2 * b * c + &5 * c pow 2) +
     &90 * s pow 2`,
  REPEAT GEN_TAC THEN CONV_TAC INT_RING);;

let CROSS124_10_7_EVEN_SHIFT = prove
 (`!q s:num.
     45 * s EXP 2 <= q /\
     ~(?a m. q - 45 * s EXP 2 = 4 EXP a * (8 * m + 7))
     ==> cross124_child_rep (&1) (&0) (&7) (2 * q)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2
    (LABEL_TAC "bound") (LABEL_TAC "not_exception")) THEN
  MP_TAC(MATCH_MP
    (SPEC `q - 45 * s EXP 2` INT_REPRESENTS_CROSS125_OF_LEGENDRE)
    (ASSUME
      `~(?a m. q - 45 * s EXP 2 = 4 EXP a * (8 * m + 7))`)) THEN
  DISCH_THEN(X_CHOOSE_THEN `a:int`
    (X_CHOOSE_THEN `b:int`
      (X_CHOOSE_THEN `c:int` (LABEL_TAC "ternary")))) THEN
  REWRITE_TAC[cross124_child_rep] THEN
  MAP_EVERY EXISTS_TAC
   [`-- &2 * b - c:int`;
    `--a - c - &s:int`;
    `c + &4 * &s:int`;
    `c - &2 * &s:int`] THEN
  MP_TAC(SPECL [`a:int`; `b:int`; `c:int`; `&s:int`]
    INT_CROSS124_10_7_TABLE2_IDENTITY) THEN
  MP_TAC(MATCH_MP
    (SPECL [`q:num`; `45`; `s:num`] INT_CROSS124_OFFSET_COERCE)
    (ASSUME `45 * s EXP 2 <= q`)) THEN
  REMOVE_THEN "ternary" MP_TAC THEN
  REWRITE_TAC[GSYM INT_OF_NUM_MUL; GSYM INT_OF_NUM_POW] THEN
  CONV_TAC INT_RING);;

let CROSS124_90_FINITE_SHIFT_TAC =
  FIRST
   (map
     (fun s ->
       EXISTS_TAC (mk_small_numeral s) THEN
       REWRITE_TAC[num_shift_rem] THEN
       CONV_TAC NUM_REDUCE_CONV THEN ACCEPT_TAC TRUTH)
     [1;2]);;

let CROSS124_90_RESIDUE_SELECTOR = prove
 (`!r:num.
     r < 8 /\ r MOD 2 = 1
     ==> ?s.
          1 <= s /\ s <= 2 /\
          ~((num_shift_rem r (45 * s EXP 2) 8) MOD 4 = 0) /\
          ~(num_shift_rem r (45 * s EXP 2) 8 = 7)`,
  GEN_TAC THEN STRIP_TAC THEN
  NUM_RANGE_CASES_THEN `r:num` 7
   (RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
    TRY CROSS124_CONTR_FALSE_ASSUM_TAC THEN
    CROSS124_90_FINITE_SHIFT_TAC));;

let CROSS124_10_7_EVEN_LARGE = prove
 (`!q:num.
     252 < q /\ q MOD 2 = 1
     ==> cross124_child_rep (&1) (&0) (&7) (2 * q)`,
  GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPEC `q MOD 8` CROSS124_90_RESIDUE_SELECTOR) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[MOD_LT_EQ] THEN CONV_TAC NUM_REDUCE_CONV;
      SUBGOAL_THEN `q MOD 8 MOD 2 = q MOD 2` SUBST1_TAC THENL
       [REWRITE_TAC[ARITH_RULE `8 = 2 * 4`; MOD_MOD];
        ASM_REWRITE_TAC[]]];
    DISCH_THEN(X_CHOOSE_THEN `s:num` STRIP_ASSUME_TAC)] THEN
  SUBGOAL_THEN `s = 1 \/ s = 2` (LABEL_TAC "s_cases") THENL
   [UNDISCH_TAC `1 <= s` THEN UNDISCH_TAC `s <= 2` THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `45 * s EXP 2 <= q` ASSUME_TAC THENL
   [REMOVE_THEN "s_cases" (DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    CONV_TAC NUM_REDUCE_CONV THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(q - 45 * s EXP 2) MOD 8 =
    num_shift_rem (q MOD 8) (45 * s EXP 2) 8`
  ASSUME_TAC THENL
   [MATCH_MP_TAC NUM_MOD_SUB_EXACT THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  MATCH_MP_TAC(SPECL [`q:num`; `s:num`] CROSS124_10_7_EVEN_SHIFT) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(SPEC `q - 45 * s EXP 2` THREE_SQUARES_AVOIDS_OF_MOD) THEN
  CONJ_TAC THENL
   [SUBGOAL_THEN
     `(q - 45 * s EXP 2) MOD 4 =
      (q - 45 * s EXP 2) MOD 8 MOD 4`
    SUBST1_TAC THENL
     [REWRITE_TAC[ARITH_RULE `8 = 4 * 2`; MOD_MOD];
      ASM_REWRITE_TAC[]];
    ASM_REWRITE_TAC[]]);;

(* For odd targets, the original crossed <1,2,4> complement has norm 315.
   Nine square shifts suffice to avoid both exceptional residue sets. *)

let CROSS124_315_RESIDUE_SELECTOR = prove
 (`!r12 r49:num.
     r12 < 12 /\ r49 < 49 /\ r12 MOD 2 = 1
     ==> ?s.
          1 <= s /\ 315 * s EXP 2 <= 25515 /\
          ~(num_shift_rem r12 (315 * s EXP 2) 12 = 7) /\
          ~(num_shift_rem r12 (315 * s EXP 2) 12 = 10) /\
          ~(num_shift_rem r49 (315 * s EXP 2) 49 = 0) /\
          ~(num_shift_rem r49 (315 * s EXP 2) 49 = 21) /\
          ~(num_shift_rem r49 (315 * s EXP 2) 49 = 35) /\
          ~(num_shift_rem r49 (315 * s EXP 2) 49 = 42)`,
  CROSS124_BOUNDED_FINITE_SHIFT_SELECTOR_TAC);;

let CROSS124_10_7_ODD_SHIFT = prove
 (`!n s:num.
     315 * s EXP 2 <= n /\
     (?x y z:int.
        x pow 2 + &2 * y pow 2 + &2 * y * z + &4 * z pow 2 =
        &(n - 315 * s EXP 2))
     ==> cross124_child_rep (&1) (&0) (&7) n`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "bound") (LABEL_TAC "tern")) THEN
  REWRITE_TAC[cross124_child_rep] THEN
  MATCH_MP_TAC(SPECL
   [`&1:int`; `&0:int`; `&7:int`; `&s:int`; `&n:int`]
   INT_REPRESENTS_CROSS124_CHILD_SHIFT7) THEN
  REMOVE_THEN "tern"
   (X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int` (X_CHOOSE_THEN `z:int` (LABEL_TAC "tern")))) THEN
  MAP_EVERY EXISTS_TAC [`x:int`; `y:int`; `z:int`] THEN
  MP_TAC(MATCH_MP
    (SPECL [`n:num`; `315`; `s:num`] INT_CROSS124_OFFSET_COERCE)
    (ASSUME `315 * s EXP 2 <= n`)) THEN
  REMOVE_THEN "tern" MP_TAC THEN
  REWRITE_TAC[cross124_det; GSYM INT_OF_NUM_POW] THEN
  CONV_TAC INT_RING);;

let CROSS124_10_7_ODD_LARGE = prove
 (`!n:num.
     25515 < n /\ n MOD 2 = 1
     ==> cross124_child_rep (&1) (&0) (&7) n`,
  GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`n MOD 12`; `n MOD 49`]
    CROSS124_315_RESIDUE_SELECTOR) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [REWRITE_TAC[MOD_LT_EQ] THEN CONV_TAC NUM_REDUCE_CONV;
      REWRITE_TAC[MOD_LT_EQ] THEN CONV_TAC NUM_REDUCE_CONV;
      SUBGOAL_THEN `n MOD 12 MOD 2 = n MOD 2` SUBST1_TAC THENL
       [REWRITE_TAC[ARITH_RULE `12 = 2 * 6`; MOD_MOD];
        ASM_REWRITE_TAC[]]];
    DISCH_THEN(X_CHOOSE_THEN `s:num` STRIP_ASSUME_TAC)] THEN
  SUBGOAL_THEN `315 * s EXP 2 <= n` ASSUME_TAC THENL
   [UNDISCH_TAC `315 * s EXP 2 <= 25515` THEN
    UNDISCH_TAC `25515 < n` THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(n - 315 * s EXP 2) MOD 12 =
    num_shift_rem (n MOD 12) (315 * s EXP 2) 12`
  ASSUME_TAC THENL
   [MATCH_MP_TAC NUM_MOD_SUB_EXACT THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(n - 315 * s EXP 2) MOD 49 =
    num_shift_rem (n MOD 49) (315 * s EXP 2) 49`
  ASSUME_TAC THENL
   [MATCH_MP_TAC NUM_MOD_SUB_EXACT THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  MATCH_MP_TAC(SPECL [`n:num`; `s:num`] CROSS124_10_7_ODD_SHIFT) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(SPEC `n - 315 * s EXP 2` DISC7_CROSS124_REGULAR) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_ARITH_TAC;
      MATCH_MP_TAC DISC7_NOT_EXCEPTION_OF_MOD49 THEN ASM_MESON_TAC[];
      ASM_MESON_TAC[];
      ASM_MESON_TAC[]];
    MESON_TAC[]]);;

let CROSS124_10_7_ODD_BASE = prove
 (`!n:num.
     0 < n /\ n <= 25515 /\ n MOD 2 = 1 /\
     ~(49 divides n) /\ cross124_maybe_check n
     ==> cross124_child_rep (&1) (&0) (&7) n`,
  CROSS124_QUOTIENT_BASE_TAC 1 0 7 25515);;

let CROSS124_10_7_ODD_UNIVERSAL = prove
 (`!n:num.
     0 < n /\ n MOD 2 = 1
     ==> cross124_child_rep (&1) (&0) (&7) n`,
  MATCH_MP_TAC num_WF THEN X_GEN_TAC `n:num` THEN
  DISCH_THEN(LABEL_TAC "ih") THEN STRIP_TAC THEN
  ASM_CASES_TAC `49 divides n` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `q:num` ASSUME_TAC o
      REWRITE_RULE[divides]) THEN
    SUBGOAL_THEN `q < n /\ 0 < q` STRIP_ASSUME_TAC THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `q MOD 2 = 1` ASSUME_TAC THENL
     [UNDISCH_TAC `n = 49 * q` THEN DISCH_THEN SUBST_ALL_TAC THEN
      UNDISCH_TAC `(49 * q) MOD 2 = 1` THEN
      ONCE_REWRITE_TAC
       [GSYM(SPECL [`49`; `2`; `q:num`] MOD_MULT_LMOD)] THEN
      CONV_TAC NUM_REDUCE_CONV THEN REWRITE_TAC[MULT_CLAUSES];
      ALL_TAC] THEN
    SUBGOAL_THEN `n = 7 EXP 2 * q` SUBST1_TAC THENL
     [UNDISCH_TAC `n = 49 * q` THEN CONV_TAC NUM_REDUCE_CONV;
      ALL_TAC] THEN
    MATCH_MP_TAC(SPECL
     [`&1:int`; `&0:int`; `&7:int`; `7`; `q:num`]
     CROSS124_CHILD_REP_SCALE) THEN
    REMOVE_THEN "ih" (MP_TAC o SPEC `q:num`) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `n <= 25515` THENL
   [ASM_CASES_TAC `cross124_maybe_check n` THENL
     [MATCH_MP_TAC(SPEC `n:num` CROSS124_10_7_ODD_BASE) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(SPECL
       [`&1:int`; `&0:int`; `&7:int`; `n:num`]
       CROSS124_CHILD_REP_REGULAR) THEN
      ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[CROSS124_NEEDS_IMP_MAYBE_CHECK]];
    MATCH_MP_TAC(SPEC `n:num` CROSS124_10_7_ODD_LARGE) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]);;

let CROSS124_10_7_SMALL = prove
 (`!n:num.
     0 < n /\ n <= 504
     ==> cross124_child_rep (&1) (&0) (&7) n`,
  GEN_TAC THEN STRIP_TAC THEN
  NUM_RANGE_CASES_THEN `n:num` 504
   (TRY ASM_ARITH_TAC THEN
    REWRITE_TAC[cross124_child_rep] THEN
    CONV_TAC NUM_REDUCE_CONV THEN CROSS124_CERT_TAC 1 0 7));;

let CROSS124_10_7_UNIVERSAL = prove
 (`!n:num. 0 < n ==> cross124_child_rep (&1) (&0) (&7) n`,
  MATCH_MP_TAC num_WF THEN X_GEN_TAC `n:num` THEN
  DISCH_THEN(LABEL_TAC "ih") THEN DISCH_TAC THEN
  ASM_CASES_TAC `4 divides n` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `q:num` ASSUME_TAC o
      REWRITE_RULE[divides]) THEN
    SUBGOAL_THEN `q < n /\ 0 < q` STRIP_ASSUME_TAC THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `n = 2 EXP 2 * q` SUBST1_TAC THENL
     [UNDISCH_TAC `n = 4 * q` THEN CONV_TAC NUM_REDUCE_CONV;
      ALL_TAC] THEN
    MATCH_MP_TAC(SPECL
     [`&1:int`; `&0:int`; `&7:int`; `2`; `q:num`]
     CROSS124_CHILD_REP_SCALE) THEN
    REMOVE_THEN "ih" (MP_TAC o SPEC `q:num`) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `n MOD 2 = 0` THENL
   [ASM_CASES_TAC `n <= 504` THENL
     [MATCH_MP_TAC(SPEC `n:num` CROSS124_10_7_SMALL) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ABBREV_TAC `q = n DIV 2` THEN
    SUBGOAL_THEN `n = 2 * q` ASSUME_TAC THENL
     [EXPAND_TAC "q" THEN
      MP_TAC(SPECL [`n:num`; `2`] DIVISION) THEN
      CONV_TAC NUM_REDUCE_CONV THEN
      ASM_REWRITE_TAC[ADD_CLAUSES] THEN ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `q MOD 2 = 1` ASSUME_TAC THENL
     [ASM_CASES_TAC `q MOD 2 = 0` THENL
       [SUBGOAL_THEN `2 divides q` (LABEL_TAC "q_even") THENL
         [ASM_REWRITE_TAC[DIVIDES_MOD];
          ALL_TAC] THEN
        REMOVE_THEN "q_even"
         (X_CHOOSE_THEN `r:num` (LABEL_TAC "q_factor") o
          REWRITE_RULE[divides]) THEN
        SUBGOAL_THEN `4 divides n` MP_TAC THENL
         [REWRITE_TAC[divides] THEN EXISTS_TAC `r:num` THEN
          REMOVE_THEN "q_factor" MP_TAC THEN
          UNDISCH_TAC `n = 2 * q` THEN ARITH_TAC;
          ASM_REWRITE_TAC[]];
        MP_TAC(SPECL [`q:num`; `2`] MOD_LT_EQ) THEN
        CONV_TAC NUM_REDUCE_CONV THEN ASM_ARITH_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `252 < q` ASSUME_TAC THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBST1_TAC(ASSUME `n = 2 * q`) THEN
    MATCH_MP_TAC(SPEC `q:num` CROSS124_10_7_EVEN_LARGE) THEN
    ASM_REWRITE_TAC[];
    SUBGOAL_THEN `n MOD 2 = 1` ASSUME_TAC THENL
     [MP_TAC(SPECL [`n:num`; `2`] MOD_LT_EQ) THEN
      CONV_TAC NUM_REDUCE_CONV THEN ASM_ARITH_TAC;
      MATCH_MP_TAC(SPEC `n:num` CROSS124_10_7_ODD_UNIVERSAL) THEN
      ASM_REWRITE_TAC[]]]);;

let IQ_CROSS124_CHILD_REP_OF_NUM = prove
 (`!b c k m.
     cross124_child_rep b c k m
     ==> iq_represents 4
          (iqmat4 (&1) (&0) (&0) (&0)
                  (&2) (&1) b (&4) c k) (&m)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[cross124_child_rep; iq_represents] THEN
  DISCH_THEN(X_CHOOSE_THEN `x:int`
    (X_CHOOSE_THEN `y:int`
      (X_CHOOSE_THEN `z:int` (X_CHOOSE_TAC `w:int`)))) THEN
  EXISTS_TAC
   `\i:num.
      if i = 0 then (x:int) else if i = 1 then y else
      if i = 2 then z else w` THEN
  REWRITE_TAC[IQEVAL_MAT4] THEN CONV_TAC NUM_REDUCE_CONV THEN
  FIRST_X_ASSUM(MP_TAC) THEN CONV_TAC INT_RING);;

let IQ_UNIVERSAL_OF_CROSS124_REP_CHILD = prove
 (`!n A b c k.
     iq_embeds n 4
       (iqmat4 (&1) (&0) (&0) (&0)
               (&2) (&1) b (&4) c k) A /\
     (!m:num. 0 < m ==> cross124_child_rep b c k m)
     ==> iq_universal n A`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "emb") (LABEL_TAC "univ")) THEN
  REWRITE_TAC[iq_universal] THEN
  X_GEN_TAC `m:int` THEN DISCH_TAC THEN
  MP_TAC(EQ_MP (SYM(SPEC `m:int` INT_OF_NUM_EXISTS))
    (MATCH_MP (SPECL [`&0:int`; `m:int`] INT_LT_IMP_LE)
      (ASSUME `&0 < m`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `u:num` SUBST_ALL_TAC) THEN
  MATCH_MP_TAC(ISPECL
   [`n:num`; `4`;
    `iqmat4 (&1) (&0) (&0) (&0)
            (&2) (&1) b (&4) c k`;
    `A:num->num->int`; `&u:int`] IQ_REPRESENTS_OF_EMBEDS) THEN
  CONJ_TAC THENL
   [REMOVE_THEN "emb" MATCH_ACCEPT_TAC;
    MATCH_MP_TAC(SPECL [`b:int`; `c:int`; `k:int`; `u:num`]
      IQ_CROSS124_CHILD_REP_OF_NUM) THEN
    REMOVE_THEN "univ" (MATCH_MP_TAC o SPEC `u:num`) THEN
    UNDISCH_TAC `&0 < &u` THEN REWRITE_TAC[INT_OF_NUM_LT]]);;

let CROSS124_UNIVERSAL_CHILD_TAC b c k th =
  MATCH_MP_TAC(ISPECL
   [`n:num`; `A:num->num->int`; b; c; k]
   IQ_UNIVERSAL_OF_CROSS124_REP_CHILD) THEN
  CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    MATCH_ACCEPT_TAC th];;

let IQ_UNIVERSAL_OF_EMBEDS_CROSS124 = prove
 (`!n A.
     iq_symmetric n A /\ iq_positive n A /\
     iq_embeds n 3
       (iqmat3 (&1) (&0) (&0) (&2) (&1) (&4)) A /\
     iq_represents n A (&7) /\
     iq_represents n A (&10) /\
     iq_represents n A (&15)
     ==> iq_universal n A`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`n:num`; `A:num->num->int`]
    IQ_EMBEDS_QUATERNARY_CROSS124) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN
    (X_CHOOSE_THEN `k:int`
      (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC))) THENL
   [MP_TAC(ISPECL [`n:num`; `A:num->num->int`; `k:int`]
      IQ_CROSS124_00_PARAMETER_CASES) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THENL
     [CROSS124_UNIVERSAL_CHILD_TAC
       `&0:int` `&0:int` `&1:int` CROSS124_DIAG1_UNIVERSAL;
      CROSS124_UNIVERSAL_CHILD_TAC
       `&0:int` `&0:int` `&2:int` CROSS124_DIAG2_UNIVERSAL;
      MATCH_MP_TAC(SPECL [`n:num`; `A:num->num->int`]
        IQ_UNIVERSAL_OF_CROSS124_00_3_CHILD) THEN ASM_REWRITE_TAC[];
      CROSS124_UNIVERSAL_CHILD_TAC
       `&0:int` `&0:int` `&4:int` CROSS124_DIAG4_UNIVERSAL;
