      CROSS124_UNIVERSAL_CHILD_TAC
       `&0:int` `&0:int` `&7:int` CROSS124_DIAG7_UNIVERSAL];
    MP_TAC(ISPECL [`n:num`; `A:num->num->int`; `k:int`]
      IQ_CROSS124_10_PARAMETER_CASES) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THENL
     [MATCH_MP_TAC(SPECL [`n:num`; `A:num->num->int`]
        IQ_UNIVERSAL_OF_CROSS124_10_1_CHILD) THEN ASM_REWRITE_TAC[];
      CROSS124_UNIVERSAL_CHILD_TAC
       `&1:int` `&0:int` `&2:int` CROSS124_10_2_UNIVERSAL;
      CROSS124_UNIVERSAL_CHILD_TAC
       `&1:int` `&0:int` `&3:int` CROSS124_10_3_UNIVERSAL;
      CROSS124_UNIVERSAL_CHILD_TAC
       `&1:int` `&0:int` `&4:int` CROSS124_10_4_UNIVERSAL;
      CROSS124_UNIVERSAL_CHILD_TAC
       `&1:int` `&0:int` `&5:int` CROSS124_10_5_UNIVERSAL;
      CROSS124_UNIVERSAL_CHILD_TAC
       `&1:int` `&0:int` `&6:int` CROSS124_10_6_UNIVERSAL;
      CROSS124_UNIVERSAL_CHILD_TAC
       `&1:int` `&0:int` `&7:int` CROSS124_10_7_UNIVERSAL];
    MP_TAC(ISPECL [`n:num`; `A:num->num->int`; `k:int`]
      IQ_CROSS124_0_NEG1_PARAMETER_CASES) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THENL
