       `&1:int` `-- &1:int` `&4:int` CROSS124_1_NEG1_4_UNIVERSAL;
      MATCH_MP_TAC(SPECL [`n:num`; `A:num->num->int`]
        IQ_UNIVERSAL_OF_CROSS124_1_NEG1_5_CHILD) THEN ASM_REWRITE_TAC[];
      CROSS124_UNIVERSAL_CHILD_TAC
       `&1:int` `-- &1:int` `&6:int` CROSS124_1_NEG1_6_UNIVERSAL;
