       `&1:int` `-- &1:int` `&7:int` CROSS124_1_NEG1_7_UNIVERSAL]]);;

let IQ_UNIVERSAL_OF_REPRESENTS_UP_TO_15 = prove
 (`!n A.
     iq_symmetric n A /\ iq_positive n A /\
     (!m:int. &0 < m /\ m <= &15 ==> iq_represents n A m)
     ==> iq_universal n A`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  let REPRESENT_TAC =
    FIRST_ASSUM MATCH_MP_TAC THEN CONV_TAC INT_REDUCE_CONV in
  SUBGOAL_THEN `iq_represents n A (&1)` ASSUME_TAC THENL
   [REPRESENT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `iq_represents n A (&2)` ASSUME_TAC THENL
   [REPRESENT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `iq_represents n A (&3)` ASSUME_TAC THENL
   [REPRESENT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `iq_represents n A (&5)` ASSUME_TAC THENL
   [REPRESENT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `iq_represents n A (&6)` ASSUME_TAC THENL
   [REPRESENT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `iq_represents n A (&7)` ASSUME_TAC THENL
   [REPRESENT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `iq_represents n A (&10)` ASSUME_TAC THENL
   [REPRESENT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `iq_represents n A (&14)` ASSUME_TAC THENL
   [REPRESENT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `iq_represents n A (&15)` ASSUME_TAC THENL
   [REPRESENT_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`n:num`; `A:num->num->int`] IQ_EMBEDS_TERNARY) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [MATCH_MP_TAC(SPECL [`n:num`; `A:num->num->int`]
      IQ_UNIVERSAL_OF_EMBEDS_111) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(SPECL [`n:num`; `A:num->num->int`]
      IQ_UNIVERSAL_OF_EMBEDS_112) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(SPECL [`n:num`; `A:num->num->int`]
      IQ_UNIVERSAL_OF_EMBEDS_113) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(SPECL [`n:num`; `A:num->num->int`]
      IQ_UNIVERSAL_OF_EMBEDS_122) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(SPECL [`n:num`; `A:num->num->int`]
      IQ_UNIVERSAL_OF_EMBEDS_123) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(SPECL [`n:num`; `A:num->num->int`]
      IQ_UNIVERSAL_OF_EMBEDS_124) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(SPECL [`n:num`; `A:num->num->int`]
      IQ_UNIVERSAL_OF_EMBEDS_125) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(SPECL [`n:num`; `A:num->num->int`]
      IQ_UNIVERSAL_OF_EMBEDS_CROSS124) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(SPECL [`n:num`; `A:num->num->int`]
      IQ_UNIVERSAL_OF_EMBEDS_CROSS125) THEN ASM_REWRITE_TAC[]]);;

let FIFTEEN_THEOREM = prove
 (`!n A.
     iq_symmetric n A /\ iq_positive n A
     ==> ((!m:int. &0 < m /\ m <= &15 ==> iq_represents n A m) <=>
          (!m:int. &0 < m ==> iq_represents n A m))`,
  MESON_TAC[IQ_UNIVERSAL_OF_REPRESENTS_UP_TO_15; iq_universal]);;
